(window.ABHYAS_GRAPHS=window.ABHYAS_GRAPHS||{})["economics-6-10"]={"id":"economics-6-10","meta":{"subject":"Economics","band":"6-10","grades":[8,9,10],"boards":["CBSE/NCERT","ICSE","State"],"schema_version":"v0","status":"draft — hand-authored spine","note":"Social Science; MCQ-focused (definitional + relational + a little quantitative); NCERT introduces Economics mainly in classes 9-10.","assembled_from":{"mcqs_dir":"content/economics/6-10/mcqs","drills_dir":null}},"concepts":[{"id":"eco610-dev-what-is-development","concept":"what development means and why it varies by person","strand":"Economic Development","grade":10,"count":10,"difficulty":1,"prereqs":[]},{"id":"eco610-dev-income-as-indicator","concept":"average (per capita) income as a common measure of development","strand":"Economic Development","grade":10,"count":10,"difficulty":1,"prereqs":["eco610-dev-what-is-development"]},{"id":"eco610-dev-per-capita-income-calc","concept":"how per capita income is calculated from total income and population","strand":"Economic Development","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-dev-income-as-indicator"]},{"id":"eco610-dev-limitations-income","concept":"why average income alone hides inequality within a country","strand":"Economic Development","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-dev-per-capita-income-calc"]},{"id":"eco610-dev-other-criteria","concept":"using non-income criteria such as literacy and infant mortality alongside income","strand":"Economic Development","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-dev-limitations-income"]},{"id":"eco610-dev-hdi","concept":"Human Development Index as a composite measure combining income, health and education","strand":"Economic Development","grade":10,"count":10,"difficulty":3,"prereqs":["eco610-dev-other-criteria"]},{"id":"eco610-dev-public-facilities","concept":"why some goods and services need government provision rather than only the market","strand":"Economic Development","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-dev-other-criteria"]},{"id":"eco610-dev-sustainability","concept":"sustainability of development and the risk of resource depletion","strand":"Economic Development","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-dev-what-is-development"]},{"id":"eco610-sec-primary","concept":"primary sector: producing by directly exploiting natural resources","strand":"Sectors of the Economy","grade":10,"count":10,"difficulty":1,"prereqs":[]},{"id":"eco610-sec-secondary","concept":"secondary sector: transforming raw materials into manufactured goods","strand":"Sectors of the Economy","grade":10,"count":10,"difficulty":1,"prereqs":[]},{"id":"eco610-sec-tertiary","concept":"tertiary sector: services that support production in the other sectors","strand":"Sectors of the Economy","grade":10,"count":10,"difficulty":1,"prereqs":[]},{"id":"eco610-sec-comparing-three","concept":"how the three sectors of the economy differ in what they produce","strand":"Sectors of the Economy","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-sec-primary","eco610-sec-secondary","eco610-sec-tertiary"]},{"id":"eco610-sec-gdp","concept":"Gross Domestic Product as the value of all final goods and services produced in a year","strand":"Sectors of the Economy","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-sec-comparing-three"]},{"id":"eco610-sec-sector-contribution","concept":"comparing sectors by their share of GDP versus their share of employment","strand":"Sectors of the Economy","grade":10,"count":10,"difficulty":3,"prereqs":["eco610-sec-gdp"]},{"id":"eco610-sec-rising-tertiary","concept":"why the tertiary sector's share of GDP has risen fastest in India","strand":"Sectors of the Economy","grade":10,"count":10,"difficulty":3,"prereqs":["eco610-sec-sector-contribution"]},{"id":"eco610-sec-organised-unorganised","concept":"organised versus unorganised sector by job security and regulation","strand":"Sectors of the Economy","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-sec-comparing-three"]},{"id":"eco610-sec-public-private","concept":"public sector versus private sector by ownership and objective","strand":"Sectors of the Economy","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-sec-comparing-three"]},{"id":"eco610-sec-govt-role-public","concept":"why government undertakes public sector activities for collective welfare","strand":"Sectors of the Economy","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-sec-public-private"]},{"id":"eco610-mon-barter-problem","concept":"the double coincidence of wants problem in a barter system","strand":"Money and Credit","grade":10,"count":10,"difficulty":1,"prereqs":[]},{"id":"eco610-mon-money-as-medium","concept":"money as a medium of exchange that removes the need for double coincidence","strand":"Money and Credit","grade":10,"count":10,"difficulty":1,"prereqs":["eco610-mon-barter-problem"]},{"id":"eco610-mon-modern-forms","concept":"modern forms of money: currency and bank deposits","strand":"Money and Credit","grade":10,"count":10,"difficulty":1,"prereqs":["eco610-mon-money-as-medium"]},{"id":"eco610-mon-bank-deposits","concept":"how banks accept deposits from the public and pay interest on them","strand":"Money and Credit","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-mon-modern-forms"]},{"id":"eco610-mon-bank-lending","concept":"how banks lend out most of their deposited money as loans","strand":"Money and Credit","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-mon-bank-deposits"]},{"id":"eco610-mon-credit-definition","concept":"credit (loan) as an agreement to repay borrowed money with interest","strand":"Money and Credit","grade":10,"count":10,"difficulty":1,"prereqs":[]},{"id":"eco610-mon-terms-of-credit","concept":"terms of credit: interest rate, collateral and documentation required","strand":"Money and Credit","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-mon-credit-definition"]},{"id":"eco610-mon-collateral","concept":"collateral as an asset pledged as security against loan default","strand":"Money and Credit","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-mon-terms-of-credit"]},{"id":"eco610-mon-formal-credit","concept":"formal sources of credit: banks and cooperative societies","strand":"Money and Credit","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-mon-credit-definition"]},{"id":"eco610-mon-informal-credit","concept":"informal sources of credit: moneylenders, traders and relatives","strand":"Money and Credit","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-mon-credit-definition"]},{"id":"eco610-mon-formal-vs-informal","concept":"why formal credit is usually cheaper and more accountable than informal credit","strand":"Money and Credit","grade":10,"count":10,"difficulty":3,"prereqs":["eco610-mon-formal-credit","eco610-mon-informal-credit"]},{"id":"eco610-mon-rbi-supervision","concept":"RBI's role in supervising banks and the formal credit system","strand":"Money and Credit","grade":10,"count":10,"difficulty":3,"prereqs":["eco610-mon-formal-credit"]},{"id":"eco610-mon-shg","concept":"self-help groups as a source of small collective credit for the poor","strand":"Money and Credit","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-mon-formal-vs-informal"]},{"id":"eco610-glo-what-is-globalisation","concept":"globalisation as growing interconnection between economies through trade and investment","strand":"Globalisation and the Indian Economy","grade":10,"count":10,"difficulty":1,"prereqs":[]},{"id":"eco610-glo-mnc","concept":"multinational corporations and how they organise production across countries","strand":"Globalisation and the Indian Economy","grade":10,"count":10,"difficulty":1,"prereqs":["eco610-glo-what-is-globalisation"]},{"id":"eco610-glo-foreign-investment","concept":"foreign investment as capital an MNC brings to set up production in another country","strand":"Globalisation and the Indian Economy","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-glo-mnc"]},{"id":"eco610-glo-factors-enabling","concept":"technology and government liberalisation as factors enabling globalisation","strand":"Globalisation and the Indian Economy","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-glo-what-is-globalisation"]},{"id":"eco610-glo-trade-liberalisation","concept":"trade liberalisation: governments removing barriers or tariffs on foreign trade","strand":"Globalisation and the Indian Economy","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-glo-factors-enabling"]},{"id":"eco610-glo-wto","concept":"World Trade Organisation and its role in setting global trade rules","strand":"Globalisation and the Indian Economy","grade":10,"count":10,"difficulty":3,"prereqs":["eco610-glo-trade-liberalisation"]},{"id":"eco610-glo-impact-consumers","concept":"how globalisation widens consumer choice and product variety","strand":"Globalisation and the Indian Economy","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-glo-mnc"]},{"id":"eco610-glo-impact-producers-uneven","concept":"uneven impact of globalisation on small local producers versus large firms","strand":"Globalisation and the Indian Economy","grade":10,"count":10,"difficulty":3,"prereqs":["eco610-glo-mnc","eco610-glo-trade-liberalisation"]},{"id":"eco610-glo-fair-globalisation","concept":"fair globalisation: labour standards and policy needed for equitable outcomes","strand":"Globalisation and the Indian Economy","grade":10,"count":10,"difficulty":3,"prereqs":["eco610-glo-impact-producers-uneven"]},{"id":"eco610-con-marketplace-exploitation","concept":"how consumers can be exploited in the marketplace (adulteration, under-weighing, overpricing)","strand":"Consumer Rights","grade":10,"count":10,"difficulty":1,"prereqs":[]},{"id":"eco610-con-consumer-awareness","concept":"consumer awareness as protection against exploitation in the marketplace","strand":"Consumer Rights","grade":10,"count":10,"difficulty":1,"prereqs":["eco610-con-marketplace-exploitation"]},{"id":"eco610-con-movement-origins","concept":"origins and growth of the consumer movement in India","strand":"Consumer Rights","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-con-marketplace-exploitation"]},{"id":"eco610-con-copra","concept":"COPRA (Consumer Protection Act) and its objective of safeguarding consumers","strand":"Consumer Rights","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-con-movement-origins"]},{"id":"eco610-con-rights-list","concept":"the recognised consumer rights: safety, information, choice and redressal","strand":"Consumer Rights","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-con-copra"]},{"id":"eco610-con-right-to-information","concept":"right to information through standard marks like ISI, Agmark and Hallmark","strand":"Consumer Rights","grade":10,"count":10,"difficulty":2,"prereqs":["eco610-con-rights-list"]},{"id":"eco610-con-redressal-forums","concept":"three-tier consumer redressal: district, state and national forums","strand":"Consumer Rights","grade":10,"count":10,"difficulty":3,"prereqs":["eco610-con-copra"]},{"id":"eco610-ppl-human-capital","concept":"people as human capital, an asset rather than only a population count","strand":"People as Resource","grade":9,"count":10,"difficulty":1,"prereqs":[]},{"id":"eco610-ppl-economic-vs-non-economic-activity","concept":"distinguishing economic activities from unpaid non-economic activities","strand":"People as Resource","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-ppl-human-capital"]},{"id":"eco610-ppl-investment-education","concept":"education as an investment that raises human capital","strand":"People as Resource","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-ppl-human-capital"]},{"id":"eco610-ppl-investment-health","concept":"health as an investment that raises human capital","strand":"People as Resource","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-ppl-human-capital"]},{"id":"eco610-ppl-quality-population","concept":"quality of population measured by literacy rate, health status and skill formation","strand":"People as Resource","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-ppl-investment-education","eco610-ppl-investment-health"]},{"id":"eco610-ppl-unemployment-def","concept":"unemployment: people willing and able to work but unable to find it","strand":"People as Resource","grade":9,"count":10,"difficulty":1,"prereqs":[]},{"id":"eco610-ppl-types-unemployment","concept":"seasonal and disguised unemployment as two forms found in rural India","strand":"People as Resource","grade":9,"count":10,"difficulty":3,"prereqs":["eco610-ppl-unemployment-def"]},{"id":"eco610-ppl-educated-unemployment","concept":"educated unemployment as a distinct feature of urban India","strand":"People as Resource","grade":9,"count":10,"difficulty":3,"prereqs":["eco610-ppl-unemployment-def"]},{"id":"eco610-ppl-unemployment-impact","concept":"how unemployment wastes human resources and increases dependence on others","strand":"People as Resource","grade":9,"count":10,"difficulty":3,"prereqs":["eco610-ppl-types-unemployment","eco610-ppl-educated-unemployment"]},{"id":"eco610-pov-as-challenge","concept":"poverty as a major challenge facing the Indian economy","strand":"Poverty","grade":9,"count":10,"difficulty":1,"prereqs":[]},{"id":"eco610-pov-social-exclusion","concept":"social exclusion and vulnerability as dimensions of poverty beyond income","strand":"Poverty","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-pov-as-challenge"]},{"id":"eco610-pov-poverty-line","concept":"the poverty line as a minimum income or consumption benchmark","strand":"Poverty","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-pov-as-challenge"]},{"id":"eco610-pov-poverty-line-calc","concept":"how the poverty line is estimated using a minimum calorie requirement","strand":"Poverty","grade":9,"count":10,"difficulty":3,"prereqs":["eco610-pov-poverty-line"]},{"id":"eco610-pov-trends-india","concept":"trends in India's poverty ratio over recent decades","strand":"Poverty","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-pov-poverty-line"]},{"id":"eco610-pov-interstate-disparities","concept":"inter-state disparities in poverty levels within India","strand":"Poverty","grade":9,"count":10,"difficulty":3,"prereqs":["eco610-pov-trends-india"]},{"id":"eco610-pov-global-poverty","concept":"comparing poverty levels across countries globally","strand":"Poverty","grade":9,"count":10,"difficulty":3,"prereqs":["eco610-pov-poverty-line"]},{"id":"eco610-pov-causes","concept":"causes of poverty: low growth, unemployment and social factors","strand":"Poverty","grade":9,"count":10,"difficulty":3,"prereqs":["eco610-pov-as-challenge"]},{"id":"eco610-pov-anti-poverty-programmes","concept":"government anti-poverty strategy combining growth with targeted programmes","strand":"Poverty","grade":9,"count":10,"difficulty":3,"prereqs":["eco610-pov-causes"]},{"id":"eco610-food-what-is-food-security","concept":"food security: availability, accessibility and affordability of food for all","strand":"Food Security","grade":9,"count":10,"difficulty":1,"prereqs":[]},{"id":"eco610-food-affected-groups","concept":"population groups most vulnerable to food insecurity","strand":"Food Security","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-food-what-is-food-security"]},{"id":"eco610-food-famine","concept":"famine as an extreme, widespread failure of food security","strand":"Food Security","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-food-what-is-food-security"]},{"id":"eco610-food-self-sufficiency-grain","concept":"India's shift to self-sufficiency in foodgrains after the Green Revolution","strand":"Food Security","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-food-what-is-food-security"]},{"id":"eco610-food-buffer-stock","concept":"buffer stock: foodgrain the government procures and stores through the FCI","strand":"Food Security","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-food-self-sufficiency-grain"]},{"id":"eco610-food-msp","concept":"minimum support price as the government's procurement price paid to farmers","strand":"Food Security","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-food-buffer-stock"]},{"id":"eco610-food-pds","concept":"Public Distribution System: distributing food through ration shops","strand":"Food Security","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-food-buffer-stock"]},{"id":"eco610-food-pds-evolution","concept":"evolution of the PDS from universal to targeted (TPDS) distribution","strand":"Food Security","grade":9,"count":10,"difficulty":3,"prereqs":["eco610-food-pds"]},{"id":"eco610-food-role-cooperatives","concept":"role of cooperatives in running fair-price shops for food security","strand":"Food Security","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-food-pds"]},{"id":"eco610-rur-farming-as-livelihood","concept":"farming as the main livelihood activity in rural India","strand":"Rural Livelihoods and Agriculture","grade":9,"count":10,"difficulty":1,"prereqs":[]},{"id":"eco610-rur-land-as-resource","concept":"land as a fixed natural resource input to farm production","strand":"Rural Livelihoods and Agriculture","grade":9,"count":10,"difficulty":1,"prereqs":[]},{"id":"eco610-rur-labour-capital-inputs","concept":"labour and capital as variable inputs combined with land to produce output","strand":"Rural Livelihoods and Agriculture","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-rur-land-as-resource"]},{"id":"eco610-rur-non-farm-activities","concept":"non-farm activities in rural areas: dairy, small-scale manufacturing and services","strand":"Rural Livelihoods and Agriculture","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-rur-farming-as-livelihood"]},{"id":"eco610-rur-diversification","concept":"why rural livelihoods are diversifying beyond farming alone","strand":"Rural Livelihoods and Agriculture","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-rur-non-farm-activities"]},{"id":"eco610-rur-credit-need","concept":"why farmers need credit for seeds, fertiliser and equipment before the harvest","strand":"Rural Livelihoods and Agriculture","grade":9,"count":10,"difficulty":2,"prereqs":["eco610-rur-farming-as-livelihood","eco610-mon-credit-definition"]}],"mcqs":[{"id":"consumer-awareness-as-protection-against-exploitation-in-the-marketplace-001","band":"K5","grade":10,"subject":"Mathematics","concept":"consumer awareness as protection against exploitation in the marketplace","difficulty":2,"stem":"An item has a printed MRP of ₹850. A shopkeeper sells it for ₹918. What is the overcharge as a percentage of the MRP?","options":["6.8%","8%","7.4%","10%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Misplaces the decimal after computing 68/1000 instead of 68/850."},{"option_index":2,"misconception":"Divides the overcharge by the selling price (68/918×100 ≈ 7.4%) instead of by the MRP."},{"option_index":3,"misconception":"Confuses 10% of the MRP (₹85) with the actual overcharge of ₹68."}],"explanation":"Overcharge = 918 − 850 = ₹68; percentage = 68/850 × 100 = 8%.","concept_id":"eco610-con-consumer-awareness","strand":"Consumer Rights","kind":"mcq"},{"id":"consumer-awareness-as-protection-against-exploitation-in-the-marketplace-002","band":"K5","grade":10,"subject":"Mathematics","concept":"consumer awareness as protection against exploitation in the marketplace","difficulty":2,"stem":"An article marked at ₹800 is sold for ₹720. What discount percent is given?","options":["11.1%","12.5%","8%","10%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Divides the ₹80 discount by the selling price ₹720 instead of by the marked price."},{"option_index":1,"misconception":"Uses a ₹100 discount instead of the actual ₹80 discount."},{"option_index":2,"misconception":"Divides the ₹80 discount by ₹1000, a place-value error in the denominator."}],"explanation":"Discount = 800 − 720 = ₹80; discount percent = 80/800 × 100 = 10%.","concept_id":"eco610-con-consumer-awareness","strand":"Consumer Rights","kind":"mcq"},{"id":"consumer-awareness-as-protection-against-exploitation-in-the-marketplace-003","band":"K5","grade":10,"subject":"Mathematics","concept":"consumer awareness as protection against exploitation in the marketplace","difficulty":2,"stem":"Pack A contains 2 kg of rice and costs ₹240. Pack B contains 3 kg and costs ₹330. How much less per kg does the cheaper pack cost than the other?","options":["₹10","₹20","₹30","₹5"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Rounds Pack B's unit cost to ₹100 per kg after an incorrect division, then subtracts."},{"option_index":2,"misconception":"Divides the total price difference ₹90 by the weight difference 3 kg instead of comparing unit prices."},{"option_index":3,"misconception":"Takes half the correct difference by confusing 'less per kg' with average saving."}],"explanation":"Pack A = 240/2 = ₹120 per kg; Pack B = 330/3 = ₹110 per kg; cheaper by ₹10 per kg.","concept_id":"eco610-con-consumer-awareness","strand":"Consumer Rights","kind":"mcq"},{"id":"consumer-awareness-as-protection-against-exploitation-in-the-marketplace-004","band":"K5","grade":10,"subject":"Mathematics","concept":"consumer awareness as protection against exploitation in the marketplace","difficulty":2,"stem":"A consumer buys an item priced at ₹1,500 before GST. If GST is 18%, what is the total amount payable?","options":["₹1,680","₹1,800","₹1,770","₹1,620"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses 12% instead of 18% for GST, adding ₹180."},{"option_index":1,"misconception":"Uses 20% instead of 18% for GST, adding ₹300."},{"option_index":3,"misconception":"Uses 8% instead of 18% for GST, adding ₹120."}],"explanation":"GST = 18% of 1500 = ₹270; total = 1500 + 270 = ₹1,770.","concept_id":"eco610-con-consumer-awareness","strand":"Consumer Rights","kind":"mcq"},{"id":"consumer-awareness-as-protection-against-exploitation-in-the-marketplace-005","band":"K5","grade":10,"subject":"Mathematics","concept":"consumer awareness as protection against exploitation in the marketplace","difficulty":2,"stem":"A packet is labelled 500 g but actually contains 450 g. What is the short weight as a percentage of the labelled weight?","options":["11.1%","10%","9%","5%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Divides the 50 g shortage by the actual 450 g instead of the labelled 500 g."},{"option_index":2,"misconception":"Divides the 50 g shortage by 550 g, adding the shortage to the labelled weight."},{"option_index":3,"misconception":"Takes the shortage as 25 g by halving the correct difference."}],"explanation":"Short weight = 500 − 450 = 50 g; percentage = 50/500 × 100 = 10%.","concept_id":"eco610-con-consumer-awareness","strand":"Consumer Rights","kind":"mcq"},{"id":"consumer-awareness-as-protection-against-exploitation-in-the-marketplace-006","band":"K5","grade":10,"subject":"Mathematics","concept":"consumer awareness as protection against exploitation in the marketplace","difficulty":2,"stem":"A shopkeeper uses a faulty scale that shows 1 kg when the actual weight is 900 g. If he charges the marked rate of ₹90 per kg, what is the effective price per actual kg paid by the consumer?","options":["₹90","₹81","₹100","₹99"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Ignores the short weight and assumes the consumer actually receives 1 kg."},{"option_index":1,"misconception":"Calculates the honest price for 900 g (90% of ₹90) instead of the price actually paid per kg."},{"option_index":3,"misconception":"Adds 10% to ₹90 to compensate for 10% short weight instead of dividing by 0.9 kg."}],"explanation":"For ₹90 the consumer gets 0.9 kg, so effective price = 90/0.9 = ₹100 per kg.","concept_id":"eco610-con-consumer-awareness","strand":"Consumer Rights","kind":"mcq"},{"id":"consumer-awareness-as-protection-against-exploitation-in-the-marketplace-007","band":"K5","grade":10,"subject":"Mathematics","concept":"consumer awareness as protection against exploitation in the marketplace","difficulty":2,"stem":"A consumer buys 3 notebooks at ₹45 each and 2 pens at ₹12 each. The bill total is ₹195. By how much is the bill overcharged?","options":["₹24","₹135","₹60","₹36"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Uses only the cost of the pens and ignores the notebooks."},{"option_index":1,"misconception":"Uses only the cost of the notebooks and ignores the pens."},{"option_index":2,"misconception":"Subtracts only the notebook cost ₹135 from the bill total ₹195, forgetting the pens."}],"explanation":"Actual cost = 3×45 + 2×12 = 135 + 24 = ₹159; overcharge = 195 − 159 = ₹36.","concept_id":"eco610-con-consumer-awareness","strand":"Consumer Rights","kind":"mcq"},{"id":"consumer-awareness-as-protection-against-exploitation-in-the-marketplace-008","band":"K5","grade":10,"subject":"Mathematics","concept":"consumer awareness as protection against exploitation in the marketplace","difficulty":2,"stem":"A shop advertises 'Buy 2, get 1 free' on items of equal price. What is the effective discount percentage for a consumer who buys 3 items?","options":["33.33%","50%","25%","20%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Thinks one free item out of two paid items gives a 1/2 discount."},{"option_index":2,"misconception":"Counts 4 items in the deal (2 paid + 1 free + 1 mistaken extra) and uses 1/4."},{"option_index":3,"misconception":"Treats 'Buy 2, get 1 free' as a 20% discount instead of 1 free out of 3 items."}],"explanation":"Consumer pays for 2 of 3 items, so discount = 1/3 × 100 = 33.33%.","concept_id":"eco610-con-consumer-awareness","strand":"Consumer Rights","kind":"mcq"},{"id":"consumer-awareness-as-protection-against-exploitation-in-the-marketplace-009","band":"K5","grade":10,"subject":"Mathematics","concept":"consumer awareness as protection against exploitation in the marketplace","difficulty":2,"stem":"A store offers two successive discounts of 20% and 10% on an item marked ₹2,000. What is the final selling price?","options":["₹1,400","₹1,440","₹1,600","₹1,500"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Adds the two discounts to 30% and applies 30% off the marked price."},{"option_index":2,"misconception":"Applies only the first 20% discount and ignores the second discount."},{"option_index":3,"misconception":"Applies an average 25% discount instead of successive discounts."}],"explanation":"After 20%: 2000×0.8 = ₹1,600; after 10%: 1600×0.9 = ₹1,440.","concept_id":"eco610-con-consumer-awareness","strand":"Consumer Rights","kind":"mcq"},{"id":"consumer-awareness-as-protection-against-exploitation-in-the-marketplace-010","band":"K5","grade":10,"subject":"Mathematics","concept":"consumer awareness as protection against exploitation in the marketplace","difficulty":2,"stem":"A milkman adds water so that the mixture contains 20% water. He sells the mixture at the price of pure milk. What is his profit percentage?","options":["20%","16.67%","25%","80%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Assumes the profit percentage equals the water percentage in the mixture."},{"option_index":1,"misconception":"Calculates 20/120 × 100, using total mixture in the denominator instead of milk quantity."},{"option_index":3,"misconception":"Uses the milk percentage (80%) as the profit percentage."}],"explanation":"In 100 L mixture, milk = 80 L and water = 20 L; profit = 20/80 × 100 = 25%.","concept_id":"eco610-con-consumer-awareness","strand":"Consumer Rights","kind":"mcq"},{"id":"copra-consumer-protection-act-and-its-objective-of-safeguarding-consumers-001","band":"K5","grade":10,"subject":"Mathematics","concept":"COPRA (Consumer Protection Act) and its objective of safeguarding consumers","difficulty":2,"stem":"Under COPRA a consumer can file a complaint about a defective product within 2 years of the cause of action. How many months is this time limit?","options":["12 months","20 months","24 months","36 months"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reads '2 years' as 2 x 6 = 12 months, halving the year instead of multiplying by 12."},{"option_index":1,"misconception":"Assumes a year has 10 months, so 2 years = 20 months."},{"option_index":3,"misconception":"Confuses the 2-year limitation period with a 3-year period."}],"explanation":"1 year = 12 months, so 2 years = 2 x 12 = 24 months.","concept_id":"eco610-con-copra","strand":"Consumer Rights","kind":"mcq"},{"id":"copra-consumer-protection-act-and-its-objective-of-safeguarding-consumers-002","band":"K5","grade":10,"subject":"Mathematics","concept":"COPRA (Consumer Protection Act) and its objective of safeguarding consumers","difficulty":2,"stem":"Since 1 crore = 100 lakh, how many lakh rupees are equal to 10 crore rupees?","options":["100 lakh","1000 lakh","10 lakh","10000 lakh"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Treats 10 crore as 1 crore and gives 100 lakh."},{"option_index":2,"misconception":"Loses the 'crore to lakh' conversion and gives 10 lakh for 10 crore."},{"option_index":3,"misconception":"Adds one extra zero while converting, giving 10000 lakh."}],"explanation":"1 crore = 100 lakh, so 10 crore = 10 x 100 = 1000 lakh.","concept_id":"eco610-con-copra","strand":"Consumer Rights","kind":"mcq"},{"id":"copra-consumer-protection-act-and-its-objective-of-safeguarding-consumers-003","band":"K5","grade":10,"subject":"Mathematics","concept":"COPRA (Consumer Protection Act) and its objective of safeguarding consumers","difficulty":2,"stem":"A District Commission is expected to decide a consumer complaint within 3 months, and within 5 months if the goods must be tested or analysed. How many extra months are allowed when testing is needed?","options":["15 months","8 months","1.5 months","2 months"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Multiplies the two time limits (3 x 5 = 15) instead of subtracting."},{"option_index":1,"misconception":"Adds the two time limits (3 + 5 = 8) instead of finding the difference."},{"option_index":2,"misconception":"Halves the base limit of 3 months instead of comparing 5 months with 3 months."}],"explanation":"Extra time = 5 months - 3 months = 2 months.","concept_id":"eco610-con-copra","strand":"Consumer Rights","kind":"mcq"},{"id":"copra-consumer-protection-act-and-its-objective-of-safeguarding-consumers-004","band":"K5","grade":10,"subject":"Mathematics","concept":"COPRA (Consumer Protection Act) and its objective of safeguarding consumers","difficulty":2,"stem":"A consumer paid 1250 rupees for a defective mixer and the shopkeeper agreed to refund 4/5 of the price. How much refund must the consumer get?","options":["1250 rupees","250 rupees","312.50 rupees","1000 rupees"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Refunds the whole price and ignores the fraction 4/5."},{"option_index":1,"misconception":"Takes the remaining 1/5 (1250/5 = 250) instead of the 4/5 share."},{"option_index":2,"misconception":"Divides by 4 (1250/4) instead of multiplying by 4/5."}],"explanation":"4/5 of 1250 = 1250 / 5 x 4 = 250 x 4 = 1000 rupees.","concept_id":"eco610-con-copra","strand":"Consumer Rights","kind":"mcq"},{"id":"copra-consumer-protection-act-and-its-objective-of-safeguarding-consumers-005","band":"K5","grade":10,"subject":"Mathematics","concept":"COPRA (Consumer Protection Act) and its objective of safeguarding consumers","difficulty":2,"stem":"A District Commission ordered a shopkeeper to give a consumer a replacement phone worth 18000 rupees and also to pay 2000 rupees as compensation. What is the total value of the relief granted?","options":["16000 rupees","20000 rupees","18002 rupees","36000 rupees"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Subtracts the compensation from the phone value (18000 - 2000) instead of adding."},{"option_index":2,"misconception":"Writes the two amounts side by side (18000 and 2) instead of adding them."},{"option_index":3,"misconception":"Doubles the phone value (18000 x 2) instead of adding the 2000 compensation."}],"explanation":"Total relief = 18000 + 2000 = 20000 rupees.","concept_id":"eco610-con-copra","strand":"Consumer Rights","kind":"mcq"},{"id":"copra-consumer-protection-act-and-its-objective-of-safeguarding-consumers-006","band":"K5","grade":10,"subject":"Mathematics","concept":"COPRA (Consumer Protection Act) and its objective of safeguarding consumers","difficulty":2,"stem":"A survey of 250 families found that 3/5 of them knew about COPRA and its protection of consumers. How many families knew about COPRA?","options":["125","100","150","83"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Takes half of 250 instead of 3/5 of 250."},{"option_index":1,"misconception":"Finds the 2/5 who did not know (100) instead of the 3/5 who knew."},{"option_index":3,"misconception":"Divides 250 by 3 instead of multiplying by 3/5."}],"explanation":"3/5 of 250 = 250 / 5 x 3 = 50 x 3 = 150 families.","concept_id":"eco610-con-copra","strand":"Consumer Rights","kind":"mcq"},{"id":"copra-consumer-protection-act-and-its-objective-of-safeguarding-consumers-007","band":"K5","grade":10,"subject":"Mathematics","concept":"COPRA (Consumer Protection Act) and its objective of safeguarding consumers","difficulty":2,"stem":"A consumer forum received 40 complaints and settled 30 of them through the redressal process. What percentage of the complaints was settled?","options":["30%","60%","133%","75%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Reads the number 30 directly as 30 per cent without dividing by the total."},{"option_index":1,"misconception":"Compares 30 with 50 instead of with the total 40."},{"option_index":2,"misconception":"Inverts the fraction (40/30) instead of using settled/total = 30/40."}],"explanation":"Percentage settled = 30/40 x 100 = 75%.","concept_id":"eco610-con-copra","strand":"Consumer Rights","kind":"mcq"},{"id":"copra-consumer-protection-act-and-its-objective-of-safeguarding-consumers-008","band":"K5","grade":10,"subject":"Mathematics","concept":"COPRA (Consumer Protection Act) and its objective of safeguarding consumers","difficulty":3,"stem":"A shopkeeper charged a consumer for 12 kg of rice at 45 rupees per kg but actually gave only 10 kg. How much money should be refunded for the short weight?","options":["450 rupees","90 rupees","540 rupees","900 rupees"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses the delivered quantity (10 kg x 45) instead of the shortage of 2 kg."},{"option_index":2,"misconception":"Refunds the full amount paid for 12 kg (12 x 45) as if nothing was delivered."},{"option_index":3,"misconception":"Doubles the full amount paid instead of charging only the short weight."}],"explanation":"Short weight = 12 - 10 = 2 kg, so refund = 2 x 45 = 90 rupees.","concept_id":"eco610-con-copra","strand":"Consumer Rights","kind":"mcq"},{"id":"copra-consumer-protection-act-and-its-objective-of-safeguarding-consumers-009","band":"K5","grade":10,"subject":"Mathematics","concept":"COPRA (Consumer Protection Act) and its objective of safeguarding consumers","difficulty":2,"stem":"The Consumer Protection Act of 1986 was replaced by the stronger Consumer Protection Act of 2019. How many years later was the new Act passed?","options":["33 years","23 years","43 years","13 years"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Makes a subtraction slip such as 2019 - 1996 = 23 years."},{"option_index":2,"misconception":"Adds the last two digits (19 + 86 style reasoning) instead of subtracting the years."},{"option_index":3,"misconception":"Subtracts only the last digits (19 - 86 gives 13 by ignoring place value)."}],"explanation":"2019 - 1986 = 33 years.","concept_id":"eco610-con-copra","strand":"Consumer Rights","kind":"mcq"},{"id":"copra-consumer-protection-act-and-its-objective-of-safeguarding-consumers-010","band":"K5","grade":10,"subject":"Mathematics","concept":"COPRA (Consumer Protection Act) and its objective of safeguarding consumers","difficulty":3,"stem":"A State Commission received 240 consumer complaints in a year and disposed of 5/6 of them. How many complaints were disposed of?","options":["180","40","200","240"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses 3/4 of 240 instead of the given fraction 5/6."},{"option_index":1,"misconception":"Finds the undisposed 1/6 (240/6 = 40) instead of the disposed 5/6."},{"option_index":3,"misconception":"Assumes all complaints were disposed and answers with the total 240."}],"explanation":"5/6 of 240 = 240 / 6 x 5 = 40 x 5 = 200 complaints.","concept_id":"eco610-con-copra","strand":"Consumer Rights","kind":"mcq"},{"id":"how-consumers-can-be-exploited-in-the-marketplace-adulteration-under-weighing-overpricing-001","band":"K5","grade":10,"subject":"Mathematics","concept":"how consumers can be exploited in the marketplace (adulteration, under-weighing, overpricing)","difficulty":2,"stem":"A shopkeeper mixes 2 litres of water in 8 litres of pure milk. What is the percentage of water in the mixture?","options":["25%","10%","20%","80%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses water-to-milk ratio (2/8) instead of water-to-total-mixture ratio."},{"option_index":1,"misconception":"Divides water by double the total (2/20) instead of total mixture."},{"option_index":3,"misconception":"Gives the percentage of pure milk, not water."}],"explanation":"Total mixture = 2 + 8 = 10 L, so water percentage = (2/10)×100 = 20%.","concept_id":"eco610-con-marketplace-exploitation","strand":"Consumer Rights","kind":"mcq"},{"id":"how-consumers-can-be-exploited-in-the-marketplace-adulteration-under-weighing-overpricing-002","band":"K5","grade":10,"subject":"Mathematics","concept":"how consumers can be exploited in the marketplace (adulteration, under-weighing, overpricing)","difficulty":2,"stem":"A 1 kg packet of rice actually weighs 750 g. What is the percentage under-weighing?","options":["25%","33⅓%","75%","133⅓%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses shortage divided by actual weight (250/750) instead of claimed weight."},{"option_index":2,"misconception":"Gives actual weight as a percentage of claimed weight."},{"option_index":3,"misconception":"Uses claimed weight divided by actual weight (1000/750)."}],"explanation":"Shortage = 1000 − 750 = 250 g, so under-weighing = (250/1000)×100 = 25%.","concept_id":"eco610-con-marketplace-exploitation","strand":"Consumer Rights","kind":"mcq"},{"id":"how-consumers-can-be-exploited-in-the-marketplace-adulteration-under-weighing-overpricing-003","band":"K5","grade":10,"subject":"Mathematics","concept":"how consumers can be exploited in the marketplace (adulteration, under-weighing, overpricing)","difficulty":2,"stem":"A milkman adds 3 litres of water to 12 litres of milk. What is the ratio of water to milk in simplest form?","options":["1:5","1:4","1:3","4:1"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses water-to-total mixture ratio (3:15 = 1:5)."},{"option_index":2,"misconception":"Simplifies 3:12 incorrectly to 1:3."},{"option_index":3,"misconception":"Reverses the ratio to milk:water."}],"explanation":"Water : milk = 3:12 = 1:4.","concept_id":"eco610-con-marketplace-exploitation","strand":"Consumer Rights","kind":"mcq"},{"id":"how-consumers-can-be-exploited-in-the-marketplace-adulteration-under-weighing-overpricing-004","band":"K5","grade":10,"subject":"Mathematics","concept":"how consumers can be exploited in the marketplace (adulteration, under-weighing, overpricing)","difficulty":1,"stem":"An article bought for ₹100 is sold for ₹120. What is the profit percentage?","options":["16⅔%","120%","20%","25%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses profit divided by selling price (20/120) instead of cost price."},{"option_index":1,"misconception":"Gives selling price as a percentage of cost price, not profit percentage."},{"option_index":3,"misconception":"Uses profit divided by cost-minus-profit (20/80) instead of cost price."}],"explanation":"Profit = 120 − 100 = ₹20, so profit% = (20/100)×100 = 20%.","concept_id":"eco610-con-marketplace-exploitation","strand":"Consumer Rights","kind":"mcq"},{"id":"how-consumers-can-be-exploited-in-the-marketplace-adulteration-under-weighing-overpricing-005","band":"K5","grade":10,"subject":"Mathematics","concept":"how consumers can be exploited in the marketplace (adulteration, under-weighing, overpricing)","difficulty":1,"stem":"A trader uses a weight of 800 g instead of 1 kg while selling sugar. What is the percentage of under-weighing?","options":["20%","25%","80%","125%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses shortage divided by actual weight (200/800) instead of claimed weight."},{"option_index":2,"misconception":"Gives actual weight as a percentage of claimed weight."},{"option_index":3,"misconception":"Uses claimed weight divided by actual weight (1000/800)."}],"explanation":"Shortage = 1000 − 800 = 200 g, so under-weighing = (200/1000)×100 = 20%.","concept_id":"eco610-con-marketplace-exploitation","strand":"Consumer Rights","kind":"mcq"},{"id":"how-consumers-can-be-exploited-in-the-marketplace-adulteration-under-weighing-overpricing-006","band":"K5","grade":10,"subject":"Mathematics","concept":"how consumers can be exploited in the marketplace (adulteration, under-weighing, overpricing)","difficulty":1,"stem":"A 1 L bottle contains 200 mL of water and the rest pure oil. What percentage of the bottle is pure oil?","options":["20%","25%","80%","125%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Gives the water percentage instead of the oil percentage."},{"option_index":1,"misconception":"Uses water-to-oil ratio (200/800) instead of oil-to-total ratio."},{"option_index":3,"misconception":"Uses the inverse of the oil fraction (1000/800)."}],"explanation":"Pure oil = 1000 − 200 = 800 mL, so oil percentage = (800/1000)×100 = 80%.","concept_id":"eco610-con-marketplace-exploitation","strand":"Consumer Rights","kind":"mcq"},{"id":"how-consumers-can-be-exploited-in-the-marketplace-adulteration-under-weighing-overpricing-007","band":"K5","grade":10,"subject":"Mathematics","concept":"how consumers can be exploited in the marketplace (adulteration, under-weighing, overpricing)","difficulty":2,"stem":"An article bought for ₹80 is sold for ₹100. What is the profit percentage?","options":["20%","80%","125%","25%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Uses profit divided by selling price (20/100)."},{"option_index":1,"misconception":"Gives cost price as a percentage of selling price."},{"option_index":2,"misconception":"Gives selling price as a percentage of cost price."}],"explanation":"Profit = 100 − 80 = ₹20, so profit% = (20/80)×100 = 25%.","concept_id":"eco610-con-marketplace-exploitation","strand":"Consumer Rights","kind":"mcq"},{"id":"how-consumers-can-be-exploited-in-the-marketplace-adulteration-under-weighing-overpricing-008","band":"K5","grade":10,"subject":"Mathematics","concept":"how consumers can be exploited in the marketplace (adulteration, under-weighing, overpricing)","difficulty":2,"stem":"A trader uses 900 g instead of 1 kg. What percentage of the correct weight does the customer actually receive?","options":["10%","90%","100%","110%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Gives the shortage percentage instead of the received percentage."},{"option_index":2,"misconception":"Assumes the correct weight is given, ignoring under-weighing."},{"option_index":3,"misconception":"Adds the shortage percentage instead of subtracting it."}],"explanation":"Received percentage = (900/1000)×100 = 90% of the correct weight.","concept_id":"eco610-con-marketplace-exploitation","strand":"Consumer Rights","kind":"mcq"},{"id":"how-consumers-can-be-exploited-in-the-marketplace-adulteration-under-weighing-overpricing-009","band":"K5","grade":10,"subject":"Mathematics","concept":"how consumers can be exploited in the marketplace (adulteration, under-weighing, overpricing)","difficulty":1,"stem":"A shopkeeper mixes 1 part water with 4 parts milk. What fraction of the mixture is water?","options":["1/5","1/4","4/5","5/4"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses water-to-milk ratio instead of water-to-total-mixture ratio."},{"option_index":2,"misconception":"Gives the milk fraction instead of the water fraction."},{"option_index":3,"misconception":"Uses the inverse of the water fraction."}],"explanation":"Total parts = 1 + 4 = 5, so water fraction = 1/5.","concept_id":"eco610-con-marketplace-exploitation","strand":"Consumer Rights","kind":"mcq"},{"id":"how-consumers-can-be-exploited-in-the-marketplace-adulteration-under-weighing-overpricing-010","band":"K5","grade":10,"subject":"Mathematics","concept":"how consumers can be exploited in the marketplace (adulteration, under-weighing, overpricing)","difficulty":3,"stem":"A trader sells rice at ₹40 per kg but uses an 800 g weight in place of 1 kg. What is the actual amount charged per kg?","options":["₹40","₹32","₹50","₹48"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Ignores under-weighing and uses the quoted rate directly."},{"option_index":1,"misconception":"Multiplies the rate by 0.8 instead of dividing by 0.8."},{"option_index":3,"misconception":"Adds 20% of ₹40 instead of dividing ₹40 by 0.8."}],"explanation":"Customer pays ₹40 for 800 g, so per kg rate = 40 ÷ 0.8 = ₹50.","concept_id":"eco610-con-marketplace-exploitation","strand":"Consumer Rights","kind":"mcq"},{"id":"origins-and-growth-of-the-consumer-movement-in-india-001","band":"K5","grade":10,"subject":"Mathematics","concept":"origins and growth of the consumer movement in India","difficulty":2,"stem":"The first nationwide Consumer Protection Act in India was passed in 1986 and was replaced by a new Consumer Protection Act in 2019. How many years after the 1986 Act was the 2019 Act passed?","options":["32","33","23","34"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Off-by-one fence-post error: counts the span from 1987 to 2019 instead of 1986 to 2019."},{"option_index":2,"misconception":"Digit transposition: writes the difference 33 incorrectly as 23."},{"option_index":3,"misconception":"Inclusive counting: adds 1 year because both 1986 and 2019 are counted as full years."}],"explanation":"2019 - 1986 = 33 years.","concept_id":"eco610-con-movement-origins","strand":"Consumer Rights","kind":"mcq"},{"id":"origins-and-growth-of-the-consumer-movement-in-india-002","band":"K5","grade":10,"subject":"Mathematics","concept":"origins and growth of the consumer movement in India","difficulty":1,"stem":"National Consumer Day is observed in India on 24 December, marking the day the Consumer Protection Act was enacted. How many days after 1 December of the same month does National Consumer Day fall?","options":["24","22","23","25"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Counts 1 December itself as day 1, giving an off-by-one answer."},{"option_index":1,"misconception":"Off-by-one in the other direction: subtracts one day twice from the date number."},{"option_index":3,"misconception":"Adds an extra day by treating both 1 December and 24 December as extra days of the interval."}],"explanation":"24 - 1 = 23 days after 1 December.","concept_id":"eco610-con-movement-origins","strand":"Consumer Rights","kind":"mcq"},{"id":"origins-and-growth-of-the-consumer-movement-in-india-003","band":"K5","grade":10,"subject":"Mathematics","concept":"origins and growth of the consumer movement in India","difficulty":2,"stem":"In a survey of 500 households in a city, 375 households said they had heard of consumer courts. What percentage of the households had heard of consumer courts?","options":["37.5%","80%","75%","25%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Treats 'per cent' as 'per thousand' and divides 375 by 1000 instead of by 500."},{"option_index":1,"misconception":"Rounds 375 up to 400 before dividing, giving an inflated percentage."},{"option_index":3,"misconception":"Computes the complement: gives the percentage that had NOT heard of consumer courts (125/500)."}],"explanation":"375/500 × 100% = 75%.","concept_id":"eco610-con-movement-origins","strand":"Consumer Rights","kind":"mcq"},{"id":"origins-and-growth-of-the-consumer-movement-in-india-004","band":"K5","grade":10,"subject":"Mathematics","concept":"origins and growth of the consumer movement in India","difficulty":2,"stem":"In 1970 about 60 consumer organisations were registered in India; by 2019 about 600 were registered. By what factor did the number of registered consumer organisations grow?","options":["540","100","9","10"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Gives the difference 600 - 60 = 540 instead of the multiplicative factor."},{"option_index":1,"misconception":"Decimal-place slip: divides 6000 by 60 instead of 600 by 60."},{"option_index":2,"misconception":"Subtracts 1 from the factor, thinking 'growth factor' excludes the original 60."}],"explanation":"600 ÷ 60 = 10, so the number grew 10 times.","concept_id":"eco610-con-movement-origins","strand":"Consumer Rights","kind":"mcq"},{"id":"origins-and-growth-of-the-consumer-movement-in-india-005","band":"K5","grade":10,"subject":"Mathematics","concept":"origins and growth of the consumer movement in India","difficulty":2,"stem":"A state consumer helpline recorded the number of complaints in four consecutive years as 120, 180, 200 and 300. What is the mean number of complaints per year?","options":["800","190","180","200"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Reports the total of the four years, forgetting to divide by 4."},{"option_index":1,"misconception":"Computes the median (average of the middle two values 180 and 200) instead of the mean."},{"option_index":2,"misconception":"Gives the range (300 - 120) instead of the mean."}],"explanation":"(120 + 180 + 200 + 300) ÷ 4 = 800 ÷ 4 = 200.","concept_id":"eco610-con-movement-origins","strand":"Consumer Rights","kind":"mcq"},{"id":"origins-and-growth-of-the-consumer-movement-in-india-006","band":"K5","grade":10,"subject":"Mathematics","concept":"origins and growth of the consumer movement in India","difficulty":2,"stem":"Under the Consumer Protection Act, 2019, a District Commission hears complaints up to ₹1 crore and a State Commission hears complaints above ₹1 crore up to ₹10 crore. What is the width, in rupees, of the range of claim values that a State Commission hears?","options":["₹11 crore","₹9 crore","₹10 crore","₹8 crore"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Adds the two given limits (1 crore + 10 crore) instead of subtracting them."},{"option_index":2,"misconception":"Reports the upper limit of the range rather than the width of the range."},{"option_index":3,"misconception":"Off-by-two in the crore values: subtracts 2 crore from 10 crore by miscounting the crore units."}],"explanation":"10 crore - 1 crore = ₹9 crore.","concept_id":"eco610-con-movement-origins","strand":"Consumer Rights","kind":"mcq"},{"id":"origins-and-growth-of-the-consumer-movement-in-india-007","band":"K5","grade":10,"subject":"Mathematics","concept":"origins and growth of the consumer movement in India","difficulty":2,"stem":"A consumer awareness survey found that 3 out of every 8 complaints received in a district were about defective goods. If 2400 complaints were received in all, how many were about defective goods?","options":["1500","800","900","300"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Finds the remaining part, 5/8 of 2400, i.e. complaints NOT about defective goods."},{"option_index":1,"misconception":"Uses the reciprocal 1/3 of 2400 instead of 3/8 of 2400."},{"option_index":3,"misconception":"Divides 2400 by 8 but forgets to multiply by 3."}],"explanation":"3/8 × 2400 = 900 complaints.","concept_id":"eco610-con-movement-origins","strand":"Consumer Rights","kind":"mcq"},{"id":"origins-and-growth-of-the-consumer-movement-in-india-008","band":"K5","grade":10,"subject":"Mathematics","concept":"origins and growth of the consumer movement in India","difficulty":1,"stem":"In a consumer awareness camp, 60% of the 250 participants were women. How many of the participants were men?","options":["150","60","40","100"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Answers with the number of women (60% of 250) instead of the number of men."},{"option_index":1,"misconception":"Reads 60% as the plain number 60, ignoring 'per cent of 250'."},{"option_index":2,"misconception":"Reads the men's share 40% as the plain number 40 instead of working out 40% of 250."}],"explanation":"Men are 40% of 250 = 40/100 × 250 = 100.","concept_id":"eco610-con-movement-origins","strand":"Consumer Rights","kind":"mcq"},{"id":"origins-and-growth-of-the-consumer-movement-in-india-009","band":"K5","grade":10,"subject":"Mathematics","concept":"origins and growth of the consumer movement in India","difficulty":3,"stem":"A consumer complaint was filed on 5 January and finally settled on 5 April of the same non-leap year. How many days did the settlement take?","options":["90","91","88","89"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Counts both the filing day and the settlement day, adding one extra day."},{"option_index":2,"misconception":"Treats January and March as 30-day months instead of 31-day months."},{"option_index":3,"misconception":"Off-by-one: stops counting on 4 April instead of completing the interval to 5 April."}],"explanation":"26 days left in January + 28 in February + 31 in March + 5 in April = 90 days.","concept_id":"eco610-con-movement-origins","strand":"Consumer Rights","kind":"mcq"},{"id":"origins-and-growth-of-the-consumer-movement-in-india-010","band":"K5","grade":10,"subject":"Mathematics","concept":"origins and growth of the consumer movement in India","difficulty":2,"stem":"The number of registered consumer organisations in a state rose from 200 in 2010 to 250 in 2020. By what percentage did the number increase?","options":["20%","125%","25%","50%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Divides the increase (50) by the new value (250) instead of by the original value (200)."},{"option_index":1,"misconception":"Reports the ratio 250/200 as a percentage instead of the percentage increase."},{"option_index":3,"misconception":"Reports the absolute increase of 50 directly as 50%."}],"explanation":"Increase = 50; 50/200 × 100% = 25%.","concept_id":"eco610-con-movement-origins","strand":"Consumer Rights","kind":"mcq"},{"id":"three-tier-consumer-redressal-district-state-and-national-forums-001","band":"K5","grade":10,"subject":"Mathematics","concept":"three-tier consumer redressal: district, state and national forums","difficulty":2,"stem":"Under the Consumer Protection Act, 2019, the District Commission can hear claims where the value paid does not exceed ₹1,00,00,000. The State Commission can hear claims up to ₹10,00,00,000. How many times is the State Commission's upper limit compared with the District Commission's upper limit?","options":["5 times","9 times","10 times","100 times"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses the old COPRA ratio of ₹20 lakh to ₹1 crore, giving 5 times."},{"option_index":1,"misconception":"Subtracts the limits (₹10 crore − ₹1 crore = ₹9 crore) and mistakes the difference for a ratio."},{"option_index":3,"misconception":"Misplaces zeros and reads ₹10 crore as 100 times ₹1 crore."}],"explanation":"₹10,00,00,000 ÷ ₹1,00,00,000 = 10 times.","concept_id":"eco610-con-redressal-forums","strand":"Consumer Rights","kind":"mcq"},{"id":"three-tier-consumer-redressal-district-state-and-national-forums-002","band":"K5","grade":10,"subject":"Mathematics","concept":"three-tier consumer redressal: district, state and national forums","difficulty":2,"stem":"The State Commission's pecuniary jurisdiction is more than ₹1,00,00,000 and up to ₹10,00,00,000. What is the difference between its upper and lower limits?","options":["₹11,00,00,000","₹10,00,00,000","₹1,00,00,000","₹9,00,00,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Adds the limits instead of subtracting (₹10 crore + ₹1 crore = ₹11 crore)."},{"option_index":1,"misconception":"Gives only the upper limit, forgetting to subtract the lower limit."},{"option_index":2,"misconception":"Gives only the lower limit, confusing it with the difference."}],"explanation":"₹10,00,00,000 − ₹1,00,00,000 = ₹9,00,00,000.","concept_id":"eco610-con-redressal-forums","strand":"Consumer Rights","kind":"mcq"},{"id":"three-tier-consumer-redressal-district-state-and-national-forums-003","band":"K5","grade":10,"subject":"Mathematics","concept":"three-tier consumer redressal: district, state and national forums","difficulty":2,"stem":"A consumer complaint is for ₹1,20,00,000. Under the Consumer Protection Act, 2019, which commission has the jurisdiction to hear it?","options":["State Commission","District Commission","National Commission","Lok Adalat"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Thinks ₹1.2 crore is below ₹1 crore and so falls under the District Commission."},{"option_index":2,"misconception":"Thinks every claim above ₹1 crore goes directly to the National Commission."},{"option_index":3,"misconception":"Confuses the Lok Adalat, a settlement forum, with the regular three-tier commission."}],"explanation":"₹1.2 crore is more than ₹1 crore but not more than ₹10 crore, so the State Commission has jurisdiction.","concept_id":"eco610-con-redressal-forums","strand":"Consumer Rights","kind":"mcq"},{"id":"three-tier-consumer-redressal-district-state-and-national-forums-004","band":"K5","grade":10,"subject":"Mathematics","concept":"three-tier consumer redressal: district, state and national forums","difficulty":2,"stem":"A consumer complaint is for ₹15,00,00,000. Under the Consumer Protection Act, 2019, which commission has the jurisdiction to hear it?","options":["District Commission","National Commission","State Commission","Supreme Court"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Thinks every consumer complaint must first be filed in the District Commission regardless of amount."},{"option_index":2,"misconception":"Thinks the State Commission handles all claims above ₹1 crore, including ₹15 crore."},{"option_index":3,"misconception":"Thinks the Supreme Court directly hears large consumer complaints instead of the National Commission."}],"explanation":"₹15 crore exceeds ₹10 crore, so the National Commission has jurisdiction.","concept_id":"eco610-con-redressal-forums","strand":"Consumer Rights","kind":"mcq"},{"id":"three-tier-consumer-redressal-district-state-and-national-forums-005","band":"K5","grade":10,"subject":"Mathematics","concept":"three-tier consumer redressal: district, state and national forums","difficulty":2,"stem":"A consumer complaint is for ₹75,00,000. Under the Consumer Protection Act, 2019, which commission has the jurisdiction to hear it?","options":["State Commission","National Commission","District Commission","Supreme Court"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Thinks any amount in lakhs goes to the State Commission."},{"option_index":1,"misconception":"Thinks any amount above ₹50 lakh goes to the National Commission."},{"option_index":3,"misconception":"Confuses a consumer commission with the Supreme Court as the redressal forum."}],"explanation":"₹75 lakh does not exceed ₹1 crore, so the District Commission has jurisdiction.","concept_id":"eco610-con-redressal-forums","strand":"Consumer Rights","kind":"mcq"},{"id":"three-tier-consumer-redressal-district-state-and-national-forums-006","band":"K5","grade":10,"subject":"Mathematics","concept":"three-tier consumer redressal: district, state and national forums","difficulty":2,"stem":"A consumer claims exactly ₹1,00,00,000. Under the Consumer Protection Act, 2019, which commission can hear the complaint?","options":["State Commission","National Commission","Supreme Court","District Commission"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Thinks the State Commission starts at exactly ₹1 crore instead of above ₹1 crore."},{"option_index":1,"misconception":"Thinks the National Commission hears exactly ₹1 crore because it is a round figure."},{"option_index":2,"misconception":"Thinks the Supreme Court is the fourth tier for exact boundary amounts."}],"explanation":"The District Commission covers up to and including ₹1 crore; the State Commission handles amounts exceeding ₹1 crore.","concept_id":"eco610-con-redressal-forums","strand":"Consumer Rights","kind":"mcq"},{"id":"three-tier-consumer-redressal-district-state-and-national-forums-007","band":"K5","grade":10,"subject":"Mathematics","concept":"three-tier consumer redressal: district, state and national forums","difficulty":2,"stem":"The District Commission can hear claims up to ₹1,00,00,000. The State Commission can hear claims up to ₹10,00,00,000. What fraction of the State Commission's upper limit is the District Commission's upper limit?","options":["1/5","1/10","9/10","1/100"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses the old COPRA ratio ₹20 lakh to ₹1 crore, giving 1/5."},{"option_index":2,"misconception":"Uses the difference ₹9 crore out of ₹10 crore instead of the ratio of the limits."},{"option_index":3,"misconception":"Misplaces the decimal and compares ₹1 crore to ₹100 crore."}],"explanation":"₹1,00,00,000 / ₹10,00,00,000 = 1/10.","concept_id":"eco610-con-redressal-forums","strand":"Consumer Rights","kind":"mcq"},{"id":"three-tier-consumer-redressal-district-state-and-national-forums-008","band":"K5","grade":10,"subject":"Mathematics","concept":"three-tier consumer redressal: district, state and national forums","difficulty":2,"stem":"In the three-tier consumer redressal system, the National Commission handles claims exceeding ₹10,00,00,000. If a claim is for ₹10,00,00,001, which commission will hear it?","options":["National Commission","State Commission","District Commission","Supreme Court"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Thinks the State Commission covers up to ₹10 crore inclusive, so it can hear ₹10,00,00,001."},{"option_index":2,"misconception":"Thinks the District Commission handles all claims unless transferred."},{"option_index":3,"misconception":"Thinks the Supreme Court directly hears consumer claims above ₹10 crore instead of the National Commission."}],"explanation":"₹10,00,00,001 is more than ₹10 crore, so the National Commission hears it.","concept_id":"eco610-con-redressal-forums","strand":"Consumer Rights","kind":"mcq"},{"id":"three-tier-consumer-redressal-district-state-and-national-forums-009","band":"K5","grade":10,"subject":"Mathematics","concept":"three-tier consumer redressal: district, state and national forums","difficulty":2,"stem":"A consumer helpline received 1,200 complaints. 3/5 of them were filed in District Commissions, 1/4 in State Commissions, and the rest in National Commission. How many complaints were filed in the National Commission?","options":["300","720","120","180"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Gives the State Commission count (1/4 of 1,200 = 300) instead of the National count."},{"option_index":1,"misconception":"Gives the District Commission count (3/5 of 1,200 = 720) instead of the National count."},{"option_index":2,"misconception":"Subtracts 3/5 and 1/4 incorrectly as 1/10 of 1,200, giving 120."}],"explanation":"District = 720, State = 300, so National = 1,200 − 1,020 = 180.","concept_id":"eco610-con-redressal-forums","strand":"Consumer Rights","kind":"mcq"},{"id":"three-tier-consumer-redressal-district-state-and-national-forums-010","band":"K5","grade":10,"subject":"Mathematics","concept":"three-tier consumer redressal: district, state and national forums","difficulty":2,"stem":"The ratio of complaints received by District, State and National Commissions is 7:2:1. If the State Commission received 240 complaints, how many complaints were received in total by all three commissions?","options":["840","960","1200","2400"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses only the District's 7 parts (7 × 120 = 840) instead of the total 10 parts."},{"option_index":1,"misconception":"Adds 7 + 1 = 8 parts and ignores the State's 2 parts, getting 8 × 120 = 960."},{"option_index":3,"misconception":"Doubles the correct total by counting the State's 2 parts twice."}],"explanation":"State = 2 parts = 240, so 1 part = 120. Total = 10 parts = 1,200.","concept_id":"eco610-con-redressal-forums","strand":"Consumer Rights","kind":"mcq"},{"id":"right-to-information-through-standard-marks-like-isi-agmark-and-hallmark-001","band":"K5","grade":10,"subject":"Mathematics","concept":"right to information through standard marks like ISI, Agmark and Hallmark","difficulty":2,"stem":"In a market survey, 60% of 250 packaged food items were found to carry the ISI mark. How many items carried the ISI mark?","options":["15","100","150","190"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Misplaced the decimal when converting the percentage, taking 60% as 0.06 and computing 0.06 × 250"},{"option_index":1,"misconception":"Computed the number of items WITHOUT the mark (40% of 250) and reported it as the ISI-marked count"},{"option_index":3,"misconception":"Subtracted 60 from 250, treating the percentage 60 as a number of items"}],"explanation":"60% of 250 = 0.6 × 250 = 150 items.","concept_id":"eco610-con-right-to-information","strand":"Consumer Rights","kind":"mcq"},{"id":"right-to-information-through-standard-marks-like-isi-agmark-and-hallmark-002","band":"K5","grade":10,"subject":"Mathematics","concept":"right to information through standard marks like ISI, Agmark and Hallmark","difficulty":2,"stem":"A buyer checked 25 gold ornaments and found that 18 of them bore the Hallmark. What percentage of the ornaments bore the Hallmark?","options":["72%","18%","28%","139%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Read the count 18 directly as the percentage instead of forming the fraction 18/25"},{"option_index":2,"misconception":"Found the percentage of ornaments WITHOUT the Hallmark (7 of 25) and reported that"},{"option_index":3,"misconception":"Inverted the fraction and used 25/18 instead of 18/25"}],"explanation":"18/25 × 100 = 72%.","concept_id":"eco610-con-right-to-information","strand":"Consumer Rights","kind":"mcq"},{"id":"right-to-information-through-standard-marks-like-isi-agmark-and-hallmark-003","band":"K5","grade":10,"subject":"Mathematics","concept":"right to information through standard marks like ISI, Agmark and Hallmark","difficulty":2,"stem":"Of the 40 packaged items checked on a shelf, 15 carried the ISI mark. What fraction of the total items carried the ISI mark? Give the answer in lowest terms.","options":["3/5","3/8","5/8","8/3"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Compared ISI-marked items with unmarked items (15 : 25) instead of with the total"},{"option_index":2,"misconception":"Gave the fraction of items WITHOUT the ISI mark (25 out of 40)"},{"option_index":3,"misconception":"Inverted the fraction, writing total over marked items"}],"explanation":"15/40 = 3/8 after dividing numerator and denominator by 5.","concept_id":"eco610-con-right-to-information","strand":"Consumer Rights","kind":"mcq"},{"id":"right-to-information-through-standard-marks-like-isi-agmark-and-hallmark-004","band":"K5","grade":10,"subject":"Mathematics","concept":"right to information through standard marks like ISI, Agmark and Hallmark","difficulty":2,"stem":"A jeweller pays a hallmarking fee of ₹35 for each gold ornament. How much does the jeweller pay in all for getting 24 ornaments hallmarked?","options":["₹805","₹875","₹84","₹840"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Subtracted one fee of ₹35 from the total, as if one ornament were hallmarked free"},{"option_index":1,"misconception":"Counted 25 ornaments instead of 24 and computed 35 × 25"},{"option_index":2,"misconception":"Misplaced the decimal point in the product 35 × 24"}],"explanation":"35 × 24 = ₹840.","concept_id":"eco610-con-right-to-information","strand":"Consumer Rights","kind":"mcq"},{"id":"right-to-information-through-standard-marks-like-isi-agmark-and-hallmark-005","band":"K5","grade":10,"subject":"Mathematics","concept":"right to information through standard marks like ISI, Agmark and Hallmark","difficulty":2,"stem":"In shop A, 24 of the 30 items on a shelf carried the Agmark, while in shop B, 35 of the 50 items carried the Agmark. What percentage of the items in shop A carried the Agmark?","options":["24%","20%","80%","70%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Read the count 24 directly as a percentage instead of converting the fraction"},{"option_index":1,"misconception":"Found the percentage of items in shop A WITHOUT the Agmark (6 out of 30)"},{"option_index":3,"misconception":"Reported the rate of shop B instead of shop A"}],"explanation":"24/30 × 100 = 80%.","concept_id":"eco610-con-right-to-information","strand":"Consumer Rights","kind":"mcq"},{"id":"right-to-information-through-standard-marks-like-isi-agmark-and-hallmark-006","band":"K5","grade":10,"subject":"Mathematics","concept":"right to information through standard marks like ISI, Agmark and Hallmark","difficulty":3,"stem":"The numbers of ISI-marked items in five shops are 12, 18, 15, 10 and 25. What is the mean number of ISI-marked items per shop?","options":["15","16","80","20"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Took the middle value after arranging the data (the median) instead of the mean"},{"option_index":2,"misconception":"Added all five values but forgot to divide by the number of shops"},{"option_index":3,"misconception":"Divided the total 80 by 4 instead of by 5, counting only four shops"}],"explanation":"Sum = 12 + 18 + 15 + 10 + 25 = 80; mean = 80 ÷ 5 = 16.","concept_id":"eco610-con-right-to-information","strand":"Consumer Rights","kind":"mcq"},{"id":"right-to-information-through-standard-marks-like-isi-agmark-and-hallmark-007","band":"K5","grade":10,"subject":"Mathematics","concept":"right to information through standard marks like ISI, Agmark and Hallmark","difficulty":3,"stem":"An Agmark-certified packet of spice contains 400 g and costs ₹120. What is the price of this spice per 100 g?","options":["₹30","₹24","₹12","₹3"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Divided ₹120 by 500 g, taking the weight of the packet as 500 g"},{"option_index":2,"misconception":"Divided ₹120 by 1000 g, assuming the packet weighs 1 kg"},{"option_index":3,"misconception":"Used a unit conversion factor of 10 instead of 100 (gave the price per 10 g as the price per 100 g)"}],"explanation":"₹120 ÷ 400 g = ₹0.30 per g, so 100 g costs ₹30.","concept_id":"eco610-con-right-to-information","strand":"Consumer Rights","kind":"mcq"},{"id":"right-to-information-through-standard-marks-like-isi-agmark-and-hallmark-008","band":"K5","grade":10,"subject":"Mathematics","concept":"right to information through standard marks like ISI, Agmark and Hallmark","difficulty":3,"stem":"In a lot of 500 items, 320 carry the ISI mark, 100 carry the Agmark and the rest carry no mark. What percentage of the items carry no mark?","options":["20%","84%","64%","16%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Reported the Agmark fraction 100/500 instead of the unmarked fraction"},{"option_index":1,"misconception":"Found the percentage of items that DO carry a mark (420/500) and reported that"},{"option_index":2,"misconception":"Reported the ISI fraction 320/500 instead of the unmarked fraction"}],"explanation":"Unmarked items = 500 − 320 − 100 = 80, so 80/500 × 100 = 16%.","concept_id":"eco610-con-right-to-information","strand":"Consumer Rights","kind":"mcq"},{"id":"right-to-information-through-standard-marks-like-isi-agmark-and-hallmark-009","band":"K5","grade":10,"subject":"Mathematics","concept":"right to information through standard marks like ISI, Agmark and Hallmark","difficulty":3,"stem":"In a shop, the numbers of ISI-marked and Agmark-marked items are in the ratio 5 : 3. If 240 items carry one of these two marks, how many items carry the ISI mark?","options":["90","150","144","48"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Took the Agmark share, 3/8 of 240, instead of the ISI share"},{"option_index":2,"misconception":"Used 3/5 of 240, treating a ratio term as a fraction of the other term rather than of the total"},{"option_index":3,"misconception":"Divided 240 by 5 instead of by the sum of the ratio terms, 8"}],"explanation":"Total ratio parts = 5 + 3 = 8, so ISI items = 5/8 × 240 = 150.","concept_id":"eco610-con-right-to-information","strand":"Consumer Rights","kind":"mcq"},{"id":"right-to-information-through-standard-marks-like-isi-agmark-and-hallmark-010","band":"K5","grade":10,"subject":"Mathematics","concept":"right to information through standard marks like ISI, Agmark and Hallmark","difficulty":3,"stem":"A jeweller got 3/5 of the ornaments in a lot hallmarked in January and 1/4 of the remaining ornaments hallmarked in February. What fraction of the lot was hallmarked by the end of February?","options":["1/10","17/20","3/5","7/10"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Gave only the February portion (1/4 of 2/5) instead of the total hallmarked"},{"option_index":1,"misconception":"Added 3/5 and 1/4 directly, ignoring that the February fraction is of the REMAINING ornaments"},{"option_index":2,"misconception":"Counted only the January share, assuming the February ornaments were already included in it"}],"explanation":"Remaining after January = 2/5; February = 1/4 × 2/5 = 1/10; total = 3/5 + 1/10 = 7/10.","concept_id":"eco610-con-right-to-information","strand":"Consumer Rights","kind":"mcq"},{"id":"the-recognised-consumer-rights-safety-information-choice-and-redressal-001","band":"K5","grade":10,"subject":"Mathematics","concept":"the recognised consumer rights: safety, information, choice and redressal","difficulty":2,"stem":"A shopkeeper sells a school bag marked at ₹800 with a 20% discount. What is the selling price?","options":["₹640","₹760","₹960","₹160"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Subtracts only ₹20 from the marked price instead of 20% of it."},{"option_index":2,"misconception":"Adds the discount amount to the marked price."},{"option_index":3,"misconception":"Gives only the discount amount, not the price to be paid."}],"explanation":"20% of ₹800 is ₹160, so selling price = ₹800 − ₹160 = ₹640.","concept_id":"eco610-con-rights-list","strand":"Consumer Rights","kind":"mcq"},{"id":"the-recognised-consumer-rights-safety-information-choice-and-redressal-002","band":"K5","grade":10,"subject":"Mathematics","concept":"the recognised consumer rights: safety, information, choice and redressal","difficulty":2,"stem":"A food packet has net weight 500 g. The empty packet weighs 15 g. What is the gross weight?","options":["485 g","500 g","515 g","15 g"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Subtracts the packet weight from the net weight instead of adding it."},{"option_index":1,"misconception":"Ignores the packaging weight and takes net weight as gross weight."},{"option_index":3,"misconception":"Gives only the empty packet weight."}],"explanation":"Gross weight = net weight + packet weight = 500 g + 15 g = 515 g.","concept_id":"eco610-con-rights-list","strand":"Consumer Rights","kind":"mcq"},{"id":"the-recognised-consumer-rights-safety-information-choice-and-redressal-003","band":"K5","grade":10,"subject":"Mathematics","concept":"the recognised consumer rights: safety, information, choice and redressal","difficulty":2,"stem":"A medicine manufactured in January 2023 has a shelf life of 24 months. What is its expiry month and year?","options":["January 2025","January 2024","December 2024","January 2026"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Reads 24 months as 12 months (1 year)."},{"option_index":2,"misconception":"Stops one month before completing the 24-month shelf life."},{"option_index":3,"misconception":"Adds 3 years instead of 2 years."}],"explanation":"24 months after January 2023 is January 2025.","concept_id":"eco610-con-rights-list","strand":"Consumer Rights","kind":"mcq"},{"id":"the-recognised-consumer-rights-safety-information-choice-and-redressal-004","band":"K5","grade":10,"subject":"Mathematics","concept":"the recognised consumer rights: safety, information, choice and redressal","difficulty":2,"stem":"A consumer can choose from 4 brands of soap, and each brand is available in 3 sizes. How many distinct soap options are there?","options":["7","12","64","4"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Adds the number of brands and sizes instead of multiplying."},{"option_index":2,"misconception":"Cubes the number of brands (4³) instead of multiplying by 3."},{"option_index":3,"misconception":"Counts only the brands and ignores the sizes."}],"explanation":"By the multiplication principle, 4 × 3 = 12 distinct options.","concept_id":"eco610-con-rights-list","strand":"Consumer Rights","kind":"mcq"},{"id":"the-recognised-consumer-rights-safety-information-choice-and-redressal-005","band":"K5","grade":10,"subject":"Mathematics","concept":"the recognised consumer rights: safety, information, choice and redressal","difficulty":2,"stem":"A defective item costs ₹1200. The seller pays 15% compensation. How much compensation is paid?","options":["₹180","₹1020","₹1380","₹200"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Subtracts the compensation from the cost instead of finding the compensation."},{"option_index":2,"misconception":"Adds the compensation to the cost."},{"option_index":3,"misconception":"Treats 15% as 1/6 of ₹1200."}],"explanation":"15% of ₹1200 = 0.15 × 1200 = ₹180.","concept_id":"eco610-con-rights-list","strand":"Consumer Rights","kind":"mcq"},{"id":"the-recognised-consumer-rights-safety-information-choice-and-redressal-006","band":"K5","grade":10,"subject":"Mathematics","concept":"the recognised consumer rights: safety, information, choice and redressal","difficulty":2,"stem":"A product costs ₹500 before GST. If GST is 18%, what is the total price?","options":["₹518","₹482","₹90","₹590"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Adds ₹18 as a flat amount instead of 18% of ₹500."},{"option_index":1,"misconception":"Subtracts GST instead of adding it."},{"option_index":2,"misconception":"Gives only the GST amount, not the total price."}],"explanation":"GST = 18% of ₹500 = ₹90, so total = ₹500 + ₹90 = ₹590.","concept_id":"eco610-con-rights-list","strand":"Consumer Rights","kind":"mcq"},{"id":"the-recognised-consumer-rights-safety-information-choice-and-redressal-007","band":"K5","grade":10,"subject":"Mathematics","concept":"the recognised consumer rights: safety, information, choice and redressal","difficulty":2,"stem":"1 kg rice costs ₹60. A 5 kg pack costs ₹275. How much is saved per kg by buying the 5 kg pack?","options":["₹55","₹215","₹5","₹0"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Gives the per-kg cost of the 5 kg pack, not the saving."},{"option_index":1,"misconception":"Subtracts the 1 kg price from the whole 5 kg pack price."},{"option_index":3,"misconception":"Assumes both pack sizes have the same per-kg price."}],"explanation":"5 kg pack costs ₹275 ÷ 5 = ₹55 per kg; saving = ₹60 − ₹55 = ₹5 per kg.","concept_id":"eco610-con-rights-list","strand":"Consumer Rights","kind":"mcq"},{"id":"the-recognised-consumer-rights-safety-information-choice-and-redressal-008","band":"K5","grade":10,"subject":"Mathematics","concept":"the recognised consumer rights: safety, information, choice and redressal","difficulty":2,"stem":"In a batch of 250 bulbs, 10 are defective. What percentage of the bulbs is defective?","options":["2.5%","10%","0.4%","4%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Computes 10/400 by mistake instead of 10/250."},{"option_index":1,"misconception":"Takes the count of defective bulbs as the percentage."},{"option_index":2,"misconception":"Places the decimal point incorrectly when converting 0.04 to a percentage."}],"explanation":"10/250 = 0.04 = 4%.","concept_id":"eco610-con-rights-list","strand":"Consumer Rights","kind":"mcq"},{"id":"the-recognised-consumer-rights-safety-information-choice-and-redressal-009","band":"K5","grade":10,"subject":"Mathematics","concept":"the recognised consumer rights: safety, information, choice and redressal","difficulty":2,"stem":"A food label says 12% protein. If a pack contains 250 g of food, how much protein is in the pack?","options":["30 g","12 g","3000 g","2.08 g"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses the percentage number as grams and ignores the total mass."},{"option_index":2,"misconception":"Multiplies 250 by 12 instead of taking 12% of 250."},{"option_index":3,"misconception":"Divides 250 by 120 instead of finding 12% of 250."}],"explanation":"12% of 250 g = 0.12 × 250 = 30 g.","concept_id":"eco610-con-rights-list","strand":"Consumer Rights","kind":"mcq"},{"id":"the-recognised-consumer-rights-safety-information-choice-and-redressal-010","band":"K5","grade":10,"subject":"Mathematics","concept":"the recognised consumer rights: safety, information, choice and redressal","difficulty":2,"stem":"A consumer court orders a refund of ₹4500 plus simple interest at 6% per annum for 2 years. What is the interest amount?","options":["₹270","₹540","₹5400","₹5040"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Calculates interest for only 1 year instead of 2 years."},{"option_index":2,"misconception":"Divides by 10 instead of 100 when converting 6% to a decimal."},{"option_index":3,"misconception":"Adds the interest to the refund and gives the total instead of the interest."}],"explanation":"Simple interest = 4500 × 6/100 × 2 = ₹540.","concept_id":"eco610-con-rights-list","strand":"Consumer Rights","kind":"mcq"},{"id":"human-development-index-as-a-composite-measure-combining-income-health-and-education-001","band":"K5","grade":10,"subject":"Mathematics","concept":"Human Development Index as a composite measure combining income, health and education","difficulty":2,"stem":"The education index is the average of the mean years schooling index (mean years / 15) and the expected years schooling index (expected years / 18). If mean years of schooling is 9 and expected years of schooling is 15, what is the education index?","options":["43/60","3/5","5/6","43/30"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses only the mean years schooling index and ignores the expected years schooling index."},{"option_index":2,"misconception":"Uses only the expected years schooling index and ignores the mean years schooling index."},{"option_index":3,"misconception":"Adds the two normalized indices but forgets to divide by 2 to take their average."}],"explanation":"MYSI = 9/15 = 3/5, EYSI = 15/18 = 5/6, so education index = (3/5 + 5/6)/2 = 43/60.","concept_id":"eco610-dev-hdi","strand":"Economic Development","kind":"mcq"},{"id":"human-development-index-as-a-composite-measure-combining-income-health-and-education-002","band":"K5","grade":10,"subject":"Mathematics","concept":"Human Development Index as a composite measure combining income, health and education","difficulty":2,"stem":"Health index = (life expectancy − 20) / (85 − 20). If life expectancy is 65 years, what is the health index?","options":["13/9","9/13","9/17","13/17"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Inverts the health-index fraction, dividing life expectancy by the adjusted value instead of the adjusted value by life expectancy."},{"option_index":2,"misconception":"Subtracts 20 from life expectancy but divides by 85 instead of by 85 − 20 = 65."},{"option_index":3,"misconception":"Divides life expectancy by the maximum 85 and omits the subtraction of the minimum 20 from both numerator and denominator."}],"explanation":"(65 − 20)/(85 − 20) = 45/65 = 9/13.","concept_id":"eco610-dev-hdi","strand":"Economic Development","kind":"mcq"},{"id":"human-development-index-as-a-composite-measure-combining-income-health-and-education-003","band":"K5","grade":10,"subject":"Mathematics","concept":"Human Development Index as a composite measure combining income, health and education","difficulty":2,"stem":"HDI is the geometric mean of the health, education, and income indices: HDI = cube root of (health × education × income). If the indices are 0.9, 0.6, and 0.4, what is the HDI?","options":["19/30","1.9","0.6","0.216"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Takes the arithmetic mean of the three indices instead of the geometric mean."},{"option_index":1,"misconception":"Adds the three indices instead of multiplying them and taking the cube root."},{"option_index":3,"misconception":"Multiplies the three indices but forgets to take the cube root."}],"explanation":"0.9 × 0.6 × 0.4 = 0.216, and cube root of 0.216 = 0.6.","concept_id":"eco610-dev-hdi","strand":"Economic Development","kind":"mcq"},{"id":"human-development-index-as-a-composite-measure-combining-income-health-and-education-004","band":"K5","grade":10,"subject":"Mathematics","concept":"Human Development Index as a composite measure combining income, health and education","difficulty":3,"stem":"For a country, HDI = 0.4, health index = 0.8, and education index = 0.5. Using HDI = cube root of (health × education × income), find the income index.","options":["0.064","0.4","0.8","0.16"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Cubes the HDI but forgets to divide by the product of the other two indices."},{"option_index":1,"misconception":"Confuses the product of health and education indices with the income index."},{"option_index":2,"misconception":"Assumes the missing income index equals the given health index."}],"explanation":"HDI³ = 0.4³ = 0.064; income = 0.064 / (0.8 × 0.5) = 0.064 / 0.4 = 0.16.","concept_id":"eco610-dev-hdi","strand":"Economic Development","kind":"mcq"},{"id":"human-development-index-as-a-composite-measure-combining-income-health-and-education-005","band":"K5","grade":10,"subject":"Mathematics","concept":"Human Development Index as a composite measure combining income, health and education","difficulty":2,"stem":"HDI is the geometric mean of health, education, and income indices: HDI = cube root of (health × education × income). If the indices are 0.1, 0.3, and 0.9, what is the HDI?","options":["0.3","13/30","0.027","1.3"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Takes the arithmetic mean of the three indices instead of the geometric mean."},{"option_index":2,"misconception":"Multiplies the three indices but forgets to take the cube root."},{"option_index":3,"misconception":"Adds the three indices instead of using the geometric mean."}],"explanation":"0.1 × 0.3 × 0.9 = 0.027, and cube root of 0.027 = 0.3.","concept_id":"eco610-dev-hdi","strand":"Economic Development","kind":"mcq"},{"id":"human-development-index-as-a-composite-measure-combining-income-health-and-education-006","band":"K5","grade":10,"subject":"Mathematics","concept":"Human Development Index as a composite measure combining income, health and education","difficulty":2,"stem":"HDI is the geometric mean of health, education, and income indices: HDI = cube root of (health × education × income). If the indices are 0.2, 0.4, and 0.8, what is the HDI?","options":["7/15","0.4","0.064","1.4"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Takes the arithmetic mean of the three indices instead of the geometric mean."},{"option_index":2,"misconception":"Multiplies the three indices but forgets to take the cube root."},{"option_index":3,"misconception":"Adds the three indices instead of using the geometric mean."}],"explanation":"0.2 × 0.4 × 0.8 = 0.064, and cube root of 0.064 = 0.4.","concept_id":"eco610-dev-hdi","strand":"Economic Development","kind":"mcq"},{"id":"human-development-index-as-a-composite-measure-combining-income-health-and-education-007","band":"K5","grade":10,"subject":"Mathematics","concept":"Human Development Index as a composite measure combining income, health and education","difficulty":2,"stem":"HDI is the geometric mean of health, education, and income indices: HDI = cube root of (health × education × income). If the indices are 1/2, 1/4, and 1/8, what is the HDI?","options":["7/24","7/8","1/4","1/64"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Takes the arithmetic mean of the three indices instead of the geometric mean."},{"option_index":1,"misconception":"Adds the three indices instead of using the geometric mean."},{"option_index":3,"misconception":"Multiplies the three indices but forgets to take the cube root."}],"explanation":"(1/2) × (1/4) × (1/8) = 1/64, and cube root of 1/64 = 1/4.","concept_id":"eco610-dev-hdi","strand":"Economic Development","kind":"mcq"},{"id":"human-development-index-as-a-composite-measure-combining-income-health-and-education-008","band":"K5","grade":10,"subject":"Mathematics","concept":"Human Development Index as a composite measure combining income, health and education","difficulty":3,"stem":"For a country, HDI = 0.5, health index = 0.8, and income index = 0.5. Using HDI = cube root of (health × education × income), find the education index.","options":["0.125","0.4","0.5","5/16"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Cubes the HDI but forgets to divide by the product of the other two indices."},{"option_index":1,"misconception":"Confuses the product of the known health and income indices with the missing education index."},{"option_index":2,"misconception":"Assumes the missing education index equals the HDI or the given income index."}],"explanation":"HDI³ = 0.5³ = 0.125; education = 0.125 / (0.8 × 0.5) = 0.125 / 0.4 = 5/16.","concept_id":"eco610-dev-hdi","strand":"Economic Development","kind":"mcq"},{"id":"human-development-index-as-a-composite-measure-combining-income-health-and-education-009","band":"K5","grade":10,"subject":"Mathematics","concept":"Human Development Index as a composite measure combining income, health and education","difficulty":2,"stem":"HDI is the geometric mean of health, education, and income indices: HDI = cube root of (health × education × income). If the indices are 0.9, 0.3, and 0.8, what is the HDI?","options":["0.6","2/3","0.216","2.0"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Takes the arithmetic mean of the three indices instead of the geometric mean."},{"option_index":2,"misconception":"Multiplies the three indices but forgets to take the cube root."},{"option_index":3,"misconception":"Adds the three indices instead of using the geometric mean."}],"explanation":"0.9 × 0.3 × 0.8 = 0.216, and cube root of 0.216 = 0.6.","concept_id":"eco610-dev-hdi","strand":"Economic Development","kind":"mcq"},{"id":"human-development-index-as-a-composite-measure-combining-income-health-and-education-010","band":"K5","grade":10,"subject":"Mathematics","concept":"Human Development Index as a composite measure combining income, health and education","difficulty":3,"stem":"HDI is the geometric mean of health, education, and income indices: HDI = cube root of (health × education × income). If the indices are 1/2, 1/3, and 2/9, what is the HDI?","options":["19/54","1/3","19/18","1/27"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Takes the arithmetic mean of the three indices instead of the geometric mean."},{"option_index":2,"misconception":"Adds the three indices instead of using the geometric mean."},{"option_index":3,"misconception":"Multiplies the three indices but forgets to take the cube root."}],"explanation":"(1/2) × (1/3) × (2/9) = 1/27, and cube root of 1/27 = 1/3.","concept_id":"eco610-dev-hdi","strand":"Economic Development","kind":"mcq"},{"id":"average-per-capita-income-as-a-common-measure-of-development-001","band":"K5","grade":10,"subject":"Mathematics","concept":"average (per capita) income as a common measure of development","difficulty":2,"stem":"A country has a total income of ₹8,00,000 and a population of 400. What is its per capita income?","options":["₹200","₹20,000","₹2,000","₹32,00,00,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Divides by 4000 instead of 400, shifting the decimal one place too far."},{"option_index":1,"misconception":"Uses 40 instead of 400 as the divisor, adding an extra zero to the quotient."},{"option_index":3,"misconception":"Multiplies total income by population instead of dividing total income by population."}],"explanation":"Per capita income = total income ÷ population = ₹8,00,000 ÷ 400 = ₹2,000.","concept_id":"eco610-dev-income-as-indicator","strand":"Economic Development","kind":"mcq"},{"id":"average-per-capita-income-as-a-common-measure-of-development-002","band":"K5","grade":10,"subject":"Mathematics","concept":"average (per capita) income as a common measure of development","difficulty":2,"stem":"The per capita income of a town is ₹45,000 and its population is 800. What is the town's total income?","options":["₹3,60,00,000","₹36,00,000","₹3,60,000","₹45,800"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Multiplies by 80 instead of 800, dropping one zero."},{"option_index":2,"misconception":"Multiplies by 8 instead of 800, dropping two zeros."},{"option_index":3,"misconception":"Adds the population to the per capita income instead of multiplying."}],"explanation":"Total income = per capita income × population = ₹45,000 × 800 = ₹3,60,00,000.","concept_id":"eco610-dev-income-as-indicator","strand":"Economic Development","kind":"mcq"},{"id":"average-per-capita-income-as-a-common-measure-of-development-003","band":"K5","grade":10,"subject":"Mathematics","concept":"average (per capita) income as a common measure of development","difficulty":2,"stem":"Country X has total income ₹90,00,000 and population 300. Country Y has total income ₹90,00,000 and population 450. What is the difference between their per capita incomes (X − Y)?","options":["₹20,000","₹10,000","₹30,000","₹0"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses Country Y's per capita income instead of the difference."},{"option_index":2,"misconception":"Uses Country X's per capita income instead of the difference."},{"option_index":3,"misconception":"Assumes equal total income means equal per capita income."}],"explanation":"X per capita = ₹90,00,000 ÷ 300 = ₹30,000; Y per capita = ₹90,00,000 ÷ 450 = ₹20,000; difference = ₹10,000.","concept_id":"eco610-dev-income-as-indicator","strand":"Economic Development","kind":"mcq"},{"id":"average-per-capita-income-as-a-common-measure-of-development-004","band":"K5","grade":10,"subject":"Mathematics","concept":"average (per capita) income as a common measure of development","difficulty":2,"stem":"In a village, 9 people earn ₹20,000 each and 1 person earns ₹3,20,000. What is the average (per capita) income of these 10 people?","options":["₹20,000","₹3,20,000","₹5,00,000","₹50,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Uses the income earned by most people (the mode/typical income) as the average."},{"option_index":1,"misconception":"Uses the highest income as the average."},{"option_index":2,"misconception":"Reports total income without dividing by the number of people."}],"explanation":"Total income = 9×₹20,000 + ₹3,20,000 = ₹5,00,000; average = ₹5,00,000 ÷ 10 = ₹50,000.","concept_id":"eco610-dev-income-as-indicator","strand":"Economic Development","kind":"mcq"},{"id":"average-per-capita-income-as-a-common-measure-of-development-005","band":"K5","grade":10,"subject":"Mathematics","concept":"average (per capita) income as a common measure of development","difficulty":2,"stem":"Country A has per capita income ₹80,000 and Country B has per capita income ₹40,000. By how much is A's per capita income more than B's?","options":["2","₹1,20,000","₹40,000","₹80,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Gives the ratio (80,000 ÷ 40,000 = 2) instead of the difference in rupees."},{"option_index":1,"misconception":"Adds the two per capita incomes instead of subtracting."},{"option_index":3,"misconception":"Gives Country A's per capita income instead of the difference."}],"explanation":"Difference = ₹80,000 − ₹40,000 = ₹40,000.","concept_id":"eco610-dev-income-as-indicator","strand":"Economic Development","kind":"mcq"},{"id":"average-per-capita-income-as-a-common-measure-of-development-006","band":"K5","grade":10,"subject":"Mathematics","concept":"average (per capita) income as a common measure of development","difficulty":2,"stem":"In a country of 5 people, incomes are ₹10,000, ₹20,000, ₹30,000, ₹40,000 and ₹1,00,000. What is the average income?","options":["₹40,000","₹30,000","₹1,00,000","₹10,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses the middle (median) income instead of the mean."},{"option_index":2,"misconception":"Uses the highest income as the average."},{"option_index":3,"misconception":"Uses the lowest income as the average."}],"explanation":"Sum = ₹10,000 + ₹20,000 + ₹30,000 + ₹40,000 + ₹1,00,000 = ₹2,00,000; average = ₹2,00,000 ÷ 5 = ₹40,000.","concept_id":"eco610-dev-income-as-indicator","strand":"Economic Development","kind":"mcq"},{"id":"average-per-capita-income-as-a-common-measure-of-development-007","band":"K5","grade":10,"subject":"Mathematics","concept":"average (per capita) income as a common measure of development","difficulty":2,"stem":"A state has total income ₹12,000 crore and population 10 crore. What is its per capita income?","options":["₹120","₹12,000","₹1,20,000","₹1,200"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Divides by 100 instead of 10, shifting the decimal an extra place."},{"option_index":1,"misconception":"Takes the total income itself as the per capita income."},{"option_index":2,"misconception":"Multiplies by 10 instead of dividing by 10."}],"explanation":"Per capita income = ₹12,000 crore ÷ 10 crore = ₹1,200.","concept_id":"eco610-dev-income-as-indicator","strand":"Economic Development","kind":"mcq"},{"id":"average-per-capita-income-as-a-common-measure-of-development-008","band":"K5","grade":10,"subject":"Mathematics","concept":"average (per capita) income as a common measure of development","difficulty":2,"stem":"Country P has total income ₹1,50,00,000 and population 500. Country Q has total income ₹2,00,00,000 and population 500. What is the difference between their per capita incomes (Q − P)?","options":["₹50,00,000","₹10,000","₹30,000","₹40,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Subtracts total incomes instead of per capita incomes."},{"option_index":2,"misconception":"Gives Country P's per capita income instead of the difference."},{"option_index":3,"misconception":"Gives Country Q's per capita income instead of the difference."}],"explanation":"P per capita = ₹1,50,00,000 ÷ 500 = ₹30,000; Q per capita = ₹2,00,00,000 ÷ 500 = ₹40,000; difference = ₹10,000.","concept_id":"eco610-dev-income-as-indicator","strand":"Economic Development","kind":"mcq"},{"id":"average-per-capita-income-as-a-common-measure-of-development-009","band":"K5","grade":10,"subject":"Mathematics","concept":"average (per capita) income as a common measure of development","difficulty":2,"stem":"The average income of 4 people is ₹25,000. If their total income increases by ₹20,000 and one more person joins, what is the new average income?","options":["₹30,000","₹25,000","₹24,000","₹20,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Adds ₹20,000 ÷ 4 = ₹5,000 to the old average instead of recalculating for 5 people."},{"option_index":1,"misconception":"Assumes the average cannot change when both total income and population increase."},{"option_index":3,"misconception":"Uses the income increase as the new average."}],"explanation":"New total = 4×₹25,000 + ₹20,000 = ₹1,20,000; new average = ₹1,20,000 ÷ 5 = ₹24,000.","concept_id":"eco610-dev-income-as-indicator","strand":"Economic Development","kind":"mcq"},{"id":"average-per-capita-income-as-a-common-measure-of-development-010","band":"K5","grade":10,"subject":"Mathematics","concept":"average (per capita) income as a common measure of development","difficulty":2,"stem":"Country A has total income ₹40,00,000 and population 5,000. Country B has total income ₹90,00,000 and population 10,000. How much higher is Country B's per capita income than Country A's?","options":["₹800","₹900","₹50,00,000","₹100"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Gives Country A's per capita income instead of the difference."},{"option_index":1,"misconception":"Gives Country B's per capita income instead of the difference."},{"option_index":2,"misconception":"Subtracts total incomes instead of per capita incomes."}],"explanation":"A per capita = ₹40,00,000 ÷ 5,000 = ₹800; B per capita = ₹90,00,000 ÷ 10,000 = ₹900; difference = ₹100.","concept_id":"eco610-dev-income-as-indicator","strand":"Economic Development","kind":"mcq"},{"id":"why-average-income-alone-hides-inequality-within-a-country-001","band":"K5","grade":10,"subject":"Mathematics","concept":"why average income alone hides inequality within a country","difficulty":2,"stem":"The yearly incomes (in ₹ thousand) of 5 people in a country are 10, 20, 20, 30, and 120. A report gives only the average income. What is the average income?","options":["20","40","120","200"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Confuses the median or most common income with the mean."},{"option_index":2,"misconception":"Assumes the highest income is the average."},{"option_index":3,"misconception":"Adds all incomes but forgets to divide by the number of people."}],"explanation":"Sum = 10 + 20 + 20 + 30 + 120 = 200, and 200 ÷ 5 = 40.","concept_id":"eco610-dev-limitations-income","strand":"Economic Development","kind":"mcq"},{"id":"why-average-income-alone-hides-inequality-within-a-country-002","band":"K5","grade":10,"subject":"Mathematics","concept":"why average income alone hides inequality within a country","difficulty":2,"stem":"The yearly incomes (in ₹ thousand) of 5 people are 10, 20, 20, 30, and 120. The average income alone does not show the typical income. What is the median income?","options":["10","40","20","120"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Thinks the median is the lowest income."},{"option_index":1,"misconception":"Confuses the mean with the median."},{"option_index":3,"misconception":"Thinks the median is the highest income."}],"explanation":"Arranged in order: 10, 20, 20, 30, 120, so the middle value is 20.","concept_id":"eco610-dev-limitations-income","strand":"Economic Development","kind":"mcq"},{"id":"why-average-income-alone-hides-inequality-within-a-country-003","band":"K5","grade":10,"subject":"Mathematics","concept":"why average income alone hides inequality within a country","difficulty":2,"stem":"The yearly incomes (in ₹ thousand) of 5 people in a country are 5, 6, 7, 8, and 74. One very high income can pull the average up. What is the average income?","options":["7","74","100","20"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Confuses the median with the mean."},{"option_index":1,"misconception":"Assumes the highest income is the average."},{"option_index":2,"misconception":"Gives the total income instead of dividing by 5."}],"explanation":"Sum = 5 + 6 + 7 + 8 + 74 = 100, and 100 ÷ 5 = 20.","concept_id":"eco610-dev-limitations-income","strand":"Economic Development","kind":"mcq"},{"id":"why-average-income-alone-hides-inequality-within-a-country-004","band":"K5","grade":10,"subject":"Mathematics","concept":"why average income alone hides inequality within a country","difficulty":3,"stem":"The yearly incomes (in ₹ thousand) of 5 people are 5, 6, 7, 8, and 74. The average income is ₹20 thousand. How many people earn less than the average income?","options":["1","2","4","5"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Assumes the number below average equals the number above average."},{"option_index":1,"misconception":"Counts only the two smallest incomes as below average."},{"option_index":3,"misconception":"Thinks everyone must be below the average when one income is very high."}],"explanation":"5, 6, 7, and 8 are below 20, so 4 people earn less than the average.","concept_id":"eco610-dev-limitations-income","strand":"Economic Development","kind":"mcq"},{"id":"why-average-income-alone-hides-inequality-within-a-country-005","band":"K5","grade":10,"subject":"Mathematics","concept":"why average income alone hides inequality within a country","difficulty":3,"stem":"The yearly incomes (in ₹ thousand) of 5 people are 20, 20, 20, 20, and 100. The average income is ₹36 thousand. How far above the average is the highest income?","options":["36","64","80","100"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Gives the average instead of the gap from the average."},{"option_index":2,"misconception":"Confuses this gap with the range (100 − 20)."},{"option_index":3,"misconception":"Gives the highest income instead of the difference."}],"explanation":"Highest income − average = 100 − 36 = 64.","concept_id":"eco610-dev-limitations-income","strand":"Economic Development","kind":"mcq"},{"id":"why-average-income-alone-hides-inequality-within-a-country-006","band":"K5","grade":10,"subject":"Mathematics","concept":"why average income alone hides inequality within a country","difficulty":3,"stem":"The yearly incomes (in ₹ thousand) of 5 people are 10, 10, 10, 10, and 50. The average income is ₹18 thousand, but most people earn ₹10 thousand. What is the gap between the average and the income earned by most people?","options":["8","10","18","40"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Gives the typical income, not the gap."},{"option_index":2,"misconception":"Gives the average, not the gap."},{"option_index":3,"misconception":"Uses highest income minus typical income instead of average minus typical."}],"explanation":"Gap = average − most common income = 18 − 10 = 8.","concept_id":"eco610-dev-limitations-income","strand":"Economic Development","kind":"mcq"},{"id":"why-average-income-alone-hides-inequality-within-a-country-007","band":"K5","grade":10,"subject":"Mathematics","concept":"why average income alone hides inequality within a country","difficulty":3,"stem":"The yearly incomes (in ₹ lakh) of 5 people are 1, 2, 3, 4, and 20. The average is ₹6 lakh. If the richest person's income is removed, what is the new average of the remaining 4 incomes?","options":["3","6","2.5","10"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Confuses the median with the mean."},{"option_index":1,"misconception":"Thinks the average stays the same after removing an extreme value."},{"option_index":3,"misconception":"Gives the total of remaining incomes instead of dividing by 4."}],"explanation":"Remaining sum = 1 + 2 + 3 + 4 = 10, and 10 ÷ 4 = 2.5.","concept_id":"eco610-dev-limitations-income","strand":"Economic Development","kind":"mcq"},{"id":"why-average-income-alone-hides-inequality-within-a-country-008","band":"K5","grade":10,"subject":"Mathematics","concept":"why average income alone hides inequality within a country","difficulty":3,"stem":"Country A has incomes (in ₹ thousand) 10, 10, 10, 10, and 60. Country B has incomes 20, 20, 20, 20, and 20. Both countries have average income ₹20 thousand. In Country A, how many people earn below the average income?","options":["0","1","5","4"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Assumes equal averages mean everyone earns exactly the average."},{"option_index":1,"misconception":"Counts the one person above the average instead of below."},{"option_index":2,"misconception":"Ignores that the richest person earns above the average."}],"explanation":"Four people earn ₹10 thousand, which is below ₹20 thousand.","concept_id":"eco610-dev-limitations-income","strand":"Economic Development","kind":"mcq"},{"id":"why-average-income-alone-hides-inequality-within-a-country-009","band":"K5","grade":10,"subject":"Mathematics","concept":"why average income alone hides inequality within a country","difficulty":2,"stem":"A country has an average income of ₹25,000 and a median income of ₹12,000. The average alone hides inequality because it is much higher. What is the difference between the average income and the median income?","options":["12,000","13,000","25,000","37,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Gives the median instead of the difference."},{"option_index":2,"misconception":"Gives the average instead of the difference."},{"option_index":3,"misconception":"Adds average and median instead of subtracting."}],"explanation":"Difference = 25,000 − 12,000 = 13,000.","concept_id":"eco610-dev-limitations-income","strand":"Economic Development","kind":"mcq"},{"id":"why-average-income-alone-hides-inequality-within-a-country-010","band":"K5","grade":10,"subject":"Mathematics","concept":"why average income alone hides inequality within a country","difficulty":3,"stem":"The yearly incomes (in ₹ thousand) of 5 people are 30, 30, 30, 30, and 130. The average income is ₹50 thousand, but most people earn ₹30 thousand. How much is the average above the most common income?","options":["20","30","50","100"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Gives the most common income, not the gap."},{"option_index":2,"misconception":"Gives the average, not the gap."},{"option_index":3,"misconception":"Uses highest income minus most common income instead of average minus most common."}],"explanation":"Average − most common income = 50 − 30 = 20.","concept_id":"eco610-dev-limitations-income","strand":"Economic Development","kind":"mcq"},{"id":"using-non-income-criteria-such-as-literacy-and-infant-mortality-alongside-income-001","band":"K5","grade":10,"subject":"Mathematics","concept":"using non-income criteria such as literacy and infant mortality alongside income","difficulty":2,"stem":"A state's well-being score is the simple average of three indices: income index, literacy index, and infant mortality index. If the indices are income 0.40, literacy 0.80, and infant mortality 0.30, what is the well-being score?","options":["0.40","0.60","0.50","1.50"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses only the income index as the well-being score."},{"option_index":1,"misconception":"Averages income and literacy but ignores infant mortality."},{"option_index":3,"misconception":"Adds the three indices instead of finding their average."}],"explanation":"(0.40 + 0.80 + 0.30) ÷ 3 = 1.50 ÷ 3 = 0.50.","concept_id":"eco610-dev-other-criteria","strand":"Economic Development","kind":"mcq"},{"id":"using-non-income-criteria-such-as-literacy-and-infant-mortality-alongside-income-002","band":"K5","grade":10,"subject":"Mathematics","concept":"using non-income criteria such as literacy and infant mortality alongside income","difficulty":2,"stem":"A weighted well-being score uses weights: income 1/2, literacy 1/4, infant mortality 1/4. For a state, income index = 0.80, literacy index = 0.60, infant mortality index = 0.40. What is the weighted score?","options":["0.60","0.65","0.80","1.80"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses equal weights (simple average) instead of the given weights."},{"option_index":2,"misconception":"Uses only the income index."},{"option_index":3,"misconception":"Adds the raw indices without applying weights."}],"explanation":"0.5×0.80 + 0.25×0.60 + 0.25×0.40 = 0.40 + 0.15 + 0.10 = 0.65.","concept_id":"eco610-dev-other-criteria","strand":"Economic Development","kind":"mcq"},{"id":"using-non-income-criteria-such-as-literacy-and-infant-mortality-alongside-income-003","band":"K5","grade":10,"subject":"Mathematics","concept":"using non-income criteria such as literacy and infant mortality alongside income","difficulty":2,"stem":"The table shows three indices for three states. Using the simple average of the three indices, what is the highest well-being score among the states? State A: income 0.80, literacy 0.40, infant mortality 0.30; State B: income 0.50, literacy 0.70, infant mortality 0.60; State C: income 0.60, literacy 0.80, infant mortality 0.70.","options":["0.70","0.60","0.80","0.50"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Takes State B's score (second highest) as the highest."},{"option_index":2,"misconception":"Uses the highest single index (State A's income) instead of the composite average."},{"option_index":3,"misconception":"Takes State A's score because it has the highest income, ignoring non-income criteria."}],"explanation":"A = 1.50/3 = 0.50, B = 1.80/3 = 0.60, C = 2.10/3 = 0.70; highest is 0.70.","concept_id":"eco610-dev-other-criteria","strand":"Economic Development","kind":"mcq"},{"id":"using-non-income-criteria-such-as-literacy-and-infant-mortality-alongside-income-004","band":"K5","grade":10,"subject":"Mathematics","concept":"using non-income criteria such as literacy and infant mortality alongside income","difficulty":2,"stem":"In a town, 2400 people out of 3000 people aged 7 and above are literate. What is the literacy rate?","options":["20%","125%","8%","80%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Calculates the illiteracy rate (600/3000) instead of the literacy rate."},{"option_index":1,"misconception":"Divides total people by literate people (3000/2400)."},{"option_index":2,"misconception":"Moves the decimal point wrong, writing 0.80 as 8%."}],"explanation":"2400/3000 = 0.80 = 80%.","concept_id":"eco610-dev-other-criteria","strand":"Economic Development","kind":"mcq"},{"id":"using-non-income-criteria-such-as-literacy-and-infant-mortality-alongside-income-005","band":"K5","grade":10,"subject":"Mathematics","concept":"using non-income criteria such as literacy and infant mortality alongside income","difficulty":2,"stem":"A city recorded 48 infant deaths out of 2000 live births. What is the infant mortality rate per 1000 live births?","options":["48","2.4","24","240"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reports the number of infant deaths as the rate per 1000."},{"option_index":1,"misconception":"Multiplies by 100 instead of 1000."},{"option_index":3,"misconception":"Multiplies by 10000 instead of 1000."}],"explanation":"(48 ÷ 2000) × 1000 = 24.","concept_id":"eco610-dev-other-criteria","strand":"Economic Development","kind":"mcq"},{"id":"using-non-income-criteria-such-as-literacy-and-infant-mortality-alongside-income-006","band":"K5","grade":10,"subject":"Mathematics","concept":"using non-income criteria such as literacy and infant mortality alongside income","difficulty":2,"stem":"State X and State Y have the same income index, 0.60. State X has literacy index 0.90 and infant mortality index 0.60. State Y has literacy index 0.60 and infant mortality index 0.30. Using the simple average of the three indices, how much higher is State X's score than State Y's?","options":["0.00","0.20","0.60","0.30"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Sees the same income index and concludes there is no difference, ignoring non-income criteria."},{"option_index":2,"misconception":"Subtracts the sums of indices (2.10 - 1.50) but forgets to divide by 3."},{"option_index":3,"misconception":"Compares only the literacy indices (0.90 - 0.60) and ignores the other criteria."}],"explanation":"X = 2.10/3 = 0.70, Y = 1.50/3 = 0.50, difference = 0.20.","concept_id":"eco610-dev-other-criteria","strand":"Economic Development","kind":"mcq"},{"id":"using-non-income-criteria-such-as-literacy-and-infant-mortality-alongside-income-007","band":"K5","grade":10,"subject":"Mathematics","concept":"using non-income criteria such as literacy and infant mortality alongside income","difficulty":2,"stem":"A well-being index uses weights: income 0.5, literacy 0.3, infant mortality 0.2. If a state has income index 0.70, literacy index 0.80, and infant mortality index 0.50, what is its weighted score?","options":["0.69","0.67","0.70","2.00"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses equal weights (simple average) instead of the given weights."},{"option_index":2,"misconception":"Uses only the income index."},{"option_index":3,"misconception":"Adds the raw indices without weighting."}],"explanation":"0.5×0.70 + 0.3×0.80 + 0.2×0.50 = 0.35 + 0.24 + 0.10 = 0.69.","concept_id":"eco610-dev-other-criteria","strand":"Economic Development","kind":"mcq"},{"id":"using-non-income-criteria-such-as-literacy-and-infant-mortality-alongside-income-008","band":"K5","grade":10,"subject":"Mathematics","concept":"using non-income criteria such as literacy and infant mortality alongside income","difficulty":2,"stem":"State P has income index 0.40, literacy index 0.90, and infant mortality index 0.80. State Q has income index 0.80, literacy index 0.50, and infant mortality index 0.50. Using the simple average of the three indices, what is P's score minus Q's score?","options":["0.30","0.40","-0.10","0.10"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Subtracts the sums of indices (2.10 - 1.80) but forgets to divide by 3."},{"option_index":1,"misconception":"Compares only the income indices (0.80 - 0.40)."},{"option_index":2,"misconception":"Assumes the state with the higher income (Q) must have the higher well-being score, so reverses the difference."}],"explanation":"P = 2.10/3 = 0.70, Q = 1.80/3 = 0.60, so P - Q = 0.10.","concept_id":"eco610-dev-other-criteria","strand":"Economic Development","kind":"mcq"},{"id":"using-non-income-criteria-such-as-literacy-and-infant-mortality-alongside-income-009","band":"K5","grade":10,"subject":"Mathematics","concept":"using non-income criteria such as literacy and infant mortality alongside income","difficulty":2,"stem":"An infant mortality index is calculated as 1 - (IMR / 100), where IMR is infant deaths per 1000 live births. If a region has IMR = 40, what is its infant mortality index?","options":["0.40","0.96","0.60","0.04"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses the IMR/100 value directly instead of subtracting from 1."},{"option_index":1,"misconception":"Divides IMR by 1000 instead of 100 before subtracting."},{"option_index":3,"misconception":"Converts IMR per 1000 to a decimal (40/1000 = 0.04) and uses that as the index."}],"explanation":"1 - (40/100) = 1 - 0.40 = 0.60.","concept_id":"eco610-dev-other-criteria","strand":"Economic Development","kind":"mcq"},{"id":"using-non-income-criteria-such-as-literacy-and-infant-mortality-alongside-income-010","band":"K5","grade":10,"subject":"Mathematics","concept":"using non-income criteria such as literacy and infant mortality alongside income","difficulty":2,"stem":"A literacy index is the literacy rate written as a decimal. In a district, 720 out of 900 people are literate. What is the literacy index?","options":["0.20","0.80","0.72","0.90"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Calculates the illiteracy rate (180/900) instead of the literacy rate."},{"option_index":2,"misconception":"Uses 720/1000 without considering the actual total of 900."},{"option_index":3,"misconception":"Uses total people/1000 (900/1000) instead of literate people/total people."}],"explanation":"720/900 = 0.80.","concept_id":"eco610-dev-other-criteria","strand":"Economic Development","kind":"mcq"},{"id":"how-per-capita-income-is-calculated-from-total-income-and-population-001","band":"K5","grade":10,"subject":"Mathematics","concept":"how per capita income is calculated from total income and population","difficulty":2,"stem":"A country's total income is ₹80,000 and its population is 200. What is its per capita income?","options":["₹4,000","₹40","₹400","₹1,60,00,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Adds one extra zero when dividing total income by population"},{"option_index":1,"misconception":"Removes one extra zero when dividing total income by population"},{"option_index":3,"misconception":"Multiplies total income by population instead of dividing"}],"explanation":"Per capita income = total income ÷ population = ₹80,000 ÷ 200 = ₹400.","concept_id":"eco610-dev-per-capita-income-calc","strand":"Economic Development","kind":"mcq"},{"id":"how-per-capita-income-is-calculated-from-total-income-and-population-002","band":"K5","grade":10,"subject":"Mathematics","concept":"how per capita income is calculated from total income and population","difficulty":2,"stem":"A state's total income is ₹1,50,000 and its population is 500. What is its per capita income?","options":["₹300","₹3,000","₹30","₹7,50,00,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds one extra zero when dividing total income by population"},{"option_index":2,"misconception":"Removes one extra zero when dividing total income by population"},{"option_index":3,"misconception":"Multiplies total income by population instead of dividing"}],"explanation":"₹1,50,000 ÷ 500 = ₹300.","concept_id":"eco610-dev-per-capita-income-calc","strand":"Economic Development","kind":"mcq"},{"id":"how-per-capita-income-is-calculated-from-total-income-and-population-003","band":"K5","grade":10,"subject":"Mathematics","concept":"how per capita income is calculated from total income and population","difficulty":2,"stem":"A town's total income is ₹60,000 and its population is 300. What is its per capita income?","options":["₹1,80,00,000","₹2,000","₹20","₹200"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Multiplies total income by population instead of dividing"},{"option_index":1,"misconception":"Adds one extra zero when dividing total income by population"},{"option_index":2,"misconception":"Removes one extra zero when dividing total income by population"}],"explanation":"₹60,000 ÷ 300 = ₹200.","concept_id":"eco610-dev-per-capita-income-calc","strand":"Economic Development","kind":"mcq"},{"id":"how-per-capita-income-is-calculated-from-total-income-and-population-004","band":"K5","grade":10,"subject":"Mathematics","concept":"how per capita income is calculated from total income and population","difficulty":2,"stem":"A district's total income is ₹10,00,000 and its population is 2,500. What is its per capita income?","options":["₹40","₹4,000","₹400","₹2,50,00,00,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Removes one extra zero when dividing total income by population"},{"option_index":1,"misconception":"Adds one extra zero when dividing total income by population"},{"option_index":3,"misconception":"Multiplies total income by population instead of dividing"}],"explanation":"₹10,00,000 ÷ 2,500 = ₹400.","concept_id":"eco610-dev-per-capita-income-calc","strand":"Economic Development","kind":"mcq"},{"id":"how-per-capita-income-is-calculated-from-total-income-and-population-005","band":"K5","grade":10,"subject":"Mathematics","concept":"how per capita income is calculated from total income and population","difficulty":2,"stem":"A village's total income is ₹12,00,000 and its per capita income is ₹400. What is its population?","options":["30,000","3,000","300","3,00,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Adds one extra zero when dividing total income by per capita income"},{"option_index":2,"misconception":"Removes one extra zero when dividing total income by per capita income"},{"option_index":3,"misconception":"Adds two extra zeros when dividing total income by per capita income"}],"explanation":"Population = total income ÷ per capita income = ₹12,00,000 ÷ ₹400 = 3,000.","concept_id":"eco610-dev-per-capita-income-calc","strand":"Economic Development","kind":"mcq"},{"id":"how-per-capita-income-is-calculated-from-total-income-and-population-006","band":"K5","grade":10,"subject":"Mathematics","concept":"how per capita income is calculated from total income and population","difficulty":2,"stem":"A city's population is 4,000 and its per capita income is ₹250. What is its total income?","options":["₹1,00,000","₹2,50,000","₹10,00,000","₹1,00,00,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses population 400 instead of 4,000 when multiplying"},{"option_index":1,"misconception":"Multiplies by 1,000 instead of 4,000"},{"option_index":3,"misconception":"Uses population 40,000 instead of 4,000 when multiplying"}],"explanation":"Total income = per capita income × population = ₹250 × 4,000 = ₹10,00,000.","concept_id":"eco610-dev-per-capita-income-calc","strand":"Economic Development","kind":"mcq"},{"id":"how-per-capita-income-is-calculated-from-total-income-and-population-007","band":"K5","grade":10,"subject":"Mathematics","concept":"how per capita income is calculated from total income and population","difficulty":2,"stem":"Country A has total income ₹50,00,000 and population 10,000. Country B has total income ₹60,00,000 and population 20,000. What is the difference between their per capita incomes?","options":["₹500","₹800","₹200","₹300"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Gives Country A's per capita income instead of the difference"},{"option_index":1,"misconception":"Adds the two per capita incomes instead of subtracting"},{"option_index":3,"misconception":"Gives Country B's per capita income instead of the difference"}],"explanation":"A's per capita = ₹50,00,000 ÷ 10,000 = ₹500; B's = ₹60,00,000 ÷ 20,000 = ₹300; difference = ₹200.","concept_id":"eco610-dev-per-capita-income-calc","strand":"Economic Development","kind":"mcq"},{"id":"how-per-capita-income-is-calculated-from-total-income-and-population-008","band":"K5","grade":10,"subject":"Mathematics","concept":"how per capita income is calculated from total income and population","difficulty":2,"stem":"A country's total income is ₹18,00,000 and its population is 6,000. What is its per capita income?","options":["₹30","₹3,000","₹30,000","₹300"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Removes one extra zero when dividing total income by population"},{"option_index":1,"misconception":"Adds one extra zero when dividing total income by population"},{"option_index":2,"misconception":"Adds two extra zeros when dividing total income by population"}],"explanation":"₹18,00,000 ÷ 6,000 = ₹300.","concept_id":"eco610-dev-per-capita-income-calc","strand":"Economic Development","kind":"mcq"},{"id":"how-per-capita-income-is-calculated-from-total-income-and-population-009","band":"K5","grade":10,"subject":"Mathematics","concept":"how per capita income is calculated from total income and population","difficulty":2,"stem":"A state's total income is ₹7,20,000 and its population is 2,400. What is its per capita income?","options":["₹300","₹30","₹3,000","₹30,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Removes one extra zero when dividing total income by population"},{"option_index":2,"misconception":"Adds one extra zero when dividing total income by population"},{"option_index":3,"misconception":"Adds two extra zeros when dividing total income by population"}],"explanation":"₹7,20,000 ÷ 2,400 = ₹300.","concept_id":"eco610-dev-per-capita-income-calc","strand":"Economic Development","kind":"mcq"},{"id":"how-per-capita-income-is-calculated-from-total-income-and-population-010","band":"K5","grade":10,"subject":"Mathematics","concept":"how per capita income is calculated from total income and population","difficulty":2,"stem":"A district's total income is ₹2,50,000 and its population is 500. What is its per capita income?","options":["₹5,000","₹500","₹50","₹12,50,00,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Adds one extra zero when dividing total income by population"},{"option_index":2,"misconception":"Removes one extra zero when dividing total income by population"},{"option_index":3,"misconception":"Multiplies total income by population instead of dividing"}],"explanation":"₹2,50,000 ÷ 500 = ₹500.","concept_id":"eco610-dev-per-capita-income-calc","strand":"Economic Development","kind":"mcq"},{"id":"why-some-goods-and-services-need-government-provision-rather-than-only-the-market-001","band":"K5","grade":10,"subject":"Mathematics","concept":"why some goods and services need government provision rather than only the market","difficulty":2,"stem":"A village needs mosquito-control spraying that protects all 500 households equally. The total cost is ₹12,000, and 200 households each pay ₹24 voluntarily. How much must the government fund so that the service is provided for everyone?","options":["₹12,000","₹4,800","₹7,200","₹24"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Thinks the government must pay the whole cost, ignoring the voluntary contributions already collected"},{"option_index":1,"misconception":"Reports the amount already collected instead of the remaining shortfall"},{"option_index":3,"misconception":"Gives the per-household share and mistakes it for the total gap"}],"explanation":"Voluntary money = 200 × ₹24 = ₹4,800, so government must add ₹12,000 − ₹4,800 = ₹7,200.","concept_id":"eco610-dev-public-facilities","strand":"Economic Development","kind":"mcq"},{"id":"why-some-goods-and-services-need-government-provision-rather-than-only-the-market-002","band":"K5","grade":10,"subject":"Mathematics","concept":"why some goods and services need government provision rather than only the market","difficulty":2,"stem":"A bridge costs ₹5,00,000 to build, and the extra cost of one more vehicle crossing is ₹0. A private firm charges ₹10 per crossing. How many crossings must it sell to exactly cover the ₹5,00,000 building cost?","options":["5,000","50,000","5,00,000","50,00,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Decimal-place error: divides by 100 instead of by 10"},{"option_index":2,"misconception":"Uses the fixed cost itself as the number of crossings, forgetting to divide by the toll"},{"option_index":3,"misconception":"Multiplies the fixed cost by the toll instead of dividing"}],"explanation":"Crossings needed = ₹5,00,000 ÷ ₹10 = 50,000, showing a zero marginal cost good cannot cover its fixed cost without many users.","concept_id":"eco610-dev-public-facilities","strand":"Economic Development","kind":"mcq"},{"id":"why-some-goods-and-services-need-government-provision-rather-than-only-the-market-003","band":"K5","grade":10,"subject":"Mathematics","concept":"why some goods and services need government provision rather than only the market","difficulty":3,"stem":"Ten shopkeepers share a night patrol costing ₹7,000, so each pays ₹700. Three shopkeepers refuse to pay anything, but the patrol still protects them. How much must each of the remaining 7 shopkeepers now pay?","options":["₹700","₹300","₹100","₹1,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Assumes every shopkeeper pays the equal share, ignoring the free-riders"},{"option_index":1,"misconception":"Gives the increase in payment rather than the new amount each must pay"},{"option_index":2,"misconception":"Divides the ₹700 share again by 7 instead of re-splitting the total cost"}],"explanation":"₹7,000 spread over the 7 paying shopkeepers is ₹7,000 ÷ 7 = ₹1,000 each, which is why free-riding forces public provision.","concept_id":"eco610-dev-public-facilities","strand":"Economic Development","kind":"mcq"},{"id":"why-some-goods-and-services-need-government-provision-rather-than-only-the-market-004","band":"K5","grade":10,"subject":"Mathematics","concept":"why some goods and services need government provision rather than only the market","difficulty":1,"stem":"A city park costs ₹2,40,000 a year to maintain, and one extra visitor adds ₹0 to that cost. The 60,000 residents share the cost equally through taxes. How much does each resident pay per year?","options":["₹4","₹0","₹2,40,000","₹24"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Believes zero marginal cost means a zero price, forgetting the fixed cost must still be covered"},{"option_index":2,"misconception":"Gives the total cost instead of the amount per resident"},{"option_index":3,"misconception":"Decimal-place error when dividing by 60,000"}],"explanation":"₹2,40,000 ÷ 60,000 = ₹4 per resident, the tax price of a non-rival good that the market would not supply at zero price.","concept_id":"eco610-dev-public-facilities","strand":"Economic Development","kind":"mcq"},{"id":"why-some-goods-and-services-need-government-provision-rather-than-only-the-market-005","band":"K5","grade":10,"subject":"Mathematics","concept":"why some goods and services need government provision rather than only the market","difficulty":3,"stem":"One year of schooling costs ₹15,000. The student gains ₹11,000 of private benefit, and the rest of society gains ₹7,000 of external benefit. By how much does the total social benefit exceed the cost?","options":["₹4,000","₹18,000","₹3,000","₹26,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reports the private shortfall (cost minus private benefit) instead of the social surplus"},{"option_index":1,"misconception":"Gives total social benefit but forgets to subtract the cost"},{"option_index":3,"misconception":"Adds the cost to the private benefit instead of comparing social benefit with cost"}],"explanation":"Social benefit = ₹11,000 + ₹7,000 = ₹18,000, and ₹18,000 − ₹15,000 = ₹3,000, so society gains although the student alone would not buy it.","concept_id":"eco610-dev-public-facilities","strand":"Economic Development","kind":"mcq"},{"id":"why-some-goods-and-services-need-government-provision-rather-than-only-the-market-006","band":"K5","grade":10,"subject":"Mathematics","concept":"why some goods and services need government provision rather than only the market","difficulty":2,"stem":"A highway costs ₹80,00,000 to build. Tolls would bring in only ₹50,00,000. How much extra public money must the government add so the highway is built?","options":["₹1,30,00,000","₹50,00,000","₹80,00,000","₹30,00,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Adds cost and revenue instead of finding the gap between them"},{"option_index":1,"misconception":"Gives the revenue collected, not the amount still needed"},{"option_index":2,"misconception":"Gives the total cost, ignoring the toll revenue already available"}],"explanation":"Extra funds = ₹80,00,000 − ₹50,00,000 = ₹30,00,000, the loss a private builder would refuse to bear.","concept_id":"eco610-dev-public-facilities","strand":"Economic Development","kind":"mcq"},{"id":"why-some-goods-and-services-need-government-provision-rather-than-only-the-market-007","band":"K5","grade":10,"subject":"Mathematics","concept":"why some goods and services need government provision rather than only the market","difficulty":2,"stem":"National defence costs ₹45,00,000 and gives each of 4,00,000 citizens ₹15 worth of protection. What is the net benefit, that is total benefit minus cost?","options":["₹15,00,000","₹45,00,000","₹60,00,000","₹1,05,00,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Gives the cost figure instead of the net benefit"},{"option_index":2,"misconception":"Gives the total benefit without subtracting the cost"},{"option_index":3,"misconception":"Adds total benefit and cost instead of subtracting"}],"explanation":"Total benefit = 4,00,000 × ₹15 = ₹60,00,000, and ₹60,00,000 − ₹45,00,000 = ₹15,00,000, so the scheme is worth doing publicly.","concept_id":"eco610-dev-public-facilities","strand":"Economic Development","kind":"mcq"},{"id":"why-some-goods-and-services-need-government-provision-rather-than-only-the-market-008","band":"K5","grade":10,"subject":"Mathematics","concept":"why some goods and services need government provision rather than only the market","difficulty":1,"stem":"Of 400 households, 3/5 would pay ₹25 each towards a public drainage scheme costing ₹9,000 in total. How many households would pay voluntarily?","options":["160","240","300","400"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses the non-paying fraction 2/5 instead of the paying fraction 3/5"},{"option_index":2,"misconception":"Uses the fraction 3/4 in place of 3/5"},{"option_index":3,"misconception":"Assumes every household pays, i.e. that no one free-rides"}],"explanation":"3/5 of 400 = 240 households pay, giving only 240 × ₹25 = ₹6,000 of the ₹9,000 needed.","concept_id":"eco610-dev-public-facilities","strand":"Economic Development","kind":"mcq"},{"id":"why-some-goods-and-services-need-government-provision-rather-than-only-the-market-009","band":"K5","grade":10,"subject":"Mathematics","concept":"why some goods and services need government provision rather than only the market","difficulty":3,"stem":"A public library costs ₹3,000 to run. Twenty residents would each pay ₹30, and thirty residents would each pay ₹50. How much more money is needed beyond what they would pay voluntarily?","options":["₹2,100","₹500","₹900","₹3,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Gives the total voluntary contribution instead of the remaining shortfall"},{"option_index":1,"misconception":"Assumes all 50 residents pay the highest amount ₹50, giving a gap of only ₹500"},{"option_index":3,"misconception":"Gives the total running cost, ignoring the voluntary payments"}],"explanation":"Voluntary total = 20 × ₹30 + 30 × ₹50 = ₹2,100, so the shortfall is ₹3,000 − ₹2,100 = ₹900.","concept_id":"eco610-dev-public-facilities","strand":"Economic Development","kind":"mcq"},{"id":"why-some-goods-and-services-need-government-provision-rather-than-only-the-market-010","band":"K5","grade":10,"subject":"Mathematics","concept":"why some goods and services need government provision rather than only the market","difficulty":1,"stem":"Supplying clean water publicly costs ₹18 per person, while a private supplier charges ₹25 per person. How much less per person does the public supply cost?","options":["₹7","₹18","₹25","₹43"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Quotes the public cost itself rather than the difference between the two costs"},{"option_index":2,"misconception":"Quotes the private charge itself rather than the saving"},{"option_index":3,"misconception":"Adds the two per-person costs instead of subtracting them"}],"explanation":"Saving per person = ₹25 − ₹18 = ₹7, which is why public provision reaches people a private supplier would price out.","concept_id":"eco610-dev-public-facilities","strand":"Economic Development","kind":"mcq"},{"id":"sustainability-of-development-and-the-risk-of-resource-depletion-001","band":"K5","grade":10,"subject":"Mathematics","concept":"sustainability of development and the risk of resource depletion","difficulty":2,"stem":"A city uses 500,000 litres of water per day. A reservoir has 45,000,000 litres of usable water. If no water is added, for how many full days will the reservoir last?","options":["90 days","9 days","900 days","80 days"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Decimal place error when cancelling zeros: divides 45 by 5 to get 9 instead of 90."},{"option_index":2,"misconception":"Place-value error: adds an extra zero when dividing 45,000,000 by 500,000."},{"option_index":3,"misconception":"Rounds the reservoir capacity down to 40,000,000 before dividing (40,000,000 ÷ 500,000 = 80)."}],"explanation":"45,000,000 ÷ 500,000 = 90 full days.","concept_id":"eco610-dev-sustainability","strand":"Economic Development","kind":"mcq"},{"id":"sustainability-of-development-and-the-risk-of-resource-depletion-002","band":"K5","grade":10,"subject":"Mathematics","concept":"sustainability of development and the risk of resource depletion","difficulty":2,"stem":"A country's average resource use is 8 tonnes per person per year. If it meets a sustainability target by reducing this by 25%, what is the new average use?","options":["2 tonnes","6 tonnes","32 tonnes","7.75 tonnes"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Finds only the amount of reduction (25% of 8 = 2 tonnes) and gives that instead of the remaining use."},{"option_index":2,"misconception":"Divides 8 by 25% (0.25) instead of subtracting 25% of 8 from 8."},{"option_index":3,"misconception":"Subtracts 0.25 tonnes as if 25% meant 0.25 tonnes regardless of the total."}],"explanation":"25% of 8 = 2, so new use = 8 − 2 = 6 tonnes.","concept_id":"eco610-dev-sustainability","strand":"Economic Development","kind":"mcq"},{"id":"sustainability-of-development-and-the-risk-of-resource-depletion-003","band":"K5","grade":10,"subject":"Mathematics","concept":"sustainability of development and the risk of resource depletion","difficulty":2,"stem":"A school uses 2,400 sheets of paper per week. A recycling programme reduces this by one third. How many sheets per week are used after the reduction?","options":["800 sheets","1,800 sheets","1,600 sheets","3,600 sheets"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Finds the number of sheets reduced (1/3 of 2,400 = 800) instead of the remaining sheets."},{"option_index":1,"misconception":"Subtracts 1/4 of 2,400 (600) instead of 1/3 (800)."},{"option_index":3,"misconception":"Adds one third instead of subtracting one third."}],"explanation":"Reduction = 2,400 ÷ 3 = 800, so remaining = 2,400 − 800 = 1,600 sheets.","concept_id":"eco610-dev-sustainability","strand":"Economic Development","kind":"mcq"},{"id":"sustainability-of-development-and-the-risk-of-resource-depletion-004","band":"K5","grade":10,"subject":"Mathematics","concept":"sustainability of development and the risk of resource depletion","difficulty":2,"stem":"A coal reserve has 1,200 million tonnes. The country uses 80 million tonnes per year, but recycling and substitution replace 25% of that use. How many years will the reserve last?","options":["15 years","12 years","19 years","20 years"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Ignores the replacement and divides by the gross annual use: 1,200 ÷ 80 = 15."},{"option_index":1,"misconception":"Adds 25% to annual consumption instead of subtracting it: 1,200 ÷ (80 + 20) = 12."},{"option_index":2,"misconception":"Increases the 15-year lifetime by 25% (15 × 1.25 ≈ 19) instead of reducing annual consumption by 25%."}],"explanation":"Net use = 80 × 0.75 = 60 million tonnes/year, so 1,200 ÷ 60 = 20 years.","concept_id":"eco610-dev-sustainability","strand":"Economic Development","kind":"mcq"},{"id":"sustainability-of-development-and-the-risk-of-resource-depletion-005","band":"K5","grade":10,"subject":"Mathematics","concept":"sustainability of development and the risk of resource depletion","difficulty":2,"stem":"A country uses 500 terawatt-hours (TWh) of energy in a year. If 125 TWh comes from renewable sources, what percentage of total energy is renewable?","options":["25%","4%","20%","75%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses the reciprocal 500 ÷ 125 to get 4% instead of part ÷ whole."},{"option_index":2,"misconception":"Divides renewable energy by total plus renewable energy: 125 ÷ 625 = 20%."},{"option_index":3,"misconception":"Finds the non-renewable percentage (375 ÷ 500 = 75%) and calls it renewable."}],"explanation":"125 ÷ 500 × 100 = 25%.","concept_id":"eco610-dev-sustainability","strand":"Economic Development","kind":"mcq"},{"id":"sustainability-of-development-and-the-risk-of-resource-depletion-006","band":"K5","grade":10,"subject":"Mathematics","concept":"sustainability of development and the risk of resource depletion","difficulty":2,"stem":"A city currently consumes 2 million tonnes of resources per year. If consumption doubles every 30 years, what will annual consumption be after 60 years?","options":["4 million tonnes","6 million tonnes","8 million tonnes","18 million tonnes"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Applies only one doubling (for 30 years) instead of two doublings for 60 years."},{"option_index":1,"misconception":"Treats growth as linear: adds 2 million tonnes for each 30-year period."},{"option_index":3,"misconception":"Uses tripling per 30-year period instead of doubling."}],"explanation":"60 years = two 30-year periods, so 2 × 2 × 2 = 8 million tonnes.","concept_id":"eco610-dev-sustainability","strand":"Economic Development","kind":"mcq"},{"id":"sustainability-of-development-and-the-risk-of-resource-depletion-007","band":"K5","grade":10,"subject":"Mathematics","concept":"sustainability of development and the risk of resource depletion","difficulty":2,"stem":"A resource consumption grows at 7% per year. Using the rule of 70, approximately how many years will it take to double?","options":["7 years","14 years","70 years","10 years"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Uses the growth rate itself (7) as the doubling time."},{"option_index":1,"misconception":"Divides 100 by 7 instead of 70 by 7."},{"option_index":2,"misconception":"Forgets to divide the rule-of-70 constant by the growth rate."}],"explanation":"Rule of 70: doubling time ≈ 70 ÷ 7 = 10 years.","concept_id":"eco610-dev-sustainability","strand":"Economic Development","kind":"mcq"},{"id":"sustainability-of-development-and-the-risk-of-resource-depletion-008","band":"K5","grade":10,"subject":"Mathematics","concept":"sustainability of development and the risk of resource depletion","difficulty":2,"stem":"A city produces 120 tonnes of waste per day. A recycling programme reduces this by 40%. How many tonnes of waste per day remain after recycling?","options":["72 tonnes","48 tonnes","80 tonnes","168 tonnes"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Finds the amount reduced (40% of 120 = 48 tonnes) instead of the remaining amount."},{"option_index":2,"misconception":"Subtracts 40 tonnes as if 40% meant 40 units (or 1/3 of 120), giving 80 tonnes."},{"option_index":3,"misconception":"Adds 40% instead of subtracting it."}],"explanation":"Reduction = 40% of 120 = 48, so remaining = 120 − 48 = 72 tonnes.","concept_id":"eco610-dev-sustainability","strand":"Economic Development","kind":"mcq"},{"id":"sustainability-of-development-and-the-risk-of-resource-depletion-009","band":"K5","grade":10,"subject":"Mathematics","concept":"sustainability of development and the risk of resource depletion","difficulty":2,"stem":"A shower uses 12 litres of water per minute. A low-flow showerhead reduces this by 3 litres per minute. How much water is saved in a 5-minute shower?","options":["3 litres","45 litres","15 litres","60 litres"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Gives only the per-minute saving, not the total for 5 minutes."},{"option_index":1,"misconception":"Finds the water used by the low-flow shower (9 × 5 = 45) instead of the amount saved."},{"option_index":3,"misconception":"Finds the original water use (12 × 5 = 60) instead of the savings."}],"explanation":"Saving = 3 litres/min × 5 min = 15 litres.","concept_id":"eco610-dev-sustainability","strand":"Economic Development","kind":"mcq"},{"id":"sustainability-of-development-and-the-risk-of-resource-depletion-010","band":"K5","grade":10,"subject":"Mathematics","concept":"sustainability of development and the risk of resource depletion","difficulty":2,"stem":"A forest has 96,000 trees. Logging removes 2,500 trees per year, while replanting adds 500 trees per year. If these rates continue, how many years until the forest has no trees?","options":["38.4 years","32 years","192 years","48 years"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Uses only the logging rate: 96,000 ÷ 2,500 = 38.4, ignoring replanting."},{"option_index":1,"misconception":"Adds logging and replanting instead of finding net loss: 96,000 ÷ 3,000 = 32."},{"option_index":2,"misconception":"Uses only the replanting rate: 96,000 ÷ 500 = 192, ignoring logging."}],"explanation":"Net loss = 2,500 − 500 = 2,000 trees/year, so 96,000 ÷ 2,000 = 48 years.","concept_id":"eco610-dev-sustainability","strand":"Economic Development","kind":"mcq"},{"id":"what-development-means-and-why-it-varies-by-person-001","band":"K5","grade":10,"subject":"Mathematics","concept":"what development means and why it varies by person","difficulty":2,"stem":"A country has a total income of ₹36,000 crore and a population of 4 crore. What is its per capita income in rupees?","options":["144000","8000","9000","900"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"multiplies total income by population instead of dividing"},{"option_index":1,"misconception":"subtracts population from total income"},{"option_index":3,"misconception":"divides by 40 instead of 4 (off by factor of 10)"}],"explanation":"Per capita income = total income / population = 36000/4 = 9000.","concept_id":"eco610-dev-what-is-development","strand":"Economic Development","kind":"mcq"},{"id":"what-development-means-and-why-it-varies-by-person-002","band":"K5","grade":10,"subject":"Mathematics","concept":"what development means and why it varies by person","difficulty":2,"stem":"The average income of 5 households is ₹12,000. If the income of one household is excluded, the average of the remaining 4 is ₹10,000. What is the income of the excluded household?","options":["2000","20000","10000","22000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"misplaces decimal (divides by 10)"},{"option_index":2,"misconception":"thinks excluded income equals the new average"},{"option_index":3,"misconception":"adds the two averages (12000+10000)"}],"explanation":"Total of 5 = 5×12000 = 60000; total of 4 = 4×10000 = 40000; excluded = 60000−40000 = 20000.","concept_id":"eco610-dev-what-is-development","strand":"Economic Development","kind":"mcq"},{"id":"what-development-means-and-why-it-varies-by-person-003","band":"K5","grade":10,"subject":"Mathematics","concept":"what development means and why it varies by person","difficulty":2,"stem":"A simple version of the Human Development Index uses the average of three indices: income index 0.6, education index 0.7, and health index 0.8. What is this average?","options":["2.1","0.6","0.7","0.8"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"adds the indices instead of averaging"},{"option_index":1,"misconception":"takes the minimum index as the overall"},{"option_index":3,"misconception":"takes the maximum index as the overall"}],"explanation":"Average = (0.6+0.7+0.8)/3 = 2.1/3 = 0.7.","concept_id":"eco610-dev-what-is-development","strand":"Economic Development","kind":"mcq"},{"id":"what-development-means-and-why-it-varies-by-person-004","band":"K5","grade":10,"subject":"Mathematics","concept":"what development means and why it varies by person","difficulty":2,"stem":"In a region, 30% of 2000 people are below the poverty line. How many people are below the poverty line?","options":["60","300","1400","600"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"misplaces decimal (divides by 1000 instead of 100)"},{"option_index":1,"misconception":"takes half of 30% (15% of 2000)"},{"option_index":2,"misconception":"finds the complement (70% of 2000 instead of 30%)"}],"explanation":"30% of 2000 = (30/100)×2000 = 600.","concept_id":"eco610-dev-what-is-development","strand":"Economic Development","kind":"mcq"},{"id":"what-development-means-and-why-it-varies-by-person-005","band":"K5","grade":10,"subject":"Mathematics","concept":"what development means and why it varies by person","difficulty":2,"stem":"A country's per capita income increased from ₹20,000 to ₹25,000. What is the percentage increase?","options":["20","5","25","125"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"divides the increase by the new value instead of the original"},{"option_index":1,"misconception":"reports the absolute increase as the percentage"},{"option_index":3,"misconception":"adds 100% to the actual percentage increase"}],"explanation":"Percentage increase = (25000−20000)/20000 × 100 = 5000/20000 × 100 = 25%.","concept_id":"eco610-dev-what-is-development","strand":"Economic Development","kind":"mcq"},{"id":"what-development-means-and-why-it-varies-by-person-006","band":"K5","grade":10,"subject":"Mathematics","concept":"what development means and why it varies by person","difficulty":2,"stem":"The average income of 10 people is ₹15,000. If 9 people have an average income of ₹10,000, what is the income of the 10th person?","options":["5000","15000","135000","60000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"subtracts the averages (15000−10000)"},{"option_index":1,"misconception":"assumes the 10th person's income equals the overall average"},{"option_index":2,"misconception":"subtracts the overall average from total income (150000−15000)"}],"explanation":"Total of 10 = 10×15000 = 150000; total of 9 = 9×10000 = 90000; 10th = 150000−90000 = 60000.","concept_id":"eco610-dev-what-is-development","strand":"Economic Development","kind":"mcq"},{"id":"what-development-means-and-why-it-varies-by-person-007","band":"K5","grade":10,"subject":"Mathematics","concept":"what development means and why it varies by person","difficulty":2,"stem":"A farmer's income is ₹8,000 and a factory worker's income is ₹12,000. What fraction of the factory worker's income is the farmer's income?","options":["3/2","2/3","1/2","2/5"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"reverses the numerator and denominator"},{"option_index":2,"misconception":"approximates or uses difference (4000/8000 = 1/2)"},{"option_index":3,"misconception":"divides by the sum of incomes instead of the factory worker's income"}],"explanation":"Fraction = 8000/12000 = 2/3.","concept_id":"eco610-dev-what-is-development","strand":"Economic Development","kind":"mcq"},{"id":"what-development-means-and-why-it-varies-by-person-008","band":"K5","grade":10,"subject":"Mathematics","concept":"what development means and why it varies by person","difficulty":2,"stem":"A country's total income is ₹80,000 crore and its population is 10 crore. What is its per capita income in rupees?","options":["80000","800","8000","8"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"misplaces decimal (multiplies by 10 instead of dividing)"},{"option_index":1,"misconception":"divides by 100 instead of 10 (off by factor of 10)"},{"option_index":3,"misconception":"divides by 1000 (off by factor of 100)"}],"explanation":"Per capita income = 80000/10 = 8000.","concept_id":"eco610-dev-what-is-development","strand":"Economic Development","kind":"mcq"},{"id":"what-development-means-and-why-it-varies-by-person-009","band":"K5","grade":10,"subject":"Mathematics","concept":"what development means and why it varies by person","difficulty":2,"stem":"In a survey, 60% of 500 girls and 40% of 500 boys wanted higher education. How many more girls than boys wanted higher education?","options":["20","200","300","100"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"subtracts the percentages (60−40) instead of the actual numbers"},{"option_index":1,"misconception":"reports the number of boys (40% of 500) as the difference"},{"option_index":2,"misconception":"reports the number of girls (60% of 500) as the difference"}],"explanation":"Girls = 0.60×500 = 300; Boys = 0.40×500 = 200; Difference = 100.","concept_id":"eco610-dev-what-is-development","strand":"Economic Development","kind":"mcq"},{"id":"what-development-means-and-why-it-varies-by-person-010","band":"K5","grade":10,"subject":"Mathematics","concept":"what development means and why it varies by person","difficulty":2,"stem":"In a village, the total income is ₹2,00,000 and there are 10 households. What is the per capita income (income per household) in rupees?","options":["2000","20000","200000","10000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"misplaces decimal (divides by 100 instead of 10)"},{"option_index":2,"misconception":"thinks per capita income is the total income"},{"option_index":3,"misconception":"divides by 20 instead of 10 (halves the population)"}],"explanation":"Per capita income = 200000/10 = 20000.","concept_id":"eco610-dev-what-is-development","strand":"Economic Development","kind":"mcq"},{"id":"population-groups-most-vulnerable-to-food-insecurity-001","band":"K5","grade":9,"subject":"Mathematics","concept":"population groups most vulnerable to food insecurity","difficulty":2,"stem":"In a survey of 800 food-insecure households, 2/5 were landless agricultural labourers. How many households were landless agricultural labourers?","options":["320","200","400","2000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Treats 2/5 as 1/4 and finds 200."},{"option_index":2,"misconception":"Uses 1/2 of the total instead of 2/5."},{"option_index":3,"misconception":"Inverts the fraction and computes 800 × 5/2."}],"explanation":"800 × 2/5 = 320.","concept_id":"eco610-food-affected-groups","strand":"Food Security","kind":"mcq"},{"id":"population-groups-most-vulnerable-to-food-insecurity-002","band":"K5","grade":9,"subject":"Mathematics","concept":"population groups most vulnerable to food insecurity","difficulty":2,"stem":"Among 640 food-insecure persons in a study, children and elderly were in the ratio 5:3. How many were children?","options":["240","400","320","384"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Finds the number of elderly instead of children."},{"option_index":2,"misconception":"Splits the total equally between the two groups."},{"option_index":3,"misconception":"Uses 3/5 of the total instead of 5/8."}],"explanation":"Total parts = 8; one part = 80; children = 5 × 80 = 400.","concept_id":"eco610-food-affected-groups","strand":"Food Security","kind":"mcq"},{"id":"population-groups-most-vulnerable-to-food-insecurity-003","band":"K5","grade":9,"subject":"Mathematics","concept":"population groups most vulnerable to food insecurity","difficulty":2,"stem":"The number of food-insecure elderly in a district rose from 200 to 250. What was the percentage increase?","options":["20%","50%","25%","125%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Divides the increase by the new value (50/250)."},{"option_index":1,"misconception":"Reports the numerical increase 50 as a percentage."},{"option_index":3,"misconception":"Expresses the new value as a percentage of the original (250/200)."}],"explanation":"Increase = 50; percentage increase = (50/200) × 100 = 25%.","concept_id":"eco610-food-affected-groups","strand":"Food Security","kind":"mcq"},{"id":"population-groups-most-vulnerable-to-food-insecurity-004","band":"K5","grade":9,"subject":"Mathematics","concept":"population groups most vulnerable to food insecurity","difficulty":2,"stem":"A food-security survey counted 120 landless labourers, 90 slum dwellers, 70 marginal farmers, and 160 informal workers. What is the mean number per group?","options":["440","100","120","110"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Adds all groups but forgets to divide by the number of groups."},{"option_index":1,"misconception":"Makes an addition error and divides 400 by 4."},{"option_index":2,"misconception":"Chooses one listed group size instead of calculating the mean."}],"explanation":"Sum = 120 + 90 + 70 + 160 = 440; mean = 440 ÷ 4 = 110.","concept_id":"eco610-food-affected-groups","strand":"Food Security","kind":"mcq"},{"id":"population-groups-most-vulnerable-to-food-insecurity-005","band":"K5","grade":9,"subject":"Mathematics","concept":"population groups most vulnerable to food insecurity","difficulty":2,"stem":"In a village, 3/5 of the 450 food-insecure families belong to landless labourer or marginal farmer groups. How many families belong to these two vulnerable groups?","options":["150","270","180","300"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses 1/3 of the total instead of 3/5."},{"option_index":2,"misconception":"Finds the complement 2/5 of the total."},{"option_index":3,"misconception":"Uses 2/3 of the total instead of 3/5."}],"explanation":"450 × 3/5 = 270.","concept_id":"eco610-food-affected-groups","strand":"Food Security","kind":"mcq"},{"id":"population-groups-most-vulnerable-to-food-insecurity-006","band":"K5","grade":9,"subject":"Mathematics","concept":"population groups most vulnerable to food insecurity","difficulty":2,"stem":"A survey found that 24 out of 60 food-insecure children were girls. What percentage of these children were girls?","options":["24%","60%","40%","0.4%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses the count 24 directly as a percentage."},{"option_index":1,"misconception":"Finds the percentage of boys instead of girls."},{"option_index":3,"misconception":"Writes the decimal 0.4 as 0.4% instead of 40%."}],"explanation":"(24/60) × 100 = 40%.","concept_id":"eco610-food-affected-groups","strand":"Food Security","kind":"mcq"},{"id":"population-groups-most-vulnerable-to-food-insecurity-007","band":"K5","grade":9,"subject":"Mathematics","concept":"population groups most vulnerable to food insecurity","difficulty":2,"stem":"A food relief centre gives 2.5 kg of rice per person per week to 80 elderly persons. How many kilograms of rice are needed per week?","options":["32 kg","20 kg","250 kg","200 kg"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Divides 80 by 2.5 instead of multiplying."},{"option_index":1,"misconception":"Uses 8 instead of 80, giving 2.5 × 8 = 20."},{"option_index":2,"misconception":"Multiplies by 100 persons instead of 80."}],"explanation":"2.5 kg × 80 = 200 kg.","concept_id":"eco610-food-affected-groups","strand":"Food Security","kind":"mcq"},{"id":"population-groups-most-vulnerable-to-food-insecurity-008","band":"K5","grade":9,"subject":"Mathematics","concept":"population groups most vulnerable to food insecurity","difficulty":2,"stem":"In a slum, 48% of 250 households are food-insecure. How many households are food-insecure?","options":["120","48","100","130"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses the percentage value 48 as the count of households."},{"option_index":2,"misconception":"Uses 40% of 250 instead of 48%."},{"option_index":3,"misconception":"Finds the food-secure households, which are 52% of 250."}],"explanation":"250 × 48/100 = 120.","concept_id":"eco610-food-affected-groups","strand":"Food Security","kind":"mcq"},{"id":"population-groups-most-vulnerable-to-food-insecurity-009","band":"K5","grade":9,"subject":"Mathematics","concept":"population groups most vulnerable to food insecurity","difficulty":2,"stem":"Among 720 food-insecure persons, the ratio of women to men is 7:5. How many women are there?","options":["300","360","504","420"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Finds the number of men instead of women."},{"option_index":1,"misconception":"Splits the total equally between women and men."},{"option_index":2,"misconception":"Uses 7/10 instead of 7/12 for the women’s share."}],"explanation":"Total parts = 12; one part = 60; women = 7 × 60 = 420.","concept_id":"eco610-food-affected-groups","strand":"Food Security","kind":"mcq"},{"id":"population-groups-most-vulnerable-to-food-insecurity-010","band":"K5","grade":9,"subject":"Mathematics","concept":"population groups most vulnerable to food insecurity","difficulty":2,"stem":"A state has 15% tribal population. If 40% of the tribal population is food-insecure, what percent of the state's total population is food-insecure tribal?","options":["0.06%","25%","6%","55%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Writes the decimal 0.06 as 0.06% instead of 6%."},{"option_index":1,"misconception":"Subtracts the percentages: 40% − 15%."},{"option_index":3,"misconception":"Adds the percentages: 40% + 15%."}],"explanation":"0.15 × 0.40 = 0.06 = 6%.","concept_id":"eco610-food-affected-groups","strand":"Food Security","kind":"mcq"},{"id":"buffer-stock-foodgrain-the-government-procures-and-stores-through-the-fci-001","band":"K5","grade":9,"subject":"Mathematics","concept":"buffer stock: foodgrain the government procures and stores through the FCI","difficulty":2,"stem":"The FCI already has 0.8 million tonnes of wheat in buffer stock. It procures another 2.4 million tonnes. What is the total buffer stock of wheat?","options":["3.2 million tonnes","1.6 million tonnes","1.92 million tonnes","2.4 million tonnes"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Subtracted the existing stock instead of adding it."},{"option_index":2,"misconception":"Multiplied the two quantities instead of adding them."},{"option_index":3,"misconception":"Ignored the existing buffer stock and used only the newly procured amount."}],"explanation":"Total = 0.8 + 2.4 = 3.2 million tonnes.","concept_id":"eco610-food-buffer-stock","strand":"Food Security","kind":"mcq"},{"id":"buffer-stock-foodgrain-the-government-procures-and-stores-through-the-fci-002","band":"K5","grade":9,"subject":"Mathematics","concept":"buffer stock: foodgrain the government procures and stores through the FCI","difficulty":2,"stem":"A godown has capacity 25,000 tonnes. FCI stores 18,500 tonnes of wheat and 4,750 tonnes of rice. How many tonnes of capacity remain empty?","options":["6,500 tonnes","20,250 tonnes","1,750 tonnes","23,250 tonnes"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Subtracted only the wheat from the total capacity and forgot the rice."},{"option_index":1,"misconception":"Subtracted only the rice from the total capacity and forgot the wheat."},{"option_index":3,"misconception":"Added the stored wheat and rice but did not subtract from capacity."}],"explanation":"Total stored = 18,500 + 4,750 = 23,250 t. Remaining = 25,000 − 23,250 = 1,750 t.","concept_id":"eco610-food-buffer-stock","strand":"Food Security","kind":"mcq"},{"id":"buffer-stock-foodgrain-the-government-procures-and-stores-through-the-fci-003","band":"K5","grade":9,"subject":"Mathematics","concept":"buffer stock: foodgrain the government procures and stores through the FCI","difficulty":2,"stem":"FCI procures wheat at ₹2,150 per quintal. What is the cost of 40 quintals?","options":["₹8,600","₹86,000","₹84,000","₹88,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Placed the decimal point incorrectly, giving one-tenth of the correct cost."},{"option_index":2,"misconception":"Rounded ₹2,150 down to ₹2,100 before multiplying."},{"option_index":3,"misconception":"Rounded ₹2,150 up to ₹2,200 before multiplying."}],"explanation":"Cost = 2,150 × 40 = ₹86,000.","concept_id":"eco610-food-buffer-stock","strand":"Food Security","kind":"mcq"},{"id":"buffer-stock-foodgrain-the-government-procures-and-stores-through-the-fci-004","band":"K5","grade":9,"subject":"Mathematics","concept":"buffer stock: foodgrain the government procures and stores through the FCI","difficulty":2,"stem":"A buffer stock of 50,000 tonnes of rice is reduced by 12%. How many tonnes is the reduction?","options":["5,000 tonnes","6,500 tonnes","44,000 tonnes","6,000 tonnes"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Calculated 10% of 50,000 instead of 12%."},{"option_index":1,"misconception":"Rounded 12% to 13% before finding the reduction."},{"option_index":2,"misconception":"Found the remaining stock instead of the amount of reduction."}],"explanation":"Reduction = 12% of 50,000 = 0.12 × 50,000 = 6,000 tonnes.","concept_id":"eco610-food-buffer-stock","strand":"Food Security","kind":"mcq"},{"id":"buffer-stock-foodgrain-the-government-procures-and-stores-through-the-fci-005","band":"K5","grade":9,"subject":"Mathematics","concept":"buffer stock: foodgrain the government procures and stores through the FCI","difficulty":2,"stem":"FCI stores foodgrain in sacks of 50 kg each. How many sacks are needed to store 4.5 tonnes? (1 tonne = 1000 kg)","options":["90 sacks","9 sacks","225 sacks","4,500 sacks"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Dropped a zero: divided 450 by 50 instead of 4,500 by 50."},{"option_index":2,"misconception":"Multiplied 4.5 by 50 instead of converting tonnes to kilograms first."},{"option_index":3,"misconception":"Converted to kilograms but forgot to divide by the sack weight."}],"explanation":"4.5 tonnes = 4,500 kg. Sacks = 4,500 ÷ 50 = 90.","concept_id":"eco610-food-buffer-stock","strand":"Food Security","kind":"mcq"},{"id":"buffer-stock-foodgrain-the-government-procures-and-stores-through-the-fci-006","band":"K5","grade":9,"subject":"Mathematics","concept":"buffer stock: foodgrain the government procures and stores through the FCI","difficulty":2,"stem":"A godown has 3 stacks of sacks. Each stack has 120 sacks, and each sack weighs 50 kg. What is the total weight in tonnes?","options":["1.8 tonnes","36 tonnes","180 tonnes","18 tonnes"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Converted kilograms to tonnes by dividing by 10,000 instead of 1,000."},{"option_index":1,"misconception":"Used 100 kg per sack instead of 50 kg."},{"option_index":2,"misconception":"Converted kilograms to tonnes by dividing by 100 instead of 1,000."}],"explanation":"Total sacks = 3 × 120 = 360. Weight = 360 × 50 = 18,000 kg = 18 tonnes.","concept_id":"eco610-food-buffer-stock","strand":"Food Security","kind":"mcq"},{"id":"buffer-stock-foodgrain-the-government-procures-and-stores-through-the-fci-007","band":"K5","grade":9,"subject":"Mathematics","concept":"buffer stock: foodgrain the government procures and stores through the FCI","difficulty":2,"stem":"FCI has 2,400 tonnes of wheat and 1,600 tonnes of rice. What fraction of the total stock is wheat?","options":["2/5","3/2","3/5","5/3"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Found the fraction of rice instead of wheat."},{"option_index":1,"misconception":"Wrote the ratio of wheat to rice as a fraction, not the fraction of total stock."},{"option_index":3,"misconception":"Wrote the reciprocal of the fraction of wheat in the total stock."}],"explanation":"Total = 2,400 + 1,600 = 4,000. Wheat fraction = 2,400/4,000 = 3/5.","concept_id":"eco610-food-buffer-stock","strand":"Food Security","kind":"mcq"},{"id":"buffer-stock-foodgrain-the-government-procures-and-stores-through-the-fci-008","band":"K5","grade":9,"subject":"Mathematics","concept":"buffer stock: foodgrain the government procures and stores through the FCI","difficulty":2,"stem":"FCI procured 12,000, 15,000 and 18,000 tonnes of wheat in three consecutive years. What is the average procurement per year?","options":["15,000 tonnes","12,000 tonnes","13,500 tonnes","45,000 tonnes"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Chose the smallest year's procurement as the average."},{"option_index":2,"misconception":"Averaged only the first two years."},{"option_index":3,"misconception":"Found the total procurement instead of the average."}],"explanation":"Average = (12,000 + 15,000 + 18,000) ÷ 3 = 45,000 ÷ 3 = 15,000 tonnes.","concept_id":"eco610-food-buffer-stock","strand":"Food Security","kind":"mcq"},{"id":"buffer-stock-foodgrain-the-government-procures-and-stores-through-the-fci-009","band":"K5","grade":9,"subject":"Mathematics","concept":"buffer stock: foodgrain the government procures and stores through the FCI","difficulty":2,"stem":"The buffer stock of wheat increased from 20,000 tonnes to 25,000 tonnes. What is the percentage increase?","options":["5%","25%","20%","125%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Divided the increase by 100,000 instead of 20,000."},{"option_index":2,"misconception":"Used the new stock as the base instead of the original stock."},{"option_index":3,"misconception":"Found the new stock as a percentage of the original stock, not the percentage increase."}],"explanation":"Increase = 25,000 − 20,000 = 5,000. Percentage increase = (5,000 ÷ 20,000) × 100 = 25%.","concept_id":"eco610-food-buffer-stock","strand":"Food Security","kind":"mcq"},{"id":"buffer-stock-foodgrain-the-government-procures-and-stores-through-the-fci-010","band":"K5","grade":9,"subject":"Mathematics","concept":"buffer stock: foodgrain the government procures and stores through the FCI","difficulty":2,"stem":"A buffer stock of 30,000 tonnes is planned to last 60 days at a constant daily use. How many tonnes should be used per day?","options":["500 tonnes","50 tonnes","300 tonnes","1,800 tonnes"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Division error: dropped a zero from 500."},{"option_index":2,"misconception":"Divided 30,000 by 100 instead of 60."},{"option_index":3,"misconception":"Multiplied 30 by 60 instead of dividing 30,000 by 60."}],"explanation":"Daily use = 30,000 ÷ 60 = 500 tonnes.","concept_id":"eco610-food-buffer-stock","strand":"Food Security","kind":"mcq"},{"id":"famine-as-an-extreme-widespread-failure-of-food-security-001","band":"K5","grade":9,"subject":"Mathematics","concept":"famine as an extreme, widespread failure of food security","difficulty":2,"stem":"A region has 500,000 people. A famine is declared when more than 20% of the population faces extreme food shortage. If 120,000 people face extreme food shortage, what percentage of the population is that?","options":["20%","12%","24%","30%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Confusing the famine threshold with the actual percentage calculated."},{"option_index":1,"misconception":"Dividing 120,000 by 1,000,000 instead of 500,000."},{"option_index":3,"misconception":"Adding 10% to the threshold instead of computing the actual percentage."}],"explanation":"120,000 ÷ 500,000 = 0.24 = 24%.","concept_id":"eco610-food-famine","strand":"Food Security","kind":"mcq"},{"id":"famine-as-an-extreme-widespread-failure-of-food-security-002","band":"K5","grade":9,"subject":"Mathematics","concept":"famine as an extreme, widespread failure of food security","difficulty":2,"stem":"A family needs 2,200 kcal per person per day for food security. In a famine-affected area, the average available is 1,650 kcal per person per day. What is the percentage deficit?","options":["33%","25%","20%","75%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Computing deficit as a percentage of the available calories (550 ÷ 1,650) instead of the required calories."},{"option_index":2,"misconception":"Using 550 ÷ 2,750 (adding required and available) instead of 550 ÷ 2,200."},{"option_index":3,"misconception":"Computing the percentage of required calories that are available (1,650 ÷ 2,200) instead of the deficit."}],"explanation":"Deficit = (2200 - 1650) = 550 kcal. Percentage deficit = (550 ÷ 2200) × 100 = 25%.","concept_id":"eco610-food-famine","strand":"Food Security","kind":"mcq"},{"id":"famine-as-an-extreme-widespread-failure-of-food-security-003","band":"K5","grade":9,"subject":"Mathematics","concept":"famine as an extreme, widespread failure of food security","difficulty":2,"stem":"A famine relief program distributes 45,000 kg of rice to 3,000 families. If each family gets an equal share, how many kg of rice does each family get?","options":["150 kg","1.5 kg","30 kg","15 kg"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Misplacing the decimal point when dividing by 3,000 (thinking 45,000 ÷ 300 = 150)."},{"option_index":1,"misconception":"Dividing by 30,000 instead of 3,000 (misplacing decimal point)."},{"option_index":2,"misconception":"Dividing total rice by 1,500 families (halving the number of families)."}],"explanation":"45,000 kg ÷ 3,000 families = 15 kg per family.","concept_id":"eco610-food-famine","strand":"Food Security","kind":"mcq"},{"id":"famine-as-an-extreme-widespread-failure-of-food-security-004","band":"K5","grade":9,"subject":"Mathematics","concept":"famine as an extreme, widespread failure of food security","difficulty":2,"stem":"In a famine, the price of a sack of wheat rises from ₹1,200 to ₹1,800. What is the percentage increase?","options":["33%","60%","50%","150%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Computing increase as a percentage of the new price (600 ÷ 1,800) instead of the original price."},{"option_index":1,"misconception":"Computing 600 ÷ 1,000 (using a wrong base of 1,000)."},{"option_index":3,"misconception":"Computing the new price as a percentage of the old price (1,800 ÷ 1,200) instead of the increase."}],"explanation":"Increase = ₹600. Percentage increase = (600 ÷ 1,200) × 100 = 50%.","concept_id":"eco610-food-famine","strand":"Food Security","kind":"mcq"},{"id":"famine-as-an-extreme-widespread-failure-of-food-security-005","band":"K5","grade":9,"subject":"Mathematics","concept":"famine as an extreme, widespread failure of food security","difficulty":2,"stem":"A region's food production dropped from 80,000 tonnes to 48,000 tonnes. What is the percentage decrease?","options":["60%","40%","32%","20%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Computing the remaining fraction (48,000 ÷ 80,000) instead of the decrease."},{"option_index":2,"misconception":"Computing 32,000 ÷ 100,000 (using a wrong base of 100,000)."},{"option_index":3,"misconception":"Computing half the decrease (16,000 ÷ 80,000)."}],"explanation":"Decrease = 80,000 - 48,000 = 32,000 tonnes. Percentage decrease = (32,000 ÷ 80,000) × 100 = 40%.","concept_id":"eco610-food-famine","strand":"Food Security","kind":"mcq"},{"id":"famine-as-an-extreme-widespread-failure-of-food-security-006","band":"K5","grade":9,"subject":"Mathematics","concept":"famine as an extreme, widespread failure of food security","difficulty":2,"stem":"A food security index is calculated as (available food ÷ required food) × 100. If available food is 3,600 tonnes and required food is 4,500 tonnes, what is the index?","options":["125","90","20","80"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Computing required ÷ available (4,500 ÷ 3,600) instead of available ÷ required."},{"option_index":1,"misconception":"Using 3,600 ÷ 4,000 (a wrong denominator) instead of 4,500."},{"option_index":2,"misconception":"Computing the percentage deficit (900 ÷ 4,500) instead of the index."}],"explanation":"(3,600 ÷ 4,500) × 100 = 0.8 × 100 = 80.","concept_id":"eco610-food-famine","strand":"Food Security","kind":"mcq"},{"id":"famine-as-an-extreme-widespread-failure-of-food-security-007","band":"K5","grade":9,"subject":"Mathematics","concept":"famine as an extreme, widespread failure of food security","difficulty":2,"stem":"A famine is declared when the food security index falls below 70. A region has required food of 5,000 tonnes and available food of 3,200 tonnes. What is the food security index?","options":["70","56","64","156"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Confusing the threshold value with the calculated index."},{"option_index":1,"misconception":"Computing 2,800 ÷ 5,000 (using a wrong available value)."},{"option_index":3,"misconception":"Computing required ÷ available (5,000 ÷ 3,200) and rounding."}],"explanation":"(3,200 ÷ 5,000) × 100 = 0.64 × 100 = 64.","concept_id":"eco610-food-famine","strand":"Food Security","kind":"mcq"},{"id":"famine-as-an-extreme-widespread-failure-of-food-security-008","band":"K5","grade":9,"subject":"Mathematics","concept":"famine as an extreme, widespread failure of food security","difficulty":2,"stem":"In a famine, 15% of children under 5 suffer from acute malnutrition. If there are 20,000 children under 5, how many suffer from acute malnutrition?","options":["1,500","3,000","300","15,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Computing 7.5% instead of 15% (halving the percentage)."},{"option_index":2,"misconception":"Misplacing the decimal point when multiplying (20,000 × 0.015)."},{"option_index":3,"misconception":"Computing 75% instead of 15% (misreading the percentage)."}],"explanation":"15% of 20,000 = 0.15 × 20,000 = 3,000.","concept_id":"eco610-food-famine","strand":"Food Security","kind":"mcq"},{"id":"famine-as-an-extreme-widespread-failure-of-food-security-009","band":"K5","grade":9,"subject":"Mathematics","concept":"famine as an extreme, widespread failure of food security","difficulty":2,"stem":"A famine-affected country needs 2.4 million tonnes of grain. It receives 1.8 million tonnes as aid. What fraction of the need is met?","options":["1/2","2/3","4/5","3/4"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Approximating the fraction as one half without calculating."},{"option_index":1,"misconception":"Incorrectly simplifying 1.8/2.4 by dividing numerator and denominator by 0.9 instead of 0.6."},{"option_index":2,"misconception":"Computing 1.6/2.0 (using a wrong numerator) instead of 1.8/2.4."}],"explanation":"1.8 ÷ 2.4 = 18/24 = 3/4.","concept_id":"eco610-food-famine","strand":"Food Security","kind":"mcq"},{"id":"famine-as-an-extreme-widespread-failure-of-food-security-010","band":"K5","grade":9,"subject":"Mathematics","concept":"famine as an extreme, widespread failure of food security","difficulty":2,"stem":"A famine early warning system uses a scale: 1 = minimal, 2 = stressed, 3 = crisis, 4 = emergency, 5 = famine. A region's score is calculated as (number of failed harvests + 1). If there are 3 failed harvests, what is the score?","options":["3","4","5","2"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Using the number of failed harvests directly without adding 1."},{"option_index":2,"misconception":"Adding 2 instead of 1 to the number of failed harvests."},{"option_index":3,"misconception":"Subtracting 1 instead of adding 1."}],"explanation":"Score = 3 + 1 = 4.","concept_id":"eco610-food-famine","strand":"Food Security","kind":"mcq"},{"id":"minimum-support-price-as-the-government-s-procurement-price-paid-to-farmers-001","band":"K5","grade":9,"subject":"Mathematics","concept":"minimum support price as the government's procurement price paid to farmers","difficulty":2,"stem":"The Minimum Support Price (MSP) of paddy is ₹2,000 per quintal. A farmer sells 15 quintals to the government at MSP. How much money does the government pay the farmer?","options":["₹30,000","₹3,000","₹20,000","₹2,015"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Misplaces a zero when multiplying ₹2,000 by 15."},{"option_index":2,"misconception":"Uses only 10 quintals instead of 15."},{"option_index":3,"misconception":"Adds price and quantity (2,000 + 15) instead of multiplying."}],"explanation":"₹2,000 × 15 = ₹30,000.","concept_id":"eco610-food-msp","strand":"Food Security","kind":"mcq"},{"id":"minimum-support-price-as-the-government-s-procurement-price-paid-to-farmers-002","band":"K5","grade":9,"subject":"Mathematics","concept":"minimum support price as the government's procurement price paid to farmers","difficulty":2,"stem":"The MSP of wheat is ₹2,125 per quintal. The market price is ₹1,900 per quintal. How much more per quintal does a farmer get by selling at MSP instead of at market price?","options":["₹125","₹225","₹325","₹4,025"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Subtracts ₹1,900 from ₹2,025 by misaligning the hundreds digit."},{"option_index":2,"misconception":"Subtracts ₹1,900 from ₹2,225 by misaligning the hundreds digit."},{"option_index":3,"misconception":"Adds the two prices instead of finding the difference."}],"explanation":"₹2,125 − ₹1,900 = ₹225.","concept_id":"eco610-food-msp","strand":"Food Security","kind":"mcq"},{"id":"minimum-support-price-as-the-government-s-procurement-price-paid-to-farmers-003","band":"K5","grade":9,"subject":"Mathematics","concept":"minimum support price as the government's procurement price paid to farmers","difficulty":3,"stem":"A farmer produces 80 quintals of rice. The government procures 60% of it at MSP ₹2,000 per quintal. How much does the government pay for the procured quantity?","options":["₹1,60,000","₹1,20,000","₹48,000","₹96,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Uses all 80 quintals at MSP instead of only 60%."},{"option_index":1,"misconception":"Treats 60% as 60 quintals and multiplies by ₹2,000."},{"option_index":2,"misconception":"Finds 48 quintals but multiplies by ₹1,000 instead of ₹2,000."}],"explanation":"60% of 80 = 48 quintals; 48 × ₹2,000 = ₹96,000.","concept_id":"eco610-food-msp","strand":"Food Security","kind":"mcq"},{"id":"minimum-support-price-as-the-government-s-procurement-price-paid-to-farmers-004","band":"K5","grade":9,"subject":"Mathematics","concept":"minimum support price as the government's procurement price paid to farmers","difficulty":3,"stem":"The MSP of a crop increased from ₹1,500 per quintal to ₹1,800 per quintal. What is the percentage increase?","options":["15%","25%","20%","30%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Divides the increase ₹300 by ₹2,000 instead of the original price."},{"option_index":1,"misconception":"Divides the increase ₹300 by ₹1,200 instead of the original price."},{"option_index":3,"misconception":"Divides the increase ₹300 by ₹1,000 instead of the original price."}],"explanation":"Increase = ₹300; percentage increase = (300 ÷ 1500) × 100 = 20%.","concept_id":"eco610-food-msp","strand":"Food Security","kind":"mcq"},{"id":"minimum-support-price-as-the-government-s-procurement-price-paid-to-farmers-005","band":"K5","grade":9,"subject":"Mathematics","concept":"minimum support price as the government's procurement price paid to farmers","difficulty":2,"stem":"The MSP for soybean is ₹4,600 per quintal. A farmer sells 12 quintals to the government at MSP. How much does the government pay?","options":["₹5,520","₹55,000","₹55,200","₹46,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Misplaces the decimal point when multiplying ₹4,600 by 12."},{"option_index":1,"misconception":"Rounds 12 quintals to 10 quintals and multiplies."},{"option_index":3,"misconception":"Uses 10 quintals instead of 12 quintals when multiplying by ₹4,600."}],"explanation":"₹4,600 × 12 = ₹55,200.","concept_id":"eco610-food-msp","strand":"Food Security","kind":"mcq"},{"id":"minimum-support-price-as-the-government-s-procurement-price-paid-to-farmers-006","band":"K5","grade":9,"subject":"Mathematics","concept":"minimum support price as the government's procurement price paid to farmers","difficulty":2,"stem":"The government procures 2,400 kg of wheat at MSP ₹18 per kg. What is the total amount paid?","options":["₹4,320","₹43,000","₹4,32,000","₹43,200"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Divides by 10 instead of multiplying correctly, giving a decimal-place error."},{"option_index":1,"misconception":"Rounds ₹43,200 to ₹43,000."},{"option_index":2,"misconception":"Adds an extra zero when multiplying 2,400 by 18."}],"explanation":"2,400 × ₹18 = ₹43,200.","concept_id":"eco610-food-msp","strand":"Food Security","kind":"mcq"},{"id":"minimum-support-price-as-the-government-s-procurement-price-paid-to-farmers-007","band":"K5","grade":9,"subject":"Mathematics","concept":"minimum support price as the government's procurement price paid to farmers","difficulty":2,"stem":"The MSP for maize is ₹1,850 per quintal. A farmer receives ₹74,000 from the government. How many quintals did the government procure?","options":["40","4","400","37"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Misplaces the decimal point, dividing by 10 too much."},{"option_index":2,"misconception":"Adds an extra zero to the quotient."},{"option_index":3,"misconception":"Rounds ₹1,850 to ₹2,000 and computes 74,000 ÷ 2,000."}],"explanation":"₹74,000 ÷ ₹1,850 = 40 quintals.","concept_id":"eco610-food-msp","strand":"Food Security","kind":"mcq"},{"id":"minimum-support-price-as-the-government-s-procurement-price-paid-to-farmers-008","band":"K5","grade":9,"subject":"Mathematics","concept":"minimum support price as the government's procurement price paid to farmers","difficulty":2,"stem":"A farmer sells 35 quintals at MSP ₹2,400 per quintal. What total amount does the farmer receive?","options":["₹8,400","₹80,000","₹84,000","₹84,400"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Misplaces the decimal point, making the total ten times too small."},{"option_index":1,"misconception":"Uses 35 × ₹2,000 and ignores the ₹400 part of the MSP."},{"option_index":3,"misconception":"Makes a carry error in the multiplication."}],"explanation":"35 × ₹2,400 = ₹84,000.","concept_id":"eco610-food-msp","strand":"Food Security","kind":"mcq"},{"id":"minimum-support-price-as-the-government-s-procurement-price-paid-to-farmers-009","band":"K5","grade":9,"subject":"Mathematics","concept":"minimum support price as the government's procurement price paid to farmers","difficulty":2,"stem":"The MSP is ₹2,000 per quintal. If a farmer earns ₹1,20,000 from selling at MSP, how many quintals were sold?","options":["6","600","50","60"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Misplaces the decimal point, dividing by 10 too much."},{"option_index":1,"misconception":"Adds an extra zero to the correct quotient."},{"option_index":2,"misconception":"Rounds ₹1,20,000 to ₹1,00,000 before dividing."}],"explanation":"₹1,20,000 ÷ ₹2,000 = 60 quintals.","concept_id":"eco610-food-msp","strand":"Food Security","kind":"mcq"},{"id":"minimum-support-price-as-the-government-s-procurement-price-paid-to-farmers-010","band":"K5","grade":9,"subject":"Mathematics","concept":"minimum support price as the government's procurement price paid to farmers","difficulty":3,"stem":"The government pays an MSP of ₹1,600 per quintal for 25 quintals. The market price is ₹1,450 per quintal. How much extra does the farmer get compared to selling all 25 quintals at market price?","options":["₹150","₹3,750","₹37,500","₹4,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Reports only the per-quintal difference, not the total extra for 25 quintals."},{"option_index":2,"misconception":"Adds an extra zero to the total extra amount."},{"option_index":3,"misconception":"Rounds the per-quintal difference to ₹160 and multiplies by 25."}],"explanation":"Extra per quintal = ₹1,600 − ₹1,450 = ₹150; total extra = 150 × 25 = ₹3,750.","concept_id":"eco610-food-msp","strand":"Food Security","kind":"mcq"},{"id":"evolution-of-the-pds-from-universal-to-targeted-tpds-distribution-001","band":"K5","grade":9,"subject":"Mathematics","concept":"evolution of the PDS from universal to targeted (TPDS) distribution","difficulty":2,"stem":"Under the universal PDS, a family got 25 kg of food grains per month. Under TPDS, a BPL family got 10 kg per month. By what percent did the monthly quantity decrease?","options":["15%","40%","60%","250%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Treats the 15 kg decrease as 15% without dividing by the original 25 kg."},{"option_index":1,"misconception":"Uses the new quantity as a fraction of the old (10/25 = 40%) and calls that the decrease."},{"option_index":3,"misconception":"Inverts the ratio and calculates 25/10 = 250% as the decrease."}],"explanation":"Decrease = 25 − 10 = 15 kg, so percent decrease = 15/25 × 100 = 60%.","concept_id":"eco610-food-pds-evolution","strand":"Food Security","kind":"mcq"},{"id":"evolution-of-the-pds-from-universal-to-targeted-tpds-distribution-002","band":"K5","grade":9,"subject":"Mathematics","concept":"evolution of the PDS from universal to targeted (TPDS) distribution","difficulty":2,"stem":"A state had 8,00,000 PDS beneficiaries under the universal system. After TPDS targeting, only 60% of them were identified as BPL. How many BPL beneficiaries were there?","options":["4,80,000","3,20,000","48,000","5,60,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Finds the non-BPL complement (40% of 8,00,000) instead of the BPL number."},{"option_index":2,"misconception":"Makes a place-value error and divides the correct answer by 10."},{"option_index":3,"misconception":"Uses 70% instead of 60%."}],"explanation":"60% of 8,00,000 = 0.60 × 8,00,000 = 4,80,000.","concept_id":"eco610-food-pds-evolution","strand":"Food Security","kind":"mcq"},{"id":"evolution-of-the-pds-from-universal-to-targeted-tpds-distribution-003","band":"K5","grade":9,"subject":"Mathematics","concept":"evolution of the PDS from universal to targeted (TPDS) distribution","difficulty":2,"stem":"Under TPDS, a BPL family gets 35 kg of wheat per month at ₹2 per kg. If the family buys the full quota, what is the monthly cost?","options":["₹105","₹245","₹30","₹70"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Multiplies 35 kg by ₹3 per kg instead of ₹2 per kg."},{"option_index":1,"misconception":"Multiplies by ₹7 per kg, confusing the BPL price with a higher APL price."},{"option_index":2,"misconception":"Uses 15 kg (an APL quota) instead of the BPL quota of 35 kg."}],"explanation":"Cost = 35 kg × ₹2 per kg = ₹70.","concept_id":"eco610-food-pds-evolution","strand":"Food Security","kind":"mcq"},{"id":"evolution-of-the-pds-from-universal-to-targeted-tpds-distribution-004","band":"K5","grade":9,"subject":"Mathematics","concept":"evolution of the PDS from universal to targeted (TPDS) distribution","difficulty":2,"stem":"Under universal PDS, 500 families each got 20 kg of rice per month. Under TPDS, only 300 families each got 25 kg per month. By how many kg did the total monthly rice distribution decrease?","options":["5,000 kg","2,500 kg","7,500 kg","10,000 kg"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Subtracts the number of families (500 − 300 = 200) and multiplies by 25 kg."},{"option_index":2,"misconception":"Gives only the TPDS total and forgets to subtract it from the universal total."},{"option_index":3,"misconception":"Gives only the universal total and does not subtract the TPDS total."}],"explanation":"Universal total = 500 × 20 = 10,000 kg; TPDS total = 300 × 25 = 7,500 kg; decrease = 2,500 kg.","concept_id":"eco610-food-pds-evolution","strand":"Food Security","kind":"mcq"},{"id":"evolution-of-the-pds-from-universal-to-targeted-tpds-distribution-005","band":"K5","grade":9,"subject":"Mathematics","concept":"evolution of the PDS from universal to targeted (TPDS) distribution","difficulty":2,"stem":"A state spent ₹120 crore on PDS under the universal system. Under TPDS, it spent ₹90 crore. By what percent did the spending decrease?","options":["30%","75%","25%","33⅓%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Treats the ₹30 crore decrease as 30%."},{"option_index":1,"misconception":"Calculates 90/120 = 75% and mistakes the remaining percent for the decrease."},{"option_index":3,"misconception":"Uses the new spending ₹90 crore as the base: 30/90 = 33⅓%."}],"explanation":"Decrease = 120 − 90 = ₹30 crore, so percent decrease = 30/120 × 100 = 25%.","concept_id":"eco610-food-pds-evolution","strand":"Food Security","kind":"mcq"},{"id":"evolution-of-the-pds-from-universal-to-targeted-tpds-distribution-006","band":"K5","grade":9,"subject":"Mathematics","concept":"evolution of the PDS from universal to targeted (TPDS) distribution","difficulty":2,"stem":"A district has 45,000 households. TPDS surveys show 36% of them are BPL. How many BPL households are eligible for TPDS ration?","options":["16,200","28,800","1,620","15,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Finds the non-BPL complement (64% of 45,000) instead of the BPL number."},{"option_index":2,"misconception":"Makes a decimal place error and divides the correct answer by 10."},{"option_index":3,"misconception":"Assumes exactly one-third of households are BPL."}],"explanation":"36% of 45,000 = 0.36 × 45,000 = 16,200.","concept_id":"eco610-food-pds-evolution","strand":"Food Security","kind":"mcq"},{"id":"evolution-of-the-pds-from-universal-to-targeted-tpds-distribution-007","band":"K5","grade":9,"subject":"Mathematics","concept":"evolution of the PDS from universal to targeted (TPDS) distribution","difficulty":2,"stem":"Under TPDS, a BPL family gets 20 kg of rice per month, while an APL family gets 15 kg. What is the ratio of the APL quota to the BPL quota?","options":["4:3","1:4","2:3","3:4"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Reverses the ratio and gives BPL:APL instead of APL:BPL."},{"option_index":1,"misconception":"Uses the difference (20 − 15 = 5) and compares it with 20 to get 1:4."},{"option_index":2,"misconception":"Simplifies 15:20 by subtracting 5 from both terms to get 10:15 = 2:3 instead of dividing."}],"explanation":"APL:BPL = 15:20 = 3:4 after dividing both terms by 5.","concept_id":"eco610-food-pds-evolution","strand":"Food Security","kind":"mcq"},{"id":"evolution-of-the-pds-from-universal-to-targeted-tpds-distribution-008","band":"K5","grade":9,"subject":"Mathematics","concept":"evolution of the PDS from universal to targeted (TPDS) distribution","difficulty":2,"stem":"A ration shop sold 480 quintals of grain under universal PDS. After targeting, it sold 360 quintals. What is the ratio of the decrease to the original amount?","options":["1:3","1:4","3:4","4:1"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Compares the decrease 120 to the new amount 360 to get 1:3."},{"option_index":2,"misconception":"Compares the new amount 360 to the original 480 to get 3:4."},{"option_index":3,"misconception":"Reverses the correct ratio to get 4:1."}],"explanation":"Decrease = 480 − 360 = 120 quintals; ratio to original = 120:480 = 1:4.","concept_id":"eco610-food-pds-evolution","strand":"Food Security","kind":"mcq"},{"id":"evolution-of-the-pds-from-universal-to-targeted-tpds-distribution-009","band":"K5","grade":9,"subject":"Mathematics","concept":"evolution of the PDS from universal to targeted (TPDS) distribution","difficulty":2,"stem":"The government allocated 72,000 tonnes of food grains for TPDS. If 5/8 of it was for BPL families and the rest for APL families, how many tonnes were for APL families?","options":["45,000","18,000","27,000","24,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Finds the BPL share (5/8 of 72,000) instead of the APL share."},{"option_index":1,"misconception":"Uses 1/4 of the total instead of 3/8."},{"option_index":3,"misconception":"Uses 1/3 of the total instead of 3/8."}],"explanation":"APL share = 1 − 5/8 = 3/8, so 3/8 × 72,000 = 27,000 tonnes.","concept_id":"eco610-food-pds-evolution","strand":"Food Security","kind":"mcq"},{"id":"evolution-of-the-pds-from-universal-to-targeted-tpds-distribution-010","band":"K5","grade":9,"subject":"Mathematics","concept":"evolution of the PDS from universal to targeted (TPDS) distribution","difficulty":2,"stem":"The number of PDS beneficiaries fell from 12 lakh to 9 lakh after TPDS targeting. What is the ratio of the decrease to the new number of beneficiaries?","options":["1:3","1:4","3:1","3:4"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Compares the decrease 3 lakh to the original 12 lakh to get 1:4."},{"option_index":2,"misconception":"Reverses the correct ratio to get 3:1."},{"option_index":3,"misconception":"Compares the new number 9 lakh to the original 12 lakh to get 3:4."}],"explanation":"Decrease = 12 − 9 = 3 lakh; ratio to new number = 3:9 = 1:3.","concept_id":"eco610-food-pds-evolution","strand":"Food Security","kind":"mcq"},{"id":"public-distribution-system-distributing-food-through-ration-shops-001","band":"K5","grade":9,"subject":"Mathematics","concept":"Public Distribution System: distributing food through ration shops","difficulty":2,"stem":"A ration shop distributes 120 kg of wheat and rice in the ratio 3:2. How many kg of wheat is distributed?","options":["72 kg","48 kg","80 kg","180 kg"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Found the quantity of rice instead of wheat by using the ratio part 2."},{"option_index":2,"misconception":"Inverted the ratio to 2:3 and calculated the wheat share."},{"option_index":3,"misconception":"Multiplied the total by the ratio 3/2 instead of finding the part-to-whole share."}],"explanation":"Total parts = 3+2=5. Wheat = (3/5)×120 = 72 kg.","concept_id":"eco610-food-pds","strand":"Food Security","kind":"mcq"},{"id":"public-distribution-system-distributing-food-through-ration-shops-002","band":"K5","grade":9,"subject":"Mathematics","concept":"Public Distribution System: distributing food through ration shops","difficulty":2,"stem":"A ration shop has 500 kg of food grains. If 15% is lost in storage, how many kg are left?","options":["75 kg","425 kg","485 kg","575 kg"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Found the quantity lost instead of the quantity remaining."},{"option_index":2,"misconception":"Subtracted 15 (the percentage number) from 500 instead of 15% of 500."},{"option_index":3,"misconception":"Added 15% to 500 instead of subtracting."}],"explanation":"Loss = 15% of 500 = 75 kg. Remaining = 500 - 75 = 425 kg.","concept_id":"eco610-food-pds","strand":"Food Security","kind":"mcq"},{"id":"public-distribution-system-distributing-food-through-ration-shops-003","band":"K5","grade":9,"subject":"Mathematics","concept":"Public Distribution System: distributing food through ration shops","difficulty":2,"stem":"A ration shop distributes 3 kg of rice per family. If it has 1 quintal (100 kg) of rice, what is the maximum number of complete families it can serve?","options":["34","100/3","33","300"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Rounded up to 34 instead of rounding down, which would require serving a partial family."},{"option_index":1,"misconception":"Gave the exact quotient 100/3 without considering that only complete families can be served."},{"option_index":3,"misconception":"Multiplied 100 by 3 instead of dividing."}],"explanation":"100 ÷ 3 = 33.33..., so maximum complete families = 33.","concept_id":"eco610-food-pds","strand":"Food Security","kind":"mcq"},{"id":"public-distribution-system-distributing-food-through-ration-shops-004","band":"K5","grade":9,"subject":"Mathematics","concept":"Public Distribution System: distributing food through ration shops","difficulty":2,"stem":"A ration shop has 15 1/2 kg of sugar. It packs them into 1/2 kg packets. How many packets can be made?","options":["7 3/4","16","30","31"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Divided by 2 instead of multiplying by 2 (or multiplied by 1/2)."},{"option_index":1,"misconception":"Added 1/2 to 15 1/2 instead of dividing."},{"option_index":2,"misconception":"Ignored the extra 1/2 kg and used 15 kg only."}],"explanation":"15 1/2 = 31/2. Packets = (31/2) ÷ (1/2) = 31.","concept_id":"eco610-food-pds","strand":"Food Security","kind":"mcq"},{"id":"public-distribution-system-distributing-food-through-ration-shops-005","band":"K5","grade":9,"subject":"Mathematics","concept":"Public Distribution System: distributing food through ration shops","difficulty":2,"stem":"A ration shop distributes wheat to 5 families: 2 kg, 3 kg, 4 kg, 5 kg, and 6 kg. What is the average quantity per family?","options":["4 kg","20 kg","5 kg","10/3 kg"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Found the total sum instead of the average."},{"option_index":2,"misconception":"Divided the sum by 4 instead of 5."},{"option_index":3,"misconception":"Divided the sum by 6 instead of 5."}],"explanation":"Average = (2+3+4+5+6)/5 = 20/5 = 4 kg.","concept_id":"eco610-food-pds","strand":"Food Security","kind":"mcq"},{"id":"public-distribution-system-distributing-food-through-ration-shops-006","band":"K5","grade":9,"subject":"Mathematics","concept":"Public Distribution System: distributing food through ration shops","difficulty":2,"stem":"A ration shop has 800 kg of rice. If 5% is distributed to priority families, how much rice is distributed to priority families?","options":["4000 kg","40 kg","160 kg","760 kg"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Multiplied by 5 instead of 5/100."},{"option_index":2,"misconception":"Divided by 5 instead of multiplying by 0.05."},{"option_index":3,"misconception":"Found the remaining quantity (800 - 40) instead of the distributed quantity."}],"explanation":"Distributed = 5% of 800 = (5/100)×800 = 40 kg.","concept_id":"eco610-food-pds","strand":"Food Security","kind":"mcq"},{"id":"public-distribution-system-distributing-food-through-ration-shops-007","band":"K5","grade":9,"subject":"Mathematics","concept":"Public Distribution System: distributing food through ration shops","difficulty":2,"stem":"A ration shop distributes rice and wheat. The total quantity is 150 kg. If the quantity of rice is twice the quantity of wheat, how many kg of wheat is distributed?","options":["100 kg","75 kg","50 kg","150 kg"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Found the quantity of rice instead of wheat (swapped the ratio)."},{"option_index":1,"misconception":"Divided the total by 2, assuming equal quantities."},{"option_index":3,"misconception":"Gave the total quantity instead of the wheat quantity."}],"explanation":"Let wheat = x, rice = 2x. Then 3x = 150, so x = 50 kg.","concept_id":"eco610-food-pds","strand":"Food Security","kind":"mcq"},{"id":"public-distribution-system-distributing-food-through-ration-shops-008","band":"K5","grade":9,"subject":"Mathematics","concept":"Public Distribution System: distributing food through ration shops","difficulty":2,"stem":"A ration shop distributes 2/5 of its stock of 250 kg of wheat on Monday. How many kg are left?","options":["100 kg","249 3/5 kg","625 kg","150 kg"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Found the quantity distributed instead of the quantity left."},{"option_index":1,"misconception":"Subtracted the fraction 2/5 as a number from 250."},{"option_index":2,"misconception":"Divided 250 by 2/5 instead of multiplying."}],"explanation":"Distributed = (2/5)×250 = 100 kg. Left = 250 - 100 = 150 kg.","concept_id":"eco610-food-pds","strand":"Food Security","kind":"mcq"},{"id":"public-distribution-system-distributing-food-through-ration-shops-009","band":"K5","grade":9,"subject":"Mathematics","concept":"Public Distribution System: distributing food through ration shops","difficulty":2,"stem":"A ration shop has 3 types of grains: rice, wheat, and millet in the ratio 4:3:2. If the total quantity is 180 kg, how many kg of millet is there?","options":["40 kg","90 kg","120 kg","20 kg"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Used the ratio of millet to rice (2/4) instead of to the total."},{"option_index":2,"misconception":"Used the ratio of millet to wheat (2/3) instead of to the total."},{"option_index":3,"misconception":"Found one part (180/9) instead of millet's share."}],"explanation":"Total parts = 4+3+2 = 9. Millet = (2/9)×180 = 40 kg.","concept_id":"eco610-food-pds","strand":"Food Security","kind":"mcq"},{"id":"public-distribution-system-distributing-food-through-ration-shops-010","band":"K5","grade":9,"subject":"Mathematics","concept":"Public Distribution System: distributing food through ration shops","difficulty":2,"stem":"A ration shop increased the quantity of rice distributed per family from 3 kg to 4 kg. What is the percentage increase?","options":["25%","33 1/3 %","33%","133 1/3 %"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Used the new value as the base instead of the original."},{"option_index":2,"misconception":"Truncated the exact fraction 33 1/3 % to 33%."},{"option_index":3,"misconception":"Added 100% to the increase percentage."}],"explanation":"Increase = 1 kg. Percentage increase = (1/3)×100 = 33 1/3 %.","concept_id":"eco610-food-pds","strand":"Food Security","kind":"mcq"},{"id":"role-of-cooperatives-in-running-fair-price-shops-for-food-security-001","band":"K5","grade":9,"subject":"Mathematics","concept":"role of cooperatives in running fair-price shops for food security","difficulty":2,"stem":"A cooperative fair-price shop receives 480 kg of rice. It packs the rice into 5 kg bags for distribution. How many bags can it make?","options":["475","2400","96","485"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Subtracts the bag size from the total instead of dividing."},{"option_index":1,"misconception":"Multiplies total rice by bag size instead of dividing."},{"option_index":3,"misconception":"Adds the bag size to the total instead of dividing."}],"explanation":"480 ÷ 5 = 96 bags.","concept_id":"eco610-food-role-cooperatives","strand":"Food Security","kind":"mcq"},{"id":"role-of-cooperatives-in-running-fair-price-shops-for-food-security-002","band":"K5","grade":9,"subject":"Mathematics","concept":"role of cooperatives in running fair-price shops for food security","difficulty":2,"stem":"A cooperative buys wheat at ₹22 per kg and spends ₹3 per kg on transport. It sells the wheat at ₹25 per kg. What is its profit or loss per kg?","options":["₹3 profit","₹0","₹3 loss","₹6 profit"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Ignores the transport cost and uses only buying price."},{"option_index":2,"misconception":"Reverses profit and loss by using the wrong sign."},{"option_index":3,"misconception":"Adds transport cost to profit instead of subtracting it from selling price."}],"explanation":"Total cost = 22 + 3 = ₹25; selling price = ₹25; profit = ₹0.","concept_id":"eco610-food-role-cooperatives","strand":"Food Security","kind":"mcq"},{"id":"role-of-cooperatives-in-running-fair-price-shops-for-food-security-003","band":"K5","grade":9,"subject":"Mathematics","concept":"role of cooperatives in running fair-price shops for food security","difficulty":2,"stem":"A cooperative fair-price shop has 1,200 kg of wheat. It distributes the wheat equally among 150 families. How many kilograms does each family get?","options":["8","80","1050","180000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Makes a place-value error in the division result."},{"option_index":2,"misconception":"Subtracts the number of families from the total kilograms."},{"option_index":3,"misconception":"Multiplies total kilograms by the number of families."}],"explanation":"1200 ÷ 150 = 8 kg per family.","concept_id":"eco610-food-role-cooperatives","strand":"Food Security","kind":"mcq"},{"id":"role-of-cooperatives-in-running-fair-price-shops-for-food-security-004","band":"K5","grade":9,"subject":"Mathematics","concept":"role of cooperatives in running fair-price shops for food security","difficulty":2,"stem":"A cooperative runs 12 fair-price shops. Each shop serves 85 families, and each family receives 4 kg of rice per month. How much rice do all the shops distribute per month?","options":["1020 kg","340 kg","408 kg","4080 kg"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Finds only 12 × 85 and forgets to multiply by 4 kg per family."},{"option_index":1,"misconception":"Finds only 85 × 4 and forgets the number of shops."},{"option_index":2,"misconception":"Makes a place-value error in the final multiplication."}],"explanation":"12 × 85 × 4 = 4080 kg.","concept_id":"eco610-food-role-cooperatives","strand":"Food Security","kind":"mcq"},{"id":"role-of-cooperatives-in-running-fair-price-shops-for-food-security-005","band":"K5","grade":9,"subject":"Mathematics","concept":"role of cooperatives in running fair-price shops for food security","difficulty":2,"stem":"A cooperative fair-price shop sells rice at ₹30 per kg. For BPL families it gives a 10% discount. How much does a BPL family pay for 5 kg of rice?","options":["₹150","₹135","₹120","₹15"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Ignores the discount and charges the full price."},{"option_index":2,"misconception":"Treats 10% as ₹10 off instead of 10% of the price."},{"option_index":3,"misconception":"Gives only the discount amount instead of the final price paid."}],"explanation":"5 kg costs ₹150; 10% discount = ₹15; payment = 150 − 15 = ₹135.","concept_id":"eco610-food-role-cooperatives","strand":"Food Security","kind":"mcq"},{"id":"role-of-cooperatives-in-running-fair-price-shops-for-food-security-006","band":"K5","grade":9,"subject":"Mathematics","concept":"role of cooperatives in running fair-price shops for food security","difficulty":2,"stem":"A cooperative has 300 kg of sugar. It keeps 10% aside for emergency and distributes the rest equally among 3 fair-price shops. How many kilograms does each shop get?","options":["100 kg","270 kg","90 kg","30 kg"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Ignores the 10% emergency reserve and divides the full amount."},{"option_index":1,"misconception":"Finds the amount left after reserve but forgets to divide among 3 shops."},{"option_index":3,"misconception":"Computes only the 10% reserve amount instead of the distributed amount."}],"explanation":"10% of 300 = 30 kg reserved; 300 − 30 = 270 kg; 270 ÷ 3 = 90 kg per shop.","concept_id":"eco610-food-role-cooperatives","strand":"Food Security","kind":"mcq"},{"id":"role-of-cooperatives-in-running-fair-price-shops-for-food-security-007","band":"K5","grade":9,"subject":"Mathematics","concept":"role of cooperatives in running fair-price shops for food security","difficulty":2,"stem":"A cooperative fair-price shop gives each family 4 kg of wheat and 3 kg of rice. Wheat costs ₹20 per kg and rice costs ₹35 per kg. What is the total cost per family?","options":["₹185","₹245","₹140","₹105"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Swaps the prices of wheat and rice."},{"option_index":2,"misconception":"Uses the rice price for wheat and ignores the rice quantity."},{"option_index":3,"misconception":"Computes only the cost of rice and ignores wheat."}],"explanation":"4 × 20 + 3 × 35 = 80 + 105 = ₹185.","concept_id":"eco610-food-role-cooperatives","strand":"Food Security","kind":"mcq"},{"id":"role-of-cooperatives-in-running-fair-price-shops-for-food-security-008","band":"K5","grade":9,"subject":"Mathematics","concept":"role of cooperatives in running fair-price shops for food security","difficulty":2,"stem":"A cooperative buys 500 kg of dal at ₹80 per kg. It sells the dal at ₹75 per kg to families. What is the total loss?","options":["₹5","₹40,000","₹37,500","₹2500"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Reports the loss per kg instead of the total loss."},{"option_index":1,"misconception":"Computes total cost instead of total loss."},{"option_index":2,"misconception":"Computes total selling price instead of total loss."}],"explanation":"Loss per kg = 80 − 75 = ₹5; total loss = 5 × 500 = ₹2500.","concept_id":"eco610-food-role-cooperatives","strand":"Food Security","kind":"mcq"},{"id":"role-of-cooperatives-in-running-fair-price-shops-for-food-security-009","band":"K5","grade":9,"subject":"Mathematics","concept":"role of cooperatives in running fair-price shops for food security","difficulty":2,"stem":"A cooperative fair-price shop has 2,400 kg of rice. It sells 65% of the stock in the first week. How many kilograms remain?","options":["1560 kg","840 kg","65 kg","2335 kg"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Finds the amount sold instead of the amount remaining."},{"option_index":2,"misconception":"Treats 65% as 65 kg directly."},{"option_index":3,"misconception":"Subtracts 65 from 2400 as if the percentage were a fixed number of kilograms."}],"explanation":"Remaining = 35% of 2400 = 840 kg.","concept_id":"eco610-food-role-cooperatives","strand":"Food Security","kind":"mcq"},{"id":"role-of-cooperatives-in-running-fair-price-shops-for-food-security-010","band":"K5","grade":9,"subject":"Mathematics","concept":"role of cooperatives in running fair-price shops for food security","difficulty":2,"stem":"A cooperative has 8 fair-price shops. The total monthly profit of ₹72,000 is shared equally among the shops for a community fund. How much does each shop get?","options":["₹900","₹576,000","₹9,000","₹7,200"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Makes a place-value error by dividing by 80 instead of 8."},{"option_index":1,"misconception":"Multiplies the total profit by the number of shops instead of dividing."},{"option_index":3,"misconception":"Divides by 10 instead of 8, misplacing a zero."}],"explanation":"72,000 ÷ 8 = ₹9,000 per shop.","concept_id":"eco610-food-role-cooperatives","strand":"Food Security","kind":"mcq"},{"id":"india-s-shift-to-self-sufficiency-in-foodgrains-after-the-green-revolution-001","band":"K5","grade":9,"subject":"Mathematics","concept":"India's shift to self-sufficiency in foodgrains after the Green Revolution","difficulty":2,"stem":"After the Green Revolution, wheat production in a district rose from 20 million tonnes to 25 million tonnes. What was the percentage increase?","options":["20%","125%","25%","5%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses the new production as the base: 5/25 = 20%."},{"option_index":1,"misconception":"Compares new production to old as a percentage: 25/20 = 125%."},{"option_index":3,"misconception":"Reports the absolute increase 5 as a percentage without dividing by the original."}],"explanation":"Increase is 5 million tonnes; 5/20 x 100 = 25%.","concept_id":"eco610-food-self-sufficiency-grain","strand":"Food Security","kind":"mcq"},{"id":"india-s-shift-to-self-sufficiency-in-foodgrains-after-the-green-revolution-002","band":"K5","grade":9,"subject":"Mathematics","concept":"India's shift to self-sufficiency in foodgrains after the Green Revolution","difficulty":2,"stem":"Rice yield in a Green Revolution belt increased from 1500 kg/ha to 2400 kg/ha. What was the percentage increase?","options":["60%","37.5%","160%","90%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses the new yield as the base: 900/2400 = 37.5%."},{"option_index":2,"misconception":"Compares new yield to old as a percentage: 2400/1500 = 160%."},{"option_index":3,"misconception":"Divides the increase by 1000 instead of the original 1500."}],"explanation":"Increase is 900 kg/ha; 900/1500 x 100 = 60%.","concept_id":"eco610-food-self-sufficiency-grain","strand":"Food Security","kind":"mcq"},{"id":"india-s-shift-to-self-sufficiency-in-foodgrains-after-the-green-revolution-003","band":"K5","grade":9,"subject":"Mathematics","concept":"India's shift to self-sufficiency in foodgrains after the Green Revolution","difficulty":2,"stem":"A farmer adopted HYV seeds and his wheat output rose from 4 tonnes to 5.5 tonnes. What was the increase in kilograms?","options":["150 kg","1500 kg","5500 kg","4000 kg"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Makes a decimal-place error when converting 1.5 tonnes to kilograms."},{"option_index":2,"misconception":"Gives the total new output in kilograms instead of the increase."},{"option_index":3,"misconception":"Gives the original output in kilograms instead of the increase."}],"explanation":"Increase is 5.5 - 4 = 1.5 tonnes = 1500 kg.","concept_id":"eco610-food-self-sufficiency-grain","strand":"Food Security","kind":"mcq"},{"id":"india-s-shift-to-self-sufficiency-in-foodgrains-after-the-green-revolution-004","band":"K5","grade":9,"subject":"Mathematics","concept":"India's shift to self-sufficiency in foodgrains after the Green Revolution","difficulty":2,"stem":"Punjab produced 1.2 million tonnes of wheat in 1967-68 and 2.4 million tonnes in 1971-72. What is the ratio of later production to earlier production in simplest form?","options":["1:2","1:3","3:1","2:1"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Inverts the ratio or compares the increase to the later production."},{"option_index":1,"misconception":"Divides the earlier production by the sum: 1.2/3.6 = 1:3."},{"option_index":2,"misconception":"Adds the increase to the earlier production before simplifying: 3.6:1.2 = 3:1."}],"explanation":"Later/earlier = 2.4/1.2 = 2, so the ratio is 2:1.","concept_id":"eco610-food-self-sufficiency-grain","strand":"Food Security","kind":"mcq"},{"id":"india-s-shift-to-self-sufficiency-in-foodgrains-after-the-green-revolution-005","band":"K5","grade":9,"subject":"Mathematics","concept":"India's shift to self-sufficiency in foodgrains after the Green Revolution","difficulty":2,"stem":"Foodgrain production rose from 50 million tonnes to 75 million tonnes. What is the increase as a fraction of the original production?","options":["1/3","2/3","1/2","3/2"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Divides the increase by the new production: 25/75 = 1/3."},{"option_index":1,"misconception":"Divides the original production by the new production: 50/75 = 2/3."},{"option_index":3,"misconception":"Divides the new production by the original production: 75/50 = 3/2."}],"explanation":"Increase is 25; 25/50 = 1/2.","concept_id":"eco610-food-self-sufficiency-grain","strand":"Food Security","kind":"mcq"},{"id":"india-s-shift-to-self-sufficiency-in-foodgrains-after-the-green-revolution-006","band":"K5","grade":9,"subject":"Mathematics","concept":"India's shift to self-sufficiency in foodgrains after the Green Revolution","difficulty":2,"stem":"A state's wheat yield increased from 1.6 t/ha to 2.4 t/ha. What was the increase in yield?","options":["0.8 t/ha","0.8 ha/t","1.5 t/ha","2.4 t/ha"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Writes the yield rate upside down as hectares per tonne."},{"option_index":2,"misconception":"Divides new yield by old yield: 2.4/1.6 = 1.5 instead of subtracting."},{"option_index":3,"misconception":"Reports the final yield instead of the increase in yield."}],"explanation":"Increase = 2.4 - 1.6 = 0.8 t/ha.","concept_id":"eco610-food-self-sufficiency-grain","strand":"Food Security","kind":"mcq"},{"id":"india-s-shift-to-self-sufficiency-in-foodgrains-after-the-green-revolution-007","band":"K5","grade":9,"subject":"Mathematics","concept":"India's shift to self-sufficiency in foodgrains after the Green Revolution","difficulty":2,"stem":"If foodgrain production increased by 25% from 80 million tonnes, what was the new production?","options":["105 million tonnes","20 million tonnes","60 million tonnes","100 million tonnes"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Adds 25 as a flat number to 80 instead of finding 25% of 80."},{"option_index":1,"misconception":"Gives only the increase, not the new total production."},{"option_index":2,"misconception":"Subtracts 25% from 80 instead of adding it."}],"explanation":"80 x 1.25 = 100 million tonnes.","concept_id":"eco610-food-self-sufficiency-grain","strand":"Food Security","kind":"mcq"},{"id":"india-s-shift-to-self-sufficiency-in-foodgrains-after-the-green-revolution-008","band":"K5","grade":9,"subject":"Mathematics","concept":"India's shift to self-sufficiency in foodgrains after the Green Revolution","difficulty":2,"stem":"A farmer uses 3/4 of his 12 hectares for wheat and the rest for rice. How many hectares are used for rice?","options":["9 hectares","3 hectares","4 hectares","6 hectares"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Finds the wheat area, 3/4 of 12, instead of the rice area."},{"option_index":2,"misconception":"Divides the total by 3 instead of finding 1/4 of the land."},{"option_index":3,"misconception":"Assumes half the land is used for rice."}],"explanation":"Rice area = 12 x 1/4 = 3 hectares.","concept_id":"eco610-food-self-sufficiency-grain","strand":"Food Security","kind":"mcq"},{"id":"india-s-shift-to-self-sufficiency-in-foodgrains-after-the-green-revolution-009","band":"K5","grade":9,"subject":"Mathematics","concept":"India's shift to self-sufficiency in foodgrains after the Green Revolution","difficulty":2,"stem":"The Green Revolution increased wheat production by 40% over 5 years. If the initial production was 15 million tonnes, what was the increase in production?","options":["6 million tonnes","21 million tonnes","0.6 million tonnes","9 million tonnes"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds the increase to the original and gives final production."},{"option_index":2,"misconception":"Makes a decimal error and uses 4% instead of 40%."},{"option_index":3,"misconception":"Calculates 60% of 15, using the complement of 40%."}],"explanation":"Increase = 15 x 40/100 = 6 million tonnes.","concept_id":"eco610-food-self-sufficiency-grain","strand":"Food Security","kind":"mcq"},{"id":"india-s-shift-to-self-sufficiency-in-foodgrains-after-the-green-revolution-010","band":"K5","grade":9,"subject":"Mathematics","concept":"India's shift to self-sufficiency in foodgrains after the Green Revolution","difficulty":2,"stem":"In a village, 5 farmers together produce 120 tonnes of wheat. If the production is shared equally, how many tonnes does each farmer produce?","options":["25 tonnes","120 tonnes","24 tonnes","600 tonnes"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Rounds the quotient 24 to 25."},{"option_index":1,"misconception":"Gives the total production instead of the production per farmer."},{"option_index":3,"misconception":"Multiplies 120 by 5 instead of dividing by 5."}],"explanation":"120 / 5 = 24 tonnes per farmer.","concept_id":"eco610-food-self-sufficiency-grain","strand":"Food Security","kind":"mcq"},{"id":"food-security-availability-accessibility-and-affordability-of-food-for-all-001","band":"K5","grade":9,"subject":"Mathematics","concept":"food security: availability, accessibility and affordability of food for all","difficulty":2,"stem":"In a village of 800 people, 600 have access to sufficient food. What fraction of the people lack access to sufficient food?","options":["3/4","1/3","1/4","1/5"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reports the fraction with access (600/800) instead of the fraction lacking access."},{"option_index":1,"misconception":"Uses the part-to-part ratio of people lacking to people having food (200/600)."},{"option_index":3,"misconception":"Divides the number lacking by the total plus the number lacking (200/1000), using the wrong base."}],"explanation":"People lacking = 800 - 600 = 200; fraction = 200/800 = 1/4.","concept_id":"eco610-food-what-is-food-security","strand":"Food Security","kind":"mcq"},{"id":"food-security-availability-accessibility-and-affordability-of-food-for-all-002","band":"K5","grade":9,"subject":"Mathematics","concept":"food security: availability, accessibility and affordability of food for all","difficulty":2,"stem":"A state produces 12,000 tonnes of wheat but needs 15,000 tonnes. What is the shortage as a percentage of the need?","options":["25%","20%","80%","125%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses production (12,000) as the base: 3,000/12,000 = 25%."},{"option_index":2,"misconception":"Calculates availability as a percentage of need (12,000/15,000) instead of shortage."},{"option_index":3,"misconception":"Calculates need as a percentage of production (15,000/12,000) instead of shortage."}],"explanation":"Shortage = 15,000 - 12,000 = 3,000 tonnes; 3,000/15,000 = 20%.","concept_id":"eco610-food-what-is-food-security","strand":"Food Security","kind":"mcq"},{"id":"food-security-availability-accessibility-and-affordability-of-food-for-all-003","band":"K5","grade":9,"subject":"Mathematics","concept":"food security: availability, accessibility and affordability of food for all","difficulty":2,"stem":"A family earns ₹18,000 per month and spends ₹6,300 per month on food. What percentage of the family’s income is spent on food?","options":["3.5%","65%","35%","350%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Converts the decimal 0.35 to a percentage incorrectly as 3.5% instead of 35%."},{"option_index":1,"misconception":"Reports the percentage of income not spent on food (100% - 35%)."},{"option_index":3,"misconception":"Multiplies by 100 twice, treating 0.35 as 350%."}],"explanation":"6300/18000 = 0.35 = 35%.","concept_id":"eco610-food-what-is-food-security","strand":"Food Security","kind":"mcq"},{"id":"food-security-availability-accessibility-and-affordability-of-food-for-all-004","band":"K5","grade":9,"subject":"Mathematics","concept":"food security: availability, accessibility and affordability of food for all","difficulty":2,"stem":"A food bank has 1,200 kg of rice to distribute equally among 80 families. How many kilograms does each family receive?","options":["15 kg","96,000 kg","1/15 kg","150 kg"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Multiplies 1,200 by 80 instead of dividing."},{"option_index":2,"misconception":"Divides 80 by 1,200, inverting the division."},{"option_index":3,"misconception":"Moves the decimal point one place, giving 150 kg instead of 15 kg."}],"explanation":"1,200 kg ÷ 80 = 15 kg per family.","concept_id":"eco610-food-what-is-food-security","strand":"Food Security","kind":"mcq"},{"id":"food-security-availability-accessibility-and-affordability-of-food-for-all-005","band":"K5","grade":9,"subject":"Mathematics","concept":"food security: availability, accessibility and affordability of food for all","difficulty":2,"stem":"A ration shop has 2,400 kg of wheat. It gives 4 kg per person per month. How many people can it support for one month?","options":["9,600","240","60","600"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Multiplies 2,400 by 4 instead of dividing."},{"option_index":1,"misconception":"Divides by 10 instead of by 4."},{"option_index":2,"misconception":"Divides by 40 instead of by 4, misplacing a zero."}],"explanation":"2,400 ÷ 4 = 600 people.","concept_id":"eco610-food-what-is-food-security","strand":"Food Security","kind":"mcq"},{"id":"food-security-availability-accessibility-and-affordability-of-food-for-all-006","band":"K5","grade":9,"subject":"Mathematics","concept":"food security: availability, accessibility and affordability of food for all","difficulty":2,"stem":"The minimum monthly food cost per person is ₹2,100. What is the monthly food cost for a family of 5?","options":["₹420","₹10,500","₹2,105","₹10,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Divides ₹2,100 by 5 instead of multiplying by 5."},{"option_index":2,"misconception":"Adds 5 to ₹2,100 instead of multiplying by 5."},{"option_index":3,"misconception":"Rounds ₹2,100 down to ₹2,000 before multiplying by 5."}],"explanation":"5 × ₹2,100 = ₹10,500.","concept_id":"eco610-food-what-is-food-security","strand":"Food Security","kind":"mcq"},{"id":"food-security-availability-accessibility-and-affordability-of-food-for-all-007","band":"K5","grade":9,"subject":"Mathematics","concept":"food security: availability, accessibility and affordability of food for all","difficulty":2,"stem":"In a survey, 45% of 800 households have a ration card, but only 320 households actually receive food. What percentage of all 800 households receive food?","options":["45%","5%","40%","80%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses the percentage of households with a ration card, not the percentage receiving food."},{"option_index":1,"misconception":"Finds the gap between card holders (360) and receivers (320) as a percentage of all households."},{"option_index":3,"misconception":"Calculates 320 as a percentage of 400 instead of 800."}],"explanation":"320/800 = 0.40 = 40%.","concept_id":"eco610-food-what-is-food-security","strand":"Food Security","kind":"mcq"},{"id":"food-security-availability-accessibility-and-affordability-of-food-for-all-008","band":"K5","grade":9,"subject":"Mathematics","concept":"food security: availability, accessibility and affordability of food for all","difficulty":2,"stem":"A family of 5 consumes 2 kg of rice per person per week. How many kilograms of rice does the family need for 4 weeks?","options":["10 kg","40 kg","20 kg","80 kg"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Calculates only one week’s consumption: 5 × 2 = 10 kg."},{"option_index":2,"misconception":"Calculates for 2 weeks instead of 4 weeks."},{"option_index":3,"misconception":"Multiplies the weekly amount by 8 instead of 4."}],"explanation":"Weekly need = 5 × 2 = 10 kg; for 4 weeks = 10 × 4 = 40 kg.","concept_id":"eco610-food-what-is-food-security","strand":"Food Security","kind":"mcq"},{"id":"food-security-availability-accessibility-and-affordability-of-food-for-all-009","band":"K5","grade":9,"subject":"Mathematics","concept":"food security: availability, accessibility and affordability of food for all","difficulty":2,"stem":"A scheme provides 5 kg of food grain per person per month at ₹3 per kg. What is the monthly cost for a family of 6?","options":["₹15","₹18","₹30","₹90"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Calculates the cost for one person only: 5 × ₹3 = ₹15."},{"option_index":1,"misconception":"Multiplies the number of persons by the price per kg but forgets the 5 kg per person: 6 × ₹3 = ₹18."},{"option_index":2,"misconception":"Calculates total kilograms (6 × 5 = 30) but does not multiply by the price."}],"explanation":"Total grain = 6 × 5 = 30 kg; cost = 30 × ₹3 = ₹90.","concept_id":"eco610-food-what-is-food-security","strand":"Food Security","kind":"mcq"},{"id":"food-security-availability-accessibility-and-affordability-of-food-for-all-010","band":"K5","grade":9,"subject":"Mathematics","concept":"food security: availability, accessibility and affordability of food for all","difficulty":2,"stem":"A village has 2,500 people. If 80% are eligible for food aid and 60% of the eligible people receive it, how many people receive food aid?","options":["1,500","2,000","1,200","3,500"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Applies 60% to all 2,500 people, ignoring the eligibility condition."},{"option_index":1,"misconception":"Stops at the number eligible (80% of 2,500) and does not apply the 60% receiving rate."},{"option_index":3,"misconception":"Adds the two percentages (80% + 60%) and applies 140% to 2,500."}],"explanation":"Eligible = 80% of 2,500 = 2,000; receiving = 60% of 2,000 = 1,200.","concept_id":"eco610-food-what-is-food-security","strand":"Food Security","kind":"mcq"},{"id":"technology-and-government-liberalisation-as-factors-enabling-globalisation-001","band":"K5","grade":10,"subject":"Mathematics","concept":"technology and government liberalisation as factors enabling globalisation","difficulty":2,"stem":"A government liberalised imports by removing a 40% tariff. If an imported item cost ₹700 including the tariff before liberalisation, what is its price after the tariff is removed?","options":["₹500","₹420","₹280","₹560"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Subtracts 40% of the tariff-inclusive price instead of finding the pre-tariff base price."},{"option_index":2,"misconception":"Reports 40% of ₹700 as the final price rather than the tariff amount."},{"option_index":3,"misconception":"Subtracts only 20%, confusing 40% with half its value."}],"explanation":"Base price = 700 / 1.40 = ₹500.","concept_id":"eco610-glo-factors-enabling","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"technology-and-government-liberalisation-as-factors-enabling-globalisation-002","band":"K5","grade":10,"subject":"Mathematics","concept":"technology and government liberalisation as factors enabling globalisation","difficulty":2,"stem":"Using e-commerce technology, a firm's online exports rose from ₹8 crore to ₹10 crore. What is the percentage increase?","options":["20%","25%","80%","125%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses the new value as the denominator (2/10) instead of the original value."},{"option_index":2,"misconception":"Reports the original value as a percent of the new value (8/10)."},{"option_index":3,"misconception":"Reports the final value as a percent of the original value (10/8)."}],"explanation":"Increase = ₹2 crore; 2/8 x 100 = 25%.","concept_id":"eco610-glo-factors-enabling","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"technology-and-government-liberalisation-as-factors-enabling-globalisation-003","band":"K5","grade":10,"subject":"Mathematics","concept":"technology and government liberalisation as factors enabling globalisation","difficulty":2,"stem":"Due to government liberalisation, FDI in a sector rose from ₹12,000 crore to ₹18,000 crore. What fraction of the original FDI is the increase?","options":["1/3","2/3","1/2","3/2"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses the new FDI as the denominator (6000/18000)."},{"option_index":1,"misconception":"Finds the original FDI as a fraction of the new FDI (12000/18000)."},{"option_index":3,"misconception":"Finds the final FDI as a multiple of the original (18000/12000)."}],"explanation":"Increase = ₹6000 crore; 6000/12000 = 1/2.","concept_id":"eco610-glo-factors-enabling","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"technology-and-government-liberalisation-as-factors-enabling-globalisation-004","band":"K5","grade":10,"subject":"Mathematics","concept":"technology and government liberalisation as factors enabling globalisation","difficulty":2,"stem":"Internet calling technology reduced the cost of a 10-minute international call from ₹250 to ₹50. What fraction of the original cost is the decrease?","options":["1/5","5/4","4","4/5"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Reports the remaining cost as a fraction of the original cost (50/250)."},{"option_index":1,"misconception":"Divides the original cost by the decrease (250/200)."},{"option_index":2,"misconception":"Divides the decrease by the new cost (200/50)."}],"explanation":"Decrease = ₹200; 200/250 = 4/5.","concept_id":"eco610-glo-factors-enabling","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"technology-and-government-liberalisation-as-factors-enabling-globalisation-005","band":"K5","grade":10,"subject":"Mathematics","concept":"technology and government liberalisation as factors enabling globalisation","difficulty":2,"stem":"After the government removed import quotas, a country's imports increased from 5 lakh tonnes to 8 lakh tonnes. What fraction of the original imports is the increase?","options":["3/8","3/5","5/8","8/5"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses the new import quantity as the denominator (3/8)."},{"option_index":2,"misconception":"Finds the original imports as a fraction of the new imports (5/8)."},{"option_index":3,"misconception":"Finds the final imports as a multiple of the original (8/5)."}],"explanation":"Increase = 3 lakh tonnes; 3/5 of original.","concept_id":"eco610-glo-factors-enabling","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"technology-and-government-liberalisation-as-factors-enabling-globalisation-006","band":"K5","grade":10,"subject":"Mathematics","concept":"technology and government liberalisation as factors enabling globalisation","difficulty":3,"stem":"Technology helped internet access rise from 20% of a country's population to 65%. What is the increase in percentage points?","options":["45 percentage points","45%","225%","325%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Confuses percentage-point increase with a percent value written using the % sign."},{"option_index":2,"misconception":"Computes the relative percentage increase ((65-20)/20) instead of percentage points."},{"option_index":3,"misconception":"Computes the final value as a percent of the initial value (65/20)."}],"explanation":"65 - 20 = 45 percentage points.","concept_id":"eco610-glo-factors-enabling","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"technology-and-government-liberalisation-as-factors-enabling-globalisation-007","band":"K5","grade":10,"subject":"Mathematics","concept":"technology and government liberalisation as factors enabling globalisation","difficulty":2,"stem":"Before liberalisation, an imported machine cost ₹1,20,000 including a 20% tariff. After the tariff was removed, what is its price?","options":["₹96,000","₹1,44,000","₹24,000","₹1,00,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Subtracts 20% of the tariff-inclusive price instead of finding the pre-tariff base price."},{"option_index":1,"misconception":"Adds 20% instead of removing the tariff."},{"option_index":2,"misconception":"Reports 20% of ₹1,20,000 as the final price rather than the tariff amount."}],"explanation":"Base price = 1,20,000 / 1.20 = ₹1,00,000.","concept_id":"eco610-glo-factors-enabling","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"technology-and-government-liberalisation-as-factors-enabling-globalisation-008","band":"K5","grade":10,"subject":"Mathematics","concept":"technology and government liberalisation as factors enabling globalisation","difficulty":2,"stem":"A courier's international delivery charge was ₹500. Online tracking technology reduced the charge by 12%. What is the new charge?","options":["₹60","₹488","₹440","₹450"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Gives only the amount reduced, not the new charge."},{"option_index":1,"misconception":"Treats 12% as ₹12 and subtracts ₹12."},{"option_index":3,"misconception":"Subtracts 10% instead of 12%."}],"explanation":"12% of ₹500 = ₹60; 500 - 60 = ₹440.","concept_id":"eco610-glo-factors-enabling","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"technology-and-government-liberalisation-as-factors-enabling-globalisation-009","band":"K5","grade":10,"subject":"Mathematics","concept":"technology and government liberalisation as factors enabling globalisation","difficulty":2,"stem":"After liberalisation, the number of foreign banks in a country rose from 4 to 10. By what factor did the number increase?","options":["1.5","6","0.4","2.5"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Confuses 'times more' with 'times as many' and subtracts 1 from the factor."},{"option_index":1,"misconception":"Reports the absolute increase (10 - 4) instead of the factor."},{"option_index":2,"misconception":"Computes old/new (4/10) instead of new/old (10/4)."}],"explanation":"Factor = final/original = 10/4 = 2.5.","concept_id":"eco610-glo-factors-enabling","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"technology-and-government-liberalisation-as-factors-enabling-globalisation-010","band":"K5","grade":10,"subject":"Mathematics","concept":"technology and government liberalisation as factors enabling globalisation","difficulty":3,"stem":"A government reduced import duty from 25% to 10%. By how many percentage points did the duty fall?","options":["15 percentage points","15%","60%","40%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Confuses percentage-point difference with a percent value written using the % sign."},{"option_index":2,"misconception":"Computes the relative decrease ((25-10)/25)."},{"option_index":3,"misconception":"Computes the remaining duty as a percent of the old duty (10/25)."}],"explanation":"25 - 10 = 15 percentage points.","concept_id":"eco610-glo-factors-enabling","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"fair-globalisation-labour-standards-and-policy-needed-for-equitable-outcomes-001","band":"K5","grade":10,"subject":"Mathematics","concept":"fair globalisation: labour standards and policy needed for equitable outcomes","difficulty":2,"stem":"A garment factory pays a worker ₹4,800 for 48 hours of work in a week, with no overtime premium. What is the worker's hourly wage?","options":["₹96","₹120","₹100","₹480"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Divides 4,800 by 50 hours (assuming a 50-hour week) instead of the 48 hours actually worked."},{"option_index":1,"misconception":"Divides 4,800 by 40 hours (the standard full-time week) instead of the 48 hours paid."},{"option_index":3,"misconception":"Place-value slip: divides 4,800 by 10 instead of by 48."}],"explanation":"Hourly wage = total pay ÷ hours worked = 4,800 ÷ 48 = ₹100 per hour.","concept_id":"eco610-glo-fair-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"fair-globalisation-labour-standards-and-policy-needed-for-equitable-outcomes-002","band":"K5","grade":10,"subject":"Mathematics","concept":"fair globalisation: labour standards and policy needed for equitable outcomes","difficulty":2,"stem":"A worker's monthly wage is raised from ₹8,000 to ₹9,200 under a new minimum-wage rule. By what percentage did the wage rise?","options":["115%","15%","13%","67%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Reports the new wage as a percentage of the old wage (9,200 ÷ 8,000 = 115%) instead of the percentage increase."},{"option_index":2,"misconception":"Uses the NEW wage as the base: 1,200 ÷ 9,200 ≈ 13%."},{"option_index":3,"misconception":"Inverts the ratio, dividing the old wage by the increase: 8,000 ÷ 1,200 ≈ 67%."}],"explanation":"Increase = 9,200 − 8,000 = 1,200; percentage rise = 1,200 ÷ 8,000 × 100 = 15%.","concept_id":"eco610-glo-fair-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"fair-globalisation-labour-standards-and-policy-needed-for-equitable-outcomes-003","band":"K5","grade":10,"subject":"Mathematics","concept":"fair globalisation: labour standards and policy needed for equitable outcomes","difficulty":2,"stem":"A factory pays ₹12,500 a month, while a labour standard sets the minimum at ₹15,000. By what fraction of the CURRENT wage must the pay rise to reach the standard?","options":["1/6","5/6","1/5","6/5"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses the new wage as the base: 2,500 ÷ 15,000 = 1/6."},{"option_index":1,"misconception":"Gives the old wage as a fraction of the new wage (12,500 ÷ 15,000 = 5/6) instead of the rise as a fraction of the old wage."},{"option_index":3,"misconception":"Gives the new wage as a multiple of the old (15,000 ÷ 12,500 = 6/5) rather than the fractional increase."}],"explanation":"Rise = 15,000 − 12,500 = 2,500; fraction of current wage = 2,500 ÷ 12,500 = 1/5.","concept_id":"eco610-glo-fair-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"fair-globalisation-labour-standards-and-policy-needed-for-equitable-outcomes-004","band":"K5","grade":10,"subject":"Mathematics","concept":"fair globalisation: labour standards and policy needed for equitable outcomes","difficulty":3,"stem":"A worker's standard week is 45 hours at ₹80 per hour, and every hour beyond 45 is paid at 1.5 times the hourly rate. The worker works 51 hours. What is the total weekly pay?","options":["₹4,080","₹6,120","₹5,880","₹4,320"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Pays all 51 hours at the plain ₹80 rate, ignoring the overtime premium."},{"option_index":1,"misconception":"Pays all 51 hours at the overtime rate of ₹120, applying the premium to the standard hours too."},{"option_index":2,"misconception":"Swaps the rates: pays the 45 standard hours at 1.5× and the 6 overtime hours at the plain rate."}],"explanation":"Standard pay = 45 × 80 = ₹3,600; overtime = 6 × (80 × 1.5) = 6 × 120 = ₹720; total = ₹4,320.","concept_id":"eco610-glo-fair-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"fair-globalisation-labour-standards-and-policy-needed-for-equitable-outcomes-005","band":"K5","grade":10,"subject":"Mathematics","concept":"fair globalisation: labour standards and policy needed for equitable outcomes","difficulty":2,"stem":"Of 240 workers in a factory, 60% are women. A new hiring policy raises the women's share to 3/4 of the unchanged workforce. How many MORE women must be employed?","options":["36","144","180","60"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Gives the number of women before the change (60% of 240 = 144) instead of the increase."},{"option_index":2,"misconception":"Gives the number of women after the change (3/4 of 240 = 180) instead of the increase."},{"option_index":3,"misconception":"Treats the percentage 60 itself as a number of workers."}],"explanation":"Before: 0.60 × 240 = 144 women; after: 0.75 × 240 = 180 women; extra women = 180 − 144 = 36.","concept_id":"eco610-glo-fair-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"fair-globalisation-labour-standards-and-policy-needed-for-equitable-outcomes-006","band":"K5","grade":10,"subject":"Mathematics","concept":"fair globalisation: labour standards and policy needed for equitable outcomes","difficulty":2,"stem":"In a state, 480 out of 1,600 garment units meet a safety labour standard. What percentage of the units do NOT meet it?","options":["30%","43%","75%","70%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Answers with the percentage that DO meet the standard (480 ÷ 1,600 = 30%) instead of those that do not."},{"option_index":1,"misconception":"Divides compliant units by non-compliant units (480 ÷ 1,120 ≈ 43%) instead of by the total."},{"option_index":2,"misconception":"Mis-reads the non-compliant count as 1,200 and simplifies 1,200/1,600 to 3/4 = 75%."}],"explanation":"Non-compliant = 1,600 − 480 = 1,120; percentage = 1,120 ÷ 1,600 × 100 = 70%.","concept_id":"eco610-glo-fair-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"fair-globalisation-labour-standards-and-policy-needed-for-equitable-outcomes-007","band":"K5","grade":10,"subject":"Mathematics","concept":"fair globalisation: labour standards and policy needed for equitable outcomes","difficulty":2,"stem":"A labour standard requires overtime pay of at least 1.5 times the normal hourly rate of ₹96. What is the minimum total overtime pay for 7 hours of overtime?","options":["₹1,008","₹672","₹1,344","₹144"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Pays the 7 hours at the plain rate (7 × 96 = 672), ignoring the 1.5 multiplier."},{"option_index":2,"misconception":"Uses double time (₹192 per hour) instead of 1.5 times the rate."},{"option_index":3,"misconception":"Stops at the overtime hourly rate (96 × 1.5 = 144) instead of the pay for 7 hours."}],"explanation":"Overtime rate = 96 × 1.5 = ₹144 per hour; total = 144 × 7 = ₹1,008.","concept_id":"eco610-glo-fair-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"fair-globalisation-labour-standards-and-policy-needed-for-equitable-outcomes-008","band":"K5","grade":10,"subject":"Mathematics","concept":"fair globalisation: labour standards and policy needed for equitable outcomes","difficulty":3,"stem":"A shirt made in a global supply chain sells for ₹800, and the worker who stitches it is paid ₹120. What fraction of the selling price goes to the worker?","options":["1/6","3/20","20/3","17/20"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Divides the wage by the amount the company keeps (120 ÷ 720 = 1/6) instead of by the selling price."},{"option_index":2,"misconception":"Inverts the ratio and gives the price as a multiple of the wage (800 ÷ 120 = 20/3)."},{"option_index":3,"misconception":"Gives the fraction of the price NOT going to the worker (680 ÷ 800 = 17/20)."}],"explanation":"Worker's share = 120 ÷ 800 = 3/20 of the selling price.","concept_id":"eco610-glo-fair-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"fair-globalisation-labour-standards-and-policy-needed-for-equitable-outcomes-009","band":"K5","grade":10,"subject":"Mathematics","concept":"fair globalisation: labour standards and policy needed for equitable outcomes","difficulty":3,"stem":"In a year a worker's wages rise by 6% while the prices of the goods she buys rise by 10%. By what percentage does her real wage (purchasing power) change?","options":["+4%","+16%","–4%","–16%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Subtracts the smaller rate from the larger without regard to direction, so a loss of purchasing power appears as a gain."},{"option_index":1,"misconception":"Adds the two rates (6% + 10% = 16%) as if both changes pushed purchasing power up."},{"option_index":3,"misconception":"Adds the two rates and then attaches a sign, instead of finding the difference."}],"explanation":"Real change = wage change − price change = 6% − 10% = −4%, i.e. purchasing power falls by 4%.","concept_id":"eco610-glo-fair-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"fair-globalisation-labour-standards-and-policy-needed-for-equitable-outcomes-010","band":"K5","grade":10,"subject":"Mathematics","concept":"fair globalisation: labour standards and policy needed for equitable outcomes","difficulty":3,"stem":"A new wage policy adds ₹2,40,000 to a factory's yearly wage bill, to be shared equally among its 800 workers. How much extra does each worker get per month?","options":["₹300","₹25","₹20","₹2.5"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Stops at the yearly increase per worker (2,40,000 ÷ 800 = 300) and forgets to divide by 12 months."},{"option_index":2,"misconception":"Divides by 1,000 workers instead of 800, then by 12 (2,40,000 ÷ 1,000 ÷ 12 = 20)."},{"option_index":3,"misconception":"Decimal place-value error, giving one-tenth of the correct monthly amount."}],"explanation":"Per worker per year = 2,40,000 ÷ 800 = ₹300; per month = 300 ÷ 12 = ₹25.","concept_id":"eco610-glo-fair-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"foreign-investment-as-capital-an-mnc-brings-to-set-up-production-in-another-country-001","band":"K5","grade":10,"subject":"Mathematics","concept":"foreign investment as capital an MNC brings to set up production in another country","difficulty":2,"stem":"An MNC brings ₹480 crore as foreign investment to set up production in another country, while a local partner contributes ₹120 crore. What percent of the total capital is the foreign investment?","options":["20%","80%","400%","25%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Gives the local partner's share (120/600) instead of the foreign share."},{"option_index":2,"misconception":"Compares foreign capital to local capital (480/120) rather than to total capital."},{"option_index":3,"misconception":"Compares local capital to foreign capital (120/480) rather than finding foreign share of total."}],"explanation":"Total capital = 480+120=600 crore, so foreign share = 480/600 × 100 = 80%.","concept_id":"eco610-glo-foreign-investment","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"foreign-investment-as-capital-an-mnc-brings-to-set-up-production-in-another-country-002","band":"K5","grade":10,"subject":"Mathematics","concept":"foreign investment as capital an MNC brings to set up production in another country","difficulty":2,"stem":"An MNC brings $250 million as foreign investment. If $1 = ₹80, what is this investment in ₹ crore? (1 crore = ₹10,000,000)","options":["₹200 crore","₹20,000 crore","₹25 crore","₹2,000 crore"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Divides by an extra factor of 10 while converting million rupees to crore."},{"option_index":1,"misconception":"Uses 1 crore = 1 million instead of 1 crore = 10 million."},{"option_index":2,"misconception":"Forgets to multiply by the exchange rate ₹80 per dollar."}],"explanation":"$250 million = $250,000,000; × ₹80 = ₹20,000,000,000 = ₹2,000 crore.","concept_id":"eco610-glo-foreign-investment","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"foreign-investment-as-capital-an-mnc-brings-to-set-up-production-in-another-country-003","band":"K5","grade":10,"subject":"Mathematics","concept":"foreign investment as capital an MNC brings to set up production in another country","difficulty":2,"stem":"An MNC plans a total investment of ₹1,200 crore in a foreign country. It brings 3/5 of this as foreign capital. How much foreign capital does the MNC bring?","options":["₹720 crore","₹480 crore","₹2,000 crore","₹240 crore"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Finds the local share (2/5) instead of the foreign share (3/5)."},{"option_index":2,"misconception":"Inverts the fraction and computes 5/3 of the total."},{"option_index":3,"misconception":"Finds only 1/5 of the total instead of 3/5."}],"explanation":"3/5 of ₹1,200 crore = 1,200 ÷ 5 × 3 = ₹720 crore.","concept_id":"eco610-glo-foreign-investment","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"foreign-investment-as-capital-an-mnc-brings-to-set-up-production-in-another-country-004","band":"K5","grade":10,"subject":"Mathematics","concept":"foreign investment as capital an MNC brings to set up production in another country","difficulty":2,"stem":"An MNC brings ₹900 crore as foreign capital. It uses 40% to set up a factory and 25% to buy machinery. What amount of the capital remains?","options":["₹225 crore","₹360 crore","₹585 crore","₹315 crore"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Treats only the machinery amount (25%) as the remaining amount."},{"option_index":1,"misconception":"Treats only the factory amount (40%) as the remaining amount."},{"option_index":2,"misconception":"Adds the two used percentages and reports the amount used (65%), not the amount remaining."}],"explanation":"Used = 40%+25%=65%, remaining = 35% of ₹900 crore = ₹315 crore.","concept_id":"eco610-glo-foreign-investment","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"foreign-investment-as-capital-an-mnc-brings-to-set-up-production-in-another-country-005","band":"K5","grade":10,"subject":"Mathematics","concept":"foreign investment as capital an MNC brings to set up production in another country","difficulty":2,"stem":"An MNC invests ₹5,000 crore in production abroad. If the value of the investment grows at 8% per annum compounded annually, what is its value after 2 years?","options":["₹5,832 crore","₹5,800 crore","₹5,400 crore","₹6,000 crore"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses simple interest for 2 years instead of compound interest."},{"option_index":2,"misconception":"Applies the 8% growth for only one year."},{"option_index":3,"misconception":"Approximates 8% as 10% per year."}],"explanation":"₹5,000 × 1.08² = ₹5,000 × 1.1664 = ₹5,832 crore.","concept_id":"eco610-glo-foreign-investment","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"foreign-investment-as-capital-an-mnc-brings-to-set-up-production-in-another-country-006","band":"K5","grade":10,"subject":"Mathematics","concept":"foreign investment as capital an MNC brings to set up production in another country","difficulty":2,"stem":"In a joint venture, an MNC holds 60% of the total capital and the local partner holds 40%. If total capital is ₹2,500 crore, how much more capital does the MNC bring than the local partner?","options":["₹1,000 crore","₹1,500 crore","₹500 crore","₹2,500 crore"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Gives the local partner's share (40%) instead of the difference."},{"option_index":1,"misconception":"Gives the MNC's share (60%) instead of the difference."},{"option_index":3,"misconception":"Gives the total capital instead of subtracting to find the difference."}],"explanation":"Difference in shares = 60%−40%=20%; 20% of ₹2,500 crore = ₹500 crore.","concept_id":"eco610-glo-foreign-investment","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"foreign-investment-as-capital-an-mnc-brings-to-set-up-production-in-another-country-007","band":"K5","grade":10,"subject":"Mathematics","concept":"foreign investment as capital an MNC brings to set up production in another country","difficulty":2,"stem":"An MNC brings foreign capital in two installments: ₹350 crore and ₹475 crore. How much total foreign capital does it bring?","options":["₹725 crore","₹825 crore","₹815 crore","₹850 crore"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Subtracts the smaller installment from the larger instead of adding."},{"option_index":2,"misconception":"Makes a place-value error while adding the tens column."},{"option_index":3,"misconception":"Rounds ₹475 crore to ₹500 crore before adding."}],"explanation":"₹350 crore + ₹475 crore = ₹825 crore.","concept_id":"eco610-glo-foreign-investment","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"foreign-investment-as-capital-an-mnc-brings-to-set-up-production-in-another-country-008","band":"K5","grade":10,"subject":"Mathematics","concept":"foreign investment as capital an MNC brings to set up production in another country","difficulty":2,"stem":"An MNC needs total capital of ₹4,800 crore to set up production abroad. Foreign investment provides 5/8 of this. How much capital must be raised locally?","options":["₹3,000 crore","₹2,400 crore","₹1,200 crore","₹1,800 crore"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Gives the foreign investment (5/8) instead of the local share."},{"option_index":1,"misconception":"Assumes the local share is one half of the total."},{"option_index":2,"misconception":"Finds 1/4 of the total instead of the remaining 3/8."}],"explanation":"Local share = 1 − 5/8 = 3/8; 3/8 of ₹4,800 crore = ₹1,800 crore.","concept_id":"eco610-glo-foreign-investment","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"foreign-investment-as-capital-an-mnc-brings-to-set-up-production-in-another-country-009","band":"K5","grade":10,"subject":"Mathematics","concept":"foreign investment as capital an MNC brings to set up production in another country","difficulty":2,"stem":"An MNC invests ₹1,600 crore in a foreign country. It earns a profit equal to 25% of the investment. The host country taxes this profit at 12%. What is the tax amount?","options":["₹48 crore","₹192 crore","₹400 crore","₹240 crore"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Applies the 12% tax directly to the whole investment instead of to the profit."},{"option_index":2,"misconception":"Gives the profit before tax, not the tax amount."},{"option_index":3,"misconception":"Includes the investment in the taxable base by taxing ₹1,600 crore + ₹400 crore."}],"explanation":"Profit = 25% of ₹1,600 crore = ₹400 crore; tax = 12% of ₹400 crore = ₹48 crore.","concept_id":"eco610-glo-foreign-investment","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"foreign-investment-as-capital-an-mnc-brings-to-set-up-production-in-another-country-010","band":"K5","grade":10,"subject":"Mathematics","concept":"foreign investment as capital an MNC brings to set up production in another country","difficulty":2,"stem":"An MNC brings ₹2,000 crore as foreign capital to set up production. It spends 30% on land and 45% on plant. The rest is kept for working capital. How much is kept for working capital?","options":["₹600 crore","₹900 crore","₹500 crore","₹1,500 crore"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Takes only the land amount (30%) as working capital."},{"option_index":1,"misconception":"Takes only the plant amount (45%) as working capital."},{"option_index":3,"misconception":"Gives the total amount spent (75%), not the amount remaining."}],"explanation":"Spent = 30%+45%=75%, working capital = 25% of ₹2,000 crore = ₹500 crore.","concept_id":"eco610-glo-foreign-investment","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"how-globalisation-widens-consumer-choice-and-product-variety-001","band":"K5","grade":10,"subject":"Mathematics","concept":"how globalisation widens consumer choice and product variety","difficulty":2,"stem":"After globalisation, a store stocks 6 smartphone brands. Each brand comes in 4 colours, and each colour is available with 3 storage variants. How many distinct smartphone choices are there?","options":["13","24","42","72"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Adds 6 + 4 + 3 instead of multiplying the number of independent choices."},{"option_index":1,"misconception":"Multiplies brands and colours only, forgetting the storage variants."},{"option_index":2,"misconception":"Multiplies brands by the sum of colours and storage variants, 6 × (4 + 3)."}],"explanation":"Use the multiplication principle: 6 × 4 × 3 = 72.","concept_id":"eco610-glo-impact-consumers","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"how-globalisation-widens-consumer-choice-and-product-variety-002","band":"K5","grade":10,"subject":"Mathematics","concept":"how globalisation widens consumer choice and product variety","difficulty":2,"stem":"A global shoe retailer offers 5 international brands. Each brand has 7 designs, and each design comes in 8 sizes. How many distinct shoe options does the retailer offer?","options":["20","35","280","56"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Adds 5 + 7 + 8 instead of multiplying."},{"option_index":1,"misconception":"Multiplies brands and designs only, forgetting sizes."},{"option_index":3,"misconception":"Multiplies designs and sizes only, forgetting brands."}],"explanation":"5 × 7 × 8 = 280.","concept_id":"eco610-glo-impact-consumers","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"how-globalisation-widens-consumer-choice-and-product-variety-003","band":"K5","grade":10,"subject":"Mathematics","concept":"how globalisation widens consumer choice and product variety","difficulty":2,"stem":"Before globalisation, a town had 12 types of breakfast cereal. After globalisation, the variety increased by 150%. How many types of breakfast cereal are there now?","options":["18","30","24","162"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Treats 150% of the original as the new total instead of adding the increase."},{"option_index":2,"misconception":"Confuses a 150% increase with a 100% increase, doubling 12."},{"option_index":3,"misconception":"Adds the percentage number 150 directly to 12."}],"explanation":"150% of 12 is 18, so total = 12 + 18 = 30.","concept_id":"eco610-glo-impact-consumers","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"how-globalisation-widens-consumer-choice-and-product-variety-004","band":"K5","grade":10,"subject":"Mathematics","concept":"how globalisation widens consumer choice and product variety","difficulty":2,"stem":"A grocery chain sells 9 global brands of tea. Each brand offers 5 flavours, and each flavour comes in 2 package sizes. How many distinct tea choices are available?","options":["16","45","90","18"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Adds 9 + 5 + 2 instead of multiplying."},{"option_index":1,"misconception":"Multiplies brands and flavours only, ignoring package sizes."},{"option_index":3,"misconception":"Multiplies brands and package sizes only, ignoring flavours."}],"explanation":"9 × 5 × 2 = 90.","concept_id":"eco610-glo-impact-consumers","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"how-globalisation-widens-consumer-choice-and-product-variety-005","band":"K5","grade":10,"subject":"Mathematics","concept":"how globalisation widens consumer choice and product variety","difficulty":2,"stem":"The number of shampoo brands in a shop rose from 8 to 20 after globalisation. What is the percentage increase in the number of brands?","options":["150%","60%","250%","12%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses the new total, 20, as the base: (20 − 8)/20 × 100."},{"option_index":2,"misconception":"Computes the new total as a percentage of the old total: 20/8 × 100."},{"option_index":3,"misconception":"Reports only the absolute increase, 20 − 8 = 12, as a percentage."}],"explanation":"Increase = 12; percentage increase = (12/8) × 100 = 150%.","concept_id":"eco610-glo-impact-consumers","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"how-globalisation-widens-consumer-choice-and-product-variety-006","band":"K5","grade":10,"subject":"Mathematics","concept":"how globalisation widens consumer choice and product variety","difficulty":2,"stem":"A global streaming service offers 4 languages. For each language, there are 6 genres, and each genre has 5 subscription tiers. How many distinct language-genre-tier combinations are offered?","options":["15","24","30","120"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Adds 4 + 6 + 5 instead of multiplying."},{"option_index":1,"misconception":"Multiplies languages and genres only, forgetting subscription tiers."},{"option_index":2,"misconception":"Multiplies genres and tiers only, forgetting languages."}],"explanation":"4 × 6 × 5 = 120.","concept_id":"eco610-glo-impact-consumers","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"how-globalisation-widens-consumer-choice-and-product-variety-007","band":"K5","grade":10,"subject":"Mathematics","concept":"how globalisation widens consumer choice and product variety","difficulty":2,"stem":"A supermarket once sold 15 varieties of imported cheese. After a trade agreement, it now sells 45 varieties. The new variety count is how many times the original count?","options":["2","3","30","45"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Treats the increase factor as the difference divided by the original: (45 − 15)/15 = 2."},{"option_index":2,"misconception":"Gives the absolute increase, 45 − 15 = 30, instead of the multiplier."},{"option_index":3,"misconception":"Gives the new count itself rather than how many times the original count."}],"explanation":"Multiplier = new ÷ original = 45 ÷ 15 = 3.","concept_id":"eco610-glo-impact-consumers","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"how-globalisation-widens-consumer-choice-and-product-variety-008","band":"K5","grade":10,"subject":"Mathematics","concept":"how globalisation widens consumer choice and product variety","difficulty":2,"stem":"A global furniture store offers 3 sofa styles. Each style can be ordered in 5 fabrics, and each fabric is available in 4 leg finishes. How many distinct sofa choices are possible?","options":["12","15","60","20"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Adds 3 + 5 + 4 instead of multiplying."},{"option_index":1,"misconception":"Multiplies styles and fabrics only, forgetting leg finishes."},{"option_index":3,"misconception":"Multiplies fabrics and leg finishes only, forgetting sofa styles."}],"explanation":"3 × 5 × 4 = 60.","concept_id":"eco610-glo-impact-consumers","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"how-globalisation-widens-consumer-choice-and-product-variety-009","band":"K5","grade":10,"subject":"Mathematics","concept":"how globalisation widens consumer choice and product variety","difficulty":2,"stem":"A country had 7 domestic car models. After globalisation, 6 foreign brands entered, and each brand offered 4 models. How many car models are available in total?","options":["17","31","24","42"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Adds 7 + 6 + 4, treating the number of brands as if it were models."},{"option_index":2,"misconception":"Counts only the foreign models: 6 × 4 = 24."},{"option_index":3,"misconception":"Multiplies domestic models by foreign brands: 7 × 6 = 42, ignoring the 4 models per brand."}],"explanation":"Foreign models = 6 × 4 = 24; total = 7 + 24 = 31.","concept_id":"eco610-glo-impact-consumers","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"how-globalisation-widens-consumer-choice-and-product-variety-010","band":"K5","grade":10,"subject":"Mathematics","concept":"how globalisation widens consumer choice and product variety","difficulty":2,"stem":"A store had 40 imported product lines. After globalisation, it added 25 new imported product lines. What is the percentage increase in imported product lines?","options":["25%","40%","62.5%","65%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Treats the number of new lines, 25, as the percentage increase."},{"option_index":1,"misconception":"Reports the original count, 40, as a percentage."},{"option_index":3,"misconception":"Adds the original and the increase, 40 + 25, to get 65%."}],"explanation":"Percentage increase = (25/40) × 100 = 62.5%.","concept_id":"eco610-glo-impact-consumers","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"uneven-impact-of-globalisation-on-small-local-producers-versus-large-firms-001","band":"K5","grade":10,"subject":"Mathematics","concept":"uneven impact of globalisation on small local producers versus large firms","difficulty":2,"stem":"A large firm's annual profit rises from ₹4,00,000 to ₹5,00,000 after globalisation. What is the percentage increase in its profit?","options":["25%","20%","125%","80%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses the new profit as the base, computing 1,00,000/5,00,000."},{"option_index":2,"misconception":"Expresses the new profit as a percentage of the old profit instead of the increase."},{"option_index":3,"misconception":"Expresses the old profit as a percentage of the new profit or subtracts 20 from 100."}],"explanation":"Increase = ₹1,00,000; percentage increase = 1,00,000/4,00,000 × 100 = 25%.","concept_id":"eco610-glo-impact-producers-uneven","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"uneven-impact-of-globalisation-on-small-local-producers-versus-large-firms-002","band":"K5","grade":10,"subject":"Mathematics","concept":"uneven impact of globalisation on small local producers versus large firms","difficulty":2,"stem":"A small producer sold 800 items at ₹15 each before globalisation. After imports arrived, sales fell by 40%. How many items were sold after?","options":["320","480","760","1120"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Calculates 40% of 800 as the number lost, not the number remaining."},{"option_index":2,"misconception":"Subtracts 40 items, treating 40% as 40 units."},{"option_index":3,"misconception":"Adds 40% instead of subtracting for a fall."}],"explanation":"40% of 800 = 320; items remaining = 800 − 320 = 480.","concept_id":"eco610-glo-impact-producers-uneven","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"uneven-impact-of-globalisation-on-small-local-producers-versus-large-firms-003","band":"K5","grade":10,"subject":"Mathematics","concept":"uneven impact of globalisation on small local producers versus large firms","difficulty":2,"stem":"A large firm's profit rises from ₹80,000 to ₹1,00,000. A small producer's profit falls from ₹40,000 to ₹30,000. What is the net change in their combined profit?","options":["₹30,000 increase","₹10,000 decrease","₹10,000 increase","₹20,000 increase"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Adds the sizes of both changes (₹20,000 + ₹10,000) while ignoring the fall."},{"option_index":1,"misconception":"Reverses the sign of the net change."},{"option_index":3,"misconception":"Counts only the large firm's increase and ignores the small producer's fall."}],"explanation":"Large change = +₹20,000, small change = −₹10,000; net = +₹10,000.","concept_id":"eco610-glo-impact-producers-uneven","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"uneven-impact-of-globalisation-on-small-local-producers-versus-large-firms-004","band":"K5","grade":10,"subject":"Mathematics","concept":"uneven impact of globalisation on small local producers versus large firms","difficulty":3,"stem":"A small producer's market share falls from 20% to 15%. What is the percentage decrease relative to its original share?","options":["5%","33⅓%","75%","25%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Confuses the 5 percentage-point drop with the relative percentage decrease."},{"option_index":1,"misconception":"Uses the new share as the base, computing 5/15."},{"option_index":2,"misconception":"Takes the new share as a percentage of the old share (15/20) instead of the decrease."}],"explanation":"Decrease = 20% − 15% = 5 percentage points; relative decrease = 5/20 × 100 = 25%.","concept_id":"eco610-glo-impact-producers-uneven","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"uneven-impact-of-globalisation-on-small-local-producers-versus-large-firms-005","band":"K5","grade":10,"subject":"Mathematics","concept":"uneven impact of globalisation on small local producers versus large firms","difficulty":2,"stem":"A large firm hires 1,200 workers and a small producer hires 80. After globalisation, the large firm hires 25% more workers, while the small producer lays off 25%. How many more workers does the large firm have than the small producer after these changes?","options":["1440","1120","1420","1140"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Finds the difference before any change: 1200 − 80."},{"option_index":2,"misconception":"Applies the 25% increase to the large firm only and leaves the small producer unchanged."},{"option_index":3,"misconception":"Applies the 25% decrease to the small producer only and leaves the large firm unchanged."}],"explanation":"Large after = 1200 × 1.25 = 1500; small after = 80 × 0.75 = 60; difference = 1500 − 60 = 1440.","concept_id":"eco610-glo-impact-producers-uneven","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"uneven-impact-of-globalisation-on-small-local-producers-versus-large-firms-006","band":"K5","grade":10,"subject":"Mathematics","concept":"uneven impact of globalisation on small local producers versus large firms","difficulty":3,"stem":"A small producer and a large firm each had revenue of ₹2,00,000. After globalisation, the small producer's revenue falls by 30% and the large firm's revenue rises by 30%. What is their combined revenue after these changes?","options":["₹3,80,000","₹4,00,000","₹4,60,000","₹3,40,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Assumes the net effect is a 10% fall on the total combined revenue."},{"option_index":2,"misconception":"Adds the large firm's increase to the total but ignores the small producer's fall."},{"option_index":3,"misconception":"Subtracts the small producer's fall from the total but ignores the large firm's increase."}],"explanation":"Small after = ₹1,40,000, large after = ₹2,60,000; combined = ₹4,00,000.","concept_id":"eco610-glo-impact-producers-uneven","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"uneven-impact-of-globalisation-on-small-local-producers-versus-large-firms-007","band":"K5","grade":10,"subject":"Mathematics","concept":"uneven impact of globalisation on small local producers versus large firms","difficulty":3,"stem":"A large firm's export revenue is ₹12,00,000 and a small producer's export revenue is ₹1,50,000. After globalisation, the large firm's revenue becomes 1.5 times its old value, while the small producer's becomes 0.8 times its old value. What is the difference in their revenues after these changes?","options":["₹10,50,000","₹16,50,000","₹16,80,000","₹10,80,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Finds the difference before the changes: 12,00,000 − 1,50,000."},{"option_index":1,"misconception":"Uses the large firm's new revenue minus the small producer's old revenue."},{"option_index":3,"misconception":"Uses the large firm's old revenue minus the small producer's new revenue."}],"explanation":"Large after = 12,00,000 × 1.5 = ₹18,00,000; small after = 1,50,000 × 0.8 = ₹1,20,000; difference = ₹16,80,000.","concept_id":"eco610-glo-impact-producers-uneven","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"uneven-impact-of-globalisation-on-small-local-producers-versus-large-firms-008","band":"K5","grade":10,"subject":"Mathematics","concept":"uneven impact of globalisation on small local producers versus large firms","difficulty":2,"stem":"In a market worth ₹1,00,00,000, small producers' share falls from 25% to 15%. By how much does their market value decrease?","options":["₹25,00,000","₹15,00,000","₹40,00,000","₹10,00,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Reports the initial market value instead of the decrease."},{"option_index":1,"misconception":"Reports the final market value instead of the decrease."},{"option_index":2,"misconception":"Adds the initial and final market values."}],"explanation":"Initial value = 25% of ₹1,00,00,000 = ₹25,00,000; final = ₹15,00,000; decrease = ₹10,00,000.","concept_id":"eco610-glo-impact-producers-uneven","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"uneven-impact-of-globalisation-on-small-local-producers-versus-large-firms-009","band":"K5","grade":10,"subject":"Mathematics","concept":"uneven impact of globalisation on small local producers versus large firms","difficulty":2,"stem":"A large firm uses 8 machines each producing 250 units per day, while a small producer uses 3 machines each producing 80 units per day. After globalisation, the large firm increases output by 20% and the small producer decreases output by 50%. What is the new total output per day?","options":["2520","2240","2688","1120"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Finds the total output before any change."},{"option_index":2,"misconception":"Applies the 20% increase to both the large firm and the small producer."},{"option_index":3,"misconception":"Applies the 50% decrease to both the large firm and the small producer."}],"explanation":"Large after = 8×250×1.2 = 2400; small after = 3×80×0.5 = 120; total = 2520.","concept_id":"eco610-glo-impact-producers-uneven","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"uneven-impact-of-globalisation-on-small-local-producers-versus-large-firms-010","band":"K5","grade":10,"subject":"Mathematics","concept":"uneven impact of globalisation on small local producers versus large firms","difficulty":3,"stem":"A small producer's income is ₹18,000 and falls by 1/3. A large firm's income is ₹45,000 and rises by 1/5. What is the difference between the large firm's new income and the small producer's new income?","options":["₹27,000","₹42,000","₹30,000","₹36,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Finds the difference before the changes: ₹45,000 − ₹18,000."},{"option_index":2,"misconception":"Starts with the old difference and adds the net change (₹9,000 − ₹6,000) to it."},{"option_index":3,"misconception":"Uses the large firm's new income minus the small producer's old income."}],"explanation":"Small after = ₹18,000 × 2/3 = ₹12,000; large after = ₹45,000 × 6/5 = ₹54,000; difference = ₹42,000.","concept_id":"eco610-glo-impact-producers-uneven","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"multinational-corporations-and-how-they-organise-production-across-countries-001","band":"K5","grade":10,"subject":"Mathematics","concept":"multinational corporations and how they organise production across countries","difficulty":2,"stem":"An MNC makes phones in two countries. Plant A produces 40% of the total output, and Plant B produces the rest. If Plant A produces 12,000 phones, what is the total output?","options":["4,800 phones","30,000 phones","20,000 phones","16,800 phones"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Finds 40% of 12,000 instead of treating 12,000 as 40% of the total."},{"option_index":2,"misconception":"Treats 12,000 as 60% of the total (using the complement percent)."},{"option_index":3,"misconception":"Adds 40% to 12,000 (percent increase) rather than solving part-to-whole."}],"explanation":"40% of total = 12,000, so total = 12,000 ÷ 0.40 = 30,000.","concept_id":"eco610-glo-mnc","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"multinational-corporations-and-how-they-organise-production-across-countries-002","band":"K5","grade":10,"subject":"Mathematics","concept":"multinational corporations and how they organise production across countries","difficulty":2,"stem":"An MNC buys a phone part in Country Y for $8. Shipping it to Country X adds 25% to the cost. What is the total cost per part?","options":["$2","$8.25","$10","$32"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Computes only the 25% shipping increase, not the total cost."},{"option_index":1,"misconception":"Misplaces the decimal when converting 25% to dollars (treats it as $0.25 instead of 25% of $8)."},{"option_index":3,"misconception":"Confuses 25% with 400% (multiplying by 4)."}],"explanation":"Shipping = 25% of $8 = $2, so total = $8 + $2 = $10.","concept_id":"eco610-glo-mnc","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"multinational-corporations-and-how-they-organise-production-across-countries-003","band":"K5","grade":10,"subject":"Mathematics","concept":"multinational corporations and how they organise production across countries","difficulty":2,"stem":"An MNC earns a total profit of $90,000 from three countries. Country A gets 2/5 of the profit, Country B gets 1/3, and Country C gets the rest. How much profit does Country C get?","options":["$54,000","$36,000","$30,000","$24,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Subtracts only Country A's share from the total, ignoring Country B."},{"option_index":1,"misconception":"Gives Country C Country A's share instead of the remaining share."},{"option_index":2,"misconception":"Gives Country C Country B's share instead of the remaining share."}],"explanation":"A = 2/5 × 90,000 = 36,000; B = 1/3 × 90,000 = 30,000; C = 90,000 − 36,000 − 30,000 = 24,000.","concept_id":"eco610-glo-mnc","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"multinational-corporations-and-how-they-organise-production-across-countries-004","band":"K5","grade":10,"subject":"Mathematics","concept":"multinational corporations and how they organise production across countries","difficulty":2,"stem":"An MNC has factories in two countries. Factory A produces 2/5 of the total output. Factory B produces 18,000 units. What is the total output?","options":["12,000 units","30,000 units","27,000 units","45,000 units"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Finds Factory A's output instead of the total output."},{"option_index":2,"misconception":"Adds half of Factory B's output to Factory B (uses 3/2 instead of 5/3)."},{"option_index":3,"misconception":"Divides by Factory A's fraction (2/5) instead of Factory B's fraction (3/5)."}],"explanation":"B produces 3/5 of total = 18,000, so total = 18,000 × 5/3 = 30,000.","concept_id":"eco610-glo-mnc","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"multinational-corporations-and-how-they-organise-production-across-countries-005","band":"K5","grade":10,"subject":"Mathematics","concept":"multinational corporations and how they organise production across countries","difficulty":2,"stem":"An MNC pays workers in Country A $6 per hour and in Country B $4.50 per hour. A worker in A works 35 hours and a worker in B works 40 hours. What is the total wage cost for both workers?","options":["$450","$370","$390","$397.50"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses Country A's higher wage for both workers."},{"option_index":1,"misconception":"Rounds Country B's wage down to $4 per hour."},{"option_index":3,"misconception":"Swaps the hours worked between the two countries."}],"explanation":"A: 6 × 35 = 210; B: 4.50 × 40 = 180; total = 210 + 180 = 390.","concept_id":"eco610-glo-mnc","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"multinational-corporations-and-how-they-organise-production-across-countries-006","band":"K5","grade":10,"subject":"Mathematics","concept":"multinational corporations and how they organise production across countries","difficulty":2,"stem":"An MNC produces 24,000 units across three countries in the ratio 2 : 3 : 5. How many units does the country with the largest share produce?","options":["4,800 units","7,200 units","2,400 units","12,000 units"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Finds the smallest share (2 parts) instead of the largest."},{"option_index":1,"misconception":"Finds the middle share (3 parts) instead of the largest."},{"option_index":2,"misconception":"Finds the value of one ratio part (1 part) instead of five parts."}],"explanation":"Total parts = 2+3+5 = 10; largest = 5/10 × 24,000 = 12,000.","concept_id":"eco610-glo-mnc","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"multinational-corporations-and-how-they-organise-production-across-countries-007","band":"K5","grade":10,"subject":"Mathematics","concept":"multinational corporations and how they organise production across countries","difficulty":2,"stem":"An MNC imports components worth $50,000. Import duty is 12%. What is the total cost including duty?","options":["$6,000","$56,000","$44,000","$50,600"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Calculates only the import duty, not the total cost."},{"option_index":2,"misconception":"Subtracts the duty instead of adding it."},{"option_index":3,"misconception":"Misplaces the decimal when calculating 12% (treats it as 1.2%)."}],"explanation":"Duty = 12% of 50,000 = 6,000; total = 50,000 + 6,000 = 56,000.","concept_id":"eco610-glo-mnc","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"multinational-corporations-and-how-they-organise-production-across-countries-008","band":"K5","grade":10,"subject":"Mathematics","concept":"multinational corporations and how they organise production across countries","difficulty":2,"stem":"An MNC earns 80,000 units of Country Y's currency. The exchange rate is 1 unit of Country X's currency = 25 units of Country Y's currency. How many units of Country X's currency does the MNC get?","options":["2,000,000","79,975","3,200","4,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Multiplies by 25 instead of dividing by 25."},{"option_index":1,"misconception":"Subtracts 25 from the amount instead of converting by division."},{"option_index":3,"misconception":"Divides by 20 instead of by 25 (uses a wrong exchange rate)."}],"explanation":"Convert Y to X by dividing: 80,000 ÷ 25 = 3,200.","concept_id":"eco610-glo-mnc","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"multinational-corporations-and-how-they-organise-production-across-countries-009","band":"K5","grade":10,"subject":"Mathematics","concept":"multinational corporations and how they organise production across countries","difficulty":2,"stem":"An MNC has 5 factories. Factory A produces 18% of total output, B 22%, C 25%, D 15%, and E produces the rest. If total output is 200,000 units, how many units does Factory E produce?","options":["160,000 units","40,000 units","20,000 units","44,000 units"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Adds the other four factories' shares (80%) instead of finding E's share."},{"option_index":2,"misconception":"Treats E's share as 10% instead of 20%."},{"option_index":3,"misconception":"Uses Factory B's 22% for Factory E."}],"explanation":"A+B+C+D = 18+22+25+15 = 80%, so E = 20%; 20% of 200,000 = 40,000.","concept_id":"eco610-glo-mnc","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"multinational-corporations-and-how-they-organise-production-across-countries-010","band":"K5","grade":10,"subject":"Mathematics","concept":"multinational corporations and how they organise production across countries","difficulty":2,"stem":"An MNC earns a profit of $150,000, shared among three countries in the ratio 1 : 2 : 3. How much does the country with 2 parts receive?","options":["$25,000","$75,000","$50,000","$100,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Finds the share for 1 part instead of 2 parts."},{"option_index":1,"misconception":"Finds the share for 3 parts instead of 2 parts."},{"option_index":3,"misconception":"Uses 2/3 of the total instead of 2/6."}],"explanation":"Total parts = 6; 2 parts = 2/6 × 150,000 = 50,000.","concept_id":"eco610-glo-mnc","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"trade-liberalisation-governments-removing-barriers-or-tariffs-on-foreign-trade-001","band":"K5","grade":10,"subject":"Mathematics","concept":"trade liberalisation: governments removing barriers or tariffs on foreign trade","difficulty":2,"stem":"With a 20% tariff, an imported bicycle sells for ₹3000. After trade liberalisation removes the tariff, what is the price of the bicycle?","options":["₹2500","₹2400","₹3000","₹3600"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Subtracts 20% of the tariff-inclusive price instead of reversing the 20% tariff."},{"option_index":2,"misconception":"Assumes removing the tariff leaves the price unchanged."},{"option_index":3,"misconception":"Adds the 20% tariff again instead of removing it."}],"explanation":"If tariff-inclusive price is 120% of pre-tariff price, pre-tariff = 3000 ÷ 1.20 = ₹2500.","concept_id":"eco610-glo-trade-liberalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"trade-liberalisation-governments-removing-barriers-or-tariffs-on-foreign-trade-002","band":"K5","grade":10,"subject":"Mathematics","concept":"trade liberalisation: governments removing barriers or tariffs on foreign trade","difficulty":2,"stem":"A government removes a 15% tariff on imported laptops. If a laptop's tariff-inclusive price was ₹46,000, what is the price after removal?","options":["₹39,100","₹40,000","₹46,000","₹52,900"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Subtracts 15% of the tariff-inclusive price from that price."},{"option_index":2,"misconception":"Thinks removing a tariff does not change the selling price."},{"option_index":3,"misconception":"Adds 15% instead of removing the tariff."}],"explanation":"Pre-tariff price = 46000 ÷ 1.15 = ₹40,000.","concept_id":"eco610-glo-trade-liberalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"trade-liberalisation-governments-removing-barriers-or-tariffs-on-foreign-trade-003","band":"K5","grade":10,"subject":"Mathematics","concept":"trade liberalisation: governments removing barriers or tariffs on foreign trade","difficulty":2,"stem":"A 25% tariff on imported cloth is removed. If the pre-tariff price is ₹80 per metre, how much is saved per metre after liberalisation?","options":["₹25","₹60","₹20","₹100"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Mistakes the tariff rate (25) for the rupee saving."},{"option_index":1,"misconception":"Gives the new price after subtracting the tariff, not the saving."},{"option_index":3,"misconception":"Adds the tariff to the price instead of finding the saving."}],"explanation":"25% of ₹80 = ₹20 saving per metre.","concept_id":"eco610-glo-trade-liberalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"trade-liberalisation-governments-removing-barriers-or-tariffs-on-foreign-trade-004","band":"K5","grade":10,"subject":"Mathematics","concept":"trade liberalisation: governments removing barriers or tariffs on foreign trade","difficulty":2,"stem":"Before trade liberalisation, a country imported 5000 tonnes of wheat. After removing a quota barrier, imports increased by 30%. How many tonnes were imported after liberalisation?","options":["6500","1500","3500","5030"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Finds only the 30% increase and forgets to add it to the original."},{"option_index":2,"misconception":"Subtracts 30% instead of increasing by 30%."},{"option_index":3,"misconception":"Adds 30 tonnes instead of 30% of 5000."}],"explanation":"5000 × 1.30 = 6500 tonnes.","concept_id":"eco610-glo-trade-liberalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"trade-liberalisation-governments-removing-barriers-or-tariffs-on-foreign-trade-005","band":"K5","grade":10,"subject":"Mathematics","concept":"trade liberalisation: governments removing barriers or tariffs on foreign trade","difficulty":2,"stem":"A 10% tariff was collected on imports worth ₹2,00,000. After trade liberalisation removes this tariff, how much tariff revenue is lost?","options":["₹2,000","₹1,80,000","₹2,20,000","₹20,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Uses 1% instead of 10% when finding the tariff."},{"option_index":1,"misconception":"Subtracts the tariff from the import value instead of finding the tariff amount."},{"option_index":2,"misconception":"Adds the tariff to the import value instead of finding the lost revenue."}],"explanation":"10% of ₹2,00,000 = ₹20,000.","concept_id":"eco610-glo-trade-liberalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"trade-liberalisation-governments-removing-barriers-or-tariffs-on-foreign-trade-006","band":"K5","grade":10,"subject":"Mathematics","concept":"trade liberalisation: governments removing barriers or tariffs on foreign trade","difficulty":2,"stem":"Removing a 20% tariff lowers the price of an imported item from ₹1,250 to ₹1,000. By what percentage did the price fall?","options":["10%","25%","20%","80%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Halves the known tariff rate instead of calculating the actual percentage fall."},{"option_index":1,"misconception":"Uses the new price ₹1000 as the base instead of the original ₹1250."},{"option_index":3,"misconception":"Compares the new price with the old price and treats it as the fall."}],"explanation":"Fall = 250; 250/1250 × 100 = 20%.","concept_id":"eco610-glo-trade-liberalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"trade-liberalisation-governments-removing-barriers-or-tariffs-on-foreign-trade-007","band":"K5","grade":10,"subject":"Mathematics","concept":"trade liberalisation: governments removing barriers or tariffs on foreign trade","difficulty":2,"stem":"A ₹50 per unit tariff is removed on imported shoes. If a shop had 120 imported units, what is the total tariff saving?","options":["₹50","₹6000","₹120","₹600"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Gives the per-unit saving instead of the total saving."},{"option_index":2,"misconception":"Gives the number of units instead of the total saving."},{"option_index":3,"misconception":"Multiplies by 12 instead of 120."}],"explanation":"Total saving = 50 × 120 = ₹6000.","concept_id":"eco610-glo-trade-liberalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"trade-liberalisation-governments-removing-barriers-or-tariffs-on-foreign-trade-008","band":"K5","grade":10,"subject":"Mathematics","concept":"trade liberalisation: governments removing barriers or tariffs on foreign trade","difficulty":2,"stem":"A 12% tariff on imported rice is removed. If the tariff-inclusive price was ₹560 per bag, what is the pre-tariff price per bag?","options":["₹500","₹492.80","₹560","₹627.20"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Subtracts 12% of the tariff-inclusive price instead of reversing the 12% increase."},{"option_index":2,"misconception":"Assumes the tariff-inclusive price equals the pre-tariff price."},{"option_index":3,"misconception":"Adds 12% instead of removing it."}],"explanation":"Pre-tariff price = 560 ÷ 1.12 = ₹500.","concept_id":"eco610-glo-trade-liberalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"trade-liberalisation-governments-removing-barriers-or-tariffs-on-foreign-trade-009","band":"K5","grade":10,"subject":"Mathematics","concept":"trade liberalisation: governments removing barriers or tariffs on foreign trade","difficulty":2,"stem":"A 40% tariff on an imported machine was removed. If the price after removal is ₹75,000, what was the tariff-inclusive price before liberalisation?","options":["₹30,000","₹45,000","₹1,20,000","₹1,05,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Gives only the 40% tariff amount, not the tariff-inclusive price."},{"option_index":1,"misconception":"Subtracts 40% from the post-removal price instead of adding the tariff back."},{"option_index":2,"misconception":"Uses 60% (the complement of 40%) and adds it to the price."}],"explanation":"Before removal price = 75,000 × 1.40 = ₹1,05,000.","concept_id":"eco610-glo-trade-liberalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"trade-liberalisation-governments-removing-barriers-or-tariffs-on-foreign-trade-010","band":"K5","grade":10,"subject":"Mathematics","concept":"trade liberalisation: governments removing barriers or tariffs on foreign trade","difficulty":2,"stem":"Trade liberalisation removes a 10% tariff on imported steel. If the import value is ₹5,00,000, how much do consumers save?","options":["₹5,000","₹4,50,000","₹50,000","₹5,50,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses 1% instead of 10%."},{"option_index":1,"misconception":"Subtracts the tariff from the import value instead of finding the tariff amount."},{"option_index":3,"misconception":"Adds the tariff to the import value instead of finding the saving."}],"explanation":"10% of ₹5,00,000 = ₹50,000.","concept_id":"eco610-glo-trade-liberalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"globalisation-as-growing-interconnection-between-economies-through-trade-and-investment-001","band":"K5","grade":10,"subject":"Mathematics","concept":"globalisation as growing interconnection between economies through trade and investment","difficulty":2,"stem":"A country's exports are ₹240 billion and imports are ₹300 billion. What is its trade deficit?","options":["₹540 billion","₹240 billion","-₹60 billion","₹60 billion"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Adds exports and imports instead of subtracting to find the deficit"},{"option_index":1,"misconception":"Uses the export value itself as the trade deficit"},{"option_index":2,"misconception":"Reverses the subtraction and reports a negative deficit"}],"explanation":"Trade deficit = imports − exports = 300 − 240 = ₹60 billion.","concept_id":"eco610-glo-what-is-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"globalisation-as-growing-interconnection-between-economies-through-trade-and-investment-002","band":"K5","grade":10,"subject":"Mathematics","concept":"globalisation as growing interconnection between economies through trade and investment","difficulty":2,"stem":"FDI inflow to a country rose from $40 billion to $50 billion. What is the percentage increase?","options":["10%","20%","125%","25%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Treats the absolute increase (10) as the percentage increase from the original value"},{"option_index":1,"misconception":"Divides the increase by the new value instead of the original value"},{"option_index":2,"misconception":"Expresses the new value as a percentage of the original instead of the increase"}],"explanation":"Percentage increase = (50 − 40)/40 × 100 = 25%.","concept_id":"eco610-glo-what-is-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"globalisation-as-growing-interconnection-between-economies-through-trade-and-investment-003","band":"K5","grade":10,"subject":"Mathematics","concept":"globalisation as growing interconnection between economies through trade and investment","difficulty":2,"stem":"A country's GDP is ₹80 lakh crore and its exports are ₹20 lakh crore. What percentage of GDP are exports?","options":["20%","25%","400%","0.25%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Reads the export amount as the percentage directly"},{"option_index":2,"misconception":"Reverses the ratio (GDP/exports) and multiplies by 100"},{"option_index":3,"misconception":"Finds the fraction 20/80 = 0.25 but writes it as 0.25% instead of 25%"}],"explanation":"Exports as % of GDP = 20/80 × 100 = 25%.","concept_id":"eco610-glo-what-is-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"globalisation-as-growing-interconnection-between-economies-through-trade-and-investment-004","band":"K5","grade":10,"subject":"Mathematics","concept":"globalisation as growing interconnection between economies through trade and investment","difficulty":2,"stem":"If 1 US dollar is exchanged for ₹80, how many dollars can be bought with ₹24,000?","options":["1,920,000 dollars","30 dollars","300 dollars","3,000 dollars"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Multiplies rupees by the exchange rate instead of dividing"},{"option_index":1,"misconception":"Misplaces a zero in the exchange rate and divides by 800"},{"option_index":3,"misconception":"Divides by 8 instead of 80, shifting the decimal point"}],"explanation":"₹24,000 ÷ ₹80 per dollar = 300 dollars.","concept_id":"eco610-glo-what-is-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"globalisation-as-growing-interconnection-between-economies-through-trade-and-investment-005","band":"K5","grade":10,"subject":"Mathematics","concept":"globalisation as growing interconnection between economies through trade and investment","difficulty":2,"stem":"A multinational company invests ₹5 crore in each of 6 countries. What is the total investment?","options":["₹30 crore","₹11 crore","₹1.2 crore","₹56 crore"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds the per-country investment and the number of countries instead of multiplying"},{"option_index":2,"misconception":"Divides the number of countries by the per-country investment"},{"option_index":3,"misconception":"Concatenates the digits 5 and 6 instead of multiplying"}],"explanation":"Total = 5 × 6 = ₹30 crore.","concept_id":"eco610-glo-what-is-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"globalisation-as-growing-interconnection-between-economies-through-trade-and-investment-006","band":"K5","grade":10,"subject":"Mathematics","concept":"globalisation as growing interconnection between economies through trade and investment","difficulty":2,"stem":"A country imports goods worth ₹450 crore and exports goods worth ₹360 crore. What is its trade balance?","options":["₹90 crore","₹810 crore","-₹90 crore","₹360 crore"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Ignores the sign and reports the magnitude as a surplus"},{"option_index":1,"misconception":"Adds imports and exports instead of subtracting"},{"option_index":3,"misconception":"Uses the export value itself as the trade balance"}],"explanation":"Trade balance = exports − imports = 360 − 450 = −₹90 crore.","concept_id":"eco610-glo-what-is-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"globalisation-as-growing-interconnection-between-economies-through-trade-and-investment-007","band":"K5","grade":10,"subject":"Mathematics","concept":"globalisation as growing interconnection between economies through trade and investment","difficulty":2,"stem":"A country's trade as a percentage of GDP increased from 40% to 50%. What is the increase in percentage points?","options":["10 percentage points","25%","20%","10%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Computes relative increase as 10/40 × 100 = 25% instead of percentage points"},{"option_index":2,"misconception":"Computes relative increase using the new value: 10/50 × 100 = 20%"},{"option_index":3,"misconception":"Confuses percentage points with percent and writes 10%"}],"explanation":"Percentage point increase = 50 − 40 = 10 percentage points.","concept_id":"eco610-glo-what-is-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"globalisation-as-growing-interconnection-between-economies-through-trade-and-investment-008","band":"K5","grade":10,"subject":"Mathematics","concept":"globalisation as growing interconnection between economies through trade and investment","difficulty":2,"stem":"A country's FDI was $20 billion. It increases by 15%. What is the new FDI?","options":["$3 billion","$23 billion","$20.15 billion","$35 billion"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Finds only the increase (15% of 20) and stops at $3 billion"},{"option_index":2,"misconception":"Treats 15% as 0.15 billion and adds it to 20"},{"option_index":3,"misconception":"Adds 15 billion as an absolute amount instead of 15%"}],"explanation":"Increase = 15% of 20 = 3; new FDI = 20 + 3 = $23 billion.","concept_id":"eco610-glo-what-is-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"globalisation-as-growing-interconnection-between-economies-through-trade-and-investment-009","band":"K5","grade":10,"subject":"Mathematics","concept":"globalisation as growing interconnection between economies through trade and investment","difficulty":2,"stem":"A company invests ₹12 lakh in country A and ₹18 lakh in country B. What fraction of the total investment went to country A?","options":["3/5","2/3","2/5","1/2"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Finds B's share of total investment instead of A's"},{"option_index":1,"misconception":"Uses the part-to-part ratio A:B instead of the part-to-whole fraction"},{"option_index":3,"misconception":"Assumes equal investment in both countries"}],"explanation":"Total = 12 + 18 = 30; A's fraction = 12/30 = 2/5.","concept_id":"eco610-glo-what-is-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"globalisation-as-growing-interconnection-between-economies-through-trade-and-investment-010","band":"K5","grade":10,"subject":"Mathematics","concept":"globalisation as growing interconnection between economies through trade and investment","difficulty":2,"stem":"A country's exports increase from ₹500 crore to ₹600 crore, while imports remain ₹550 crore. What is its new trade balance?","options":["₹50 crore surplus","₹50 crore deficit","₹100 crore surplus","₹550 crore deficit"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Keeps the old deficit sign even though exports now exceed imports"},{"option_index":2,"misconception":"Uses only the increase in exports (600 − 500 = 100) as the balance"},{"option_index":3,"misconception":"Uses the import value itself as the trade balance"}],"explanation":"New trade balance = exports − imports = 600 − 550 = ₹50 crore surplus.","concept_id":"eco610-glo-what-is-globalisation","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"world-trade-organisation-and-its-role-in-setting-global-trade-rules-001","band":"K5","grade":10,"subject":"Mathematics","concept":"World Trade Organisation and its role in setting global trade rules","difficulty":2,"stem":"A country imposes a 20% tariff on imported bicycles valued at $250 each. What is the tariff amount per bicycle?","options":["$20","$200","$50","$300"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Treats 20% as a flat $20 charge instead of a percentage of value."},{"option_index":1,"misconception":"Subtracts 20% from the value instead of finding 20% of it."},{"option_index":3,"misconception":"Adds the tariff to the value and gives total price instead of tariff amount."}],"explanation":"20% of $250 = $50, so the tariff amount is $50.","concept_id":"eco610-glo-wto","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"world-trade-organisation-and-its-role-in-setting-global-trade-rules-002","band":"K5","grade":10,"subject":"Mathematics","concept":"World Trade Organisation and its role in setting global trade rules","difficulty":2,"stem":"A country's export earnings rose from $40 billion to $46 billion. By what percentage did exports increase?","options":["6%","15%","13.04%","11.5%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Reports the absolute increase as a percentage."},{"option_index":2,"misconception":"Divides the increase by the new value instead of the original value."},{"option_index":3,"misconception":"Divides the increase by the sum of old and new values."}],"explanation":"Increase = $6 billion; 6/40 × 100 = 15%.","concept_id":"eco610-glo-wto","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"world-trade-organisation-and-its-role-in-setting-global-trade-rules-003","band":"K5","grade":10,"subject":"Mathematics","concept":"World Trade Organisation and its role in setting global trade rules","difficulty":2,"stem":"A tariff is cut from 25% to 20%. What is the percentage decrease relative to the original tariff?","options":["5%","25%","20%","16.67%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Gives the percentage-point change, not the relative decrease."},{"option_index":1,"misconception":"Uses the original tariff rate as the answer."},{"option_index":3,"misconception":"Calculates the decrease relative to the new tariff instead of the original."}],"explanation":"Decrease = 5 percentage points; 5/25 × 100 = 20%.","concept_id":"eco610-glo-wto","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"world-trade-organisation-and-its-role-in-setting-global-trade-rules-004","band":"K5","grade":10,"subject":"Mathematics","concept":"World Trade Organisation and its role in setting global trade rules","difficulty":2,"stem":"A good has a customs value of $800 and a tariff rate of 12.5%. What is the total price after the tariff is added?","options":["$900","$100","$700","$812.50"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Gives only the tariff amount, not the total price."},{"option_index":2,"misconception":"Subtracts the tariff from the customs value."},{"option_index":3,"misconception":"Treats 12.5% as a flat $12.50 charge."}],"explanation":"Tariff = 12.5% of $800 = $100; total = $800 + $100 = $900.","concept_id":"eco610-glo-wto","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"world-trade-organisation-and-its-role-in-setting-global-trade-rules-005","band":"K5","grade":10,"subject":"Mathematics","concept":"World Trade Organisation and its role in setting global trade rules","difficulty":2,"stem":"Country X exports goods worth $120 million and imports goods worth $150 million. What is the trade deficit as a percentage of imports?","options":["25%","20%","30%","80%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Divides the deficit by exports instead of imports."},{"option_index":2,"misconception":"Mistakes the deficit amount ($30 million) for a percentage."},{"option_index":3,"misconception":"Divides exports by imports."}],"explanation":"Deficit = $150m − $120m = $30m; 30/150 × 100 = 20%.","concept_id":"eco610-glo-wto","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"world-trade-organisation-and-its-role-in-setting-global-trade-rules-006","band":"K5","grade":10,"subject":"Mathematics","concept":"World Trade Organisation and its role in setting global trade rules","difficulty":2,"stem":"A WTO ruling removes a quota that limited imports to 60% of domestic demand. If domestic demand is 250,000 units, how many units may be imported under the quota?","options":["100,000","150,000","250,000","15,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Finds 40% of demand, thinking the quota is the remaining share."},{"option_index":2,"misconception":"Ignores the quota percentage."},{"option_index":3,"misconception":"Makes a decimal-place error in the percentage calculation."}],"explanation":"60% of 250,000 = 0.60 × 250,000 = 150,000 units.","concept_id":"eco610-glo-wto","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"world-trade-organisation-and-its-role-in-setting-global-trade-rules-007","band":"K5","grade":10,"subject":"Mathematics","concept":"World Trade Organisation and its role in setting global trade rules","difficulty":2,"stem":"A country binds its tariff at 15% but actually applies a 12% tariff. What is the 'water' (difference between bound and applied tariff) in percentage points?","options":["3 percentage points","27 percentage points","15 percentage points","12 percentage points"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds the two rates instead of subtracting."},{"option_index":2,"misconception":"Gives the bound tariff rate."},{"option_index":3,"misconception":"Gives the applied tariff rate."}],"explanation":"Water = 15% − 12% = 3 percentage points.","concept_id":"eco610-glo-wto","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"world-trade-organisation-and-its-role-in-setting-global-trade-rules-008","band":"K5","grade":10,"subject":"Mathematics","concept":"World Trade Organisation and its role in setting global trade rules","difficulty":3,"stem":"Country A imports $200 million at a 10% tariff and $300 million at a 5% tariff. What is the trade-weighted average tariff rate?","options":["7.5%","8%","5%","7%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Takes a simple average of 10% and 5%."},{"option_index":1,"misconception":"Reverses the weights by applying 5% to $200 million and 10% to $300 million."},{"option_index":2,"misconception":"Uses only the lower tariff rate."}],"explanation":"Weighted average = (200×10 + 300×5) / 500 = 3500/500 = 7%.","concept_id":"eco610-glo-wto","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"world-trade-organisation-and-its-role-in-setting-global-trade-rules-009","band":"K5","grade":10,"subject":"Mathematics","concept":"World Trade Organisation and its role in setting global trade rules","difficulty":2,"stem":"A country's GDP is $2 trillion. Its trade-to-GDP ratio is 45%. What is the value of its total trade (exports + imports)?","options":["$0.45 trillion","$0.9 trillion","$4.44 trillion","$1.1 trillion"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Takes 45% of $1 trillion instead of $2 trillion."},{"option_index":2,"misconception":"Divides GDP by 0.45 instead of multiplying."},{"option_index":3,"misconception":"Subtracts 45% from GDP."}],"explanation":"Total trade = 45% of $2 trillion = 0.45 × 2 = $0.9 trillion.","concept_id":"eco610-glo-wto","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"world-trade-organisation-and-its-role-in-setting-global-trade-rules-010","band":"K5","grade":10,"subject":"Mathematics","concept":"World Trade Organisation and its role in setting global trade rules","difficulty":2,"stem":"Under WTO most-favoured-nation rules, a 10% tariff reduction granted to one member must be granted to all. If the original tariff was 30%, what is the new tariff?","options":["20%","30%","27%","33%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Subtracts 10 percentage points instead of 10% of the tariff."},{"option_index":1,"misconception":"Assumes no change."},{"option_index":3,"misconception":"Adds 10% of 30 to the original tariff instead of subtracting."}],"explanation":"10% of 30% = 3 percentage points; new tariff = 30% − 3% = 27%.","concept_id":"eco610-glo-wto","strand":"Globalisation and the Indian Economy","kind":"mcq"},{"id":"how-banks-accept-deposits-from-the-public-and-pay-interest-on-them-001","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks accept deposits from the public and pay interest on them","difficulty":2,"stem":"Ravi deposits ₹1,200 in a bank that pays 5% per annum simple interest. How much interest will he get after 2 years?","options":["₹120","₹1,200","₹1,320","₹60"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Treats 5% as 0.5 (i.e., 50%) instead of 0.05."},{"option_index":2,"misconception":"Adds the principal to the interest even though only interest is asked."},{"option_index":3,"misconception":"Uses 1 year instead of 2 years."}],"explanation":"Simple interest = P×R×T/100 = 1200×5×2/100 = ₹120.","concept_id":"eco610-mon-bank-deposits","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-accept-deposits-from-the-public-and-pay-interest-on-them-002","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks accept deposits from the public and pay interest on them","difficulty":2,"stem":"Sita deposits ₹4,000 in a bank at 5% per annum simple interest. What total amount will she have after 2 years?","options":["₹400","₹4,200","₹4,400","₹4,040"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reports only the simple interest, not the total amount."},{"option_index":1,"misconception":"Uses 1 year instead of 2 years for the interest."},{"option_index":3,"misconception":"Converts 5% to 0.005 instead of 0.05, a decimal-place error."}],"explanation":"SI = 4000×5×2/100 = ₹400; total amount = 4000 + 400 = ₹4,400.","concept_id":"eco610-mon-bank-deposits","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-accept-deposits-from-the-public-and-pay-interest-on-them-003","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks accept deposits from the public and pay interest on them","difficulty":2,"stem":"A bank pays ₹240 as simple interest on a deposit of ₹2,000 for 2 years. What is the annual rate of interest?","options":["12%","6%","0.6%","3%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Forgets to divide by the time, using 1 year instead of 2 years."},{"option_index":2,"misconception":"Moves the decimal point one extra place when writing 6% as a rate."},{"option_index":3,"misconception":"Uses 4 half-years in place of 2 years, doubling the time."}],"explanation":"R = 100×SI/(P×T) = 100×240/(2000×2) = 6%.","concept_id":"eco610-mon-bank-deposits","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-accept-deposits-from-the-public-and-pay-interest-on-them-004","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks accept deposits from the public and pay interest on them","difficulty":2,"stem":"What principal will earn ₹600 as simple interest in 3 years at 5% per annum?","options":["₹90","₹12,000","₹4,000","₹20,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Multiplies by rate and time instead of dividing when rearranging the formula."},{"option_index":1,"misconception":"Ignores the time factor in the denominator."},{"option_index":3,"misconception":"Ignores the rate factor in the denominator."}],"explanation":"P = 100×SI/(R×T) = 100×600/(5×3) = ₹4,000.","concept_id":"eco610-mon-bank-deposits","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-accept-deposits-from-the-public-and-pay-interest-on-them-005","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks accept deposits from the public and pay interest on them","difficulty":2,"stem":"How many years will it take for ₹1,000 to earn ₹150 as simple interest at 5% per annum?","options":["1.5 years","15 years","30 years","3 years"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Uses 10% instead of 5%, doubling the rate."},{"option_index":1,"misconception":"Ignores the rate in the denominator."},{"option_index":2,"misconception":"Multiplies by 1000 instead of 100, a decimal-place error."}],"explanation":"T = 100×SI/(P×R) = 100×150/(1000×5) = 3 years.","concept_id":"eco610-mon-bank-deposits","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-accept-deposits-from-the-public-and-pay-interest-on-them-006","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks accept deposits from the public and pay interest on them","difficulty":3,"stem":"A bank pays 10% per annum compound interest compounded annually. What amount will ₹1,000 become after 2 years?","options":["₹1,200","₹1,210","₹1,100","₹1,331"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses simple interest instead of compound interest."},{"option_index":2,"misconception":"Stops after one year of interest."},{"option_index":3,"misconception":"Compounds for 3 years instead of 2."}],"explanation":"Amount = 1000(1 + 10/100)^2 = 1000×1.21 = ₹1,210.","concept_id":"eco610-mon-bank-deposits","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-accept-deposits-from-the-public-and-pay-interest-on-them-007","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks accept deposits from the public and pay interest on them","difficulty":3,"stem":"Find the compound interest on ₹2,000 for 2 years at 10% per annum compounded annually.","options":["₹400","₹2,420","₹420","₹200"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses simple interest instead of compound interest."},{"option_index":1,"misconception":"Gives the total amount instead of only the compound interest."},{"option_index":3,"misconception":"Uses only one year's interest."}],"explanation":"Amount = 2000(1.1)^2 = ₹2,420; CI = 2420 − 2000 = ₹420.","concept_id":"eco610-mon-bank-deposits","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-accept-deposits-from-the-public-and-pay-interest-on-them-008","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks accept deposits from the public and pay interest on them","difficulty":3,"stem":"A bank pays 8% per annum compounded half-yearly. What amount will ₹10,000 become after 1 year?","options":["₹10,800","₹10,816","₹11,664","₹10,400"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses simple interest or annual compounding for 1 year."},{"option_index":2,"misconception":"Uses 8% per half-year instead of 4% per half-year."},{"option_index":3,"misconception":"Stops after one half-year."}],"explanation":"Half-yearly rate = 8/2 = 4%; amount = 10000(1.04)^2 = ₹10,816.","concept_id":"eco610-mon-bank-deposits","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-accept-deposits-from-the-public-and-pay-interest-on-them-009","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks accept deposits from the public and pay interest on them","difficulty":2,"stem":"A bank gives 5% per annum simple interest. How much total amount will ₹8,000 become after 3 years?","options":["₹1,200","₹9,200","₹8,400","₹8,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Reports only the interest, not the total amount."},{"option_index":2,"misconception":"Uses 1 year instead of 3 years."},{"option_index":3,"misconception":"Thinks the bank returns only the principal."}],"explanation":"SI = 8000×5×3/100 = ₹1,200; total = 8000 + 1200 = ₹9,200.","concept_id":"eco610-mon-bank-deposits","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-accept-deposits-from-the-public-and-pay-interest-on-them-010","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks accept deposits from the public and pay interest on them","difficulty":2,"stem":"A bank pays 5% per annum simple interest. What principal will earn ₹200 as interest in 4 years?","options":["₹40","₹4,000","₹5,000","₹1,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Multiplies by rate and time instead of dividing when rearranging the formula."},{"option_index":1,"misconception":"Ignores the time factor in the denominator."},{"option_index":2,"misconception":"Ignores the rate factor in the denominator."}],"explanation":"P = 100×SI/(R×T) = 100×200/(5×4) = ₹1,000.","concept_id":"eco610-mon-bank-deposits","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-lend-out-most-of-their-deposited-money-as-loans-001","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks lend out most of their deposited money as loans","difficulty":2,"stem":"A bank receives a deposit of ₹12,000. It keeps 15% as reserves and lends out the rest. How much does it lend out?","options":["₹1,800","₹10,200","₹12,000","₹6,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Calculates the 15% reserve (₹1,800) and mistakes it for the loan amount."},{"option_index":2,"misconception":"Ignores the reserve requirement and assumes the bank lends the entire deposit."},{"option_index":3,"misconception":"Assumes the bank keeps half the deposit as reserves and lends the other half."}],"explanation":"Reserve = 15% of ₹12,000 = ₹1,800; loan = ₹12,000 − ₹1,800 = ₹10,200.","concept_id":"eco610-mon-bank-lending","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-lend-out-most-of-their-deposited-money-as-loans-002","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks lend out most of their deposited money as loans","difficulty":2,"stem":"A bank keeps 25% of a deposit as reserves. What fraction of the deposit does it lend out?","options":["1/4","1/2","1","3/4"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Gives the reserve fraction instead of the fraction lent out."},{"option_index":1,"misconception":"Assumes the bank lends and keeps equal halves."},{"option_index":2,"misconception":"Assumes no reserves are kept and the whole deposit is lent."}],"explanation":"If 25% = 1/4 is reserved, the lent fraction is 1 − 1/4 = 3/4.","concept_id":"eco610-mon-bank-lending","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-lend-out-most-of-their-deposited-money-as-loans-003","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks lend out most of their deposited money as loans","difficulty":2,"stem":"A bank has ₹10,000 in deposits and lends out ₹8,000. What percentage of the deposits does it keep as reserves?","options":["20%","80%","25%","2%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Reports the lent percentage (80%) as the reserve percentage."},{"option_index":2,"misconception":"Compares reserves (₹2,000) to the loan (₹8,000) instead of to total deposits."},{"option_index":3,"misconception":"Treats ₹2,000 as 2% by dropping zeros in the place-value conversion."}],"explanation":"Reserves = ₹10,000 − ₹8,000 = ₹2,000; ₹2,000/₹10,000 = 20%.","concept_id":"eco610-mon-bank-lending","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-lend-out-most-of-their-deposited-money-as-loans-004","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks lend out most of their deposited money as loans","difficulty":2,"stem":"A bank has a 10% reserve requirement. If it lends out ₹9,000, how much deposit did it originally receive?","options":["₹9,900","₹9,000","₹10,000","₹8,100"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Adds 10% of the loan amount to the loan instead of dividing by 0.90."},{"option_index":1,"misconception":"Equates the loan amount with the total deposit, ignoring reserves."},{"option_index":3,"misconception":"Subtracts 10% of the loan amount from the loan instead of finding the original deposit."}],"explanation":"Lent fraction = 90%; deposit = ₹9,000 ÷ 0.90 = ₹10,000.","concept_id":"eco610-mon-bank-lending","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-lend-out-most-of-their-deposited-money-as-loans-005","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks lend out most of their deposited money as loans","difficulty":2,"stem":"A bank keeps 1/5 of its deposits as reserves and lends out ₹8,000. What was the total deposit?","options":["₹10,000","₹9,600","₹8,000","₹6,400"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds 1/5 of the loan amount to the loan instead of using the original deposit."},{"option_index":2,"misconception":"Assumes total deposits equal loans, ignoring reserves."},{"option_index":3,"misconception":"Subtracts 1/5 of the loan amount from the loan."}],"explanation":"Lent fraction = 4/5; deposit = ₹8,000 ÷ (4/5) = ₹10,000.","concept_id":"eco610-mon-bank-lending","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-lend-out-most-of-their-deposited-money-as-loans-006","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks lend out most of their deposited money as loans","difficulty":2,"stem":"Suppose every bank keeps 20% of deposits as reserves. Starting from an initial deposit of ₹5,000, what is the maximum total amount of loans that can eventually be created in the banking system?","options":["₹5,000","₹4,000","₹25,000","₹20,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Thinks total loans equal the initial deposit."},{"option_index":1,"misconception":"Calculates only the first round of lending (80% of ₹5,000)."},{"option_index":2,"misconception":"Calculates total deposits using the money multiplier and mistakes it for total loans."}],"explanation":"Money multiplier = 1/0.20 = 5; total deposits = ₹25,000; total loans = ₹25,000 − ₹5,000 = ₹20,000.","concept_id":"eco610-mon-bank-lending","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-lend-out-most-of-their-deposited-money-as-loans-007","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks lend out most of their deposited money as loans","difficulty":2,"stem":"If the reserve ratio is 25%, what is the money multiplier (total deposits divided by initial deposit)?","options":["1/4","4","3/4","5"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses the reserve ratio itself as the multiplier."},{"option_index":2,"misconception":"Uses the lending fraction as the multiplier."},{"option_index":3,"misconception":"Uses the multiplier for a 20% reserve ratio."}],"explanation":"Money multiplier = 1 ÷ reserve ratio = 1 ÷ (1/4) = 4.","concept_id":"eco610-mon-bank-lending","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-lend-out-most-of-their-deposited-money-as-loans-008","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks lend out most of their deposited money as loans","difficulty":2,"stem":"A bank receives ₹2,000 as deposits. It keeps 12.5% as reserves and lends out the rest. How much does it lend out?","options":["₹250","₹2,000","₹1,750","₹1,500"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Calculates the 12.5% reserve and mistakes it for the loan amount."},{"option_index":1,"misconception":"Ignores reserves and lends the whole deposit."},{"option_index":3,"misconception":"Mistakenly keeps 25% as reserves instead of 12.5%."}],"explanation":"Reserve = 12.5% of ₹2,000 = ₹250; loan = ₹2,000 − ₹250 = ₹1,750.","concept_id":"eco610-mon-bank-lending","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-lend-out-most-of-their-deposited-money-as-loans-009","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks lend out most of their deposited money as loans","difficulty":2,"stem":"A bank lends out 90% of its deposits. If it lends ₹18,000, what is the total deposit?","options":["₹19,800","₹20,000","₹18,000","₹16,200"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Adds 10% of the loan amount to the loan instead of dividing by 0.90."},{"option_index":2,"misconception":"Equates the loan amount with total deposits."},{"option_index":3,"misconception":"Subtracts 10% of the loan amount from the loan."}],"explanation":"Deposit = ₹18,000 ÷ 0.90 = ₹20,000.","concept_id":"eco610-mon-bank-lending","strand":"Money and Credit","kind":"mcq"},{"id":"how-banks-lend-out-most-of-their-deposited-money-as-loans-010","band":"K5","grade":10,"subject":"Mathematics","concept":"how banks lend out most of their deposited money as loans","difficulty":2,"stem":"In a banking system with a 5% reserve requirement, an initial deposit of ₹10,000 leads to total loans of how much eventually?","options":["₹190,000","₹10,000","₹500","₹200,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Thinks total loans equal the initial deposit."},{"option_index":2,"misconception":"Calculates only the first reserve (5% of ₹10,000) and confuses it with total loans."},{"option_index":3,"misconception":"Calculates total deposits (₹10,000 ÷ 0.05) and mistakes it for total loans."}],"explanation":"Total deposits = ₹10,000 ÷ 0.05 = ₹200,000; total loans = ₹200,000 − ₹10,000 = ₹190,000.","concept_id":"eco610-mon-bank-lending","strand":"Money and Credit","kind":"mcq"},{"id":"the-double-coincidence-of-wants-problem-in-a-barter-system-001","band":"K5","grade":10,"subject":"Mathematics","concept":"the double coincidence of wants problem in a barter system","difficulty":2,"stem":"In a barter system, two traders each want the other's good. If the first trader wants the second trader's good with probability 1/2, and the second wants the first trader's good with probability 1/4, and these wants are independent, what is the probability of a double coincidence?","options":["3/4","1/3","1/4","1/8"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Adds the two probabilities instead of multiplying them."},{"option_index":1,"misconception":"Adds fractions incorrectly by adding numerators and denominators: (1+1)/(2+4) = 1/3."},{"option_index":2,"misconception":"Subtracts the probabilities instead of multiplying them."}],"explanation":"For independent events, multiply probabilities: 1/2 × 1/4 = 1/8.","concept_id":"eco610-mon-barter-problem","strand":"Money and Credit","kind":"mcq"},{"id":"the-double-coincidence-of-wants-problem-in-a-barter-system-002","band":"K5","grade":10,"subject":"Mathematics","concept":"the double coincidence of wants problem in a barter system","difficulty":2,"stem":"In a small barter market, 5 people each have one distinct good. A double coincidence can occur only between a pair of people. How many distinct unordered pairs of people can potentially make a direct barter exchange?","options":["20","10","25","5"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Counts ordered pairs (5 × 4 = 20) instead of unordered pairs."},{"option_index":2,"misconception":"Counts each person paired with themselves as well (5 × 5 = 25)."},{"option_index":3,"misconception":"Counts only one potential partner per person instead of all pairs."}],"explanation":"Number of unordered pairs is C(5,2) = 5×4/2 = 10.","concept_id":"eco610-mon-barter-problem","strand":"Money and Credit","kind":"mcq"},{"id":"the-double-coincidence-of-wants-problem-in-a-barter-system-003","band":"K5","grade":10,"subject":"Mathematics","concept":"the double coincidence of wants problem in a barter system","difficulty":2,"stem":"A barter economy has 12 different goods. Before money, every pair of goods needs an exchange ratio. How many different pairwise exchange ratios are possible if the order of the two goods does not matter?","options":["132","144","66","24"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Counts ordered ratios (12 × 11 = 132) instead of unordered ratios."},{"option_index":1,"misconception":"Uses 12² = 144, which includes pairing a good with itself."},{"option_index":3,"misconception":"Uses 2 × 12 = 24, confusing the number of goods with twice the goods count."}],"explanation":"Unordered pairs: C(12,2) = 12×11/2 = 66.","concept_id":"eco610-mon-barter-problem","strand":"Money and Credit","kind":"mcq"},{"id":"the-double-coincidence-of-wants-problem-in-a-barter-system-004","band":"K5","grade":10,"subject":"Mathematics","concept":"the double coincidence of wants problem in a barter system","difficulty":2,"stem":"In a region with 20 traders, each pair of traders has a double coincidence with probability 1/10. What is the expected number of double-coincidence pairs?","options":["19","20","190","38"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses the number of traders (20) instead of the number of pairs."},{"option_index":2,"misconception":"Ignores the probability and reports only the total number of pairs (190)."},{"option_index":3,"misconception":"Uses ordered pairs (20 × 19 = 380) and then multiplies by 1/10."}],"explanation":"Number of pairs = C(20,2) = 190. Expected = 190 × 1/10 = 19.","concept_id":"eco610-mon-barter-problem","strand":"Money and Credit","kind":"mcq"},{"id":"the-double-coincidence-of-wants-problem-in-a-barter-system-005","band":"K5","grade":10,"subject":"Mathematics","concept":"the double coincidence of wants problem in a barter system","difficulty":2,"stem":"In a barter system, the number of possible pairwise exchange ratios between different goods is given by n(n−1)/2, where n is the number of goods. If there are 45 possible pairwise exchange ratios, how many different goods are there?","options":["9","11","10","45"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Solves n − 1 = 9 instead of n(n−1)/2 = 45."},{"option_index":1,"misconception":"Chooses n + 1 = 11 instead of solving the quadratic equation."},{"option_index":3,"misconception":"Takes the number of ratios as the number of goods."}],"explanation":"n(n−1)/2 = 45 ⇒ n(n−1) = 90 ⇒ n = 10.","concept_id":"eco610-mon-barter-problem","strand":"Money and Credit","kind":"mcq"},{"id":"the-double-coincidence-of-wants-problem-in-a-barter-system-006","band":"K5","grade":10,"subject":"Mathematics","concept":"the double coincidence of wants problem in a barter system","difficulty":2,"stem":"In a group of 4 traders, each of the 6 possible pairs has a double coincidence with probability 1/2, independently. What is the probability that no pair has a double coincidence?","options":["1/16","1/64","1/8","1/32"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses 4 pairs instead of 6: (1/2)^4 = 1/16."},{"option_index":2,"misconception":"Uses 3 pairs instead of 6: (1/2)^3 = 1/8."},{"option_index":3,"misconception":"Uses 5 pairs instead of 6: (1/2)^5 = 1/32."}],"explanation":"There are C(4,2) = 6 pairs, so probability none works is (1/2)^6 = 1/64.","concept_id":"eco610-mon-barter-problem","strand":"Money and Credit","kind":"mcq"},{"id":"the-double-coincidence-of-wants-problem-in-a-barter-system-007","band":"K5","grade":10,"subject":"Mathematics","concept":"the double coincidence of wants problem in a barter system","difficulty":2,"stem":"In a barter meeting, 6 people each have one good. Each person wants exactly one other person's good. What is the maximum number of double-coincidence pairs that can be formed?","options":["6","15","3","5"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Thinks each person can be in a separate pair, giving 6 pairs."},{"option_index":1,"misconception":"Counts all possible pairs C(6,2) = 15 instead of only mutual pairs."},{"option_index":3,"misconception":"Uses n − 1 = 5 instead of pairing people off."}],"explanation":"Each double-coincidence pair needs 2 people, so at most 6/2 = 3 pairs.","concept_id":"eco610-mon-barter-problem","strand":"Money and Credit","kind":"mcq"},{"id":"the-double-coincidence-of-wants-problem-in-a-barter-system-008","band":"K5","grade":10,"subject":"Mathematics","concept":"the double coincidence of wants problem in a barter system","difficulty":2,"stem":"A barter market with 10 different goods has many pairwise exchange ratios. If money is introduced so every good has a price in money, how many money prices are needed to replace all pairwise exchange ratios?","options":["45","10","20","9"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Keeps the pairwise exchange ratios C(10,2) = 45 instead of using money prices."},{"option_index":2,"misconception":"Uses two prices per good, 2 × 10 = 20."},{"option_index":3,"misconception":"Uses n − 1 = 9, thinking one good serves as money."}],"explanation":"With money, each of the 10 goods needs one price, so 10 prices are needed.","concept_id":"eco610-mon-barter-problem","strand":"Money and Credit","kind":"mcq"},{"id":"the-double-coincidence-of-wants-problem-in-a-barter-system-009","band":"K5","grade":10,"subject":"Mathematics","concept":"the double coincidence of wants problem in a barter system","difficulty":2,"stem":"In a barter group of 5 people, each person wants exactly 2 other people's goods. What is the maximum number of double-coincidence pairs that can occur?","options":["2","5","10","4"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Assumes double-coincidence pairs must be disjoint, giving floor(5/2) = 2."},{"option_index":2,"misconception":"Counts all possible pairs C(5,2) = 10, ignoring the limit of 2 wants per person."},{"option_index":3,"misconception":"Miscounts a 5-person cycle as having 4 mutual pairs instead of 5."}],"explanation":"Arrange the 5 people in a cycle; each wants the two neighbors, giving 5 mutual pairs.","concept_id":"eco610-mon-barter-problem","strand":"Money and Credit","kind":"mcq"},{"id":"the-double-coincidence-of-wants-problem-in-a-barter-system-010","band":"K5","grade":10,"subject":"Mathematics","concept":"the double coincidence of wants problem in a barter system","difficulty":2,"stem":"Three traders each have a distinct good. For each of the 3 possible pairs, the probability of a double coincidence is 1/4, independently. What is the probability that at least one pair has a double coincidence?","options":["37/64","3/4","27/64","1/64"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds the probabilities: 3 × 1/4 = 3/4."},{"option_index":2,"misconception":"Finds the probability that none of the pairs works: (3/4)^3 = 27/64."},{"option_index":3,"misconception":"Finds the probability that all three pairs work: (1/4)^3 = 1/64."}],"explanation":"P(at least one) = 1 − (3/4)^3 = 1 − 27/64 = 37/64.","concept_id":"eco610-mon-barter-problem","strand":"Money and Credit","kind":"mcq"},{"id":"collateral-as-an-asset-pledged-as-security-against-loan-default-001","band":"K5","grade":10,"subject":"Mathematics","concept":"collateral as an asset pledged as security against loan default","difficulty":2,"stem":"A bank accepts collateral worth ₹5,00,000 and gives a loan of ₹4,00,000. What is the loan-to-value (LTV) ratio?","options":["20%","80%","125%","25%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Mistakes the equity/down-payment share (20%) for the LTV ratio."},{"option_index":2,"misconception":"Inverts the ratio and takes collateral as a percent of loan (125%) as the LTV."},{"option_index":3,"misconception":"Computes the extra collateral as a percent of the loan (25%) instead of the LTV."}],"explanation":"LTV = loan / collateral = 4,00,000 / 5,00,000 = 80%.","concept_id":"eco610-mon-collateral","strand":"Money and Credit","kind":"mcq"},{"id":"collateral-as-an-asset-pledged-as-security-against-loan-default-002","band":"K5","grade":10,"subject":"Mathematics","concept":"collateral as an asset pledged as security against loan default","difficulty":2,"stem":"A bank lends up to 70% of the value of collateral. If collateral worth ₹5,00,000 is pledged, what is the maximum loan?","options":["₹1,50,000","₹5,00,000","₹2,50,000","₹3,50,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Takes the remaining 30% as the loan amount."},{"option_index":1,"misconception":"Thinks the bank can lend the full collateral value."},{"option_index":2,"misconception":"Confuses 70% with 50% and takes half the collateral value."}],"explanation":"Maximum loan = 70% of ₹5,00,000 = ₹3,50,000.","concept_id":"eco610-mon-collateral","strand":"Money and Credit","kind":"mcq"},{"id":"collateral-as-an-asset-pledged-as-security-against-loan-default-003","band":"K5","grade":10,"subject":"Mathematics","concept":"collateral as an asset pledged as security against loan default","difficulty":2,"stem":"A bank requires collateral worth 120% of the loan. If the loan is ₹5,00,000, what is the minimum collateral value?","options":["₹1,00,000","₹5,00,000","₹6,00,000","₹4,00,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Takes 20% of the loan as the required collateral."},{"option_index":1,"misconception":"Thinks collateral must equal the loan amount."},{"option_index":3,"misconception":"Confuses 120% with 80% and takes 80% of the loan."}],"explanation":"Minimum collateral = 120% of ₹5,00,000 = ₹6,00,000.","concept_id":"eco610-mon-collateral","strand":"Money and Credit","kind":"mcq"},{"id":"collateral-as-an-asset-pledged-as-security-against-loan-default-004","band":"K5","grade":10,"subject":"Mathematics","concept":"collateral as an asset pledged as security against loan default","difficulty":2,"stem":"A loan outstanding is ₹90,000. The pledged collateral is auctioned for ₹75,000. What is the deficit amount?","options":["₹15,000","₹1,65,000","₹90,000","₹75,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds the outstanding loan and the sale amount instead of subtracting."},{"option_index":2,"misconception":"Ignores the sale and thinks the full outstanding loan remains as deficit."},{"option_index":3,"misconception":"Takes the sale amount itself as the deficit."}],"explanation":"Deficit = ₹90,000 − ₹75,000 = ₹15,000.","concept_id":"eco610-mon-collateral","strand":"Money and Credit","kind":"mcq"},{"id":"collateral-as-an-asset-pledged-as-security-against-loan-default-005","band":"K5","grade":10,"subject":"Mathematics","concept":"collateral as an asset pledged as security against loan default","difficulty":3,"stem":"A borrower pledges gold worth ₹1,50,000 and takes a loan of ₹1,20,000 at 10% simple interest per year. After 2 years, the borrower defaults. The bank sells the gold for ₹1,35,000. What amount of the loan remains unpaid?","options":["₹24,000","₹1,44,000","₹15,000","₹9,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Takes the total interest as the unpaid amount."},{"option_index":1,"misconception":"Uses the total outstanding before sale and ignores the sale proceeds."},{"option_index":2,"misconception":"Subtracts only the principal from the sale amount and ignores interest."}],"explanation":"Outstanding = ₹1,20,000 + 2 × 10% of ₹1,20,000 = ₹1,44,000; unpaid = ₹1,44,000 − ₹1,35,000 = ₹9,000.","concept_id":"eco610-mon-collateral","strand":"Money and Credit","kind":"mcq"},{"id":"collateral-as-an-asset-pledged-as-security-against-loan-default-006","band":"K5","grade":10,"subject":"Mathematics","concept":"collateral as an asset pledged as security against loan default","difficulty":3,"stem":"A borrower pledges land worth ₹6,00,000 and jewellery worth ₹2,00,000. The bank gives a loan equal to 70% of the total collateral value. How much loan is given?","options":["₹1,40,000","₹8,00,000","₹5,60,000","₹4,20,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Takes the remaining 30% as the loan amount."},{"option_index":1,"misconception":"Uses the full collateral value instead of 70% of it."},{"option_index":3,"misconception":"Applies 70% only to the land and ignores the jewellery."}],"explanation":"Total collateral = ₹6,00,000 + ₹2,00,000 = ₹8,00,000; loan = 70% of ₹8,00,000 = ₹5,60,000.","concept_id":"eco610-mon-collateral","strand":"Money and Credit","kind":"mcq"},{"id":"collateral-as-an-asset-pledged-as-security-against-loan-default-007","band":"K5","grade":10,"subject":"Mathematics","concept":"collateral as an asset pledged as security against loan default","difficulty":3,"stem":"An asset worth ₹10,00,000 is pledged. The bank gives a loan at 80% of its value. At default, the outstanding amount is ₹8,50,000. The asset is sold for ₹9,00,000. How much surplus is returned to the borrower after repaying the bank?","options":["₹1,00,000","₹50,000","₹1,50,000","₹0"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses the original loan ₹8,00,000 instead of the outstanding amount ₹8,50,000."},{"option_index":2,"misconception":"Subtracts the outstanding amount from the asset value instead of from the sale price."},{"option_index":3,"misconception":"Thinks the bank keeps all sale proceeds on default, so surplus is zero."}],"explanation":"Surplus = sale price − outstanding = ₹9,00,000 − ₹8,50,000 = ₹50,000.","concept_id":"eco610-mon-collateral","strand":"Money and Credit","kind":"mcq"},{"id":"collateral-as-an-asset-pledged-as-security-against-loan-default-008","band":"K5","grade":10,"subject":"Mathematics","concept":"collateral as an asset pledged as security against loan default","difficulty":3,"stem":"A bank asks for collateral worth ₹3,00,000 for a loan of ₹2,40,000. The collateral value is what percent of the loan?","options":["80%","25%","125%","20%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Inverts the ratio and takes loan as a percent of collateral."},{"option_index":1,"misconception":"Computes the extra collateral as a percent of the loan."},{"option_index":3,"misconception":"Computes the extra collateral as a percent of the collateral value."}],"explanation":"Required percent = (₹3,00,000 / ₹2,40,000) × 100 = 125%.","concept_id":"eco610-mon-collateral","strand":"Money and Credit","kind":"mcq"},{"id":"collateral-as-an-asset-pledged-as-security-against-loan-default-009","band":"K5","grade":10,"subject":"Mathematics","concept":"collateral as an asset pledged as security against loan default","difficulty":2,"stem":"Gold worth ₹4,50,000 is pledged as collateral. The bank allows a loan up to 2/3 of the gold's value. What is the maximum loan?","options":["₹1,50,000","₹3,00,000","₹4,50,000","₹2,25,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Takes 1/3 of the value, the remaining fraction, instead of 2/3."},{"option_index":2,"misconception":"Uses the full collateral value as the loan."},{"option_index":3,"misconception":"Confuses 2/3 with 1/2 and takes half the value."}],"explanation":"Maximum loan = 2/3 × ₹4,50,000 = ₹3,00,000.","concept_id":"eco610-mon-collateral","strand":"Money and Credit","kind":"mcq"},{"id":"collateral-as-an-asset-pledged-as-security-against-loan-default-010","band":"K5","grade":10,"subject":"Mathematics","concept":"collateral as an asset pledged as security against loan default","difficulty":3,"stem":"An asset worth ₹9,00,000 is pledged for a loan of ₹6,00,000. The borrower defaults when the outstanding amount is ₹6,60,000. The asset is sold for ₹6,00,000. How much loss does the bank bear?","options":["₹60,000","₹0","₹3,00,000","₹2,40,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Thinks that because the sale covers the original loan, there is no loss."},{"option_index":2,"misconception":"Subtracts the original loan from the asset value instead of comparing outstanding and sale."},{"option_index":3,"misconception":"Subtracts the outstanding amount from the asset value instead of from the sale price."}],"explanation":"Loss = outstanding − sale = ₹6,60,000 − ₹6,00,000 = ₹60,000.","concept_id":"eco610-mon-collateral","strand":"Money and Credit","kind":"mcq"},{"id":"credit-loan-as-an-agreement-to-repay-borrowed-money-with-interest-001","band":"K5","grade":10,"subject":"Mathematics","concept":"credit (loan) as an agreement to repay borrowed money with interest","difficulty":2,"stem":"A loan of ₹8,000 is taken at 10% per annum simple interest for 2 years. What total amount must be repaid?","options":["₹1,600","₹8,800","₹9,600","₹10,400"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reports only the simple interest, forgetting to add the principal for total repayment."},{"option_index":1,"misconception":"Uses 1 year instead of 2 years when calculating the interest."},{"option_index":3,"misconception":"Uses 3 years instead of 2 years when calculating the interest."}],"explanation":"SI = 8000×10×2/100 = ₹1,600; amount = 8000+1600 = ₹9,600.","concept_id":"eco610-mon-credit-definition","strand":"Money and Credit","kind":"mcq"},{"id":"credit-loan-as-an-agreement-to-repay-borrowed-money-with-interest-002","band":"K5","grade":10,"subject":"Mathematics","concept":"credit (loan) as an agreement to repay borrowed money with interest","difficulty":2,"stem":"A loan of ₹12,000 is taken at 8% per annum simple interest for 3 years. What total amount must be repaid?","options":["₹14,880","₹2,880","₹12,960","₹15,360"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Reports only the simple interest, forgetting to add the principal."},{"option_index":2,"misconception":"Adds only one year's interest instead of three years' interest."},{"option_index":3,"misconception":"Uses 4 years instead of 3 years when calculating the interest."}],"explanation":"SI = 12000×8×3/100 = ₹2,880; amount = 12000+2880 = ₹14,880.","concept_id":"eco610-mon-credit-definition","strand":"Money and Credit","kind":"mcq"},{"id":"credit-loan-as-an-agreement-to-repay-borrowed-money-with-interest-003","band":"K5","grade":10,"subject":"Mathematics","concept":"credit (loan) as an agreement to repay borrowed money with interest","difficulty":2,"stem":"A loan of ₹25,000 is taken at 12% per annum simple interest for 6 months. What is the simple interest?","options":["₹18,000","₹1,500","₹3,000","₹750"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses T = 6 years instead of converting 6 months to 0.5 year."},{"option_index":2,"misconception":"Uses T = 1 year instead of converting 6 months to 0.5 year."},{"option_index":3,"misconception":"Uses T = 0.25 year (3 months) instead of 0.5 year (6 months)."}],"explanation":"SI = 25000×12×(6/12)/100 = ₹1,500.","concept_id":"eco610-mon-credit-definition","strand":"Money and Credit","kind":"mcq"},{"id":"credit-loan-as-an-agreement-to-repay-borrowed-money-with-interest-004","band":"K5","grade":10,"subject":"Mathematics","concept":"credit (loan) as an agreement to repay borrowed money with interest","difficulty":2,"stem":"A loan of ₹40,000 is taken at 9% per annum simple interest for 8 months. What total amount is repaid?","options":["₹2,400","₹43,600","₹68,800","₹42,400"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Reports only the simple interest, forgetting to add the principal."},{"option_index":1,"misconception":"Uses 1 year instead of converting 8 months to 2/3 year."},{"option_index":2,"misconception":"Uses T = 8 years instead of converting 8 months to 2/3 year."}],"explanation":"SI = 40000×9×(8/12)/100 = ₹2,400; amount = 40000+2400 = ₹42,400.","concept_id":"eco610-mon-credit-definition","strand":"Money and Credit","kind":"mcq"},{"id":"credit-loan-as-an-agreement-to-repay-borrowed-money-with-interest-005","band":"K5","grade":10,"subject":"Mathematics","concept":"credit (loan) as an agreement to repay borrowed money with interest","difficulty":2,"stem":"A person pays ₹1,800 as simple interest on a loan at 6% per annum for 3 years. What was the principal?","options":["₹10,000","₹100","₹30,000","₹5,400"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Omits the ×100 in the principal formula, giving 1800/(6×3)."},{"option_index":2,"misconception":"Omits time in the denominator, giving 1800×100/6."},{"option_index":3,"misconception":"Multiplies the interest by time instead of dividing, giving 1800×3."}],"explanation":"P = 100×SI/(R×T) = 100×1800/(6×3) = ₹10,000.","concept_id":"eco610-mon-credit-definition","strand":"Money and Credit","kind":"mcq"},{"id":"credit-loan-as-an-agreement-to-repay-borrowed-money-with-interest-006","band":"K5","grade":10,"subject":"Mathematics","concept":"credit (loan) as an agreement to repay borrowed money with interest","difficulty":2,"stem":"A loan of ₹18,000 is repaid after 2 years with total amount ₹20,160. What annual simple interest rate was charged?","options":["12%","6%","0.06%","3%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Forgets to divide by time, treating the total interest as one year's interest."},{"option_index":2,"misconception":"Decimal conversion error when changing 0.06 to a percent."},{"option_index":3,"misconception":"Uses T = 4 years instead of 2 years."}],"explanation":"SI = 20160−18000 = ₹2,160; R = 2160×100/(18000×2) = 6%.","concept_id":"eco610-mon-credit-definition","strand":"Money and Credit","kind":"mcq"},{"id":"credit-loan-as-an-agreement-to-repay-borrowed-money-with-interest-007","band":"K5","grade":10,"subject":"Mathematics","concept":"credit (loan) as an agreement to repay borrowed money with interest","difficulty":2,"stem":"A loan doubles itself in 10 years at simple interest. What is the annual rate of interest?","options":["5%","20%","10%","100%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Halves the correct rate, thinking doubling means half the rate."},{"option_index":1,"misconception":"Uses total amount 2P instead of interest P in the formula."},{"option_index":3,"misconception":"Thinks doubling means 100% interest per year."}],"explanation":"For principal P, SI = P; R = P×100/(P×10) = 10%.","concept_id":"eco610-mon-credit-definition","strand":"Money and Credit","kind":"mcq"},{"id":"credit-loan-as-an-agreement-to-repay-borrowed-money-with-interest-008","band":"K5","grade":10,"subject":"Mathematics","concept":"credit (loan) as an agreement to repay borrowed money with interest","difficulty":2,"stem":"A loan of ₹6,000 is taken at 10% per annum simple interest for 9 months. What total amount is repaid?","options":["₹450","₹6,600","₹6,900","₹6,450"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Reports only the simple interest, forgetting to add the principal."},{"option_index":1,"misconception":"Uses 1 year instead of converting 9 months to 0.75 year."},{"option_index":2,"misconception":"Converts 9 months to 1.5 years by dividing by 6 instead of 12."}],"explanation":"SI = 6000×10×(9/12)/100 = ₹450; amount = 6000+450 = ₹6,450.","concept_id":"eco610-mon-credit-definition","strand":"Money and Credit","kind":"mcq"},{"id":"credit-loan-as-an-agreement-to-repay-borrowed-money-with-interest-009","band":"K5","grade":10,"subject":"Mathematics","concept":"credit (loan) as an agreement to repay borrowed money with interest","difficulty":2,"stem":"A shopkeeper borrows ₹8,000 at 15% per annum simple interest and repays ₹9,200. For how many months was the loan taken?","options":["6 months","12 months","18 months","120 months"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Halves the correct time."},{"option_index":2,"misconception":"Uses 1.5 years instead of 1 year."},{"option_index":3,"misconception":"Conversion error: treats 1 year as 120 months instead of 12 months."}],"explanation":"SI = 9200−8000 = ₹1,200; T = 1200×100/(8000×15) = 1 year = 12 months.","concept_id":"eco610-mon-credit-definition","strand":"Money and Credit","kind":"mcq"},{"id":"credit-loan-as-an-agreement-to-repay-borrowed-money-with-interest-010","band":"K5","grade":10,"subject":"Mathematics","concept":"credit (loan) as an agreement to repay borrowed money with interest","difficulty":2,"stem":"What is the difference in simple interest between a loan of ₹10,000 at 10% per annum for 2 years and a loan of ₹12,000 at 8% per annum for 2 years?","options":["₹3,920","₹2,000","₹80","₹1,920"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Adds the two interests instead of finding the difference."},{"option_index":1,"misconception":"Reports only the first loan's interest."},{"option_index":3,"misconception":"Reports only the second loan's interest."}],"explanation":"SI1 = 10000×10×2/100 = ₹2,000; SI2 = 12000×8×2/100 = ₹1,920; difference = ₹80.","concept_id":"eco610-mon-credit-definition","strand":"Money and Credit","kind":"mcq"},{"id":"formal-sources-of-credit-banks-and-cooperative-societies-001","band":"K5","grade":10,"subject":"Mathematics","concept":"formal sources of credit: banks and cooperative societies","difficulty":2,"stem":"A cooperative society gives a loan of ₹12,000 at 8% per annum simple interest for 2 years. What is the total interest charged?","options":["960","1920","1996.8","192"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"calculated interest for only 1 year, ignoring the 2-year time period"},{"option_index":2,"misconception":"used compound interest annually instead of simple interest"},{"option_index":3,"misconception":"misplaced the decimal while multiplying by the percentage rate"}],"explanation":"SI = 12000 × 8 × 2 / 100 = ₹1920.","concept_id":"eco610-mon-formal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"formal-sources-of-credit-banks-and-cooperative-societies-002","band":"K5","grade":10,"subject":"Mathematics","concept":"formal sources of credit: banks and cooperative societies","difficulty":2,"stem":"A bank gives a loan of ₹5,000 at 10% per annum simple interest for 2 years. What total amount must be repaid?","options":["5000","1000","6050","6000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"thought only the principal is repaid, ignoring interest"},{"option_index":1,"misconception":"reported only the interest, not principal plus interest"},{"option_index":2,"misconception":"used compound interest for 2 years instead of simple interest"}],"explanation":"SI = 5000 × 10 × 2 / 100 = 1000, so total repayment = 5000 + 1000 = ₹6000.","concept_id":"eco610-mon-formal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"formal-sources-of-credit-banks-and-cooperative-societies-003","band":"K5","grade":10,"subject":"Mathematics","concept":"formal sources of credit: banks and cooperative societies","difficulty":2,"stem":"A bank charges 10% simple interest per annum and a cooperative society charges 8% simple interest per annum. For a loan of ₹15,000 for 2 years, how much less interest does the cooperative society charge?","options":["600","300","2400","3000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"found interest difference for only 1 year by using the 2% rate difference once"},{"option_index":2,"misconception":"reported the cooperative society's total interest only"},{"option_index":3,"misconception":"reported the bank's total interest only"}],"explanation":"Bank interest = 3000, cooperative interest = 2400, so difference = ₹600.","concept_id":"eco610-mon-formal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"formal-sources-of-credit-banks-and-cooperative-societies-004","band":"K5","grade":10,"subject":"Mathematics","concept":"formal sources of credit: banks and cooperative societies","difficulty":2,"stem":"A cooperative society has 25 members. Each member saves ₹120 per month. How much does the society collect in one year?","options":["3000","1440","36000","30000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"calculated collection for one month only"},{"option_index":1,"misconception":"calculated savings for one member for one year only"},{"option_index":3,"misconception":"used 10 months instead of 12 months in a year"}],"explanation":"25 × 120 × 12 = ₹36,000.","concept_id":"eco610-mon-formal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"formal-sources-of-credit-banks-and-cooperative-societies-005","band":"K5","grade":10,"subject":"Mathematics","concept":"formal sources of credit: banks and cooperative societies","difficulty":2,"stem":"A bank gives 6% per annum simple interest on savings. If ₹25,000 is deposited for 3 years, what is the total amount in the account after 3 years?","options":["4500","29500","26500","25000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"reported only the interest, not the total amount"},{"option_index":2,"misconception":"added interest for only 1 year instead of 3 years"},{"option_index":3,"misconception":"thought the deposit amount remains unchanged, ignoring interest"}],"explanation":"SI = 25000 × 6 × 3 / 100 = 4500, so total = 25000 + 4500 = ₹29,500.","concept_id":"eco610-mon-formal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"formal-sources-of-credit-banks-and-cooperative-societies-006","band":"K5","grade":10,"subject":"Mathematics","concept":"formal sources of credit: banks and cooperative societies","difficulty":2,"stem":"A cooperative bank offers a loan at 7.5% per annum simple interest. What is the simple interest on ₹8,000 for 4 years?","options":["600","3200","240","2400"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"calculated interest for only 1 year"},{"option_index":1,"misconception":"used 10% per annum instead of 7.5%"},{"option_index":2,"misconception":"misplaced the decimal in the percentage calculation"}],"explanation":"SI = 8000 × 7.5 × 4 / 100 = ₹2400.","concept_id":"eco610-mon-formal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"formal-sources-of-credit-banks-and-cooperative-societies-007","band":"K5","grade":10,"subject":"Mathematics","concept":"formal sources of credit: banks and cooperative societies","difficulty":2,"stem":"A bank gives a loan at 11% simple interest per annum. A cooperative society gives the same loan at 9.5% simple interest per annum. For ₹20,000 for 3 years, how much total interest is saved by taking the cooperative loan?","options":["300","5700","900","6600"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"calculated interest saved for only 1 year using the 1.5% rate difference"},{"option_index":1,"misconception":"reported the cooperative society's total interest only"},{"option_index":3,"misconception":"reported the bank's total interest only"}],"explanation":"Bank interest = 6600, cooperative interest = 5700, so saving = ₹900.","concept_id":"eco610-mon-formal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"formal-sources-of-credit-banks-and-cooperative-societies-008","band":"K5","grade":10,"subject":"Mathematics","concept":"formal sources of credit: banks and cooperative societies","difficulty":2,"stem":"A cooperative society gives simple interest at 6% per annum. In how many years will ₹4,000 earn ₹960 as interest?","options":["4","2","0.4","24"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"used 12% per annum instead of 6%"},{"option_index":2,"misconception":"misplaced the decimal when solving for time"},{"option_index":3,"misconception":"divided by principal only instead of principal × rate"}],"explanation":"T = 960 × 100 / (4000 × 6) = 4 years.","concept_id":"eco610-mon-formal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"formal-sources-of-credit-banks-and-cooperative-societies-009","band":"K5","grade":10,"subject":"Mathematics","concept":"formal sources of credit: banks and cooperative societies","difficulty":2,"stem":"A bank gives 8% simple interest per annum on a deposit of ₹10,000 for 2 years. A cooperative society gives 8% compound interest per annum on the same deposit for 2 years. What is the difference in the interest earned?","options":["0","64","1600","1664"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"assumed simple and compound interest are always equal"},{"option_index":2,"misconception":"reported only the simple interest"},{"option_index":3,"misconception":"reported only the compound interest"}],"explanation":"Simple interest = 1600; compound interest = 1664; difference = ₹64.","concept_id":"eco610-mon-formal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"formal-sources-of-credit-banks-and-cooperative-societies-010","band":"K5","grade":10,"subject":"Mathematics","concept":"formal sources of credit: banks and cooperative societies","difficulty":2,"stem":"A cooperative society lends ₹18,000 at 9% per annum simple interest. If the loan is repaid after 9 months, what interest is due?","options":["1620","1080","1215","810"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"used 12 months instead of 9 months"},{"option_index":1,"misconception":"used 8 months instead of 9 months"},{"option_index":3,"misconception":"used 6 months instead of 9 months"}],"explanation":"SI = 18000 × 9 × 9 / (100 × 12) = ₹1215.","concept_id":"eco610-mon-formal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"why-formal-credit-is-usually-cheaper-and-more-accountable-than-informal-credit-001","band":"K5","grade":10,"subject":"Mathematics","concept":"why formal credit is usually cheaper and more accountable than informal credit","difficulty":2,"stem":"A formal bank charges simple interest at 10% per annum on a loan of ₹20,000 for 2 years. An informal moneylender charges simple interest at 30% per annum for the same loan and period. How much less interest does the borrower pay by taking the formal loan?","options":["₹4,000","₹12,000","₹8,000","₹16,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"mistakes the formal interest alone for the saving"},{"option_index":1,"misconception":"reports the informal interest alone instead of the difference"},{"option_index":3,"misconception":"adds the two interest amounts instead of subtracting"}],"explanation":"Formal interest = 20000×10×2/100 = ₹4,000; informal interest = 20000×30×2/100 = ₹12,000; saving = 12000 − 4000 = ₹8,000.","concept_id":"eco610-mon-formal-vs-informal","strand":"Money and Credit","kind":"mcq"},{"id":"why-formal-credit-is-usually-cheaper-and-more-accountable-than-informal-credit-002","band":"K5","grade":10,"subject":"Mathematics","concept":"why formal credit is usually cheaper and more accountable than informal credit","difficulty":2,"stem":"A bank gives a loan of ₹25,000 at 8% simple interest for 4 years. A moneylender charges ₹12,000 interest for the same loan and period. How much more interest does the moneylender charge than the bank?","options":["₹8,000","₹4,000","₹12,000","₹20,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"reports the bank's interest alone instead of the extra charged by the moneylender"},{"option_index":2,"misconception":"reports the moneylender's interest alone instead of the difference"},{"option_index":3,"misconception":"adds the two interest amounts instead of subtracting"}],"explanation":"Bank interest = 25000×8×4/100 = ₹8,000; extra = 12000 − 8000 = ₹4,000.","concept_id":"eco610-mon-formal-vs-informal","strand":"Money and Credit","kind":"mcq"},{"id":"why-formal-credit-is-usually-cheaper-and-more-accountable-than-informal-credit-003","band":"K5","grade":10,"subject":"Mathematics","concept":"why formal credit is usually cheaper and more accountable than informal credit","difficulty":2,"stem":"A formal bank gives a loan of ₹40,000 at 9% simple interest per annum for 3 years. What total amount must the borrower repay?","options":["₹10,800","₹40,000","₹52,000","₹50,800"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"gives only the simple interest, not the total repayment"},{"option_index":1,"misconception":"gives only the principal, ignoring interest"},{"option_index":2,"misconception":"uses 10% instead of 9% and adds interest to principal"}],"explanation":"SI = 40000×9×3/100 = ₹10,800; total = 40000 + 10800 = ₹50,800.","concept_id":"eco610-mon-formal-vs-informal","strand":"Money and Credit","kind":"mcq"},{"id":"why-formal-credit-is-usually-cheaper-and-more-accountable-than-informal-credit-004","band":"K5","grade":10,"subject":"Mathematics","concept":"why formal credit is usually cheaper and more accountable than informal credit","difficulty":3,"stem":"A formal bank charges 9% simple interest per annum on ₹18,000 for 2 years. An informal lender charges ₹7,200 interest for the same loan and period. How much less interest does the borrower pay by using the formal bank?","options":["₹3,240","₹7,200","₹3,960","₹10,440"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"reports the formal interest alone, not the saving"},{"option_index":1,"misconception":"reports the informal interest alone, not the saving"},{"option_index":3,"misconception":"adds the two interest amounts instead of subtracting"}],"explanation":"Formal interest = 18000×9×2/100 = ₹3,240; saving = 7200 − 3240 = ₹3,960.","concept_id":"eco610-mon-formal-vs-informal","strand":"Money and Credit","kind":"mcq"},{"id":"why-formal-credit-is-usually-cheaper-and-more-accountable-than-informal-credit-005","band":"K5","grade":10,"subject":"Mathematics","concept":"why formal credit is usually cheaper and more accountable than informal credit","difficulty":2,"stem":"For a loan of ₹30,000 for 1 year, a formal bank charges 11% simple interest and an informal lender charges 25% simple interest. How much less interest does the borrower pay to the formal bank?","options":["₹3,300","₹4,200","₹7,500","₹10,800"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"reports the formal interest alone, not the difference"},{"option_index":2,"misconception":"reports the informal interest alone, not the difference"},{"option_index":3,"misconception":"adds the two interest amounts instead of subtracting"}],"explanation":"Formal interest = 30000×11×1/100 = ₹3,300; informal interest = 30000×25×1/100 = ₹7,500; difference = ₹4,200.","concept_id":"eco610-mon-formal-vs-informal","strand":"Money and Credit","kind":"mcq"},{"id":"why-formal-credit-is-usually-cheaper-and-more-accountable-than-informal-credit-006","band":"K5","grade":10,"subject":"Mathematics","concept":"why formal credit is usually cheaper and more accountable than informal credit","difficulty":3,"stem":"A formal bank charges 8% simple interest per annum. If the total interest on a loan after 3 years is ₹4,800, what is the principal amount?","options":["₹60,000","₹30,000","₹15,000","₹20,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"forgets to multiply by the time period, using P = SI×100/R"},{"option_index":1,"misconception":"uses 2 years instead of 3 years"},{"option_index":2,"misconception":"uses 4 years instead of 3 years"}],"explanation":"P = 100×SI/(R×T) = 100×4800/(8×3) = ₹20,000.","concept_id":"eco610-mon-formal-vs-informal","strand":"Money and Credit","kind":"mcq"},{"id":"why-formal-credit-is-usually-cheaper-and-more-accountable-than-informal-credit-007","band":"K5","grade":10,"subject":"Mathematics","concept":"why formal credit is usually cheaper and more accountable than informal credit","difficulty":3,"stem":"A borrower needs ₹50,000 for 2 years. A formal bank charges 12% simple interest per annum. An informal lender charges 30% simple interest per annum. What is the difference in the total repayment amounts?","options":["₹18,000","₹12,000","₹30,000","₹42,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"reports the formal interest alone, not the difference in total repayment"},{"option_index":2,"misconception":"reports the informal interest alone, not the difference in total repayment"},{"option_index":3,"misconception":"adds the two interest amounts instead of finding the difference in totals"}],"explanation":"Formal total = 50000 + 12000 = ₹62,000; informal total = 50000 + 30000 = ₹80,000; difference = ₹18,000.","concept_id":"eco610-mon-formal-vs-informal","strand":"Money and Credit","kind":"mcq"},{"id":"why-formal-credit-is-usually-cheaper-and-more-accountable-than-informal-credit-008","band":"K5","grade":10,"subject":"Mathematics","concept":"why formal credit is usually cheaper and more accountable than informal credit","difficulty":2,"stem":"A formal lender charges 6% simple interest per annum on ₹35,000 for 4 years. An informal lender charges 18% simple interest per annum for the same loan and period. How much more interest does the informal lender charge?","options":["₹8,400","₹25,200","₹16,800","₹33,600"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"reports the formal interest alone, not the extra charged"},{"option_index":1,"misconception":"reports the informal interest alone, not the extra charged"},{"option_index":3,"misconception":"adds the two interest amounts instead of subtracting"}],"explanation":"Formal interest = 35000×6×4/100 = ₹8,400; informal interest = 35000×18×4/100 = ₹25,200; extra = ₹16,800.","concept_id":"eco610-mon-formal-vs-informal","strand":"Money and Credit","kind":"mcq"},{"id":"why-formal-credit-is-usually-cheaper-and-more-accountable-than-informal-credit-009","band":"K5","grade":10,"subject":"Mathematics","concept":"why formal credit is usually cheaper and more accountable than informal credit","difficulty":2,"stem":"A formal bank gives a loan of ₹24,000 at 10% simple interest per annum for 3 years. What total amount must the borrower repay?","options":["₹7,200","₹31,200","₹24,000","₹26,400"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"gives only the simple interest, not the total repayment"},{"option_index":2,"misconception":"gives only the principal, ignoring interest"},{"option_index":3,"misconception":"uses 1 year instead of 3 years and adds interest to principal"}],"explanation":"SI = 24000×10×3/100 = ₹7,200; total = 24000 + 7200 = ₹31,200.","concept_id":"eco610-mon-formal-vs-informal","strand":"Money and Credit","kind":"mcq"},{"id":"why-formal-credit-is-usually-cheaper-and-more-accountable-than-informal-credit-010","band":"K5","grade":10,"subject":"Mathematics","concept":"why formal credit is usually cheaper and more accountable than informal credit","difficulty":3,"stem":"An informal lender charges ₹9,000 interest on ₹15,000 for 3 years. A formal bank charges 8% simple interest per annum for the same loan and period. How much more interest does the informal lender charge?","options":["₹5,400","₹3,600","₹9,000","₹12,600"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"reports the formal interest alone, not the extra charged"},{"option_index":2,"misconception":"reports the informal interest alone, not the extra charged"},{"option_index":3,"misconception":"adds the two interest amounts instead of subtracting"}],"explanation":"Formal interest = 15000×8×3/100 = ₹3,600; extra = 9000 − 3600 = ₹5,400.","concept_id":"eco610-mon-formal-vs-informal","strand":"Money and Credit","kind":"mcq"},{"id":"informal-sources-of-credit-moneylenders-traders-and-relatives-001","band":"K5","grade":10,"subject":"Mathematics","concept":"informal sources of credit: moneylenders, traders and relatives","difficulty":2,"stem":"A moneylender lends ₹12,000 at 15% per annum simple interest for 2 years. What total amount must be repaid?","options":["₹13,800","₹15,870","₹15,600","₹14,400"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Calculated simple interest for only 1 year instead of 2 years."},{"option_index":1,"misconception":"Applied compound interest instead of simple interest."},{"option_index":3,"misconception":"Misread the annual rate as 10% instead of 15%."}],"explanation":"Simple interest = ₹12,000 × 15 × 2 / 100 = ₹3,600, so total repayment = ₹12,000 + ₹3,600 = ₹15,600.","concept_id":"eco610-mon-informal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"informal-sources-of-credit-moneylenders-traders-and-relatives-002","band":"K5","grade":10,"subject":"Mathematics","concept":"informal sources of credit: moneylenders, traders and relatives","difficulty":2,"stem":"A trader gives a loan of ₹8,000 at 2% per month simple interest for 6 months. What total amount is repaid?","options":["₹8,160","₹8,960","₹9,440","₹9,600"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Charged interest for only 1 month instead of 6 months."},{"option_index":2,"misconception":"Used 9 months instead of the given 6 months."},{"option_index":3,"misconception":"Used 10 months instead of the given 6 months."}],"explanation":"Interest = ₹8,000 × 2 × 6 / 100 = ₹960, so total repayment = ₹8,000 + ₹960 = ₹8,960.","concept_id":"eco610-mon-informal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"informal-sources-of-credit-moneylenders-traders-and-relatives-003","band":"K5","grade":10,"subject":"Mathematics","concept":"informal sources of credit: moneylenders, traders and relatives","difficulty":2,"stem":"A relative lends ₹15,000 without interest. It is repaid in 12 equal monthly installments. How much is each installment?","options":["₹1,350","₹1,125","₹1,500","₹1,250"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Added 8% interest even though the relative's loan is interest-free."},{"option_index":1,"misconception":"Deducted 10% before dividing, treating an interest-free loan as discounted."},{"option_index":2,"misconception":"Divided by 10 installments instead of 12."}],"explanation":"Since the loan is interest-free, each installment = ₹15,000 ÷ 12 = ₹1,250.","concept_id":"eco610-mon-informal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"informal-sources-of-credit-moneylenders-traders-and-relatives-004","band":"K5","grade":10,"subject":"Mathematics","concept":"informal sources of credit: moneylenders, traders and relatives","difficulty":2,"stem":"A moneylender charges simple interest at 4% per month. If ₹10,000 is borrowed for 5 months, what total amount is repaid?","options":["₹12,000","₹10,200","₹12,400","₹14,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Treated 4% as total interest for the whole period, not per month."},{"option_index":2,"misconception":"Charged interest for 6 months instead of 5."},{"option_index":3,"misconception":"Treated 4% per month as 40% total interest."}],"explanation":"Interest = ₹10,000 × 4 × 5 / 100 = ₹2,000, so total repayment = ₹10,000 + ₹2,000 = ₹12,000.","concept_id":"eco610-mon-informal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"informal-sources-of-credit-moneylenders-traders-and-relatives-005","band":"K5","grade":10,"subject":"Mathematics","concept":"informal sources of credit: moneylenders, traders and relatives","difficulty":2,"stem":"A trader charges 5% simple interest per annum on a 3-month credit of ₹6,000. What total amount is repaid?","options":["₹6,900","₹6,300","₹6,075","₹6,150"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Charged the annual rate for 3 years instead of 3 months."},{"option_index":1,"misconception":"Treated 5% as total interest for the 3-month period, not an annual rate."},{"option_index":3,"misconception":"Charged interest for 6 months instead of 3."}],"explanation":"Interest = ₹6,000 × 5 × 3 / (100 × 12) = ₹75, so total repayment = ₹6,000 + ₹75 = ₹6,075.","concept_id":"eco610-mon-informal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"informal-sources-of-credit-moneylenders-traders-and-relatives-006","band":"K5","grade":10,"subject":"Mathematics","concept":"informal sources of credit: moneylenders, traders and relatives","difficulty":2,"stem":"A moneylender offers a loan at 20% simple interest per annum, while a bank offers 12% simple interest per annum. On a loan of ₹20,000 for 1 year, how much more interest does the moneylender charge than the bank?","options":["₹2,400","₹1,600","₹4,000","₹3,200"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Calculated only the bank's interest instead of the difference."},{"option_index":2,"misconception":"Calculated only the moneylender's interest instead of the difference."},{"option_index":3,"misconception":"Applied the 8% rate difference for 2 years instead of 1 year."}],"explanation":"Difference in rates = 20% − 12% = 8%, so extra interest = ₹20,000 × 8 × 1 / 100 = ₹1,600.","concept_id":"eco610-mon-informal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"informal-sources-of-credit-moneylenders-traders-and-relatives-007","band":"K5","grade":10,"subject":"Mathematics","concept":"informal sources of credit: moneylenders, traders and relatives","difficulty":2,"stem":"A relative lends ₹24,000 interest-free. The borrower repays ₹1,000 first and then the rest in 8 equal monthly installments. What is the amount of each installment?","options":["₹3,000","₹2,750","₹2,300","₹2,875"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Divided the whole ₹24,000 by 8, ignoring the first ₹1,000 payment."},{"option_index":1,"misconception":"Subtracted ₹2,000 instead of ₹1,000 before dividing."},{"option_index":2,"misconception":"Divided the remaining amount by 10 instead of 8."}],"explanation":"Remaining amount = ₹24,000 − ₹1,000 = ₹23,000, so each installment = ₹23,000 ÷ 8 = ₹2,875.","concept_id":"eco610-mon-informal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"informal-sources-of-credit-moneylenders-traders-and-relatives-008","band":"K5","grade":10,"subject":"Mathematics","concept":"informal sources of credit: moneylenders, traders and relatives","difficulty":2,"stem":"A moneylender charges ₹2,500 as simple interest on a loan of ₹25,000 for 2 years. What is the annual rate of interest?","options":["5%","10%","2.5%","20%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Forgot to divide by the time period of 2 years."},{"option_index":2,"misconception":"Used 4 years instead of 2 years."},{"option_index":3,"misconception":"Multiplied by the time period instead of dividing."}],"explanation":"Rate = 100 × SI / (P × T) = 100 × ₹2,500 / (₹25,000 × 2) = 5%.","concept_id":"eco610-mon-informal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"informal-sources-of-credit-moneylenders-traders-and-relatives-009","band":"K5","grade":10,"subject":"Mathematics","concept":"informal sources of credit: moneylenders, traders and relatives","difficulty":2,"stem":"A trader gives credit at 1.5% simple interest per month. If ₹12,000 is borrowed for 4 months, what total amount is repaid?","options":["₹12,180","₹13,080","₹12,720","₹12,900"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Charged interest for only 1 month instead of 4 months."},{"option_index":1,"misconception":"Charged interest for 6 months instead of 4 months."},{"option_index":3,"misconception":"Charged interest for 5 months instead of 4 months."}],"explanation":"Interest = ₹12,000 × 1.5 × 4 / 100 = ₹720, so total repayment = ₹12,000 + ₹720 = ₹12,720.","concept_id":"eco610-mon-informal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"informal-sources-of-credit-moneylenders-traders-and-relatives-010","band":"K5","grade":10,"subject":"Mathematics","concept":"informal sources of credit: moneylenders, traders and relatives","difficulty":2,"stem":"A moneylender lends ₹5,000 at 3% per month simple interest. A relative lends the same ₹5,000 interest-free for the same period. If the moneylender's loan is for 8 months, how much less does the borrower pay to the relative than to the moneylender?","options":["₹150","₹1,200","₹1,500","₹5,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Treated 3% as total interest for 1 month instead of a monthly rate for 8 months."},{"option_index":2,"misconception":"Charged interest for 10 months instead of 8 months."},{"option_index":3,"misconception":"Compared only the principal and ignored the moneylender's interest."}],"explanation":"Moneylender interest = ₹5,000 × 3 × 8 / 100 = ₹1,200; relative interest = ₹0, so the borrower pays ₹1,200 less to the relative.","concept_id":"eco610-mon-informal-credit","strand":"Money and Credit","kind":"mcq"},{"id":"modern-forms-of-money-currency-and-bank-deposits-001","band":"K5","grade":10,"subject":"Mathematics","concept":"modern forms of money: currency and bank deposits","difficulty":2,"stem":"Rita has ₹2,500 in currency notes and also has ₹1,750 in her bank account. What is the total amount of money she has in these modern forms?","options":["₹2,500","₹1,750","₹4,250","₹750"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Counted only currency and ignored bank deposits as money."},{"option_index":1,"misconception":"Counted only bank deposits and ignored currency."},{"option_index":3,"misconception":"Subtracted the deposit from currency instead of adding."}],"explanation":"Total modern money = currency + bank deposit = ₹2,500 + ₹1,750 = ₹4,250.","concept_id":"eco610-mon-modern-forms","strand":"Money and Credit","kind":"mcq"},{"id":"modern-forms-of-money-currency-and-bank-deposits-002","band":"K5","grade":10,"subject":"Mathematics","concept":"modern forms of money: currency and bank deposits","difficulty":2,"stem":"A shopkeeper deposits ₹3,600 in cash and later withdraws ₹1,250 from the same bank account. What is the net amount added to her bank deposit?","options":["₹4,850","₹2,350","₹1,250","₹3,600"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Added the withdrawal to the deposit instead of subtracting it."},{"option_index":2,"misconception":"Confused the withdrawal amount with the net deposit."},{"option_index":3,"misconception":"Ignored the withdrawal and kept only the initial cash deposit."}],"explanation":"Net deposit = ₹3,600 - ₹1,250 = ₹2,350.","concept_id":"eco610-mon-modern-forms","strand":"Money and Credit","kind":"mcq"},{"id":"modern-forms-of-money-currency-and-bank-deposits-003","band":"K5","grade":10,"subject":"Mathematics","concept":"modern forms of money: currency and bank deposits","difficulty":2,"stem":"A bank pays simple interest at 4% per annum on a deposit of ₹12,000 for 1 year. How much interest is earned?","options":["₹4,800","₹480","₹48","₹1,200"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Multiplied principal by rate but forgot to divide by 100."},{"option_index":2,"misconception":"Divided by 1000 instead of 100 when converting percentage."},{"option_index":3,"misconception":"Used 10% instead of the given 4% rate."}],"explanation":"Simple interest = 12,000 × 4 × 1 / 100 = ₹480.","concept_id":"eco610-mon-modern-forms","strand":"Money and Credit","kind":"mcq"},{"id":"modern-forms-of-money-currency-and-bank-deposits-004","band":"K5","grade":10,"subject":"Mathematics","concept":"modern forms of money: currency and bank deposits","difficulty":2,"stem":"A cheque of ₹7,050 is deposited into an account that already has ₹2,300. What is the new bank deposit balance?","options":["₹4,750","₹7,050","₹2,300","₹9,350"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Subtracted the cheque amount from the existing balance instead of adding it."},{"option_index":1,"misconception":"Ignored the existing balance and used only the cheque amount."},{"option_index":2,"misconception":"Ignored the cheque and kept only the existing balance."}],"explanation":"New balance = ₹2,300 + ₹7,050 = ₹9,350.","concept_id":"eco610-mon-modern-forms","strand":"Money and Credit","kind":"mcq"},{"id":"modern-forms-of-money-currency-and-bank-deposits-005","band":"K5","grade":10,"subject":"Mathematics","concept":"modern forms of money: currency and bank deposits","difficulty":2,"stem":"Meera has ₹5,000 in currency. She deposits 40% of it into her bank account. How much remains as currency?","options":["₹2,000","₹3,000","₹5,000","₹4,800"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Found the amount deposited instead of the amount remaining as currency."},{"option_index":2,"misconception":"Thought depositing money does not reduce currency held in hand."},{"option_index":3,"misconception":"Misread 40% as 4% and subtracted only ₹200."}],"explanation":"40% of ₹5,000 = ₹2,000 deposited, so remaining currency = ₹5,000 - ₹2,000 = ₹3,000.","concept_id":"eco610-mon-modern-forms","strand":"Money and Credit","kind":"mcq"},{"id":"modern-forms-of-money-currency-and-bank-deposits-006","band":"K5","grade":10,"subject":"Mathematics","concept":"modern forms of money: currency and bank deposits","difficulty":2,"stem":"A person writes a cheque for ₹4,250. If his bank balance was ₹6,000, what is the balance after the cheque is cleared?","options":["₹1,750","₹10,250","₹4,250","₹6,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Added the cheque amount to the balance instead of subtracting it."},{"option_index":2,"misconception":"Reported the cheque amount rather than the remaining balance."},{"option_index":3,"misconception":"Assumed the cheque caused no change in the balance."}],"explanation":"Balance after cheque = ₹6,000 - ₹4,250 = ₹1,750.","concept_id":"eco610-mon-modern-forms","strand":"Money and Credit","kind":"mcq"},{"id":"modern-forms-of-money-currency-and-bank-deposits-007","band":"K5","grade":10,"subject":"Mathematics","concept":"modern forms of money: currency and bank deposits","difficulty":2,"stem":"A bank accepts ₹15,000 as a fixed deposit and pays simple interest at 6% per annum for 2 years. What is the total interest?","options":["₹900","₹1,800","₹18,000","₹3,600"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Calculated interest for only 1 year, ignoring the 2-year period."},{"option_index":2,"misconception":"Multiplied principal by rate and time but forgot to divide by 100."},{"option_index":3,"misconception":"Used 12% per annum instead of 6%."}],"explanation":"Simple interest = 15,000 × 6 × 2 / 100 = ₹1,800.","concept_id":"eco610-mon-modern-forms","strand":"Money and Credit","kind":"mcq"},{"id":"modern-forms-of-money-currency-and-bank-deposits-008","band":"K5","grade":10,"subject":"Mathematics","concept":"modern forms of money: currency and bank deposits","difficulty":2,"stem":"In a bank, demand deposits are withdrawable on demand. If a person has ₹9,750 in demand deposits and withdraws ₹2,875, what is the remaining deposit?","options":["₹12,625","₹9,750","₹6,875","₹2,875"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Added the withdrawal instead of subtracting it."},{"option_index":1,"misconception":"Ignored the withdrawal and kept the original deposit."},{"option_index":3,"misconception":"Reported the withdrawal amount rather than the remaining deposit."}],"explanation":"Remaining demand deposit = ₹9,750 - ₹2,875 = ₹6,875.","concept_id":"eco610-mon-modern-forms","strand":"Money and Credit","kind":"mcq"},{"id":"modern-forms-of-money-currency-and-bank-deposits-009","band":"K5","grade":10,"subject":"Mathematics","concept":"modern forms of money: currency and bank deposits","difficulty":2,"stem":"A shopkeeper has ₹1,250 in coins and ₹3,750 in bank deposits. He uses ₹500 from bank deposit to buy goods by cheque. What is the total modern money left with him?","options":["₹5,000","₹3,250","₹4,500","₹1,250"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Forgot that the cheque payment reduces the bank deposit."},{"option_index":1,"misconception":"After subtracting the cheque, counted only the bank deposit and ignored currency."},{"option_index":3,"misconception":"Counted only the currency and ignored bank deposits."}],"explanation":"Total = ₹1,250 + ₹3,750 - ₹500 = ₹4,500.","concept_id":"eco610-mon-modern-forms","strand":"Money and Credit","kind":"mcq"},{"id":"modern-forms-of-money-currency-and-bank-deposits-010","band":"K5","grade":10,"subject":"Mathematics","concept":"modern forms of money: currency and bank deposits","difficulty":2,"stem":"A bank deposit earns simple interest at 5% per annum. If the interest after 3 years is ₹2,250, what was the principal?","options":["₹45,000","₹750","₹15,000","₹1,500"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Ignored the 3-year time period in the denominator."},{"option_index":1,"misconception":"Divided the total interest by 3 and ignored the rate."},{"option_index":3,"misconception":"Made a decimal-place error, giving one-tenth of the correct principal."}],"explanation":"P = 100 × I / (R × T) = 100 × 2,250 / (5 × 3) = ₹15,000.","concept_id":"eco610-mon-modern-forms","strand":"Money and Credit","kind":"mcq"},{"id":"money-as-a-medium-of-exchange-that-removes-the-need-for-double-coincidence-001","band":"K5","grade":10,"subject":"Mathematics","concept":"money as a medium of exchange that removes the need for double coincidence","difficulty":2,"stem":"In a barter system with 4 distinct goods, every direct exchange involves a pair of goods. How many different pairs of goods can be directly exchanged?","options":["4","8","6","12"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Assumes one exchange pair per good instead of counting pairs of goods."},{"option_index":1,"misconception":"Doubles the number of goods instead of using combinations."},{"option_index":3,"misconception":"Counts both orders (A-for-B and B-for-A) as different exchange pairs."}],"explanation":"Number of unordered pairs from 4 goods is 4×3/2 = 6.","concept_id":"eco610-mon-money-as-medium","strand":"Money and Credit","kind":"mcq"},{"id":"money-as-a-medium-of-exchange-that-removes-the-need-for-double-coincidence-002","band":"K5","grade":10,"subject":"Mathematics","concept":"money as a medium of exchange that removes the need for double coincidence","difficulty":2,"stem":"In a barter economy with 5 different goods, a direct exchange rate is needed for every pair of goods. How many direct exchange rates are needed?","options":["20","10","5","25"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Counts both directions as separate rates."},{"option_index":2,"misconception":"Assumes one rate per good."},{"option_index":3,"misconception":"Squares the number of goods."}],"explanation":"Number of unordered pairs is 5×4/2 = 10.","concept_id":"eco610-mon-money-as-medium","strand":"Money and Credit","kind":"mcq"},{"id":"money-as-a-medium-of-exchange-that-removes-the-need-for-double-coincidence-003","band":"K5","grade":10,"subject":"Mathematics","concept":"money as a medium of exchange that removes the need for double coincidence","difficulty":2,"stem":"In a market of 8 traders, each trader sells one item for money and buys one item with money. How many money payments are made in total?","options":["16","7","64","8"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Counts each trader's receiving and paying separately."},{"option_index":1,"misconception":"Uses one less than the number of traders."},{"option_index":2,"misconception":"Squares the number of traders."}],"explanation":"Each of the 8 sales involves one money payment, so 8 payments are made.","concept_id":"eco610-mon-money-as-medium","strand":"Money and Credit","kind":"mcq"},{"id":"money-as-a-medium-of-exchange-that-removes-the-need-for-double-coincidence-004","band":"K5","grade":10,"subject":"Mathematics","concept":"money as a medium of exchange that removes the need for double coincidence","difficulty":2,"stem":"A farmer with wheat wants shoes. A shoemaker with shoes wants cloth. A clothmaker with cloth wants wheat. If each trader gives their good to the next trader in this 3-person cycle, how many exchanges complete the cycle?","options":["3","1","2","6"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Thinks one direct barter exchange can satisfy all three."},{"option_index":2,"misconception":"Thinks two exchanges are enough to complete a three-person cycle."},{"option_index":3,"misconception":"Counts all ordered pairs among three traders."}],"explanation":"Three goods must move: wheat to clothmaker, cloth to shoemaker, shoes to farmer.","concept_id":"eco610-mon-money-as-medium","strand":"Money and Credit","kind":"mcq"},{"id":"money-as-a-medium-of-exchange-that-removes-the-need-for-double-coincidence-005","band":"K5","grade":10,"subject":"Mathematics","concept":"money as a medium of exchange that removes the need for double coincidence","difficulty":2,"stem":"At a barter fair, 9 traders each want one item. Only 3 mutual-want pairs form. How many traders can complete a direct barter?","options":["3","6","9","12"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Counts the mutual-want pairs instead of the traders in them."},{"option_index":2,"misconception":"Assumes every trader can barter even without a mutual-want pair."},{"option_index":3,"misconception":"Doubles the number of pairs incorrectly."}],"explanation":"Each mutual-want pair serves 2 traders, so 3 pairs serve 3×2 = 6 traders.","concept_id":"eco610-mon-money-as-medium","strand":"Money and Credit","kind":"mcq"},{"id":"money-as-a-medium-of-exchange-that-removes-the-need-for-double-coincidence-006","band":"K5","grade":10,"subject":"Mathematics","concept":"money as a medium of exchange that removes the need for double coincidence","difficulty":2,"stem":"In a barter group, 14 traders are arranged into mutual-want pairs so that each pair can barter directly. How many pairs are formed?","options":["14","28","7","6"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Assumes one pair per trader."},{"option_index":1,"misconception":"Counts both directions within each pair."},{"option_index":3,"misconception":"Subtracts one instead of dividing by two."}],"explanation":"14 traders divided into pairs gives 14÷2 = 7 pairs.","concept_id":"eco610-mon-money-as-medium","strand":"Money and Credit","kind":"mcq"},{"id":"money-as-a-medium-of-exchange-that-removes-the-need-for-double-coincidence-007","band":"K5","grade":10,"subject":"Mathematics","concept":"money as a medium of exchange that removes the need for double coincidence","difficulty":3,"stem":"In a barter economy with 12 goods, every pair of goods needs an exchange ratio. With money, each good has one price in money. How many barter exchange ratios are eliminated by using money?","options":["66","12","144","54"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Gives the total barter ratios but forgets to subtract the money prices."},{"option_index":1,"misconception":"Gives the number of money prices, not the number of eliminated barter ratios."},{"option_index":2,"misconception":"Squares the number of goods."}],"explanation":"Barter ratios = 12×11/2 = 66; money prices = 12; eliminated = 66−12 = 54.","concept_id":"eco610-mon-money-as-medium","strand":"Money and Credit","kind":"mcq"},{"id":"money-as-a-medium-of-exchange-that-removes-the-need-for-double-coincidence-008","band":"K5","grade":10,"subject":"Mathematics","concept":"money as a medium of exchange that removes the need for double coincidence","difficulty":2,"stem":"Six producers are in a barter system. If they form 3 mutual-want pairs, how many producers can trade directly without money?","options":["6","3","12","5"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Counts the pairs instead of the producers in them."},{"option_index":2,"misconception":"Doubles the number of pairs and then counts traders incorrectly."},{"option_index":3,"misconception":"Subtracts one producer from the total."}],"explanation":"3 mutual-want pairs involve 3×2 = 6 producers.","concept_id":"eco610-mon-money-as-medium","strand":"Money and Credit","kind":"mcq"},{"id":"money-as-a-medium-of-exchange-that-removes-the-need-for-double-coincidence-009","band":"K5","grade":10,"subject":"Mathematics","concept":"money as a medium of exchange that removes the need for double coincidence","difficulty":2,"stem":"Ten traders can be arranged into mutual-want pairs so that each pair can barter directly. How many pairs are formed?","options":["10","5","20","9"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Assumes one pair per trader."},{"option_index":2,"misconception":"Counts both directions for each pair."},{"option_index":3,"misconception":"Subtracts one instead of dividing by two."}],"explanation":"10 traders divided into pairs gives 10÷2 = 5 pairs.","concept_id":"eco610-mon-money-as-medium","strand":"Money and Credit","kind":"mcq"},{"id":"money-as-a-medium-of-exchange-that-removes-the-need-for-double-coincidence-010","band":"K5","grade":10,"subject":"Mathematics","concept":"money as a medium of exchange that removes the need for double coincidence","difficulty":2,"stem":"Money removes the need for double coincidence. In a market of 7 traders, each trader sells one good for money. How many selling transactions occur?","options":["14","6","7","49"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Counts buying and selling separately."},{"option_index":1,"misconception":"Uses one less than the number of traders."},{"option_index":3,"misconception":"Squares the number of traders."}],"explanation":"Each of the 7 traders sells once, so there are 7 selling transactions.","concept_id":"eco610-mon-money-as-medium","strand":"Money and Credit","kind":"mcq"},{"id":"rbi-s-role-in-supervising-banks-and-the-formal-credit-system-001","band":"K5","grade":10,"subject":"Mathematics","concept":"RBI's role in supervising banks and the formal credit system","difficulty":2,"stem":"A bank has total deposits of ₹8,000. The RBI requires it to keep 12.5% as cash reserves. How much must the bank keep as reserves?","options":["₹7,000","₹800","₹1,000","₹1,600"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Subtracts the reserve from deposits and reports the lendable amount instead of the reserve amount."},{"option_index":1,"misconception":"Ignores the decimal in 12.5% and treats it as 10%."},{"option_index":3,"misconception":"Mistakes 12.5% for 20% when finding the reserve."}],"explanation":"12.5% of ₹8,000 = 0.125 × 8000 = ₹1,000.","concept_id":"eco610-mon-rbi-supervision","strand":"Money and Credit","kind":"mcq"},{"id":"rbi-s-role-in-supervising-banks-and-the-formal-credit-system-002","band":"K5","grade":10,"subject":"Mathematics","concept":"RBI's role in supervising banks and the formal credit system","difficulty":2,"stem":"A bank has ₹20,000 in deposits. If the RBI sets the reserve requirement at 15%, what is the maximum amount the bank can lend from these deposits?","options":["₹17,000","₹3,000","₹15,000","₹18,500"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Confuses the reserve amount with the lendable amount."},{"option_index":2,"misconception":"Subtracts 25% instead of 15% from deposits."},{"option_index":3,"misconception":"Subtracts only half of the required reserve (7.5%) from deposits."}],"explanation":"Reserve = 15% of ₹20,000 = ₹3,000, so lendable = ₹20,000 − ₹3,000 = ₹17,000.","concept_id":"eco610-mon-rbi-supervision","strand":"Money and Credit","kind":"mcq"},{"id":"rbi-s-role-in-supervising-banks-and-the-formal-credit-system-003","band":"K5","grade":10,"subject":"Mathematics","concept":"RBI's role in supervising banks and the formal credit system","difficulty":2,"stem":"The RBI raises the repo rate, and a formal bank increases its simple interest rate on loans from 10% to 11% per year. On a loan of ₹40,000 for 1 year, how much extra interest will the borrower pay?","options":["₹4,000","₹4,400","₹800","₹400"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Calculates the original interest at 10% instead of the increase."},{"option_index":1,"misconception":"Calculates the new total interest at 11% instead of the increase."},{"option_index":2,"misconception":"Uses a 2 percentage point increase instead of 1 percentage point."}],"explanation":"Extra interest = ₹40,000 × (11% − 10%) × 1 = ₹40,000 × 1% = ₹400.","concept_id":"eco610-mon-rbi-supervision","strand":"Money and Credit","kind":"mcq"},{"id":"rbi-s-role-in-supervising-banks-and-the-formal-credit-system-004","band":"K5","grade":10,"subject":"Mathematics","concept":"RBI's role in supervising banks and the formal credit system","difficulty":2,"stem":"If the RBI sets the cash reserve ratio (CRR) at 25%, what is the maximum money multiplier for the banking system? (Use money multiplier = 1 / CRR.)","options":["25","4","0.25","5"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses the CRR percentage itself as the multiplier."},{"option_index":2,"misconception":"Leaves the CRR as a decimal fraction instead of taking its reciprocal."},{"option_index":3,"misconception":"Adds 1 to the reciprocal of the CRR, treating it as initial deposit plus created credit."}],"explanation":"Money multiplier = 1 / 0.25 = 4.","concept_id":"eco610-mon-rbi-supervision","strand":"Money and Credit","kind":"mcq"},{"id":"rbi-s-role-in-supervising-banks-and-the-formal-credit-system-005","band":"K5","grade":10,"subject":"Mathematics","concept":"RBI's role in supervising banks and the formal credit system","difficulty":2,"stem":"A primary deposit of ₹10,000 enters the banking system. If the RBI requires a 20% cash reserve ratio, what is the maximum total deposit creation possible? (Use total deposits = primary deposit / CRR.)","options":["₹10,000","₹12,500","₹50,000","₹40,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reports only the initial primary deposit and ignores credit creation."},{"option_index":1,"misconception":"Uses 1/(1−CRR) instead of 1/CRR, treating CRR like a leakage rate in a different multiplier formula."},{"option_index":3,"misconception":"Calculates the total lendable amount as 80% of the final total deposits and mistakes it for total deposits."}],"explanation":"Total deposits = ₹10,000 / 0.20 = ₹50,000.","concept_id":"eco610-mon-rbi-supervision","strand":"Money and Credit","kind":"mcq"},{"id":"rbi-s-role-in-supervising-banks-and-the-formal-credit-system-006","band":"K5","grade":10,"subject":"Mathematics","concept":"RBI's role in supervising banks and the formal credit system","difficulty":2,"stem":"The RBI requires a bank to maintain a statutory liquidity ratio (SLR) of 18%. If the bank has ₹2,00,000 in deposits, how much must it invest in approved securities?","options":["₹36,000","₹1,64,000","₹18,000","₹32,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Subtracts the SLR amount from deposits and reports the amount left for lending."},{"option_index":2,"misconception":"Uses half the SLR percentage (9%) instead of 18%."},{"option_index":3,"misconception":"Mistakes 18% for 16% when computing the SLR amount."}],"explanation":"SLR amount = 18% of ₹2,00,000 = ₹36,000.","concept_id":"eco610-mon-rbi-supervision","strand":"Money and Credit","kind":"mcq"},{"id":"rbi-s-role-in-supervising-banks-and-the-formal-credit-system-007","band":"K5","grade":10,"subject":"Mathematics","concept":"RBI's role in supervising banks and the formal credit system","difficulty":2,"stem":"A formal bank charges 9% simple interest per year, while an informal moneylender charges 27% per year. For a loan of ₹12,000 for 1 year, how much less interest does the borrower pay at the formal bank?","options":["₹3,240","₹1,080","₹4,320","₹2,160"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Calculates the informal lender's interest only."},{"option_index":1,"misconception":"Calculates the formal bank's interest only."},{"option_index":2,"misconception":"Adds the formal and informal interest amounts instead of subtracting."}],"explanation":"Difference = ₹12,000 × (27% − 9%) × 1 = ₹12,000 × 18% = ₹2,160.","concept_id":"eco610-mon-rbi-supervision","strand":"Money and Credit","kind":"mcq"},{"id":"rbi-s-role-in-supervising-banks-and-the-formal-credit-system-008","band":"K5","grade":10,"subject":"Mathematics","concept":"RBI's role in supervising banks and the formal credit system","difficulty":2,"stem":"RBI norms require a bank to keep capital equal to 10% of its risk-weighted assets. If the risk-weighted assets are ₹50,000 crore, how much capital must the bank maintain?","options":["₹45,000 crore","₹5,000 crore","₹500 crore","₹10,000 crore"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Subtracts the required capital from assets and reports the remaining assets."},{"option_index":2,"misconception":"Uses 1% instead of 10% because of a misplaced decimal."},{"option_index":3,"misconception":"Uses 20% instead of 10% when taking the required capital."}],"explanation":"Required capital = 10% of ₹50,000 crore = ₹5,000 crore.","concept_id":"eco610-mon-rbi-supervision","strand":"Money and Credit","kind":"mcq"},{"id":"rbi-s-role-in-supervising-banks-and-the-formal-credit-system-009","band":"K5","grade":10,"subject":"Mathematics","concept":"RBI's role in supervising banks and the formal credit system","difficulty":2,"stem":"A formal bank offers 7% simple interest per year on a fixed deposit. How much interest will a depositor earn on ₹25,000 in 3 years?","options":["₹1,750","₹7,000","₹5,250","₹525"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Calculates simple interest for only 1 year instead of 3 years."},{"option_index":1,"misconception":"Uses 28% total interest (multiplying 7% by 4) instead of 7% per year for 3 years."},{"option_index":3,"misconception":"Uses 0.7% instead of 7% because of a misplaced decimal."}],"explanation":"Interest = ₹25,000 × 7% × 3 = ₹5,250.","concept_id":"eco610-mon-rbi-supervision","strand":"Money and Credit","kind":"mcq"},{"id":"rbi-s-role-in-supervising-banks-and-the-formal-credit-system-010","band":"K5","grade":10,"subject":"Mathematics","concept":"RBI's role in supervising banks and the formal credit system","difficulty":2,"stem":"In a district, 60% of total loans are taken from formal sources supervised by the RBI. If total loans are ₹1,50,000, how much is borrowed from formal sources?","options":["₹60,000","₹90","₹15,000","₹90,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Calculates the informal share (40%) instead of the formal share (60%)."},{"option_index":1,"misconception":"Ignores the place value in ₹1,50,000 and takes 60% of 150."},{"option_index":2,"misconception":"Uses 10% instead of 60% when finding the formal share."}],"explanation":"Formal loans = 60% of ₹1,50,000 = ₹90,000.","concept_id":"eco610-mon-rbi-supervision","strand":"Money and Credit","kind":"mcq"},{"id":"self-help-groups-as-a-source-of-small-collective-credit-for-the-poor-001","band":"K5","grade":10,"subject":"Mathematics","concept":"self-help groups as a source of small collective credit for the poor","difficulty":2,"stem":"In a self-help group, 12 women save ₹250 each every month. How much does the group save in one month?","options":["₹3,000","₹262","₹2,750","₹3,600"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds the number of women to the monthly amount instead of multiplying."},{"option_index":2,"misconception":"Excludes one member and multiplies by 11 instead of 12."},{"option_index":3,"misconception":"Multiplies by ₹300 instead of ₹250 per member."}],"explanation":"12 women × ₹250 = ₹3,000.","concept_id":"eco610-mon-shg","strand":"Money and Credit","kind":"mcq"},{"id":"self-help-groups-as-a-source-of-small-collective-credit-for-the-poor-002","band":"K5","grade":10,"subject":"Mathematics","concept":"self-help groups as a source of small collective credit for the poor","difficulty":2,"stem":"An SHG has ₹1,800 in its savings fund. It lends 2/3 of this amount to a member. How much loan does the member get?","options":["₹600","₹1,200","₹900","₹2,700"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Finds the remaining one-third instead of the two-thirds lent."},{"option_index":2,"misconception":"Takes half of the fund instead of two-thirds."},{"option_index":3,"misconception":"Multiplies by 3/2 instead of 2/3."}],"explanation":"₹1,800 × 2/3 = ₹1,200.","concept_id":"eco610-mon-shg","strand":"Money and Credit","kind":"mcq"},{"id":"self-help-groups-as-a-source-of-small-collective-credit-for-the-poor-003","band":"K5","grade":10,"subject":"Mathematics","concept":"self-help groups as a source of small collective credit for the poor","difficulty":2,"stem":"A group has a corpus of ₹8,500. It gives equal loans of ₹1,250 to 4 members. How much money is left in the corpus?","options":["₹4,500","₹7,250","₹3,500","₹13,500"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses ₹1,000 per loan instead of ₹1,250."},{"option_index":1,"misconception":"Subtracts only one loan instead of four loans."},{"option_index":3,"misconception":"Adds the total loan amount to the corpus instead of subtracting it."}],"explanation":"Total loans = 4 × ₹1,250 = ₹5,000; left = ₹8,500 − ₹5,000 = ₹3,500.","concept_id":"eco610-mon-shg","strand":"Money and Credit","kind":"mcq"},{"id":"self-help-groups-as-a-source-of-small-collective-credit-for-the-poor-004","band":"K5","grade":10,"subject":"Mathematics","concept":"self-help groups as a source of small collective credit for the poor","difficulty":2,"stem":"A self-help group has 15 members. Each member repays ₹120 per month. How much will the group collect in 10 months?","options":["₹1,800","₹12,000","₹18,000","₹15,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Multiplies 15 × 120 but forgets the 10 months."},{"option_index":1,"misconception":"Uses 10 members instead of 15 across 10 months."},{"option_index":3,"misconception":"Uses ₹100 per member per month instead of ₹120."}],"explanation":"15 × ₹120 × 10 = ₹18,000.","concept_id":"eco610-mon-shg","strand":"Money and Credit","kind":"mcq"},{"id":"self-help-groups-as-a-source-of-small-collective-credit-for-the-poor-005","band":"K5","grade":10,"subject":"Mathematics","concept":"self-help groups as a source of small collective credit for the poor","difficulty":2,"stem":"An SHG lends ₹5,000 to a member at 12% simple interest per year for 6 months. How much interest must the member pay?","options":["₹600","₹300","₹150","₹360"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Charges interest for a full year instead of half a year."},{"option_index":2,"misconception":"Halves both the rate and the time."},{"option_index":3,"misconception":"Treats 6 months as 0.6 year instead of 1/2 year."}],"explanation":"Interest = ₹5,000 × 12/100 × 6/12 = ₹300.","concept_id":"eco610-mon-shg","strand":"Money and Credit","kind":"mcq"},{"id":"self-help-groups-as-a-source-of-small-collective-credit-for-the-poor-006","band":"K5","grade":10,"subject":"Mathematics","concept":"self-help groups as a source of small collective credit for the poor","difficulty":2,"stem":"In an SHG, 20 members save ₹75 per week each. How much do they save altogether in 4 weeks?","options":["₹1,500","₹300","₹6,000","₹12,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Multiplies 20 × 75 but forgets the 4 weeks."},{"option_index":1,"misconception":"Multiplies 75 × 4 but ignores the 20 members."},{"option_index":3,"misconception":"Uses 8 weeks instead of 4 weeks."}],"explanation":"20 × ₹75 × 4 = ₹6,000.","concept_id":"eco610-mon-shg","strand":"Money and Credit","kind":"mcq"},{"id":"self-help-groups-as-a-source-of-small-collective-credit-for-the-poor-007","band":"K5","grade":10,"subject":"Mathematics","concept":"self-help groups as a source of small collective credit for the poor","difficulty":2,"stem":"A member borrows ₹2,400 from an SHG at 18% simple interest per year. She repays after 4 months. What is the interest?","options":["₹432","₹72","₹288","₹144"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Charges annual interest without reducing for 4 months."},{"option_index":1,"misconception":"Uses 2 months instead of 4 months."},{"option_index":2,"misconception":"Uses 8 months instead of 4 months."}],"explanation":"Interest = ₹2,400 × 18/100 × 4/12 = ₹144.","concept_id":"eco610-mon-shg","strand":"Money and Credit","kind":"mcq"},{"id":"self-help-groups-as-a-source-of-small-collective-credit-for-the-poor-008","band":"K5","grade":10,"subject":"Mathematics","concept":"self-help groups as a source of small collective credit for the poor","difficulty":2,"stem":"Eight members of an SHG contribute equal amounts to make a loan fund of ₹10,000. How much does each member contribute?","options":["₹1,250","₹125","₹80,000","₹1,200"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Makes a place-value error when dividing by 8."},{"option_index":2,"misconception":"Multiplies 8 by ₹10,000 instead of dividing."},{"option_index":3,"misconception":"Rounds the quotient to ₹1,200 instead of dividing exactly."}],"explanation":"₹10,000 ÷ 8 = ₹1,250.","concept_id":"eco610-mon-shg","strand":"Money and Credit","kind":"mcq"},{"id":"self-help-groups-as-a-source-of-small-collective-credit-for-the-poor-009","band":"K5","grade":10,"subject":"Mathematics","concept":"self-help groups as a source of small collective credit for the poor","difficulty":2,"stem":"A self-help group's savings grew from ₹12,000 to ₹15,000 in one year. What is the percentage increase?","options":["20%","25%","125%","80%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Divides the increase by the new amount instead of the original amount."},{"option_index":2,"misconception":"Finds the new amount as a percentage of the old amount instead of the increase."},{"option_index":3,"misconception":"Finds the old amount as a percentage of the new amount."}],"explanation":"Increase = ₹3,000; percentage increase = (3000/12000) × 100 = 25%.","concept_id":"eco610-mon-shg","strand":"Money and Credit","kind":"mcq"},{"id":"self-help-groups-as-a-source-of-small-collective-credit-for-the-poor-010","band":"K5","grade":10,"subject":"Mathematics","concept":"self-help groups as a source of small collective credit for the poor","difficulty":2,"stem":"An SHG has ₹45,000. After giving 5 equal loans to members, it has ₹5,000 left. How much is each loan?","options":["₹9,000","₹40,000","₹10,000","₹8,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Divides the original ₹45,000 by 5 and ignores the remaining ₹5,000."},{"option_index":1,"misconception":"Subtracts ₹5,000 but does not divide by 5."},{"option_index":2,"misconception":"Adds the remaining ₹5,000 before dividing by 5."}],"explanation":"Total loaned = ₹45,000 − ₹5,000 = ₹40,000; each loan = ₹40,000 ÷ 5 = ₹8,000.","concept_id":"eco610-mon-shg","strand":"Money and Credit","kind":"mcq"},{"id":"terms-of-credit-interest-rate-collateral-and-documentation-required-001","band":"K5","grade":10,"subject":"Mathematics","concept":"terms of credit: interest rate, collateral and documentation required","difficulty":2,"stem":"Ravi borrows ₹20,000 at 12% per annum simple interest for 2 years. How much interest does he pay?","options":["₹2,400","₹4,800","₹5,088","₹24,800"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Calculated interest for only 1 year, ignoring the 2-year period."},{"option_index":2,"misconception":"Used compound interest instead of simple interest for 2 years."},{"option_index":3,"misconception":"Added the principal to the interest and gave total repayment instead of interest."}],"explanation":"SI = 20000 × 12 × 2 / 100 = ₹4,800.","concept_id":"eco610-mon-terms-of-credit","strand":"Money and Credit","kind":"mcq"},{"id":"terms-of-credit-interest-rate-collateral-and-documentation-required-002","band":"K5","grade":10,"subject":"Mathematics","concept":"terms of credit: interest rate, collateral and documentation required","difficulty":3,"stem":"Find the annual simple interest rate if ₹15,000 earns ₹2,700 interest in 3 years.","options":["6% per annum","18% per annum","54% per annum","0.06% per annum"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Forgot to divide by the 3-year time period, using only one year."},{"option_index":2,"misconception":"Multiplied by the time period instead of dividing."},{"option_index":3,"misconception":"Did not convert the decimal rate 0.06 into percent by multiplying by 100."}],"explanation":"Rate = 2700 × 100 / (15000 × 3) = 6% per annum.","concept_id":"eco610-mon-terms-of-credit","strand":"Money and Credit","kind":"mcq"},{"id":"terms-of-credit-interest-rate-collateral-and-documentation-required-003","band":"K5","grade":10,"subject":"Mathematics","concept":"terms of credit: interest rate, collateral and documentation required","difficulty":2,"stem":"A bank requires collateral worth at least 120% of the loan. If the loan is ₹50,000, what is the minimum collateral value?","options":["₹50,000","₹10,000","₹60,000","₹56,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Thinks collateral only needs to equal the loan amount, ignoring the 120% requirement."},{"option_index":1,"misconception":"Gave only the extra 20% required above the loan, not the total collateral."},{"option_index":3,"misconception":"Treated 120% as adding 12% to the loan instead of taking 120% of the loan."}],"explanation":"Minimum collateral = 120% of 50,000 = ₹60,000.","concept_id":"eco610-mon-terms-of-credit","strand":"Money and Credit","kind":"mcq"},{"id":"terms-of-credit-interest-rate-collateral-and-documentation-required-004","band":"K5","grade":10,"subject":"Mathematics","concept":"terms of credit: interest rate, collateral and documentation required","difficulty":2,"stem":"A loan of ₹80,000 has a documentation charge of 0.5% of the loan amount. What is the documentation fee?","options":["₹40","₹400","₹4,000","₹800"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Moved the decimal one place too far, treating 0.5% as 0.05%."},{"option_index":2,"misconception":"Moved the decimal one place the other way, treating 0.5% as 5%."},{"option_index":3,"misconception":"Confused 0.5% with 1%."}],"explanation":"0.5% of 80,000 = 80,000 × 0.5/100 = ₹400.","concept_id":"eco610-mon-terms-of-credit","strand":"Money and Credit","kind":"mcq"},{"id":"terms-of-credit-interest-rate-collateral-and-documentation-required-005","band":"K5","grade":10,"subject":"Mathematics","concept":"terms of credit: interest rate, collateral and documentation required","difficulty":3,"stem":"Loan A charges simple interest at 8% per annum for 2 years on ₹10,000. Loan B charges simple interest at 9% per annum for 1 year on ₹10,000. What is the difference between the interests of Loan A and Loan B?","options":["₹700","₹900","₹1,600","₹2,500"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Gave Loan B's interest only, not the difference."},{"option_index":2,"misconception":"Gave Loan A's interest only, not the difference."},{"option_index":3,"misconception":"Added the two interests instead of subtracting them."}],"explanation":"Loan A SI = ₹1,600; Loan B SI = ₹900; difference = ₹700.","concept_id":"eco610-mon-terms-of-credit","strand":"Money and Credit","kind":"mcq"},{"id":"terms-of-credit-interest-rate-collateral-and-documentation-required-006","band":"K5","grade":10,"subject":"Mathematics","concept":"terms of credit: interest rate, collateral and documentation required","difficulty":3,"stem":"At 10% per annum simple interest, in how many years will the interest be equal to the principal?","options":["5 years","20 years","10 years","1 year"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Halved 10 years, thinking interest becomes half the principal."},{"option_index":1,"misconception":"Doubled the time by using half the rate, 5% instead of 10%."},{"option_index":3,"misconception":"Confused the 10% rate with 1 year."}],"explanation":"For SI = P, T = 100/R = 100/10 = 10 years.","concept_id":"eco610-mon-terms-of-credit","strand":"Money and Credit","kind":"mcq"},{"id":"terms-of-credit-interest-rate-collateral-and-documentation-required-007","band":"K5","grade":10,"subject":"Mathematics","concept":"terms of credit: interest rate, collateral and documentation required","difficulty":2,"stem":"A bank gives a loan up to 75% of the collateral value. If the collateral is worth ₹2,40,000, what is the maximum loan amount?","options":["₹1,80,000","₹60,000","₹2,40,000","₹3,20,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Gave the 25% margin not covered by the loan, not the loan amount."},{"option_index":2,"misconception":"Ignored the 75% limit and used the full collateral value."},{"option_index":3,"misconception":"Divided by 75% instead of multiplying by 75%."}],"explanation":"Maximum loan = 75% of 2,40,000 = ₹1,80,000.","concept_id":"eco610-mon-terms-of-credit","strand":"Money and Credit","kind":"mcq"},{"id":"terms-of-credit-interest-rate-collateral-and-documentation-required-008","band":"K5","grade":10,"subject":"Mathematics","concept":"terms of credit: interest rate, collateral and documentation required","difficulty":2,"stem":"Stamp duty on a loan is 0.2% of the loan amount. If the loan is ₹1,50,000, what is the stamp duty?","options":["₹30","₹1,500","₹3,000","₹300"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Treated 0.2% as 0.02% by moving the decimal one place too far."},{"option_index":1,"misconception":"Confused 0.2% with 1%."},{"option_index":2,"misconception":"Treated 0.2% as 2% by moving the decimal one place the other way."}],"explanation":"0.2% of 1,50,000 = 150000 × 0.2/100 = ₹300.","concept_id":"eco610-mon-terms-of-credit","strand":"Money and Credit","kind":"mcq"},{"id":"terms-of-credit-interest-rate-collateral-and-documentation-required-009","band":"K5","grade":10,"subject":"Mathematics","concept":"terms of credit: interest rate, collateral and documentation required","difficulty":3,"stem":"A borrower repays ₹22,400 after 2 years on a loan of ₹20,000. Assuming simple interest, what is the annual rate of interest?","options":["3% per annum","12% per annum","6% per annum","24% per annum"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Divided the correct annual rate by 2 again after already accounting for time."},{"option_index":1,"misconception":"Used the total 2-year interest as if it were one year's interest."},{"option_index":3,"misconception":"Multiplied the annual rate by the time period instead of dividing by it."}],"explanation":"Interest = ₹2,400; rate = 2400 × 100 / (20000 × 2) = 6% per annum.","concept_id":"eco610-mon-terms-of-credit","strand":"Money and Credit","kind":"mcq"},{"id":"terms-of-credit-interest-rate-collateral-and-documentation-required-010","band":"K5","grade":10,"subject":"Mathematics","concept":"terms of credit: interest rate, collateral and documentation required","difficulty":2,"stem":"A loan of ₹30,000 is taken at 10% per annum simple interest for 1 year, with a documentation fee of ₹500. What is the total amount to be repaid?","options":["₹30,500","₹33,000","₹36,000","₹33,500"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Forgot the interest and added only the documentation fee to the principal."},{"option_index":1,"misconception":"Forgot the documentation fee and added only the interest to the principal."},{"option_index":2,"misconception":"Used 20% interest instead of 10% by doubling the interest amount."}],"explanation":"Interest = ₹3,000; total = 30000 + 3000 + 500 = ₹33,500.","concept_id":"eco610-mon-terms-of-credit","strand":"Money and Credit","kind":"mcq"},{"id":"government-anti-poverty-strategy-combining-growth-with-targeted-programmes-001","band":"K5","grade":9,"subject":"Mathematics","concept":"government anti-poverty strategy combining growth with targeted programmes","difficulty":2,"stem":"A poor family earns Rs. 8000. Under a combined anti-poverty strategy, GDP growth raises income by 5%, and a targeted programme adds Rs. 600. What is the family's new income?","options":["8600","8400","9000","9030"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Adds the targeted transfer but forgets to apply the 5% growth."},{"option_index":1,"misconception":"Applies the 5% growth but forgets the targeted transfer."},{"option_index":3,"misconception":"Applies 5% growth after adding the transfer: (8000+600)*1.05."}],"explanation":"New income = 8000 + 5% of 8000 + 600 = 8000 + 400 + 600 = 9000.","concept_id":"eco610-pov-anti-poverty-programmes","strand":"Poverty","kind":"mcq"},{"id":"government-anti-poverty-strategy-combining-growth-with-targeted-programmes-002","band":"K5","grade":9,"subject":"Mathematics","concept":"government anti-poverty strategy combining growth with targeted programmes","difficulty":2,"stem":"In a district of 10000 people, 5000 are poor. A combined strategy has GDP growth lifting 10% of the poor out of poverty, and targeted programmes lifting 300 more. How many poor people remain?","options":["4500","4200","4700","4000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Subtracts only the growth effect and forgets the targeted programme."},{"option_index":2,"misconception":"Subtracts only the targeted programme and forgets the growth effect."},{"option_index":3,"misconception":"Applies 10% to the total population instead of to the poor."}],"explanation":"Poor lifted by growth = 10% of 5000 = 500. Remaining = 5000 - 500 - 300 = 4200.","concept_id":"eco610-pov-anti-poverty-programmes","strand":"Poverty","kind":"mcq"},{"id":"government-anti-poverty-strategy-combining-growth-with-targeted-programmes-003","band":"K5","grade":9,"subject":"Mathematics","concept":"government anti-poverty strategy combining growth with targeted programmes","difficulty":2,"stem":"A state's anti-poverty budget is Rs. 7000 crore: Rs. 5000 crore for growth-oriented programmes and Rs. 2000 crore for targeted programmes. What fraction of the total budget is for targeted programmes?","options":["2/7","2/5","5/7","1/3"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Compares targeted spending only with growth spending instead of the total budget."},{"option_index":2,"misconception":"Gives the fraction for growth-oriented programmes, not targeted programmes."},{"option_index":3,"misconception":"Approximates the targeted share 2000/7000 as 1/3 instead of simplifying exactly."}],"explanation":"Targeted fraction = 2000/7000 = 2/7.","concept_id":"eco610-pov-anti-poverty-programmes","strand":"Poverty","kind":"mcq"},{"id":"government-anti-poverty-strategy-combining-growth-with-targeted-programmes-004","band":"K5","grade":9,"subject":"Mathematics","concept":"government anti-poverty strategy combining growth with targeted programmes","difficulty":2,"stem":"A targeted anti-poverty programme transfers Rs. 1200 to each of 250 poor families. What is the total amount transferred?","options":["30000","3000","3000000","300000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Multiplies incorrectly with one zero missing (1200*25)."},{"option_index":1,"misconception":"Multiplies incorrectly with two zeros missing (1200*2.5 or place-value error)."},{"option_index":2,"misconception":"Adds an extra zero in the product."}],"explanation":"Total = 1200*250 = 300000.","concept_id":"eco610-pov-anti-poverty-programmes","strand":"Poverty","kind":"mcq"},{"id":"government-anti-poverty-strategy-combining-growth-with-targeted-programmes-005","band":"K5","grade":9,"subject":"Mathematics","concept":"government anti-poverty strategy combining growth with targeted programmes","difficulty":2,"stem":"A poor family earns Rs. 12000. GDP growth raises income by 10%, and a targeted programme adds Rs. 800. What is the total increase in income?","options":["1200","2000","800","2080"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Counts only the growth increase and forgets the targeted transfer."},{"option_index":2,"misconception":"Counts only the targeted transfer and forgets the growth increase."},{"option_index":3,"misconception":"Applies 10% growth after adding the transfer, then adds the transfer again."}],"explanation":"Increase = 10% of 12000 + 800 = 1200 + 800 = 2000.","concept_id":"eco610-pov-anti-poverty-programmes","strand":"Poverty","kind":"mcq"},{"id":"government-anti-poverty-strategy-combining-growth-with-targeted-programmes-006","band":"K5","grade":9,"subject":"Mathematics","concept":"government anti-poverty strategy combining growth with targeted programmes","difficulty":2,"stem":"Initially 30% of 15000 people are below the poverty line. A combined strategy reduces poverty by 4 percentage points. How many people come out of poverty?","options":["180","450","600","750"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Takes 4% of the poor instead of 4 percentage points of the total population."},{"option_index":1,"misconception":"Uses 3 percentage points (3% of 15000) instead of 4 percentage points."},{"option_index":3,"misconception":"Uses 5 percentage points (5% of 15000) instead of 4 percentage points."}],"explanation":"Reduction = 4% of 15000 = 600 people.","concept_id":"eco610-pov-anti-poverty-programmes","strand":"Poverty","kind":"mcq"},{"id":"government-anti-poverty-strategy-combining-growth-with-targeted-programmes-007","band":"K5","grade":9,"subject":"Mathematics","concept":"government anti-poverty strategy combining growth with targeted programmes","difficulty":2,"stem":"In a district, 60% of 2500 poor families are covered by targeted programmes. GDP growth benefits another 200 poor families. How many poor families benefit from at least one programme, assuming no overlap?","options":["1500","200","1300","1700"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Counts only the targeted-programme coverage and forgets the growth benefit."},{"option_index":1,"misconception":"Counts only the growth benefit and forgets the targeted-programme coverage."},{"option_index":2,"misconception":"Subtracts the growth benefit from the targeted coverage instead of adding it."}],"explanation":"Covered = 60% of 2500 + 200 = 1500 + 200 = 1700.","concept_id":"eco610-pov-anti-poverty-programmes","strand":"Poverty","kind":"mcq"},{"id":"government-anti-poverty-strategy-combining-growth-with-targeted-programmes-008","band":"K5","grade":9,"subject":"Mathematics","concept":"government anti-poverty strategy combining growth with targeted programmes","difficulty":2,"stem":"A state's GDP grows from Rs. 80000 crore to Rs. 88000 crore. It spends Rs. 4000 crore on targeted programmes. What is the ratio of GDP growth to targeted spending?","options":["1:2","2:1","20:1","22:1"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Reverses the ratio, putting targeted spending before GDP growth."},{"option_index":2,"misconception":"Uses the original GDP instead of the GDP growth."},{"option_index":3,"misconception":"Uses the final GDP instead of the GDP growth."}],"explanation":"GDP growth = 88000 - 80000 = 8000. Ratio = 8000:4000 = 2:1.","concept_id":"eco610-pov-anti-poverty-programmes","strand":"Poverty","kind":"mcq"},{"id":"government-anti-poverty-strategy-combining-growth-with-targeted-programmes-009","band":"K5","grade":9,"subject":"Mathematics","concept":"government anti-poverty strategy combining growth with targeted programmes","difficulty":2,"stem":"A combined strategy reduces poverty by 6% for 20000 people through growth, and by 12% for 5000 people through targeted programmes. What is the overall poverty-reduction percentage?","options":["7.2%","9%","6%","10.8%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Takes a simple average of 6% and 12%, ignoring the different group sizes."},{"option_index":2,"misconception":"Uses only the growth component and ignores targeted programmes."},{"option_index":3,"misconception":"Uses reversed weights: 20000 with 12% and 5000 with 6%."}],"explanation":"Overall reduction = (20000*6 + 5000*12)/(20000+5000) = 180000/25000 = 7.2%.","concept_id":"eco610-pov-anti-poverty-programmes","strand":"Poverty","kind":"mcq"},{"id":"government-anti-poverty-strategy-combining-growth-with-targeted-programmes-010","band":"K5","grade":9,"subject":"Mathematics","concept":"government anti-poverty strategy combining growth with targeted programmes","difficulty":2,"stem":"A government allocates Rs. 12000 crore for an anti-poverty strategy. It spends 75% on growth-oriented programmes and the rest on targeted programmes. How much is spent on targeted programmes?","options":["9000","3000","1500","4000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Finds the growth-oriented share instead of the targeted share."},{"option_index":2,"misconception":"Takes half of the targeted share by using 12.5% instead of 25%."},{"option_index":3,"misconception":"Approximates the remaining 25% as 1/3 of the total."}],"explanation":"Targeted share = 25% of 12000 = 3000 crore.","concept_id":"eco610-pov-anti-poverty-programmes","strand":"Poverty","kind":"mcq"},{"id":"poverty-as-a-major-challenge-facing-the-indian-economy-001","band":"K5","grade":9,"subject":"Mathematics","concept":"poverty as a major challenge facing the Indian economy","difficulty":2,"stem":"In a state, 24% of 50 lakh people live below the poverty line. How many lakh people live below the poverty line?","options":["2.4 lakh","12 lakh","24 lakh","1.2 lakh"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Moves the decimal one place too far, computing 24% of 10 lakh instead of 50 lakh."},{"option_index":2,"misconception":"Treats the percentage number 24 as the answer in lakh, ignoring the total population."},{"option_index":3,"misconception":"Divides by 100 twice, effectively finding 24% of 5 lakh."}],"explanation":"24% of 50 lakh = (24/100) × 50 = 12 lakh.","concept_id":"eco610-pov-as-challenge","strand":"Poverty","kind":"mcq"},{"id":"poverty-as-a-major-challenge-facing-the-indian-economy-002","band":"K5","grade":9,"subject":"Mathematics","concept":"poverty as a major challenge facing the Indian economy","difficulty":2,"stem":"A family's monthly income is ₹8,000. If 65% is spent on food and other necessities, how much money is left?","options":["₹5,200","₹280","₹5,600","₹2,800"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Finds the amount spent (65%) instead of the amount left (35%)."},{"option_index":1,"misconception":"Makes a decimal-place error, finding 3.5% of ₹8,000 instead of 35%."},{"option_index":2,"misconception":"Uses 70% instead of 35%, doubling the remaining amount."}],"explanation":"Money left = 35% of ₹8,000 = (35/100) × 8000 = ₹2,800.","concept_id":"eco610-pov-as-challenge","strand":"Poverty","kind":"mcq"},{"id":"poverty-as-a-major-challenge-facing-the-indian-economy-003","band":"K5","grade":9,"subject":"Mathematics","concept":"poverty as a major challenge facing the Indian economy","difficulty":3,"stem":"In a state, 30% of the rural population and 10% of the urban population are poor. The rural population is 60 lakh and the urban population is 40 lakh. What is the overall poverty percentage?","options":["20%","22%","30%","40%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Takes the simple average of 30% and 10% without weighting by population."},{"option_index":2,"misconception":"Uses only the rural poverty rate, ignoring the urban population."},{"option_index":3,"misconception":"Adds the two poverty rates instead of finding a weighted overall rate."}],"explanation":"Poor = 30% of 60 lakh + 10% of 40 lakh = 18 + 4 = 22 lakh out of 100 lakh, so 22%.","concept_id":"eco610-pov-as-challenge","strand":"Poverty","kind":"mcq"},{"id":"poverty-as-a-major-challenge-facing-the-indian-economy-004","band":"K5","grade":9,"subject":"Mathematics","concept":"poverty as a major challenge facing the Indian economy","difficulty":2,"stem":"A government scheme reduced the number of poor people in a district from 8 crore to 6 crore. What is the percentage decrease?","options":["25%","20%","33 1/3%","75%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses a total of 10 crore as the base instead of the original 8 crore."},{"option_index":2,"misconception":"Uses the new value 6 crore as the base for the percentage decrease."},{"option_index":3,"misconception":"Finds the remaining poor as a percentage of the original number, not the decrease."}],"explanation":"Decrease = 2 crore; (2/8) × 100 = 25%.","concept_id":"eco610-pov-as-challenge","strand":"Poverty","kind":"mcq"},{"id":"poverty-as-a-major-challenge-facing-the-indian-economy-005","band":"K5","grade":9,"subject":"Mathematics","concept":"poverty as a major challenge facing the Indian economy","difficulty":3,"stem":"The poverty line in a region is ₹1,200 per person per month. A family of 5 has a monthly income of ₹5,400. By how much is the family's income below the poverty line for the family?","options":["₹600","₹0","₹1,200","₹4,200"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Compares family income ₹5,400 only with the per-person line ₹1,200 and thinks the family is not below the line."},{"option_index":2,"misconception":"Reports the per-person poverty line as the shortfall without multiplying by family size."},{"option_index":3,"misconception":"Subtracts the per-person line from the family income instead of using the family's poverty line."}],"explanation":"Family poverty line = 5 × ₹1,200 = ₹6,000; shortfall = ₹6,000 − ₹5,400 = ₹600.","concept_id":"eco610-pov-as-challenge","strand":"Poverty","kind":"mcq"},{"id":"poverty-as-a-major-challenge-facing-the-indian-economy-006","band":"K5","grade":9,"subject":"Mathematics","concept":"poverty as a major challenge facing the Indian economy","difficulty":2,"stem":"A survey shows 45% of the people in a district are poor. If the district has 80,000 people, how many people are NOT poor?","options":["36,000","44,000","55,000","45,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Finds the number of poor people (45%) instead of the number not poor (55%)."},{"option_index":2,"misconception":"Uses 55% of 1,00,000 instead of 55% of 80,000."},{"option_index":3,"misconception":"Uses 45% of 1,00,000 instead of 55% of 80,000."}],"explanation":"Not poor = 55% of 80,000 = (55/100) × 80000 = 44,000.","concept_id":"eco610-pov-as-challenge","strand":"Poverty","kind":"mcq"},{"id":"poverty-as-a-major-challenge-facing-the-indian-economy-007","band":"K5","grade":9,"subject":"Mathematics","concept":"poverty as a major challenge facing the Indian economy","difficulty":2,"stem":"In a village, 3/5 of the families are below the poverty line. If 240 families are below the poverty line, how many families are there in the village in total?","options":["144","720","400","600"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Multiplies 240 by 3/5 instead of dividing by 3/5."},{"option_index":1,"misconception":"Multiplies 240 by 3 only, forgetting to divide by 5."},{"option_index":3,"misconception":"Misreads 3/5 as 2/5 and finds the total when 240 is two-fifths."}],"explanation":"If 3/5 of total = 240, total = 240 × 5/3 = 400.","concept_id":"eco610-pov-as-challenge","strand":"Poverty","kind":"mcq"},{"id":"poverty-as-a-major-challenge-facing-the-indian-economy-008","band":"K5","grade":9,"subject":"Mathematics","concept":"poverty as a major challenge facing the Indian economy","difficulty":3,"stem":"A poverty alleviation program covered 15,000 people in Year 1 and 18,000 people in Year 2. What is the percentage increase in coverage?","options":["16 2/3%","25%","3%","20%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Uses the new Year 2 value 18,000 as the base instead of the original 15,000."},{"option_index":1,"misconception":"Uses 12,000 as the base instead of the original 15,000."},{"option_index":2,"misconception":"Mistakes the increase of 3,000 for 3%."}],"explanation":"Increase = 3,000; (3000/15000) × 100 = 20%.","concept_id":"eco610-pov-as-challenge","strand":"Poverty","kind":"mcq"},{"id":"poverty-as-a-major-challenge-facing-the-indian-economy-009","band":"K5","grade":9,"subject":"Mathematics","concept":"poverty as a major challenge facing the Indian economy","difficulty":3,"stem":"The number of poor in a country decreased from 30 crore to 24 crore. What fraction of the original poor were lifted out of poverty?","options":["1/4","1/5","1/6","4/5"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses the new number 24 crore as the base instead of the original 30 crore."},{"option_index":2,"misconception":"Compares the decrease of 6 crore to 36 crore instead of the original 30 crore."},{"option_index":3,"misconception":"Finds the fraction still poor (24/30) instead of the fraction lifted out of poverty."}],"explanation":"Decrease = 6 crore; 6/30 = 1/5 of the original poor were lifted out.","concept_id":"eco610-pov-as-challenge","strand":"Poverty","kind":"mcq"},{"id":"poverty-as-a-major-challenge-facing-the-indian-economy-010","band":"K5","grade":9,"subject":"Mathematics","concept":"poverty as a major challenge facing the Indian economy","difficulty":3,"stem":"In a state, 25% of the rural population and 15% of the urban population are poor. The rural population is 3 times the urban population. What is the overall poverty percentage?","options":["20%","25%","22.5%","18.75%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Takes the simple average of 25% and 15% without weighting by population."},{"option_index":1,"misconception":"Uses only the rural poverty rate, ignoring the urban population."},{"option_index":3,"misconception":"Applies the rural rate only to the rural share (25% of 3/4) and ignores the urban poor."}],"explanation":"Let urban = x, rural = 3x. Poor = 0.25(3x) + 0.15x = 0.90x; total = 4x; overall = 0.90/4 = 22.5%.","concept_id":"eco610-pov-as-challenge","strand":"Poverty","kind":"mcq"},{"id":"causes-of-poverty-low-growth-unemployment-and-social-factors-001","band":"K5","grade":9,"subject":"Mathematics","concept":"causes of poverty: low growth, unemployment and social factors","difficulty":2,"stem":"Low economic growth can increase poverty. A country's GDP rises from ₹4000 crore to ₹5000 crore. What is the growth rate?","options":["20%","25%","125%","0.25%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses the new GDP as the base: 1000/5000 = 20%."},{"option_index":2,"misconception":"Reports final GDP as a percent of initial GDP: 5000/4000 = 125%."},{"option_index":3,"misconception":"Forgets to multiply the decimal by 100."}],"explanation":"Increase = ₹1000 crore. Growth rate = (1000/4000)×100 = 25%.","concept_id":"eco610-pov-causes","strand":"Poverty","kind":"mcq"},{"id":"causes-of-poverty-low-growth-unemployment-and-social-factors-002","band":"K5","grade":9,"subject":"Mathematics","concept":"causes of poverty: low growth, unemployment and social factors","difficulty":2,"stem":"Unemployment is a major cause of poverty. In a town, 500 people are in the labour force and 100 are unemployed. What is the unemployment rate?","options":["25%","80%","100%","20%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Uses the employed number as the base: 100/400 = 25%."},{"option_index":1,"misconception":"Calculates the employed share: 400/500 = 80%."},{"option_index":2,"misconception":"Treats the number 100 unemployed as 100%."}],"explanation":"Unemployment rate = (100/500)×100 = 20%.","concept_id":"eco610-pov-causes","strand":"Poverty","kind":"mcq"},{"id":"causes-of-poverty-low-growth-unemployment-and-social-factors-003","band":"K5","grade":9,"subject":"Mathematics","concept":"causes of poverty: low growth, unemployment and social factors","difficulty":2,"stem":"Low growth keeps per capita income low. A country's total income is ₹72000 crore and its population is 80 crore. What is the per capita income?","options":["₹900","₹90","₹9000","₹800"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Divides by 800 instead of 80, adding an extra zero to the denominator."},{"option_index":2,"misconception":"Moves the decimal one place too far when dividing."},{"option_index":3,"misconception":"Uses the population figure as the per capita income."}],"explanation":"Per capita income = total income ÷ population = 72000 ÷ 80 = ₹900 crore.","concept_id":"eco610-pov-causes","strand":"Poverty","kind":"mcq"},{"id":"causes-of-poverty-low-growth-unemployment-and-social-factors-004","band":"K5","grade":9,"subject":"Mathematics","concept":"causes of poverty: low growth, unemployment and social factors","difficulty":2,"stem":"Illiteracy is a social factor that can cause poverty. In a village, 540 out of 600 people are literate. What is the literacy rate?","options":["10%","54%","90%","111%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Calculates the illiteracy rate: 60/600 = 10%."},{"option_index":1,"misconception":"Moves the decimal point incorrectly: 540/1000 = 54%."},{"option_index":3,"misconception":"Divides total by literate: 600/540 ≈ 111%."}],"explanation":"Literacy rate = (540/600)×100 = 90%.","concept_id":"eco610-pov-causes","strand":"Poverty","kind":"mcq"},{"id":"causes-of-poverty-low-growth-unemployment-and-social-factors-005","band":"K5","grade":9,"subject":"Mathematics","concept":"causes of poverty: low growth, unemployment and social factors","difficulty":2,"stem":"Poverty is measured using a poverty line. If 100 people out of 400 are below the poverty line, what is the poverty ratio?","options":["25%","20%","75%","0.25%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses 100/500 by adding the below-poverty count to the total denominator."},{"option_index":2,"misconception":"Calculates the above-poverty share: 300/400 = 75%."},{"option_index":3,"misconception":"Forgets to multiply the decimal 0.25 by 100."}],"explanation":"Poverty ratio = (100/400)×100 = 25%.","concept_id":"eco610-pov-causes","strand":"Poverty","kind":"mcq"},{"id":"causes-of-poverty-low-growth-unemployment-and-social-factors-006","band":"K5","grade":9,"subject":"Mathematics","concept":"causes of poverty: low growth, unemployment and social factors","difficulty":2,"stem":"Unemployment causes poverty. In a labour force of 1200, 240 are unemployed. How many are employed?","options":["240","960","1440","1200"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Gives the unemployed number instead of the employed number."},{"option_index":2,"misconception":"Adds unemployed to total labour force instead of subtracting."},{"option_index":3,"misconception":"Gives the total labour force, not the employed number."}],"explanation":"Employed = 1200 − 240 = 960.","concept_id":"eco610-pov-causes","strand":"Poverty","kind":"mcq"},{"id":"causes-of-poverty-low-growth-unemployment-and-social-factors-007","band":"K5","grade":9,"subject":"Mathematics","concept":"causes of poverty: low growth, unemployment and social factors","difficulty":2,"stem":"Low growth means national income rises slowly. If income increases from ₹600 crore to ₹750 crore, what is the increase?","options":["₹600 crore","₹750 crore","₹150 crore","₹1350 crore"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reports the initial income as the increase."},{"option_index":1,"misconception":"Reports the final income as the increase."},{"option_index":3,"misconception":"Adds initial and final incomes instead of subtracting."}],"explanation":"Increase = ₹750 crore − ₹600 crore = ₹150 crore.","concept_id":"eco610-pov-causes","strand":"Poverty","kind":"mcq"},{"id":"causes-of-poverty-low-growth-unemployment-and-social-factors-008","band":"K5","grade":9,"subject":"Mathematics","concept":"causes of poverty: low growth, unemployment and social factors","difficulty":2,"stem":"Social factors affect poverty. A poor family spends 60% of its ₹5000 monthly income on food. How much is spent on food?","options":["₹60","₹2000","₹5600","₹3000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Treats 60% as ₹60."},{"option_index":1,"misconception":"Calculates the remaining 40% of income."},{"option_index":2,"misconception":"Adds 60 to 5000 instead of taking 60%."}],"explanation":"Food spending = 60% of ₹5000 = 0.60 × 5000 = ₹3000.","concept_id":"eco610-pov-causes","strand":"Poverty","kind":"mcq"},{"id":"causes-of-poverty-low-growth-unemployment-and-social-factors-009","band":"K5","grade":9,"subject":"Mathematics","concept":"causes of poverty: low growth, unemployment and social factors","difficulty":2,"stem":"If GDP grows at 6% and population grows at 2%, what is the approximate per capita income growth rate?","options":["4%","3%","8%","12%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Divides GDP growth by population growth: 6 ÷ 2 = 3%."},{"option_index":2,"misconception":"Adds GDP and population growth rates."},{"option_index":3,"misconception":"Multiplies GDP and population growth rates."}],"explanation":"Per capita growth ≈ GDP growth − population growth = 6% − 2% = 4%.","concept_id":"eco610-pov-causes","strand":"Poverty","kind":"mcq"},{"id":"causes-of-poverty-low-growth-unemployment-and-social-factors-010","band":"K5","grade":9,"subject":"Mathematics","concept":"causes of poverty: low growth, unemployment and social factors","difficulty":2,"stem":"Unemployment rate in a district is 8%. If the labour force is 25000, how many people are unemployed?","options":["200","2500","2000","20000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Moves the decimal point too far when converting 8% to a decimal."},{"option_index":1,"misconception":"Uses 10% instead of 8%."},{"option_index":3,"misconception":"Treats 8% as 80%."}],"explanation":"Unemployed = 8% of 25000 = 0.08 × 25000 = 2000.","concept_id":"eco610-pov-causes","strand":"Poverty","kind":"mcq"},{"id":"comparing-poverty-levels-across-countries-globally-001","band":"K5","grade":9,"subject":"Mathematics","concept":"comparing poverty levels across countries globally","difficulty":2,"stem":"Country A has a population of 80 million and a poverty rate of 25%. Country B has a population of 50 million and a poverty rate of 30%. How many more poor people are in Country A than in Country B, in millions?","options":["15 million","20 million","5 million","35 million"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reports Country B's poor population instead of the difference."},{"option_index":1,"misconception":"Reports Country A's poor population instead of the difference."},{"option_index":3,"misconception":"Adds the two poor populations instead of subtracting."}],"explanation":"Country A has 80×0.25=20 million poor; Country B has 50×0.30=15 million poor; difference is 5 million.","concept_id":"eco610-pov-global-poverty","strand":"Poverty","kind":"mcq"},{"id":"comparing-poverty-levels-across-countries-globally-002","band":"K5","grade":9,"subject":"Mathematics","concept":"comparing poverty levels across countries globally","difficulty":2,"stem":"The international poverty line is $1.90 per person per day. What is the poverty line per person per year? (Use 1 year = 365 days.)","options":["$22.80","$69.35","$1.90","$693.50"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Multiplied by 12 months instead of 365 days."},{"option_index":1,"misconception":"Misplaced the decimal after multiplying by 365 (divided by 10)."},{"option_index":2,"misconception":"Did not convert daily to yearly."}],"explanation":"$1.90 × 365 = $693.50 per year.","concept_id":"eco610-pov-global-poverty","strand":"Poverty","kind":"mcq"},{"id":"comparing-poverty-levels-across-countries-globally-003","band":"K5","grade":9,"subject":"Mathematics","concept":"comparing poverty levels across countries globally","difficulty":2,"stem":"Country X has a population of 200 million and a poverty rate of 18%. How many poor people are in Country X, in millions?","options":["3.6 million","36 million","11.1 million","360 million"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Used 0.018 instead of 0.18 (divided by 100 twice)."},{"option_index":2,"misconception":"Divided population by 18 instead of multiplying by 18%."},{"option_index":3,"misconception":"Multiplied by 18 instead of 0.18."}],"explanation":"18% of 200 million = 0.18 × 200 million = 36 million.","concept_id":"eco610-pov-global-poverty","strand":"Poverty","kind":"mcq"},{"id":"comparing-poverty-levels-across-countries-globally-004","band":"K5","grade":9,"subject":"Mathematics","concept":"comparing poverty levels across countries globally","difficulty":2,"stem":"Country P has 40 million poor people out of a population of 200 million. Country Q has 30 million poor people out of a population of 100 million. By how many percentage points is Country Q's poverty rate higher than Country P's?","options":["10 percentage points","20 percentage points","30 percentage points","5 percentage points"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Reports Country P's poverty rate, not the difference."},{"option_index":2,"misconception":"Reports Country Q's poverty rate, not the difference."},{"option_index":3,"misconception":"Halves the difference between the two rates."}],"explanation":"P rate = 40/200 = 20%; Q rate = 30/100 = 30%; difference = 10 percentage points.","concept_id":"eco610-pov-global-poverty","strand":"Poverty","kind":"mcq"},{"id":"comparing-poverty-levels-across-countries-globally-005","band":"K5","grade":9,"subject":"Mathematics","concept":"comparing poverty levels across countries globally","difficulty":2,"stem":"Country A has a poverty rate of 25% and Country B has a poverty rate of 20%. What is the ratio of Country A's poverty rate to Country B's poverty rate in simplest form?","options":["4:5","4:3","5:4","9:4"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Inverted the ratio (B to A instead of A to B)."},{"option_index":1,"misconception":"Simplified by subtracting 5 from both parts: 20:15 = 4:3."},{"option_index":3,"misconception":"Added the rates (25+20=45) and compared to B's rate, simplifying 45:20 to 9:4."}],"explanation":"25:20 simplifies by dividing both by 5 to 5:4.","concept_id":"eco610-pov-global-poverty","strand":"Poverty","kind":"mcq"},{"id":"comparing-poverty-levels-across-countries-globally-006","band":"K5","grade":9,"subject":"Mathematics","concept":"comparing poverty levels across countries globally","difficulty":2,"stem":"Country X has a poverty rate of 12% and a population of 300 million. Country Y has a poverty rate of 15% and a population of 100 million. How many more poor people are in Country X than in Country Y, in millions?","options":["3 million","51 million","15 million","21 million"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Compared the 3 percentage-point rate difference using only Country Y's population."},{"option_index":1,"misconception":"Added the two poor populations instead of subtracting."},{"option_index":2,"misconception":"Reports Country Y's poor population, not the difference."}],"explanation":"X has 0.12×300=36 million poor; Y has 0.15×100=15 million poor; difference is 21 million.","concept_id":"eco610-pov-global-poverty","strand":"Poverty","kind":"mcq"},{"id":"comparing-poverty-levels-across-countries-globally-007","band":"K5","grade":9,"subject":"Mathematics","concept":"comparing poverty levels across countries globally","difficulty":2,"stem":"The international poverty line changed from $1.90 per person per day to $2.15 per person per day. What is the increase in the poverty line per person per year? (Use 1 year = 365 days.)","options":["$0.25","$91.25","$3.00","$7.50"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Reports the daily increase without converting to yearly."},{"option_index":2,"misconception":"Multiplied the daily increase by 12 months instead of 365 days."},{"option_index":3,"misconception":"Multiplied the daily increase by 30 days instead of 365 days."}],"explanation":"Increase = ($2.15−$1.90)×365 = $0.25×365 = $91.25.","concept_id":"eco610-pov-global-poverty","strand":"Poverty","kind":"mcq"},{"id":"comparing-poverty-levels-across-countries-globally-008","band":"K5","grade":9,"subject":"Mathematics","concept":"comparing poverty levels across countries globally","difficulty":2,"stem":"Country A has a poverty rate of 40% and Country B has a poverty rate of 10%. How many percentage points lower is Country B's poverty rate than Country A's?","options":["30 percentage points","4 times","25 percentage points","10 percentage points"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Compares by ratio (40÷10) instead of percentage-point difference."},{"option_index":2,"misconception":"Averages the two rates ((40+10)/2) instead of finding the difference."},{"option_index":3,"misconception":"Reports Country B's rate, not the difference."}],"explanation":"Difference = 40%−10% = 30 percentage points.","concept_id":"eco610-pov-global-poverty","strand":"Poverty","kind":"mcq"},{"id":"comparing-poverty-levels-across-countries-globally-009","band":"K5","grade":9,"subject":"Mathematics","concept":"comparing poverty levels across countries globally","difficulty":2,"stem":"Country P has 45 million poor people out of a population of 900 million. Country Q has 10 million poor people out of a population of 50 million. By how many percentage points is Country Q's poverty rate higher than Country P's?","options":["5 percentage points","20 percentage points","15 percentage points","35 percentage points"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reports Country P's poverty rate, not the difference."},{"option_index":1,"misconception":"Reports Country Q's poverty rate, not the difference."},{"option_index":3,"misconception":"Subtracts the poor counts (45−10=35) and treats the result as percentage points."}],"explanation":"P rate = 45/900 = 5%; Q rate = 10/50 = 20%; difference = 15 percentage points.","concept_id":"eco610-pov-global-poverty","strand":"Poverty","kind":"mcq"},{"id":"comparing-poverty-levels-across-countries-globally-010","band":"K5","grade":9,"subject":"Mathematics","concept":"comparing poverty levels across countries globally","difficulty":2,"stem":"Country A has a poverty rate of 22% and a population of 50 million. Country B has a poverty rate of 18% and a population of 100 million. How many poor people are there in total in the two countries, in millions?","options":["7 million","29 million","40 million","20 million"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Subtracts the poor populations (18−11=7) instead of adding."},{"option_index":2,"misconception":"Adds the two percentage rates (22+18=40) and writes the result as millions."},{"option_index":3,"misconception":"Averages the two poverty rates to 20% and applies it to Country B's population only."}],"explanation":"A has 0.22×50=11 million poor; B has 0.18×100=18 million poor; total = 29 million.","concept_id":"eco610-pov-global-poverty","strand":"Poverty","kind":"mcq"},{"id":"inter-state-disparities-in-poverty-levels-within-india-001","band":"K5","grade":9,"subject":"Mathematics","concept":"inter-state disparities in poverty levels within India","difficulty":2,"stem":"In a study of inter-state poverty in India, State A has 11% of its people below the poverty line and State B has 26%. By how many percentage points is State B's poverty rate higher than State A's?","options":["26 percentage points","37 percentage points","15 percentage points","11 percentage points"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reports State B's poverty rate itself instead of finding the difference."},{"option_index":1,"misconception":"Adds the two poverty rates instead of subtracting them."},{"option_index":3,"misconception":"Reports State A's poverty rate itself instead of finding the difference."}],"explanation":"Difference = 26% - 11% = 15 percentage points.","concept_id":"eco610-pov-interstate-disparities","strand":"Poverty","kind":"mcq"},{"id":"inter-state-disparities-in-poverty-levels-within-india-002","band":"K5","grade":9,"subject":"Mathematics","concept":"inter-state disparities in poverty levels within India","difficulty":2,"stem":"In a data set on inter-state poverty, State X has a poverty rate of 12% and State Y has a poverty rate of 36%. The poverty rate of State Y is how many times the poverty rate of State X?","options":["3","24","48","1/3"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Subtracts the rates (36 - 12 = 24) instead of dividing."},{"option_index":2,"misconception":"Adds the rates (36 + 12 = 48) instead of dividing."},{"option_index":3,"misconception":"Divides the smaller rate by the larger rate (12/36) instead of the larger by the smaller."}],"explanation":"36% ÷ 12% = 3.","concept_id":"eco610-pov-interstate-disparities","strand":"Poverty","kind":"mcq"},{"id":"inter-state-disparities-in-poverty-levels-within-india-003","band":"K5","grade":9,"subject":"Mathematics","concept":"inter-state disparities in poverty levels within India","difficulty":2,"stem":"The poverty rates of three states in a study are 10%, 20%, and 30%. What is their average poverty rate?","options":["60%","30%","10%","20%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Adds the three rates and does not divide by 3."},{"option_index":1,"misconception":"Chooses the highest poverty rate as the average."},{"option_index":2,"misconception":"Chooses the lowest poverty rate as the average."}],"explanation":"Average = (10% + 20% + 30%) ÷ 3 = 20%.","concept_id":"eco610-pov-interstate-disparities","strand":"Poverty","kind":"mcq"},{"id":"inter-state-disparities-in-poverty-levels-within-india-004","band":"K5","grade":9,"subject":"Mathematics","concept":"inter-state disparities in poverty levels within India","difficulty":2,"stem":"A state has a population of 20 million and a poverty rate of 15%. How many million people in the state are below the poverty line?","options":["5 million","3 million","15 million","0.75 million"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Subtracts the poverty rate from the population (20 - 15 = 5) instead of taking 15% of 20."},{"option_index":2,"misconception":"Treats the poverty rate 15% as 15 million people."},{"option_index":3,"misconception":"Divides the poverty rate by the population (15 ÷ 20 = 0.75) instead of multiplying."}],"explanation":"15% of 20 million = 0.15 × 20 = 3 million.","concept_id":"eco610-pov-interstate-disparities","strand":"Poverty","kind":"mcq"},{"id":"inter-state-disparities-in-poverty-levels-within-india-005","band":"K5","grade":9,"subject":"Mathematics","concept":"inter-state disparities in poverty levels within India","difficulty":2,"stem":"State A has population 10 million and poverty rate 20%. State B has population 30 million and poverty rate 10%. What is the combined poverty rate for the two states together?","options":["15%","10%","12.5%","30%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Takes the simple average of 20% and 10% and ignores the different populations."},{"option_index":1,"misconception":"Uses only State B's poverty rate because it has the larger population."},{"option_index":3,"misconception":"Adds the two poverty rates (20% + 10% = 30%)."}],"explanation":"Poor people = 20% of 10m + 10% of 30m = 2m + 3m = 5m; total population = 40m; 5/40 = 12.5%.","concept_id":"eco610-pov-interstate-disparities","strand":"Poverty","kind":"mcq"},{"id":"inter-state-disparities-in-poverty-levels-within-india-006","band":"K5","grade":9,"subject":"Mathematics","concept":"inter-state disparities in poverty levels within India","difficulty":2,"stem":"A state's poverty rate fell from 40% in 2000 to 24% in 2020. By how many percentage points did the poverty rate decrease?","options":["16 percentage points","64 percentage points","40 percentage points","24 percentage points"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds the two rates (40 + 24 = 64) instead of subtracting."},{"option_index":2,"misconception":"Reports the initial poverty rate instead of the decrease."},{"option_index":3,"misconception":"Reports the final poverty rate instead of the decrease."}],"explanation":"Decrease = 40% - 24% = 16 percentage points.","concept_id":"eco610-pov-interstate-disparities","strand":"Poverty","kind":"mcq"},{"id":"inter-state-disparities-in-poverty-levels-within-india-007","band":"K5","grade":9,"subject":"Mathematics","concept":"inter-state disparities in poverty levels within India","difficulty":2,"stem":"A state's poverty rate fell from 40% to 24%. What is the percentage decrease in the poverty rate?","options":["16%","24%","60%","40%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Reports the percentage-point decrease (16) as a percent of the original rate."},{"option_index":1,"misconception":"Reports the final poverty rate as the percentage decrease."},{"option_index":2,"misconception":"Computes the final rate as a percentage of the original rate (24/40 = 60%) instead of the decrease."}],"explanation":"Decrease = 16; percentage decrease = (16/40) × 100 = 40%.","concept_id":"eco610-pov-interstate-disparities","strand":"Poverty","kind":"mcq"},{"id":"inter-state-disparities-in-poverty-levels-within-india-008","band":"K5","grade":9,"subject":"Mathematics","concept":"inter-state disparities in poverty levels within India","difficulty":2,"stem":"State P has poverty rate 25% and population 8 million. State Q has poverty rate 20% and population 10 million. The number of poor people in State P is how many times the number of poor people in State Q?","options":["1.25","1","0.8","2"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Divides the poverty rates 25% ÷ 20% and ignores population."},{"option_index":2,"misconception":"Divides 20% ÷ 25% (the inverse rate ratio) and ignores population."},{"option_index":3,"misconception":"Reports the number of poor people in each state (2 million) instead of the multiplier."}],"explanation":"Poor P = 25% of 8m = 2m; poor Q = 20% of 10m = 2m; 2m ÷ 2m = 1.","concept_id":"eco610-pov-interstate-disparities","strand":"Poverty","kind":"mcq"},{"id":"inter-state-disparities-in-poverty-levels-within-india-009","band":"K5","grade":9,"subject":"Mathematics","concept":"inter-state disparities in poverty levels within India","difficulty":2,"stem":"State A has poverty rate 18% and population 5 million. State B has poverty rate 12% and population 10 million. State B has how many million more poor people than State A?","options":["0.6 million","0.9 million","0.3 million","1.2 million"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses the difference in poverty rates (6%) on State A's population instead of finding the actual difference in poor people."},{"option_index":1,"misconception":"Reports the number of poor people in State A only."},{"option_index":3,"misconception":"Reports the number of poor people in State B only."}],"explanation":"Poor A = 18% of 5m = 0.9m; poor B = 12% of 10m = 1.2m; difference = 1.2m - 0.9m = 0.3m.","concept_id":"eco610-pov-interstate-disparities","strand":"Poverty","kind":"mcq"},{"id":"inter-state-disparities-in-poverty-levels-within-india-010","band":"K5","grade":9,"subject":"Mathematics","concept":"inter-state disparities in poverty levels within India","difficulty":2,"stem":"The poverty rates of four states are 8%, 21%, 13%, and 29%. What is the range of these poverty rates?","options":["21 percentage points","29 percentage points","8 percentage points","37 percentage points"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Chooses the highest rate as the range."},{"option_index":2,"misconception":"Chooses the lowest rate as the range."},{"option_index":3,"misconception":"Adds the highest and lowest rates (29 + 8 = 37) instead of subtracting."}],"explanation":"Range = highest - lowest = 29% - 8% = 21 percentage points.","concept_id":"eco610-pov-interstate-disparities","strand":"Poverty","kind":"mcq"},{"id":"how-the-poverty-line-is-estimated-using-a-minimum-calorie-requirement-001","band":"K5","grade":9,"subject":"Mathematics","concept":"how the poverty line is estimated using a minimum calorie requirement","difficulty":2,"stem":"In a textbook model, the rural minimum calorie requirement is 2400 calories per person per day. If food costing ₹1 provides 300 calories, what is the minimum daily food expenditure per person?","options":["0.125","720000","8","2700"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reversed the ratio by dividing calories per rupee by the daily calorie need instead of dividing the calorie need by calories per rupee."},{"option_index":1,"misconception":"Multiplied the calorie need by calories per rupee instead of dividing to convert calories into rupees."},{"option_index":3,"misconception":"Added the calorie need and calories per rupee instead of using a unit rate."}],"explanation":"2400 ÷ 300 = 8 rupees per person per day.","concept_id":"eco610-pov-poverty-line-calc","strand":"Poverty","kind":"mcq"},{"id":"how-the-poverty-line-is-estimated-using-a-minimum-calorie-requirement-002","band":"K5","grade":9,"subject":"Mathematics","concept":"how the poverty line is estimated using a minimum calorie requirement","difficulty":2,"stem":"In a textbook model, the urban minimum calorie requirement is 2100 calories per person per day. If ₹1 buys 350 calories, what is the minimum daily food expenditure per person?","options":["735000","6","2450","1/6"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Multiplied the calorie requirement by calories per rupee instead of dividing to find the rupee cost."},{"option_index":2,"misconception":"Added the calorie requirement and calories per rupee instead of using a unit rate."},{"option_index":3,"misconception":"Reversed the ratio by computing calories per rupee divided by the calorie requirement."}],"explanation":"2100 ÷ 350 = 6 rupees per person per day.","concept_id":"eco610-pov-poverty-line-calc","strand":"Poverty","kind":"mcq"},{"id":"how-the-poverty-line-is-estimated-using-a-minimum-calorie-requirement-003","band":"K5","grade":9,"subject":"Mathematics","concept":"how the poverty line is estimated using a minimum calorie requirement","difficulty":2,"stem":"A rural family has 5 members. The rural minimum is 2400 calories per person per day. If ₹1 buys 400 calories, what is the family's minimum daily food expenditure?","options":["6","12000","150","30"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Computed only one person's expenditure and forgot to multiply by the number of family members."},{"option_index":1,"misconception":"Found the total calories needed but did not convert calories into rupees."},{"option_index":2,"misconception":"Multiplied the correct family expenditure by 5 again, double-counting the family members."}],"explanation":"(5 × 2400) ÷ 400 = 12000 ÷ 400 = 30 rupees per day for the family.","concept_id":"eco610-pov-poverty-line-calc","strand":"Poverty","kind":"mcq"},{"id":"how-the-poverty-line-is-estimated-using-a-minimum-calorie-requirement-004","band":"K5","grade":9,"subject":"Mathematics","concept":"how the poverty line is estimated using a minimum calorie requirement","difficulty":2,"stem":"A rural poverty line is ₹8 per person per day. What is the poverty line expenditure for one person for a 30-day month?","options":["240","8","38","3.75"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Used the daily expenditure as if it were already the monthly expenditure."},{"option_index":2,"misconception":"Added 30 days to ₹8 instead of multiplying the daily amount by 30."},{"option_index":3,"misconception":"Divided 30 by 8 instead of multiplying 8 by 30."}],"explanation":"8 × 30 = 240 rupees per person per month.","concept_id":"eco610-pov-poverty-line-calc","strand":"Poverty","kind":"mcq"},{"id":"how-the-poverty-line-is-estimated-using-a-minimum-calorie-requirement-005","band":"K5","grade":9,"subject":"Mathematics","concept":"how the poverty line is estimated using a minimum calorie requirement","difficulty":2,"stem":"If the rural poverty line is ₹12 per person per day and the minimum calorie requirement is 2400 calories, what is the implied cost per calorie?","options":["200","28800","0.005","0.05"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Divided 2400 by 12, finding calories per rupee instead of rupees per calorie."},{"option_index":1,"misconception":"Multiplied rupees by calories instead of dividing rupees by calories."},{"option_index":3,"misconception":"Made a place-value error and shifted the decimal one place too far."}],"explanation":"12 ÷ 2400 = 0.005 rupees per calorie.","concept_id":"eco610-pov-poverty-line-calc","strand":"Poverty","kind":"mcq"},{"id":"how-the-poverty-line-is-estimated-using-a-minimum-calorie-requirement-006","band":"K5","grade":9,"subject":"Mathematics","concept":"how the poverty line is estimated using a minimum calorie requirement","difficulty":2,"stem":"A state fixes the urban poverty line at ₹900 per person per month. If the month is taken as 30 days, what daily expenditure per person does this allow?","options":["900","30","27000","870"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Used the monthly amount as the daily amount."},{"option_index":2,"misconception":"Multiplied ₹900 by 30 instead of dividing the monthly amount by 30."},{"option_index":3,"misconception":"Subtracted 30 from 900 instead of dividing by 30."}],"explanation":"900 ÷ 30 = 30 rupees per person per day.","concept_id":"eco610-pov-poverty-line-calc","strand":"Poverty","kind":"mcq"},{"id":"how-the-poverty-line-is-estimated-using-a-minimum-calorie-requirement-007","band":"K5","grade":9,"subject":"Mathematics","concept":"how the poverty line is estimated using a minimum calorie requirement","difficulty":3,"stem":"The urban minimum calorie requirement is 2100 calories per person per day. If food costs ₹7 per 1000 calories, what is the minimum daily food expenditure per person?","options":["14700","300","10/3","14.7"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Multiplied 2100 by 7 and ignored that the cost is per 1000 calories, not per calorie."},{"option_index":1,"misconception":"Divided 2100 by 7 instead of using the rate ₹7 per 1000 calories."},{"option_index":2,"misconception":"Inverted the rate by dividing 7 by 2.1, confusing cost per 1000 calories with calories per rupee."}],"explanation":"2100 ÷ 1000 = 2.1 thousand calories, and 2.1 × 7 = 14.7 rupees per person per day.","concept_id":"eco610-pov-poverty-line-calc","strand":"Poverty","kind":"mcq"},{"id":"how-the-poverty-line-is-estimated-using-a-minimum-calorie-requirement-008","band":"K5","grade":9,"subject":"Mathematics","concept":"how the poverty line is estimated using a minimum calorie requirement","difficulty":2,"stem":"To check against the rural minimum of 2400 calories, a person spends ₹9 per day on food. If ₹1 buys 250 calories, how many calories does this food provide?","options":["2250","800/3","9.6","259"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Divided 2400 by 9 instead of multiplying the rupees spent by calories per rupee."},{"option_index":2,"misconception":"Computed the rupees needed for 2400 calories rather than the calories provided by ₹9."},{"option_index":3,"misconception":"Added 9 and 250 instead of multiplying 9 by 250."}],"explanation":"9 × 250 = 2250 calories.","concept_id":"eco610-pov-poverty-line-calc","strand":"Poverty","kind":"mcq"},{"id":"how-the-poverty-line-is-estimated-using-a-minimum-calorie-requirement-009","band":"K5","grade":9,"subject":"Mathematics","concept":"how the poverty line is estimated using a minimum calorie requirement","difficulty":2,"stem":"An urban family has 4 members. The urban minimum is 2100 calories per person per day. If ₹1 buys 300 calories, what is the family's minimum daily food expenditure?","options":["7","8400","28","112"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Computed only one person's expenditure and forgot to multiply by the number of family members."},{"option_index":1,"misconception":"Found the total calories needed but did not convert calories into rupees."},{"option_index":3,"misconception":"Multiplied the correct family expenditure by 4 again, double-counting the family members."}],"explanation":"(4 × 2100) ÷ 300 = 8400 ÷ 300 = 28 rupees per day for the family.","concept_id":"eco610-pov-poverty-line-calc","strand":"Poverty","kind":"mcq"},{"id":"how-the-poverty-line-is-estimated-using-a-minimum-calorie-requirement-010","band":"K5","grade":9,"subject":"Mathematics","concept":"how the poverty line is estimated using a minimum calorie requirement","difficulty":3,"stem":"A rural family of 6 spends ₹4320 in a 30-day month to meet the minimum 2400 calories per person per day. What is the implied cost per 1000 calories?","options":["1","10","100","0.01"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Misread cost per 1000 calories as cost per 100 calories, causing a factor-of-10 error."},{"option_index":2,"misconception":"Made a decimal place error by shifting the answer one more place to the left."},{"option_index":3,"misconception":"Gave the cost per calorie instead of the cost per 1000 calories."}],"explanation":"Total monthly calories = 6 × 2400 × 30 = 432000, so cost per 1000 calories = (4320 ÷ 432000) × 1000 = 10 rupees.","concept_id":"eco610-pov-poverty-line-calc","strand":"Poverty","kind":"mcq"},{"id":"the-poverty-line-as-a-minimum-income-or-consumption-benchmark-001","band":"K5","grade":9,"subject":"Mathematics","concept":"the poverty line as a minimum income or consumption benchmark","difficulty":2,"stem":"The poverty line in a district is ₹1,200 per person per month. What is the minimum monthly income needed for a family of 5 to be at the poverty line?","options":["₹6,000","₹240","₹1,205","₹5,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"divides the per-person poverty line by household size instead of multiplying"},{"option_index":2,"misconception":"adds the household size to the poverty line instead of multiplying"},{"option_index":3,"misconception":"uses ₹1,000 as the poverty line instead of ₹1,200"}],"explanation":"₹1,200 × 5 = ₹6,000.","concept_id":"eco610-pov-poverty-line","strand":"Poverty","kind":"mcq"},{"id":"the-poverty-line-as-a-minimum-income-or-consumption-benchmark-002","band":"K5","grade":9,"subject":"Mathematics","concept":"the poverty line as a minimum income or consumption benchmark","difficulty":2,"stem":"A family of 4 has a monthly income of ₹5,000. The poverty line is ₹1,200 per person per month. By how many rupees is the family's income above the poverty-line benchmark for the family?","options":["₹4,800","₹3,800","₹200","₹5,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"reports the family's poverty-line benchmark instead of the surplus above it"},{"option_index":1,"misconception":"subtracts the per-person poverty line from total income without multiplying by family size"},{"option_index":3,"misconception":"reports the total income instead of the amount above the benchmark"}],"explanation":"4 × ₹1,200 = ₹4,800; ₹5,000 − ₹4,800 = ₹200.","concept_id":"eco610-pov-poverty-line","strand":"Poverty","kind":"mcq"},{"id":"the-poverty-line-as-a-minimum-income-or-consumption-benchmark-003","band":"K5","grade":9,"subject":"Mathematics","concept":"the poverty line as a minimum income or consumption benchmark","difficulty":2,"stem":"The poverty line in a state is ₹1,500 per person per month. A household of 6 earns ₹8,400 per month. How many rupees below the poverty line is the household?","options":["₹9,000","₹600","₹2,400","₹1,500"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"reports the household's minimum required income instead of the shortfall"},{"option_index":2,"misconception":"uses a family size of 4 instead of 6 when finding the shortfall"},{"option_index":3,"misconception":"gives the per-person poverty line, not the total shortfall"}],"explanation":"6 × ₹1,500 = ₹9,000; ₹9,000 − ₹8,400 = ₹600.","concept_id":"eco610-pov-poverty-line","strand":"Poverty","kind":"mcq"},{"id":"the-poverty-line-as-a-minimum-income-or-consumption-benchmark-004","band":"K5","grade":9,"subject":"Mathematics","concept":"the poverty line as a minimum income or consumption benchmark","difficulty":2,"stem":"For a family of 4, the poverty line is ₹1,000 per person per month. The family's monthly consumption is ₹3,200. By what percent is the family's consumption below the poverty line for the family?","options":["25%","80%","8%","20%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"divides the shortfall by the actual consumption instead of by the poverty-line benchmark"},{"option_index":1,"misconception":"expresses actual consumption as a percent of the benchmark instead of the shortfall percent"},{"option_index":2,"misconception":"divides the rupee shortfall by 100 as if it were already a percent"}],"explanation":"Poverty-line total = 4 × ₹1,000 = ₹4,000; shortfall = ₹800; ₹800/₹4,000 × 100 = 20%.","concept_id":"eco610-pov-poverty-line","strand":"Poverty","kind":"mcq"},{"id":"the-poverty-line-as-a-minimum-income-or-consumption-benchmark-005","band":"K5","grade":9,"subject":"Mathematics","concept":"the poverty line as a minimum income or consumption benchmark","difficulty":2,"stem":"The poverty line is ₹1,250 per person per month. A family of 5 has a total monthly income of ₹7,000. What is the minimum total monthly income this family needs to reach the poverty line?","options":["₹1,250","₹6,250","₹7,000","₹5,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"gives the per-person poverty line, not the family total"},{"option_index":2,"misconception":"gives the family's actual income, not the minimum required"},{"option_index":3,"misconception":"multiplies ₹1,250 by 4 instead of by 5"}],"explanation":"₹1,250 × 5 = ₹6,250.","concept_id":"eco610-pov-poverty-line","strand":"Poverty","kind":"mcq"},{"id":"the-poverty-line-as-a-minimum-income-or-consumption-benchmark-006","band":"K5","grade":9,"subject":"Mathematics","concept":"the poverty line as a minimum income or consumption benchmark","difficulty":2,"stem":"A poverty line based on consumption is ₹900 per person per month. A family of 4 consumes goods worth ₹3,200 per month. How much extra monthly consumption is needed to reach the poverty line?","options":["₹400","₹3,600","₹2,300","₹3,200"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"reports the minimum total consumption needed, not the extra amount"},{"option_index":2,"misconception":"subtracts the per-person poverty line from total consumption instead of comparing with the total benchmark"},{"option_index":3,"misconception":"reports the current consumption, not the additional amount needed"}],"explanation":"Poverty-line total = 4 × ₹900 = ₹3,600; extra needed = ₹3,600 − ₹3,200 = ₹400.","concept_id":"eco610-pov-poverty-line","strand":"Poverty","kind":"mcq"},{"id":"the-poverty-line-as-a-minimum-income-or-consumption-benchmark-007","band":"K5","grade":9,"subject":"Mathematics","concept":"the poverty line as a minimum income or consumption benchmark","difficulty":2,"stem":"In a village of 200 people, the poverty line is ₹1,000 per person per month. What total monthly income is needed for all 200 people to be exactly at the poverty line?","options":["₹5","₹1,000","₹100,000","₹200,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"divides the per-person poverty line by the population instead of multiplying"},{"option_index":1,"misconception":"gives the per-person poverty line, not the total for the village"},{"option_index":2,"misconception":"uses 100 people instead of 200 in the multiplication"}],"explanation":"₹1,000 × 200 = ₹200,000.","concept_id":"eco610-pov-poverty-line","strand":"Poverty","kind":"mcq"},{"id":"the-poverty-line-as-a-minimum-income-or-consumption-benchmark-008","band":"K5","grade":9,"subject":"Mathematics","concept":"the poverty line as a minimum income or consumption benchmark","difficulty":2,"stem":"The poverty line is ₹1,200 per person per month. A family of 5 has a monthly income of ₹5,500. How much less than the poverty line is each person's share of the family income?","options":["₹1,100","₹100","₹500","₹1,200"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"gives the per-person income, not the shortfall per person"},{"option_index":2,"misconception":"gives the family's total shortfall, not the per-person shortfall"},{"option_index":3,"misconception":"gives the poverty line itself, not the shortfall"}],"explanation":"Per-person income = ₹5,500 ÷ 5 = ₹1,100; shortfall per person = ₹1,200 − ₹1,100 = ₹100.","concept_id":"eco610-pov-poverty-line","strand":"Poverty","kind":"mcq"},{"id":"the-poverty-line-as-a-minimum-income-or-consumption-benchmark-009","band":"K5","grade":9,"subject":"Mathematics","concept":"the poverty line as a minimum income or consumption benchmark","difficulty":2,"stem":"The poverty line is ₹1,000 per person per month. A household of 4 earns ₹2,800 per month. What is the total monthly shortfall below the poverty line?","options":["₹300","₹4,000","₹1,200","₹2,800"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"gives the per-person shortfall instead of the total household shortfall"},{"option_index":1,"misconception":"reports the household's poverty-line benchmark, not the shortfall"},{"option_index":3,"misconception":"reports the household's income, not the shortfall"}],"explanation":"Poverty-line total = 4 × ₹1,000 = ₹4,000; shortfall = ₹4,000 − ₹2,800 = ₹1,200.","concept_id":"eco610-pov-poverty-line","strand":"Poverty","kind":"mcq"},{"id":"the-poverty-line-as-a-minimum-income-or-consumption-benchmark-010","band":"K5","grade":9,"subject":"Mathematics","concept":"the poverty line as a minimum income or consumption benchmark","difficulty":2,"stem":"The poverty line is ₹1,000 per person per month. A family of 5 earns ₹4,000. What is the per-person shortfall below the poverty line?","options":["₹1,000","₹800","₹5,000","₹200"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"gives the total household shortfall, not the per-person shortfall"},{"option_index":1,"misconception":"gives the per-person income, not the shortfall per person"},{"option_index":2,"misconception":"reports the household's poverty-line benchmark, not the shortfall"}],"explanation":"Poverty-line total = 5 × ₹1,000 = ₹5,000; total shortfall = ₹1,000; per-person shortfall = ₹1,000 ÷ 5 = ₹200.","concept_id":"eco610-pov-poverty-line","strand":"Poverty","kind":"mcq"},{"id":"social-exclusion-and-vulnerability-as-dimensions-of-poverty-beyond-income-001","band":"K5","grade":9,"subject":"Mathematics","concept":"social exclusion and vulnerability as dimensions of poverty beyond income","difficulty":2,"stem":"A survey of 300 households finds that 40% are income-poor. Of the income-poor households, 60% are also socially excluded from school access. How many households are both income-poor and socially excluded?","options":["120","72","180","60"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Treats all income-poor households as socially excluded, ignoring the 60% condition."},{"option_index":2,"misconception":"Takes 60% of all 300 households instead of 60% of the 120 income-poor households."},{"option_index":3,"misconception":"Subtracts the percentages (60% - 40% = 20%) and applies 20% to 300."}],"explanation":"40% of 300 = 120 income-poor; 60% of 120 = 72.","concept_id":"eco610-pov-social-exclusion","strand":"Poverty","kind":"mcq"},{"id":"social-exclusion-and-vulnerability-as-dimensions-of-poverty-beyond-income-002","band":"K5","grade":9,"subject":"Mathematics","concept":"social exclusion and vulnerability as dimensions of poverty beyond income","difficulty":2,"stem":"A household earns ₹8,000 per month. The poverty line is ₹5,000 per month. What is the largest health shock, in rupees, the household can suffer and still remain at or above the poverty line?","options":["5000","8000","3000","13000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses the poverty line itself as the shock instead of the difference between income and the poverty line."},{"option_index":1,"misconception":"Confuses total income with the maximum allowable health shock."},{"option_index":3,"misconception":"Adds income and poverty line (₹8,000 + ₹5,000) instead of subtracting."}],"explanation":"8000 - 5000 = 3000.","concept_id":"eco610-pov-social-exclusion","strand":"Poverty","kind":"mcq"},{"id":"social-exclusion-and-vulnerability-as-dimensions-of-poverty-beyond-income-003","band":"K5","grade":9,"subject":"Mathematics","concept":"social exclusion and vulnerability as dimensions of poverty beyond income","difficulty":2,"stem":"A household has access to 4 out of 10 public services. What percentage of services is it excluded from?","options":["60%","40%","150%","20%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Reports the accessed share (4/10 = 40%) instead of the excluded share."},{"option_index":2,"misconception":"Divides excluded services by accessed services (6/4 = 150%) instead of by total services."},{"option_index":3,"misconception":"Uses the difference between excluded and accessed services (6 - 4 = 2) as 2/10 = 20%."}],"explanation":"10 - 4 = 6 excluded; 6/10 = 60%.","concept_id":"eco610-pov-social-exclusion","strand":"Poverty","kind":"mcq"},{"id":"social-exclusion-and-vulnerability-as-dimensions-of-poverty-beyond-income-004","band":"K5","grade":9,"subject":"Mathematics","concept":"social exclusion and vulnerability as dimensions of poverty beyond income","difficulty":2,"stem":"A multidimensional poverty index counts deprivations in 12 indicators equally. A household is multidimensionally poor if its deprivation score is at least one-third. What is the minimum number of deprivations needed to be multidimensionally poor?","options":["3","6","4","12"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Rounds one-third of 12 down to 3 instead of finding the exact whole-number threshold."},{"option_index":1,"misconception":"Uses one-half as the threshold instead of one-third."},{"option_index":3,"misconception":"Thinks all 12 deprivations are needed."}],"explanation":"12 × 1/3 = 4.","concept_id":"eco610-pov-social-exclusion","strand":"Poverty","kind":"mcq"},{"id":"social-exclusion-and-vulnerability-as-dimensions-of-poverty-beyond-income-005","band":"K5","grade":9,"subject":"Mathematics","concept":"social exclusion and vulnerability as dimensions of poverty beyond income","difficulty":2,"stem":"In a class of 40 students, 8 are from a socially excluded group. What fraction of the class is from the socially excluded group, in simplest form?","options":["1/4","1/5","2/5","4/5"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Compares excluded students with non-excluded students: 8/32 = 1/4."},{"option_index":2,"misconception":"Uses total 20 instead of 40 when simplifying 8/40, giving 8/20 = 2/5."},{"option_index":3,"misconception":"Finds the fraction of students not in the excluded group (32/40 = 4/5) instead of the excluded fraction."}],"explanation":"8/40 simplifies to 1/5.","concept_id":"eco610-pov-social-exclusion","strand":"Poverty","kind":"mcq"},{"id":"social-exclusion-and-vulnerability-as-dimensions-of-poverty-beyond-income-006","band":"K5","grade":9,"subject":"Mathematics","concept":"social exclusion and vulnerability as dimensions of poverty beyond income","difficulty":2,"stem":"A family's monthly income is ₹12,000. An illness reduces it by 40%. What is the new monthly income in rupees?","options":["4800","7200","16800","8000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Finds only the amount of the 40% reduction (₹4,800) and forgets to subtract it from the original income."},{"option_index":2,"misconception":"Adds 40% to the income instead of subtracting the reduction."},{"option_index":3,"misconception":"Subtracts ₹4,000 (one-third of income) instead of 40%."}],"explanation":"40% of 12000 = 4800; 12000 - 4800 = 7200.","concept_id":"eco610-pov-social-exclusion","strand":"Poverty","kind":"mcq"},{"id":"social-exclusion-and-vulnerability-as-dimensions-of-poverty-beyond-income-007","band":"K5","grade":9,"subject":"Mathematics","concept":"social exclusion and vulnerability as dimensions of poverty beyond income","difficulty":2,"stem":"A composite poverty score uses income score 0.6 and social inclusion score 0.3, with equal weights of 50% each. What is the composite score?","options":["0.9","0.18","0.3","0.45"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Adds the two scores without applying the 50% weights."},{"option_index":1,"misconception":"Multiplies the two scores (0.6 × 0.3) instead of taking a weighted average."},{"option_index":2,"misconception":"Uses only the lower of the two scores."}],"explanation":"0.5(0.6) + 0.5(0.3) = 0.45.","concept_id":"eco610-pov-social-exclusion","strand":"Poverty","kind":"mcq"},{"id":"social-exclusion-and-vulnerability-as-dimensions-of-poverty-beyond-income-008","band":"K5","grade":9,"subject":"Mathematics","concept":"social exclusion and vulnerability as dimensions of poverty beyond income","difficulty":2,"stem":"In a survey, 150 households are below the income poverty line. Of these, 90 also lack access to safe drinking water. What percentage of the income-poor households lack safe drinking water?","options":["60%","40%","90%","150%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Finds the complement (100% - 60% = 40%) instead of the required percentage."},{"option_index":2,"misconception":"Reports the count 90 as 90% without dividing by 150."},{"option_index":3,"misconception":"Uses the total number of income-poor households (150) as a percentage."}],"explanation":"90/150 × 100 = 60%.","concept_id":"eco610-pov-social-exclusion","strand":"Poverty","kind":"mcq"},{"id":"social-exclusion-and-vulnerability-as-dimensions-of-poverty-beyond-income-009","band":"K5","grade":9,"subject":"Mathematics","concept":"social exclusion and vulnerability as dimensions of poverty beyond income","difficulty":2,"stem":"A household is considered vulnerable if it has less than 3 months of expenses as savings. Its monthly expenses are ₹4,500. What is the minimum savings in rupees needed to avoid being vulnerable?","options":["4500","1500","13500","9000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses one month of expenses instead of 3 months."},{"option_index":1,"misconception":"Divides monthly expenses by 3 instead of multiplying."},{"option_index":3,"misconception":"Uses only 2 months of expenses."}],"explanation":"3 × 4500 = 13500.","concept_id":"eco610-pov-social-exclusion","strand":"Poverty","kind":"mcq"},{"id":"social-exclusion-and-vulnerability-as-dimensions-of-poverty-beyond-income-010","band":"K5","grade":9,"subject":"Mathematics","concept":"social exclusion and vulnerability as dimensions of poverty beyond income","difficulty":2,"stem":"In a town, 120 people are income-poor, and 80 people are socially excluded but not income-poor. How many people are poor in at least one of these two dimensions?","options":["80","200","120","40"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Counts only the socially excluded group and omits the income-poor group."},{"option_index":2,"misconception":"Counts only the income-poor group and omits the socially excluded group."},{"option_index":3,"misconception":"Subtracts 80 from 120 instead of adding the two non-overlapping groups."}],"explanation":"Since the 80 are not income-poor, total = 120 + 80 = 200.","concept_id":"eco610-pov-social-exclusion","strand":"Poverty","kind":"mcq"},{"id":"trends-in-india-s-poverty-ratio-over-recent-decades-001","band":"K5","grade":9,"subject":"Mathematics","concept":"trends in India's poverty ratio over recent decades","difficulty":2,"stem":"India's poverty ratio was about 45.3% in 1993-94 and about 21.9% in 2011-12. By how many percentage points did it fall?","options":["23.4%","21.9%","45.3%","67.2%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses the final poverty ratio as the fall."},{"option_index":2,"misconception":"Uses the initial poverty ratio as the fall."},{"option_index":3,"misconception":"Adds the two ratios instead of subtracting."}],"explanation":"45.3 - 21.9 = 23.4 percentage points.","concept_id":"eco610-pov-trends-india","strand":"Poverty","kind":"mcq"},{"id":"trends-in-india-s-poverty-ratio-over-recent-decades-002","band":"K5","grade":9,"subject":"Mathematics","concept":"trends in India's poverty ratio over recent decades","difficulty":2,"stem":"The poverty ratio was 37.2% in 2004-05 and 21.9% in 2011-12. What was the decline in percentage points?","options":["21.9%","15.3%","37.2%","59.1%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses the later ratio as the decline."},{"option_index":2,"misconception":"Uses the earlier ratio as the decline."},{"option_index":3,"misconception":"Adds the two ratios instead of subtracting."}],"explanation":"37.2 - 21.9 = 15.3 percentage points.","concept_id":"eco610-pov-trends-india","strand":"Poverty","kind":"mcq"},{"id":"trends-in-india-s-poverty-ratio-over-recent-decades-003","band":"K5","grade":9,"subject":"Mathematics","concept":"trends in India's poverty ratio over recent decades","difficulty":2,"stem":"From 1993-94 to 2004-05, India's poverty ratio fell from 45.3% to 37.2%. What was the decline?","options":["37.2%","45.3%","8.1%","82.5%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses the later ratio as the decline."},{"option_index":1,"misconception":"Uses the earlier ratio as the decline."},{"option_index":3,"misconception":"Adds the two ratios instead of subtracting."}],"explanation":"45.3 - 37.2 = 8.1 percentage points.","concept_id":"eco610-pov-trends-india","strand":"Poverty","kind":"mcq"},{"id":"trends-in-india-s-poverty-ratio-over-recent-decades-004","band":"K5","grade":9,"subject":"Mathematics","concept":"trends in India's poverty ratio over recent decades","difficulty":2,"stem":"The poverty ratio in 2011-12 was 21.9%. Express this as a decimal.","options":["2.19","0.0219","0.219","21.9"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Moves the decimal point one place left instead of two when converting percent to decimal."},{"option_index":1,"misconception":"Moves the decimal point four places left instead of two."},{"option_index":3,"misconception":"Leaves the number as a percent value without dividing by 100."}],"explanation":"21.9% = 21.9/100 = 0.219.","concept_id":"eco610-pov-trends-india","strand":"Poverty","kind":"mcq"},{"id":"trends-in-india-s-poverty-ratio-over-recent-decades-005","band":"K5","grade":9,"subject":"Mathematics","concept":"trends in India's poverty ratio over recent decades","difficulty":2,"stem":"Express 37.2% as a fraction in lowest terms.","options":["93/250","37/2","93/25","93/100"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Treats 37.2% as 37.2/1 instead of dividing by 100."},{"option_index":2,"misconception":"Moves the decimal one place too far when simplifying the denominator."},{"option_index":3,"misconception":"Incorrectly simplifies 372/1000 by dividing numerator by 4 but denominator by 10."}],"explanation":"37.2% = 372/1000 = 93/250.","concept_id":"eco610-pov-trends-india","strand":"Poverty","kind":"mcq"},{"id":"trends-in-india-s-poverty-ratio-over-recent-decades-006","band":"K5","grade":9,"subject":"Mathematics","concept":"trends in India's poverty ratio over recent decades","difficulty":2,"stem":"In 2011-12, India's poverty ratio was 21.9%. This was 15.3 percentage points lower than in 2004-05. What was the poverty ratio in 2004-05?","options":["6.6%","37.2%","21.9%","45.3%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Subtracts the decline from the 2011-12 ratio instead of adding."},{"option_index":2,"misconception":"Repeats the 2011-12 ratio."},{"option_index":3,"misconception":"Uses the 1993-94 ratio."}],"explanation":"21.9 + 15.3 = 37.2%.","concept_id":"eco610-pov-trends-india","strand":"Poverty","kind":"mcq"},{"id":"trends-in-india-s-poverty-ratio-over-recent-decades-007","band":"K5","grade":9,"subject":"Mathematics","concept":"trends in India's poverty ratio over recent decades","difficulty":2,"stem":"Poverty ratio fell from 37.2% in 2004-05 to 21.9% in 2011-12. What is the percentage decrease relative to the 2004-05 value?","options":["15.3%","21.9%","41.1%","58.9%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses the percentage-point decline as the percentage decrease."},{"option_index":1,"misconception":"Uses the final value as the decrease."},{"option_index":3,"misconception":"Uses the complement of the correct percentage decrease."}],"explanation":"(37.2 - 21.9)/37.2 × 100 = 15.3/37.2 × 100 ≈ 41.1%.","concept_id":"eco610-pov-trends-india","strand":"Poverty","kind":"mcq"},{"id":"trends-in-india-s-poverty-ratio-over-recent-decades-008","band":"K5","grade":9,"subject":"Mathematics","concept":"trends in India's poverty ratio over recent decades","difficulty":2,"stem":"Poverty ratio fell from 45.3% in 1993-94 to 21.9% in 2011-12. What is the percentage decrease relative to the 1993-94 value?","options":["48.3%","23.4%","21.9%","51.7%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Uses the complement of the correct percentage decrease."},{"option_index":1,"misconception":"Uses the percentage-point decline as the percentage decrease."},{"option_index":2,"misconception":"Uses the final value as the decrease."}],"explanation":"(45.3 - 21.9)/45.3 × 100 = 23.4/45.3 × 100 ≈ 51.7%.","concept_id":"eco610-pov-trends-india","strand":"Poverty","kind":"mcq"},{"id":"trends-in-india-s-poverty-ratio-over-recent-decades-009","band":"K5","grade":9,"subject":"Mathematics","concept":"trends in India's poverty ratio over recent decades","difficulty":2,"stem":"The poverty ratio in 2011-12 was 21.9% and in 2004-05 was 37.2%. What is the ratio 21.9 : 37.2 rounded to two decimal places?","options":["1.70","0.41","0.59","0.22"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reverses the ratio (37.2/21.9)."},{"option_index":1,"misconception":"Uses the decline divided by the 2004-05 value."},{"option_index":3,"misconception":"Turns 21.9% into 0.22 instead of using the ratio."}],"explanation":"21.9/37.2 ≈ 0.59.","concept_id":"eco610-pov-trends-india","strand":"Poverty","kind":"mcq"},{"id":"trends-in-india-s-poverty-ratio-over-recent-decades-010","band":"K5","grade":9,"subject":"Mathematics","concept":"trends in India's poverty ratio over recent decades","difficulty":2,"stem":"Between 2004-05 and 2011-12, the poverty ratio fell by 15.3 percentage points over 7 years. What was the average annual decline?","options":["2.19 percentage points","0.22 percentage points","15.3 percentage points","5.10 percentage points"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Misplaces the decimal when dividing 15.3 by 7."},{"option_index":2,"misconception":"Does not divide by the number of years."},{"option_index":3,"misconception":"Divides by 3 instead of 7."}],"explanation":"15.3 / 7 ≈ 2.19 percentage points per year.","concept_id":"eco610-pov-trends-india","strand":"Poverty","kind":"mcq"},{"id":"distinguishing-economic-activities-from-unpaid-non-economic-activities-001","band":"K5","grade":9,"subject":"Mathematics","concept":"distinguishing economic activities from unpaid non-economic activities","difficulty":2,"stem":"In a family of five: the father sells vegetables in the market, the mother cooks food for the family without payment, the grandfather teaches in a school for a salary, the sister cleans the house without payment, and the brother runs a small repair shop. How many family members are engaged in economic activities?","options":["5","3","2","1"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Counts the unpaid household work of the mother and sister as economic activity, so counts all five members"},{"option_index":2,"misconception":"Counts only work done outside the home (selling vegetables and salaried teaching) and ignores the brother's profit-earning shop as economic activity"},{"option_index":3,"misconception":"Counts only salaried work as economic and treats every self-employed or profit-earning activity as non-economic"}],"explanation":"Economic activities are those done for payment, profit or produce to be sold: father, grandfather and brother give 3 members.","concept_id":"eco610-ppl-economic-vs-non-economic-activity","strand":"People as Resource","kind":"mcq"},{"id":"distinguishing-economic-activities-from-unpaid-non-economic-activities-002","band":"K5","grade":9,"subject":"Mathematics","concept":"distinguishing economic activities from unpaid non-economic activities","difficulty":2,"stem":"A woman spends 2 hours a day cooking for her family without any payment and 3 hours a day selling homemade papads, for which she earns 40 rupees for every hour. How much does she earn per day from her economic activity?","options":["₹200","₹80","₹120","₹0"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Treats the unpaid cooking at home as earning work and multiplies all 5 hours of work by ₹40"},{"option_index":1,"misconception":"Multiplies the 2 hours of unpaid cooking by ₹40, counting a non-economic activity as an earning activity"},{"option_index":3,"misconception":"Assumes that making and selling homemade goods is not an economic activity, so no earning is counted"}],"explanation":"Only the 3 hours of selling papads earn money, so 3 × ₹40 = ₹120; the 2 unpaid cooking hours earn ₹0.","concept_id":"eco610-ppl-economic-vs-non-economic-activity","strand":"People as Resource","kind":"mcq"},{"id":"distinguishing-economic-activities-from-unpaid-non-economic-activities-003","band":"K5","grade":9,"subject":"Mathematics","concept":"distinguishing economic activities from unpaid non-economic activities","difficulty":3,"stem":"In a survey of 20 women in a village, 12 spend all their time on unpaid household work, 5 run their own tailoring shops, and 3 work as paid domestic help. How many of these women are doing economic activities?","options":["12","15","3","8"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Counts the unpaid household workers themselves as people doing economic activity"},{"option_index":1,"misconception":"Adds the unpaid household workers to the paid domestic help instead of counting only paid and self-employed work"},{"option_index":2,"misconception":"Counts only paid work outside the home and treats running one's own shop as non-economic"}],"explanation":"Only paid domestic help and profit-earning shop work count: 5 + 3 = 8 women.","concept_id":"eco610-ppl-economic-vs-non-economic-activity","strand":"People as Resource","kind":"mcq"},{"id":"distinguishing-economic-activities-from-unpaid-non-economic-activities-004","band":"K5","grade":9,"subject":"Mathematics","concept":"distinguishing economic activities from unpaid non-economic activities","difficulty":2,"stem":"Out of 40 activities recorded in a village survey, 25 are paid work and 15 are unpaid household work. What percentage of the recorded activities are economic activities?","options":["62.5%","37.5%","25%","60%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Calculates the unpaid share 15 out of 40 instead of the economic share"},{"option_index":2,"misconception":"Uses the count 25 directly as a percentage without dividing by the total 40 activities"},{"option_index":3,"misconception":"Uses 24 out of 40, rounding the counted activities before dividing"}],"explanation":"Economic activities = 25, so 25/40 × 100 = 62.5%.","concept_id":"eco610-ppl-economic-vs-non-economic-activity","strand":"People as Resource","kind":"mcq"},{"id":"distinguishing-economic-activities-from-unpaid-non-economic-activities-005","band":"K5","grade":9,"subject":"Mathematics","concept":"distinguishing economic activities from unpaid non-economic activities","difficulty":2,"stem":"A farmer harvests 3 tonnes of wheat and sells it at ₹2000 per tonne. He also keeps 1 tonne for his family's own consumption. How much money does he get from this economic activity?","options":["₹8000","₹2000","₹6000","₹4000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Treats the tonne kept for the family's own use as if it were also sold in the market"},{"option_index":1,"misconception":"Values only the tonne kept for the family and ignores the wheat actually sold"},{"option_index":3,"misconception":"Subtracts the self-consumed tonne from the sold quantity instead of ignoring it"}],"explanation":"Only the marketed 3 tonnes earn money: 3 × ₹2000 = ₹6000.","concept_id":"eco610-ppl-economic-vs-non-economic-activity","strand":"People as Resource","kind":"mcq"},{"id":"distinguishing-economic-activities-from-unpaid-non-economic-activities-006","band":"K5","grade":9,"subject":"Mathematics","concept":"distinguishing economic activities from unpaid non-economic activities","difficulty":3,"stem":"In a village survey of 60 workers, the numbers of workers doing paid economic work and workers doing only unpaid household work are in the ratio 3 : 2. How many workers do paid economic work?","options":["36","24","30","45"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Takes the smaller ratio part 2 for the paid workers instead of the part 3"},{"option_index":2,"misconception":"Splits 60 into two equal halves by ignoring the given ratio"},{"option_index":3,"misconception":"Takes 3 out of 4 equal parts, forgetting that the ratio compares 3 parts with 2 parts"}],"explanation":"Total parts = 5, one part = 60 ÷ 5 = 12, so paid workers = 3 × 12 = 36.","concept_id":"eco610-ppl-economic-vs-non-economic-activity","strand":"People as Resource","kind":"mcq"},{"id":"distinguishing-economic-activities-from-unpaid-non-economic-activities-007","band":"K5","grade":9,"subject":"Mathematics","concept":"distinguishing economic activities from unpaid non-economic activities","difficulty":3,"stem":"In one day a family spends 6 hours on paid work, 8 hours on unpaid household work and 10 hours resting. What fraction of the family's working hours are spent on economic activity?","options":["1/4","3/7","4/7","3/4"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Divides the 6 paid hours by all 24 hours of the day, counting resting time as working time"},{"option_index":2,"misconception":"Counts the unpaid household hours as economic activity and so takes 8 out of 14 hours"},{"option_index":3,"misconception":"Compares paid hours with unpaid household hours only, using 6 out of 8"}],"explanation":"Working hours = 6 + 8 = 14, of which 6 are economic, giving 6/14 = 3/7.","concept_id":"eco610-ppl-economic-vs-non-economic-activity","strand":"People as Resource","kind":"mcq"},{"id":"distinguishing-economic-activities-from-unpaid-non-economic-activities-008","band":"K5","grade":9,"subject":"Mathematics","concept":"distinguishing economic activities from unpaid non-economic activities","difficulty":2,"stem":"A tailor stitches 4 shirts for a customer at ₹250 each and also stitches 2 shirts free of charge for her brother. How much money does she earn from her stitching work?","options":["₹1500","₹500","₹250","₹1000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Counts the free stitching also as paid work and prices all 6 shirts"},{"option_index":1,"misconception":"Prices only the 2 free shirts as if they were paid work"},{"option_index":2,"misconception":"Counts the earning from just one shirt and stops there"}],"explanation":"Only the 4 paid shirts earn money: 4 × ₹250 = ₹1000.","concept_id":"eco610-ppl-economic-vs-non-economic-activity","strand":"People as Resource","kind":"mcq"},{"id":"distinguishing-economic-activities-from-unpaid-non-economic-activities-009","band":"K5","grade":9,"subject":"Mathematics","concept":"distinguishing economic activities from unpaid non-economic activities","difficulty":2,"stem":"A man paints his own house for 5 hours without any payment. The next day he paints a neighbour's house for 5 hours and is paid ₹150 per hour. How much does he earn?","options":["₹1500","₹750","₹0","₹375"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Counts the unpaid painting of his own house as paid work and prices all 10 hours"},{"option_index":2,"misconception":"Treats all painting work as unpaid household work, so no earning is counted at all"},{"option_index":3,"misconception":"Splits the paid 5 hours equally between the two houses and prices only 2.5 hours"}],"explanation":"Only the neighbour's house brings payment: 5 × ₹150 = ₹750.","concept_id":"eco610-ppl-economic-vs-non-economic-activity","strand":"People as Resource","kind":"mcq"},{"id":"distinguishing-economic-activities-from-unpaid-non-economic-activities-010","band":"K5","grade":9,"subject":"Mathematics","concept":"distinguishing economic activities from unpaid non-economic activities","difficulty":3,"stem":"In a survey of 64 activities, 3 out of every 8 activities were unpaid non-economic activities. How many of the 64 activities were economic activities?","options":["24","8","40","32"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Gives the number of unpaid non-economic activities instead of the economic ones"},{"option_index":1,"misconception":"Uses the denominator 8 of the ratio itself as the answer"},{"option_index":3,"misconception":"Assumes half of the 64 activities must be economic without using the given 3 out of 8"}],"explanation":"Unpaid activities = 3/8 × 64 = 24, so economic activities = 64 − 24 = 40.","concept_id":"eco610-ppl-economic-vs-non-economic-activity","strand":"People as Resource","kind":"mcq"},{"id":"educated-unemployment-as-a-distinct-feature-of-urban-india-001","band":"K5","grade":9,"subject":"Mathematics","concept":"educated unemployment as a distinct feature of urban India","difficulty":2,"stem":"In an urban area, 45% of 1200 unemployed persons are graduates. How many graduate unemployed persons are there?","options":["540","660","450","54"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Computed the complementary percentage (100% - 45% = 55%) instead of 45%."},{"option_index":2,"misconception":"Applied 45% to 1000 instead of 1200 (misread the total)."},{"option_index":3,"misconception":"Misplaced the decimal, treating 45% as 4.5%."}],"explanation":"45% of 1200 = 0.45 * 1200 = 540.","concept_id":"eco610-ppl-educated-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"educated-unemployment-as-a-distinct-feature-of-urban-india-002","band":"K5","grade":9,"subject":"Mathematics","concept":"educated unemployment as a distinct feature of urban India","difficulty":2,"stem":"The unemployment rate among educated urban youth is 12%. If there are 20000 educated urban youth in the labour force, how many are unemployed?","options":["2000","240000","2400","4000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Used 10% instead of 12%."},{"option_index":1,"misconception":"Multiplied by 12 instead of 0.12 (decimal misplaced)."},{"option_index":3,"misconception":"Used 20% instead of 12%."}],"explanation":"12% of 20000 = 0.12 * 20000 = 2400.","concept_id":"eco610-ppl-educated-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"educated-unemployment-as-a-distinct-feature-of-urban-india-003","band":"K5","grade":9,"subject":"Mathematics","concept":"educated unemployment as a distinct feature of urban India","difficulty":2,"stem":"In an urban district, 15% of 4000 educated women and 10% of 6000 educated men are unemployed. How many educated unemployed persons are there in total?","options":["1000","1200","1500","600"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Computed 10% of the total labour force 10000 (using a single combined rate)."},{"option_index":2,"misconception":"Computed 15% of the total labour force 10000 (using women's rate for all)."},{"option_index":3,"misconception":"Gave only one group's unemployed count instead of summing both groups."}],"explanation":"15% of 4000 = 600 and 10% of 6000 = 600; total = 1200.","concept_id":"eco610-ppl-educated-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"educated-unemployment-as-a-distinct-feature-of-urban-india-004","band":"K5","grade":9,"subject":"Mathematics","concept":"educated unemployment as a distinct feature of urban India","difficulty":2,"stem":"In an urban area, the educated unemployment rate is 9%. If 27000 educated urban persons are unemployed, what is the total educated urban labour force?","options":["243000","3000","270000","300000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Multiplied 27000 by 9 instead of dividing by 0.09."},{"option_index":1,"misconception":"Divided 27000 by 9 (treating 9% as 9 times)."},{"option_index":2,"misconception":"Used 10% instead of 9%."}],"explanation":"Total = 27000 / 0.09 = 300000.","concept_id":"eco610-ppl-educated-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"educated-unemployment-as-a-distinct-feature-of-urban-india-005","band":"K5","grade":9,"subject":"Mathematics","concept":"educated unemployment as a distinct feature of urban India","difficulty":2,"stem":"Urban educated unemployment increased from 800 to 1000 in a year. What is the percentage increase?","options":["20%","125%","25%","200%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Computed the increase as a percentage of the new value (200/1000) instead of the original."},{"option_index":1,"misconception":"Computed the new value as a percentage of the original (1000/800) instead of the increase."},{"option_index":3,"misconception":"Used the absolute increase 200 as the percentage without dividing by the original."}],"explanation":"Increase = 200; percentage increase = (200/800) * 100 = 25%.","concept_id":"eco610-ppl-educated-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"educated-unemployment-as-a-distinct-feature-of-urban-india-006","band":"K5","grade":9,"subject":"Mathematics","concept":"educated unemployment as a distinct feature of urban India","difficulty":2,"stem":"In an urban sample, the ratio of educated unemployed to uneducated unemployed is 3:2. If total unemployed is 5000, how many are educated unemployed?","options":["2000","3000","1500","2500"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Reversed the ratio, using 2 parts for educated unemployed."},{"option_index":2,"misconception":"Used 3/10 instead of 3/5."},{"option_index":3,"misconception":"Assumed an equal split (half of the total)."}],"explanation":"Total parts = 3 + 2 = 5; one part = 5000/5 = 1000; educated = 3 * 1000 = 3000.","concept_id":"eco610-ppl-educated-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"educated-unemployment-as-a-distinct-feature-of-urban-india-007","band":"K5","grade":9,"subject":"Mathematics","concept":"educated unemployment as a distinct feature of urban India","difficulty":2,"stem":"Educated unemployment rate in an urban area is 10% for men and 15% for women. If the educated urban labour force has 20000 men and 10000 women, how many educated unemployed persons are there in total?","options":["2500","3500","4000","3750"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Applied 10% to the total labour force 30000."},{"option_index":2,"misconception":"Swapped the rates (15% of men, 10% of women)."},{"option_index":3,"misconception":"Took the simple average of 10% and 15% (12.5%) and applied it to total 30000."}],"explanation":"10% of 20000 = 2000 and 15% of 10000 = 1500; total = 3500.","concept_id":"eco610-ppl-educated-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"educated-unemployment-as-a-distinct-feature-of-urban-india-008","band":"K5","grade":9,"subject":"Mathematics","concept":"educated unemployment as a distinct feature of urban India","difficulty":2,"stem":"A survey found that 60% of urban unemployed youth are educated. If 2400 educated unemployed youth are there, what is the total number of unemployed youth?","options":["1440","3600","6000","4000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Computed 60% of 2400 instead of finding the whole."},{"option_index":1,"misconception":"Used 2/3 instead of 60%."},{"option_index":2,"misconception":"Used 40% instead of 60% as the given proportion."}],"explanation":"Total = 2400 / 0.60 = 4000.","concept_id":"eco610-ppl-educated-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"educated-unemployment-as-a-distinct-feature-of-urban-india-009","band":"K5","grade":9,"subject":"Mathematics","concept":"educated unemployment as a distinct feature of urban India","difficulty":2,"stem":"The unemployment rate among educated urban youth is twice that among uneducated urban youth. If the uneducated unemployment rate is 5% and there are 40000 educated urban youth in the labour force, how many educated urban youth are unemployed?","options":["2000","8000","4000","400"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Used the uneducated rate 5% for educated youth."},{"option_index":1,"misconception":"Doubled the correct rate to 20% instead of 10%."},{"option_index":3,"misconception":"Misplaced the decimal in 10%, using 1%."}],"explanation":"Educated rate = 2 * 5% = 10%; 10% of 40000 = 4000.","concept_id":"eco610-ppl-educated-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"educated-unemployment-as-a-distinct-feature-of-urban-india-010","band":"K5","grade":9,"subject":"Mathematics","concept":"educated unemployment as a distinct feature of urban India","difficulty":2,"stem":"In urban India, 8% of the educated labour force is unemployed. If the educated labour force is 250000, how many educated persons are employed?","options":["20000","230000","245000","200000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Found the number unemployed instead of employed."},{"option_index":2,"misconception":"Used 2% unemployed instead of 8% (98% employed)."},{"option_index":3,"misconception":"Used 20% unemployed instead of 8% (80% employed)."}],"explanation":"Unemployed = 8% of 250000 = 20000; employed = 250000 - 20000 = 230000.","concept_id":"eco610-ppl-educated-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"people-as-human-capital-an-asset-rather-than-only-a-population-count-001","band":"K5","grade":9,"subject":"Mathematics","concept":"people as human capital, an asset rather than only a population count","difficulty":2,"stem":"A village has a total population of 6000. Of these, 3600 are people of working age who can work. What percentage of the total population is the working population?","options":["40%","166 2/3%","60%","36%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Computes the non-working share (2400/6000) instead of the working share."},{"option_index":1,"misconception":"Inverts the ratio and computes 6000/3600 × 100."},{"option_index":3,"misconception":"Simplifies 3600/6000 to 36/60 and mistakenly reads 36 as the percentage."}],"explanation":"Working population = 3600/6000 × 100% = 60%.","concept_id":"eco610-ppl-human-capital","strand":"People as Resource","kind":"mcq"},{"id":"people-as-human-capital-an-asset-rather-than-only-a-population-count-002","band":"K5","grade":9,"subject":"Mathematics","concept":"people as human capital, an asset rather than only a population count","difficulty":2,"stem":"A government spends ₹2,000 per person on skill training for 450 people. What is the total amount spent on this human capital investment?","options":["₹90,000","₹9,00,000","₹2,450","₹90,00,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Multiplies 2000 × 45 instead of 2000 × 450 (drops a zero)."},{"option_index":2,"misconception":"Adds 2000 and 450 instead of multiplying."},{"option_index":3,"misconception":"Multiplies 2000 × 4500 (adds an extra zero)."}],"explanation":"Total = ₹2,000 × 450 = ₹9,00,000.","concept_id":"eco610-ppl-human-capital","strand":"People as Resource","kind":"mcq"},{"id":"people-as-human-capital-an-asset-rather-than-only-a-population-count-003","band":"K5","grade":9,"subject":"Mathematics","concept":"people as human capital, an asset rather than only a population count","difficulty":2,"stem":"In a town of 8000 people, 6400 are literate. What is the literacy rate of the town?","options":["125%","20%","64%","80%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Inverts the ratio and computes 8000/6400 × 100."},{"option_index":1,"misconception":"Computes the non-literate percentage (1600/8000 × 100)."},{"option_index":2,"misconception":"Treats the number 6400 as 64% by misplacing the decimal."}],"explanation":"Literacy rate = 6400/8000 × 100% = 80%.","concept_id":"eco610-ppl-human-capital","strand":"People as Resource","kind":"mcq"},{"id":"people-as-human-capital-an-asset-rather-than-only-a-population-count-004","band":"K5","grade":9,"subject":"Mathematics","concept":"people as human capital, an asset rather than only a population count","difficulty":2,"stem":"A worker produces 40 units per day without training. After training, productivity increases by 25%. How many units per day does the worker produce after training?","options":["50 units/day","45 units/day","65 units/day","10 units/day"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds half of the 25% increase (5 units) instead of the full 25% of 40 (10 units)."},{"option_index":2,"misconception":"Adds 25 directly to 40, confusing percentage points with units."},{"option_index":3,"misconception":"Gives only the increase (25% of 40 = 10 units) and not the final production."}],"explanation":"Increase = 25% of 40 = 10; final = 40 + 10 = 50 units/day.","concept_id":"eco610-ppl-human-capital","strand":"People as Resource","kind":"mcq"},{"id":"people-as-human-capital-an-asset-rather-than-only-a-population-count-005","band":"K5","grade":9,"subject":"Mathematics","concept":"people as human capital, an asset rather than only a population count","difficulty":2,"stem":"A state has a population of 50,000. If 45% are children, 30% are working adults, and 25% are elderly, how many working adults are there?","options":["22,500","12,500","15,000","1,500"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Finds the number of children (45% of 50,000) instead of working adults."},{"option_index":1,"misconception":"Finds the number of elderly (25% of 50,000) instead of working adults."},{"option_index":3,"misconception":"Multiplies 50,000 by 0.03 instead of 0.30 (decimal-place error)."}],"explanation":"Working adults = 30% of 50,000 = 15,000.","concept_id":"eco610-ppl-human-capital","strand":"People as Resource","kind":"mcq"},{"id":"people-as-human-capital-an-asset-rather-than-only-a-population-count-006","band":"K5","grade":9,"subject":"Mathematics","concept":"people as human capital, an asset rather than only a population count","difficulty":2,"stem":"A country's population is 1,20,000. If 70% of the people are literate, how many people are not literate?","options":["84,000","36,000","30,000","70,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Finds the number of literate people (70%) instead of not literate."},{"option_index":2,"misconception":"Computes 30% of 1,00,000 instead of 1,20,000 (place-value error)."},{"option_index":3,"misconception":"Reads 70% as 70,000 directly."}],"explanation":"Not literate = 30% of 1,20,000 = 36,000.","concept_id":"eco610-ppl-human-capital","strand":"People as Resource","kind":"mcq"},{"id":"people-as-human-capital-an-asset-rather-than-only-a-population-count-007","band":"K5","grade":9,"subject":"Mathematics","concept":"people as human capital, an asset rather than only a population count","difficulty":2,"stem":"A company has 240 employees. After training, the average productivity increases from 25 units to 30 units per employee per day. What is the percentage increase in productivity?","options":["5%","20%","16 2/3%","120%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Takes the absolute increase (5 units) as a percentage."},{"option_index":2,"misconception":"Uses the new value (30) as the base: 5/30 × 100."},{"option_index":3,"misconception":"Computes the ratio of new to old productivity (30/25 × 100) instead of the percentage increase."}],"explanation":"Increase = (30 − 25)/25 × 100% = 20%.","concept_id":"eco610-ppl-human-capital","strand":"People as Resource","kind":"mcq"},{"id":"people-as-human-capital-an-asset-rather-than-only-a-population-count-008","band":"K5","grade":9,"subject":"Mathematics","concept":"people as human capital, an asset rather than only a population count","difficulty":2,"stem":"A village has 4,800 people. If 3/8 of them are children, how many are adults?","options":["1,800","2,400","4,200","3,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Finds the number of children (3/8 of 4,800) instead of adults."},{"option_index":1,"misconception":"Takes half the population as adults."},{"option_index":2,"misconception":"Subtracts 600 (which is 1/8 of 4,800) instead of 1,800 (3/8 of 4,800)."}],"explanation":"Adults = 5/8 of 4,800 = 3,000.","concept_id":"eco610-ppl-human-capital","strand":"People as Resource","kind":"mcq"},{"id":"people-as-human-capital-an-asset-rather-than-only-a-population-count-009","band":"K5","grade":9,"subject":"Mathematics","concept":"people as human capital, an asset rather than only a population count","difficulty":2,"stem":"A population of 2,500 produces goods and services worth ₹75,00,000 in a year. What is the value produced per person?","options":["₹30,000","₹300","₹3,000","₹3,00,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Divides by 250 instead of 2,500 (drops a zero)."},{"option_index":1,"misconception":"Divides by 25,000 instead of 2,500 (adds a zero)."},{"option_index":3,"misconception":"Divides by 25 instead of 2,500."}],"explanation":"Value per person = ₹75,00,000 ÷ 2,500 = ₹3,000.","concept_id":"eco610-ppl-human-capital","strand":"People as Resource","kind":"mcq"},{"id":"people-as-human-capital-an-asset-rather-than-only-a-population-count-010","band":"K5","grade":9,"subject":"Mathematics","concept":"people as human capital, an asset rather than only a population count","difficulty":2,"stem":"A state spends ₹1,200 per student on books and ₹800 per student on vocational training. If there are 5,000 students, what is the total spending on these human capital inputs?","options":["₹60,00,000","₹40,00,000","₹2,000","₹1,00,00,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Uses only the book cost (₹1,200 × 5,000)."},{"option_index":1,"misconception":"Uses only the training cost (₹800 × 5,000)."},{"option_index":2,"misconception":"Adds the per-student costs but forgets to multiply by 5,000."}],"explanation":"Total = (₹1,200 + ₹800) × 5,000 = ₹1,00,00,000.","concept_id":"eco610-ppl-human-capital","strand":"People as Resource","kind":"mcq"},{"id":"education-as-an-investment-that-raises-human-capital-001","band":"K5","grade":9,"subject":"Mathematics","concept":"education as an investment that raises human capital","difficulty":2,"stem":"A worker earns ₹18,000 per month. After completing a training course, her monthly earnings increase by ₹1,500. What are her monthly earnings after the course?","options":["₹16,500","₹18,125","₹19,500","₹1,500"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Subtracts the increase from the original earnings instead of adding it."},{"option_index":1,"misconception":"Treats the ₹1,500 increase as annual and divides it by 12 before adding."},{"option_index":3,"misconception":"Reports only the increase, not the new total earnings."}],"explanation":"New monthly earnings = ₹18,000 + ₹1,500 = ₹19,500.","concept_id":"eco610-ppl-investment-education","strand":"People as Resource","kind":"mcq"},{"id":"education-as-an-investment-that-raises-human-capital-002","band":"K5","grade":9,"subject":"Mathematics","concept":"education as an investment that raises human capital","difficulty":2,"stem":"A student spends ₹24,000 on a skill course. The course raises her yearly income by ₹8,000. In how many years will the extra income equal the cost of the course?","options":["2 years","3 years","1/3 year","4 years"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Subtracts the yearly increase from the course cost before dividing."},{"option_index":2,"misconception":"Inverts the ratio and divides yearly increase by course cost."},{"option_index":3,"misconception":"Adds the course cost and yearly increase before dividing."}],"explanation":"Payback years = cost ÷ yearly increase = 24,000 ÷ 8,000 = 3.","concept_id":"eco610-ppl-investment-education","strand":"People as Resource","kind":"mcq"},{"id":"education-as-an-investment-that-raises-human-capital-003","band":"K5","grade":9,"subject":"Mathematics","concept":"education as an investment that raises human capital","difficulty":2,"stem":"Education raises a worker's annual income from ₹1,80,000 to ₹2,16,000. What is the annual increase in income?","options":["₹3,60,000","₹18,000","₹2,16,000","₹36,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Misplaces the decimal and makes ₹36,000 into ₹3,60,000."},{"option_index":1,"misconception":"Halves the actual difference."},{"option_index":2,"misconception":"Reports the new annual income instead of the increase."}],"explanation":"Increase = 2,16,000 − 1,80,000 = 36,000.","concept_id":"eco610-ppl-investment-education","strand":"People as Resource","kind":"mcq"},{"id":"education-as-an-investment-that-raises-human-capital-004","band":"K5","grade":9,"subject":"Mathematics","concept":"education as an investment that raises human capital","difficulty":2,"stem":"A family invests ₹60,000 in education. This raises total lifetime earnings by ₹3,00,000. What is the extra lifetime earnings per rupee invested?","options":["5","0.2","2,40,000","50"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Inverts the ratio and divides investment by lifetime extra earnings."},{"option_index":2,"misconception":"Subtracts investment from lifetime extra earnings instead of dividing."},{"option_index":3,"misconception":"Divides by ₹6,000 instead of ₹60,000, a place-value error."}],"explanation":"Extra earnings per rupee = 3,00,000 ÷ 60,000 = 5.","concept_id":"eco610-ppl-investment-education","strand":"People as Resource","kind":"mcq"},{"id":"education-as-an-investment-that-raises-human-capital-005","band":"K5","grade":9,"subject":"Mathematics","concept":"education as an investment that raises human capital","difficulty":2,"stem":"A one-year course costs ₹15,000 and raises a worker's monthly income by ₹600. How many months of the extra income are needed to recover the course cost?","options":["25 months","2.5 months","15 months","30 months"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Divides by ₹6,000 instead of ₹600, a place-value error."},{"option_index":2,"misconception":"Uses ₹1,000 as the monthly increase instead of ₹600."},{"option_index":3,"misconception":"Uses ₹500 as the monthly increase instead of ₹600."}],"explanation":"Recovery months = 15,000 ÷ 600 = 25.","concept_id":"eco610-ppl-investment-education","strand":"People as Resource","kind":"mcq"},{"id":"education-as-an-investment-that-raises-human-capital-006","band":"K5","grade":9,"subject":"Mathematics","concept":"education as an investment that raises human capital","difficulty":2,"stem":"Worker A has 10 years of schooling and earns ₹12,000 per month. Worker B has 12 years of schooling and earns ₹15,000 per month. How much more does Worker B earn per year than Worker A?","options":["₹3,000","₹36,000","₹72,000","₹1,80,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Finds only the monthly difference, not the yearly difference."},{"option_index":2,"misconception":"Multiplies the monthly difference by 24 months instead of 12."},{"option_index":3,"misconception":"Reports Worker B's annual income only."}],"explanation":"Yearly difference = (15,000 − 12,000) × 12 = 36,000.","concept_id":"eco610-ppl-investment-education","strand":"People as Resource","kind":"mcq"},{"id":"education-as-an-investment-that-raises-human-capital-007","band":"K5","grade":9,"subject":"Mathematics","concept":"education as an investment that raises human capital","difficulty":2,"stem":"A scholarship of ₹9,000 helps a student finish a course. The course raises income by ₹1,500 per month. What fraction of one year's extra income does the scholarship cover?","options":["3/4","2","1/6","1/2"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Uses ₹1,000 as the monthly increase, giving yearly extra ₹12,000."},{"option_index":1,"misconception":"Inverts the fraction: yearly extra income ÷ scholarship."},{"option_index":2,"misconception":"Divides ₹1,500 by ₹9,000 instead of comparing yearly extra income."}],"explanation":"Yearly extra income = 1,500 × 12 = 18,000; fraction = 9,000/18,000 = 1/2.","concept_id":"eco610-ppl-investment-education","strand":"People as Resource","kind":"mcq"},{"id":"education-as-an-investment-that-raises-human-capital-008","band":"K5","grade":9,"subject":"Mathematics","concept":"education as an investment that raises human capital","difficulty":2,"stem":"If 3 years of education increase a worker's annual income by ₹45,000 in total, what is the average annual income increase per year of education?","options":["₹45,000","₹1,35,000","₹15,000","₹5,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reports the total increase instead of the per-year increase."},{"option_index":1,"misconception":"Multiplies the total by 3 instead of dividing by 3."},{"option_index":3,"misconception":"Divides by 9, as if applying division by 3 twice."}],"explanation":"Average per year = 45,000 ÷ 3 = 15,000.","concept_id":"eco610-ppl-investment-education","strand":"People as Resource","kind":"mcq"},{"id":"education-as-an-investment-that-raises-human-capital-009","band":"K5","grade":9,"subject":"Mathematics","concept":"education as an investment that raises human capital","difficulty":2,"stem":"A worker spends ₹2,400 on a certificate that raises monthly pay by ₹200. In how many months will the extra pay equal the cost?","options":["12 months","24 months","6 months","10 months"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Divides by ₹100, confusing ₹200 with ₹100."},{"option_index":2,"misconception":"Divides by ₹400, doubling the monthly increase."},{"option_index":3,"misconception":"Rounds the correct 12 months down to 10 months."}],"explanation":"Months to recover = 2,400 ÷ 200 = 12.","concept_id":"eco610-ppl-investment-education","strand":"People as Resource","kind":"mcq"},{"id":"education-as-an-investment-that-raises-human-capital-010","band":"K5","grade":9,"subject":"Mathematics","concept":"education as an investment that raises human capital","difficulty":2,"stem":"A village has 40 students. If 25% of them complete extra training and each trained student earns ₹1,200 more per month, what is the total extra monthly earning of the trained students?","options":["₹48,000","₹12,000","₹300","₹1,200"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses all 40 students instead of 25% of them."},{"option_index":2,"misconception":"Finds 25% of ₹1,200 instead of 25% of the students."},{"option_index":3,"misconception":"Reports the per-student extra earning, not the total."}],"explanation":"Trained students = 25% of 40 = 10; total extra = 10 × 1,200 = 12,000.","concept_id":"eco610-ppl-investment-education","strand":"People as Resource","kind":"mcq"},{"id":"health-as-an-investment-that-raises-human-capital-001","band":"K5","grade":9,"subject":"Mathematics","concept":"health as an investment that raises human capital","difficulty":2,"stem":"A company spends ₹8,000 per worker per year on health check-ups. Each worker's yearly output then rises by ₹10,400. What is the net gain in output per worker per year after paying for the health check-ups?","options":["₹2,400","₹10,400","₹18,400","₹8,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Ignores the health investment cost and reports the gross productivity gain."},{"option_index":2,"misconception":"Adds the investment cost to the gain instead of subtracting it."},{"option_index":3,"misconception":"Confuses the investment cost with the net gain."}],"explanation":"Net gain = ₹10,400 − ₹8,000 = ₹2,400.","concept_id":"eco610-ppl-investment-health","strand":"People as Resource","kind":"mcq"},{"id":"health-as-an-investment-that-raises-human-capital-002","band":"K5","grade":9,"subject":"Mathematics","concept":"health as an investment that raises human capital","difficulty":2,"stem":"After a workplace health program, a worker's daily output increases from 40 units to 50 units. What is the percentage increase in output?","options":["10%","125%","25%","80%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses the absolute increase of 10 units as the percentage."},{"option_index":1,"misconception":"Calculates the new output as a percentage of the old output instead of the increase."},{"option_index":3,"misconception":"Calculates the old output as a percentage of the new output."}],"explanation":"Increase = 10 units; percentage increase = 10 ÷ 40 × 100 = 25%.","concept_id":"eco610-ppl-investment-health","strand":"People as Resource","kind":"mcq"},{"id":"health-as-an-investment-that-raises-human-capital-003","band":"K5","grade":9,"subject":"Mathematics","concept":"health as an investment that raises human capital","difficulty":2,"stem":"A firm invests ₹1,200 per worker in an annual health program. This raises each worker's yearly productivity value by ₹300. What is the annual return on the health investment as a percentage of the amount invested?","options":["20%","400%","0.25%","25%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Uses gain divided by investment plus gain instead of gain divided by investment."},{"option_index":1,"misconception":"Inverts the ratio and divides investment by gain."},{"option_index":2,"misconception":"Leaves the decimal 0.25 as a percentage instead of multiplying by 100."}],"explanation":"Return = ₹300 ÷ ₹1,200 × 100 = 25%.","concept_id":"eco610-ppl-investment-health","strand":"People as Resource","kind":"mcq"},{"id":"health-as-an-investment-that-raises-human-capital-004","band":"K5","grade":9,"subject":"Mathematics","concept":"health as an investment that raises human capital","difficulty":2,"stem":"A worker used to take 8 sick days per year. After a health program, the number of sick days falls by 25%. How many sick days does the worker take now?","options":["2 days","6 days","10 days","4 days"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Gives only the reduction in sick days, not the remaining sick days."},{"option_index":2,"misconception":"Adds the reduction to the original number instead of subtracting it."},{"option_index":3,"misconception":"Uses a 50% reduction instead of 25%."}],"explanation":"Reduction = 25% of 8 = 2 days; remaining = 8 − 2 = 6 days.","concept_id":"eco610-ppl-investment-health","strand":"People as Resource","kind":"mcq"},{"id":"health-as-an-investment-that-raises-human-capital-005","band":"K5","grade":9,"subject":"Mathematics","concept":"health as an investment that raises human capital","difficulty":2,"stem":"Plan A: health investment ₹12,000 per worker, productivity gain ₹15,000. Plan B: health investment ₹9,000 per worker, productivity gain ₹10,800. How much more net gain does Plan A give than Plan B?","options":["₹1,200","₹3,000","₹1,800","₹4,200"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Gives Plan A's net gain, not the difference between the two net gains."},{"option_index":2,"misconception":"Gives Plan B's net gain, not the difference between the two net gains."},{"option_index":3,"misconception":"Subtracts the gross productivity gains without subtracting the health investments."}],"explanation":"Plan A net = ₹3,000; Plan B net = ₹1,800; difference = ₹1,200.","concept_id":"eco610-ppl-investment-health","strand":"People as Resource","kind":"mcq"},{"id":"health-as-an-investment-that-raises-human-capital-006","band":"K5","grade":9,"subject":"Mathematics","concept":"health as an investment that raises human capital","difficulty":2,"stem":"A factory spends ₹1,500 per worker on a health program. There are 240 workers. What is the total health investment for the factory?","options":["₹3,00,000","₹60,000","₹36,000","₹3,60,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Uses only 200 workers instead of all 240 workers."},{"option_index":1,"misconception":"Uses only 40 workers instead of all 240 workers."},{"option_index":2,"misconception":"Makes a place-value error and drops a zero from the product."}],"explanation":"Total = ₹1,500 × 240 = ₹3,60,000.","concept_id":"eco610-ppl-investment-health","strand":"People as Resource","kind":"mcq"},{"id":"health-as-an-investment-that-raises-human-capital-007","band":"K5","grade":9,"subject":"Mathematics","concept":"health as an investment that raises human capital","difficulty":2,"stem":"A health program raises a worker's output by 8%. If the worker currently produces 25,000 units per year, what is the increase in output?","options":["2,00,000 units","2,000 units","2,500 units","27,000 units"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Multiplies by 8 instead of finding 8% of the output."},{"option_index":2,"misconception":"Uses 10% instead of 8%."},{"option_index":3,"misconception":"Gives the new total output, not the increase in output."}],"explanation":"Increase = 8% of 25,000 = 2,000 units.","concept_id":"eco610-ppl-investment-health","strand":"People as Resource","kind":"mcq"},{"id":"health-as-an-investment-that-raises-human-capital-008","band":"K5","grade":9,"subject":"Mathematics","concept":"health as an investment that raises human capital","difficulty":2,"stem":"A worker's annual income rises from ₹2,00,000 to ₹2,50,000 after better health. What is the percentage increase in income?","options":["50%","125%","25%","20%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Treats the ₹50,000 increase as 50% instead of comparing it with the original income."},{"option_index":1,"misconception":"Calculates the new income as a percentage of the old income instead of the increase."},{"option_index":3,"misconception":"Calculates the increase as a percentage of the new income instead of the original income."}],"explanation":"Increase = ₹50,000; percentage increase = ₹50,000 ÷ ₹2,00,000 × 100 = 25%.","concept_id":"eco610-ppl-investment-health","strand":"People as Resource","kind":"mcq"},{"id":"health-as-an-investment-that-raises-human-capital-009","band":"K5","grade":9,"subject":"Mathematics","concept":"health as an investment that raises human capital","difficulty":2,"stem":"A health program costs ₹30,000 and gives ₹5,000 extra income every year. After how many years will the total extra income equal the cost?","options":["6 years","5 years","35 years","3 years"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Subtracts 1 year by an off-by-one error instead of dividing exactly."},{"option_index":2,"misconception":"Adds the cost and yearly income instead of dividing cost by yearly income."},{"option_index":3,"misconception":"Halves the correct number of years."}],"explanation":"Years = ₹30,000 ÷ ₹5,000 = 6 years.","concept_id":"eco610-ppl-investment-health","strand":"People as Resource","kind":"mcq"},{"id":"health-as-an-investment-that-raises-human-capital-010","band":"K5","grade":9,"subject":"Mathematics","concept":"health as an investment that raises human capital","difficulty":2,"stem":"A school health program costs ₹40 per student per month. If 150 students join, what is the total cost for one year?","options":["₹6,000","₹60,000","₹48,000","₹72,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Gives the monthly total cost, not the yearly total cost."},{"option_index":1,"misconception":"Uses 10 months instead of 12 months in a year."},{"option_index":2,"misconception":"Uses 8 months instead of 12 months in a year."}],"explanation":"Total = ₹40 × 150 × 12 = ₹72,000.","concept_id":"eco610-ppl-investment-health","strand":"People as Resource","kind":"mcq"},{"id":"quality-of-population-measured-by-literacy-rate-health-status-and-skill-formation-001","band":"K5","grade":9,"subject":"Mathematics","concept":"quality of population measured by literacy rate, health status and skill formation","difficulty":2,"stem":"In a town, the total population is 25,000 and the number of literate people is 18,000. What is the literacy rate (in %)?","options":["28","72","18","82"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Calculating the illiteracy rate (100 - 72 = 28) instead of the literacy rate."},{"option_index":2,"misconception":"Using the literate count (18,000) as a percentage by ignoring the thousand multiplier."},{"option_index":3,"misconception":"Subtracting the literate count in thousands (18) from 100 instead of using percentages."}],"explanation":"Literacy rate = (18,000 / 25,000) × 100 = 72%.","concept_id":"eco610-ppl-quality-population","strand":"People as Resource","kind":"mcq"},{"id":"quality-of-population-measured-by-literacy-rate-health-status-and-skill-formation-002","band":"K5","grade":9,"subject":"Mathematics","concept":"quality of population measured by literacy rate, health status and skill formation","difficulty":2,"stem":"A state has a literacy rate of 85%. If its population is 40,000, how many people are literate?","options":["6,000","8,500","34,000","3,400"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Calculating the illiterate population (15% of 40,000) instead of the literate population."},{"option_index":1,"misconception":"Using 10,000 as the base instead of 40,000 (85% of 10,000 = 8,500)."},{"option_index":3,"misconception":"Dividing by 10 instead of multiplying by 0.85 (decimal shift error)."}],"explanation":"Literate = 85% of 40,000 = 0.85 × 40,000 = 34,000.","concept_id":"eco610-ppl-quality-population","strand":"People as Resource","kind":"mcq"},{"id":"quality-of-population-measured-by-literacy-rate-health-status-and-skill-formation-003","band":"K5","grade":9,"subject":"Mathematics","concept":"quality of population measured by literacy rate, health status and skill formation","difficulty":2,"stem":"In a region, there were 60 infant deaths among 20,000 live births. What is the infant mortality rate per 1,000 live births?","options":["3","0.3","30","300"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Multiplying by 100 instead of 1,000 after dividing by total live births."},{"option_index":2,"misconception":"Dividing by 2,000 instead of 20,000 (place value error)."},{"option_index":3,"misconception":"Multiplying by 100,000 instead of 1,000 (place value error)."}],"explanation":"IMR = (60 / 20,000) × 1,000 = 3 per 1,000.","concept_id":"eco610-ppl-quality-population","strand":"People as Resource","kind":"mcq"},{"id":"quality-of-population-measured-by-literacy-rate-health-status-and-skill-formation-004","band":"K5","grade":9,"subject":"Mathematics","concept":"quality of population measured by literacy rate, health status and skill formation","difficulty":2,"stem":"A district has 600 males and 400 females. Among them, 480 males and 280 females are literate. What is the overall literacy rate (in %) of the district?","options":["75","80","76","70"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Averaging the male literacy rate (80%) and female literacy rate (70%) without weighting by population."},{"option_index":1,"misconception":"Using only the male literacy rate as the overall rate."},{"option_index":3,"misconception":"Using only the female literacy rate as the overall rate."}],"explanation":"Total literate = 480 + 280 = 760; total population = 1,000; literacy rate = 760/1000 × 100 = 76%.","concept_id":"eco610-ppl-quality-population","strand":"People as Resource","kind":"mcq"},{"id":"quality-of-population-measured-by-literacy-rate-health-status-and-skill-formation-005","band":"K5","grade":9,"subject":"Mathematics","concept":"quality of population measured by literacy rate, health status and skill formation","difficulty":2,"stem":"A skill development program trains 15% of 8,000 youth in a block. How many youth are trained?","options":["120","1,200","800","6,800"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Using 800 instead of 8,000 as the base (15% of 800 = 120)."},{"option_index":2,"misconception":"Calculating 10% of 8,000 instead of 15%."},{"option_index":3,"misconception":"Calculating the number not trained (85% of 8,000)."}],"explanation":"Trained youth = 15% of 8,000 = 0.15 × 8,000 = 1,200.","concept_id":"eco610-ppl-quality-population","strand":"People as Resource","kind":"mcq"},{"id":"quality-of-population-measured-by-literacy-rate-health-status-and-skill-formation-006","band":"K5","grade":9,"subject":"Mathematics","concept":"quality of population measured by literacy rate, health status and skill formation","difficulty":2,"stem":"In a village of 1,200 people, 720 are literate. What is the illiteracy rate (in %)?","options":["60","72","48","40"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Calculating the literacy rate instead of the illiteracy rate."},{"option_index":1,"misconception":"Using the literate count (720) as a percentage by ignoring the ten multiplier."},{"option_index":2,"misconception":"Subtracting 72 from 120 (mixing count and percentage)."}],"explanation":"Illiterate = 1,200 - 720 = 480; illiteracy rate = 480/1,200 × 100 = 40%.","concept_id":"eco610-ppl-quality-population","strand":"People as Resource","kind":"mcq"},{"id":"quality-of-population-measured-by-literacy-rate-health-status-and-skill-formation-007","band":"K5","grade":9,"subject":"Mathematics","concept":"quality of population measured by literacy rate, health status and skill formation","difficulty":2,"stem":"A state has a doctor-population ratio of 1 doctor per 1,500 people. How many doctors are needed for a population of 1,20,000?","options":["80","180","800","12"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Multiplying 1,20,000 by 1,500 instead of dividing (or misplacing a zero)."},{"option_index":2,"misconception":"Dividing by 150 instead of 1,500 (place value error)."},{"option_index":3,"misconception":"Dividing 1,20,000 by 10,000 instead of 1,500."}],"explanation":"Doctors = 1,20,000 ÷ 1,500 = 80.","concept_id":"eco610-ppl-quality-population","strand":"People as Resource","kind":"mcq"},{"id":"quality-of-population-measured-by-literacy-rate-health-status-and-skill-formation-008","band":"K5","grade":9,"subject":"Mathematics","concept":"quality of population measured by literacy rate, health status and skill formation","difficulty":2,"stem":"A program trains 2,500 people every year. How many people will be trained in 4 years?","options":["10,000","7,500","1,000","2,500"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Counting only 3 years instead of 4 (off-by-one in the number of years)."},{"option_index":2,"misconception":"Dividing 2,500 by 2.5 instead of multiplying by 4 (misusing the operation)."},{"option_index":3,"misconception":"Using the annual number as the total for 4 years (forgetting to multiply)."}],"explanation":"Total trained = 2,500 × 4 = 10,000.","concept_id":"eco610-ppl-quality-population","strand":"People as Resource","kind":"mcq"},{"id":"quality-of-population-measured-by-literacy-rate-health-status-and-skill-formation-009","band":"K5","grade":9,"subject":"Mathematics","concept":"quality of population measured by literacy rate, health status and skill formation","difficulty":2,"stem":"In a district, 720 out of 900 children are immunized. What percentage of children are NOT immunized?","options":["80","28","20","18"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Calculating the immunized percentage instead of the non-immunized percentage."},{"option_index":1,"misconception":"Using 720 as 72% and subtracting from 100 to get 28%."},{"option_index":3,"misconception":"Dividing the non-immunized count (180) by 1,000 instead of 900."}],"explanation":"Non-immunized = 900 - 720 = 180; percentage = 180/900 × 100 = 20%.","concept_id":"eco610-ppl-quality-population","strand":"People as Resource","kind":"mcq"},{"id":"quality-of-population-measured-by-literacy-rate-health-status-and-skill-formation-010","band":"K5","grade":9,"subject":"Mathematics","concept":"quality of population measured by literacy rate, health status and skill formation","difficulty":2,"stem":"A survey finds that 45% of 20,000 workers are skilled. How many workers are unskilled?","options":["9,000","5,500","4,500","11,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Calculating the skilled workers (45% of 20,000) instead of unskilled."},{"option_index":1,"misconception":"Calculating 55% of 10,000 (using half the population)."},{"option_index":2,"misconception":"Calculating 45% of 10,000 (using half the population)."}],"explanation":"Unskilled percentage = 100% - 45% = 55%; unskilled workers = 55% of 20,000 = 11,000.","concept_id":"eco610-ppl-quality-population","strand":"People as Resource","kind":"mcq"},{"id":"seasonal-and-disguised-unemployment-as-two-forms-found-in-rural-india-001","band":"K5","grade":9,"subject":"Mathematics","concept":"seasonal and disguised unemployment as two forms found in rural India","difficulty":2,"stem":"A farm needs 4 workers to cultivate a plot. 7 family members work on it, so the extra workers are disguisedly unemployed. How many are disguisedly unemployed?","options":["3","11","4","7"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds required workers and total workers instead of subtracting."},{"option_index":2,"misconception":"Confuses the required number of workers with the surplus workers."},{"option_index":3,"misconception":"Treats all working family members as disguisedly unemployed."}],"explanation":"Extra workers = 7 total workers − 4 needed workers = 3.","concept_id":"eco610-ppl-types-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"seasonal-and-disguised-unemployment-as-two-forms-found-in-rural-india-002","band":"K5","grade":9,"subject":"Mathematics","concept":"seasonal and disguised unemployment as two forms found in rural India","difficulty":2,"stem":"A farmer works 8 months in a year and has no work for the rest. How many months is he seasonally unemployed?","options":["8","4","20","12"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Confuses months worked with months seasonally unemployed."},{"option_index":2,"misconception":"Adds months worked to 12 months instead of subtracting."},{"option_index":3,"misconception":"Treats the whole year as unemployment."}],"explanation":"Seasonal unemployment months = 12 − 8 = 4.","concept_id":"eco610-ppl-types-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"seasonal-and-disguised-unemployment-as-two-forms-found-in-rural-india-003","band":"K5","grade":9,"subject":"Mathematics","concept":"seasonal and disguised unemployment as two forms found in rural India","difficulty":2,"stem":"In a village, 12 farmers are engaged in farming during harvest season, but only 5 are needed. How many are disguisedly unemployed?","options":["5","12","7","17"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Confuses needed workers with disguisedly unemployed workers."},{"option_index":1,"misconception":"Counts all engaged farmers as disguisedly unemployed."},{"option_index":3,"misconception":"Adds engaged and needed workers instead of subtracting."}],"explanation":"Extra workers = 12 engaged − 5 needed = 7.","concept_id":"eco610-ppl-types-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"seasonal-and-disguised-unemployment-as-two-forms-found-in-rural-india-004","band":"K5","grade":9,"subject":"Mathematics","concept":"seasonal and disguised unemployment as two forms found in rural India","difficulty":2,"stem":"A field has 9 workers, but the output would be the same with 4. The extra workers are disguisedly unemployed. How many extra workers are there?","options":["4","9","13","5"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Confuses needed workers with extra workers."},{"option_index":1,"misconception":"Counts all workers as disguisedly unemployed."},{"option_index":2,"misconception":"Adds workers and needed workers instead of subtracting."}],"explanation":"Extra workers = 9 present workers − 4 needed workers = 5.","concept_id":"eco610-ppl-types-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"seasonal-and-disguised-unemployment-as-two-forms-found-in-rural-india-005","band":"K5","grade":9,"subject":"Mathematics","concept":"seasonal and disguised unemployment as two forms found in rural India","difficulty":2,"stem":"A sugarcane worker gets work for 6 months in a year. How many months is she without work?","options":["12","18","0","6"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Treats the whole year as unemployed months."},{"option_index":1,"misconception":"Adds 6 months worked to 12 months instead of subtracting."},{"option_index":2,"misconception":"Thinks there is no seasonal unemployment because she has some work."}],"explanation":"Months without work = 12 − 6 = 6.","concept_id":"eco610-ppl-types-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"seasonal-and-disguised-unemployment-as-two-forms-found-in-rural-india-006","band":"K5","grade":9,"subject":"Mathematics","concept":"seasonal and disguised unemployment as two forms found in rural India","difficulty":2,"stem":"A family of 8 works on a farm. Only 5 workers are needed. What fraction of the family workforce is disguisedly unemployed?","options":["5/8","3/8","8/3","3/5"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses required workers as the unemployed fraction."},{"option_index":2,"misconception":"Inverts the ratio of total family to unemployed workers."},{"option_index":3,"misconception":"Compares unemployed to required workers instead of to total family."}],"explanation":"Extra workers = 8 − 5 = 3, so fraction = 3/8.","concept_id":"eco610-ppl-types-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"seasonal-and-disguised-unemployment-as-two-forms-found-in-rural-india-007","band":"K5","grade":9,"subject":"Mathematics","concept":"seasonal and disguised unemployment as two forms found in rural India","difficulty":2,"stem":"In a village, 15 workers are employed on a farm, but only 6 are actually required. How many workers are surplus?","options":["6","15","9","21"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Confuses required workers with surplus workers."},{"option_index":1,"misconception":"Counts all employed workers as surplus."},{"option_index":3,"misconception":"Adds employed and required workers instead of subtracting."}],"explanation":"Surplus workers = 15 employed − 6 required = 9.","concept_id":"eco610-ppl-types-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"seasonal-and-disguised-unemployment-as-two-forms-found-in-rural-india-008","band":"K5","grade":9,"subject":"Mathematics","concept":"seasonal and disguised unemployment as two forms found in rural India","difficulty":2,"stem":"A worker gets 5 months of work in agriculture, then 3 months in a sugar mill, and has no work for the rest of the year. How many months is he seasonally unemployed?","options":["4","8","20","12"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds working months but forgets to subtract from 12."},{"option_index":2,"misconception":"Adds total work months to 12 instead of subtracting."},{"option_index":3,"misconception":"Treats the whole year as seasonally unemployed."}],"explanation":"Total work months = 5 + 3 = 8, so unemployed months = 12 − 8 = 4.","concept_id":"eco610-ppl-types-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"seasonal-and-disguised-unemployment-as-two-forms-found-in-rural-india-009","band":"K5","grade":9,"subject":"Mathematics","concept":"seasonal and disguised unemployment as two forms found in rural India","difficulty":2,"stem":"A farm requires 10 workers for full cultivation. During sowing season, 16 workers are present. The extra workers are disguisedly unemployed. How many workers should be removed to eliminate disguised unemployment?","options":["10","6","26","16"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Confuses required workers with extra workers to remove."},{"option_index":2,"misconception":"Adds present and required workers instead of subtracting."},{"option_index":3,"misconception":"Counts all present workers as extra workers to remove."}],"explanation":"Extra workers = 16 present − 10 required = 6.","concept_id":"eco610-ppl-types-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"seasonal-and-disguised-unemployment-as-two-forms-found-in-rural-india-010","band":"K5","grade":9,"subject":"Mathematics","concept":"seasonal and disguised unemployment as two forms found in rural India","difficulty":2,"stem":"In a rural area, out of 24 farmers, 9 are seasonally unemployed and 6 are disguisedly unemployed. These groups do not overlap. How many farmers are not unemployed in either form?","options":["15","18","9","39"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Subtracts only disguised unemployment from total."},{"option_index":1,"misconception":"Subtracts only seasonal unemployment from total."},{"option_index":3,"misconception":"Adds unemployed groups to total farmers instead of subtracting."}],"explanation":"Unemployed total = 9 + 6 = 15, so not unemployed = 24 − 15 = 9.","concept_id":"eco610-ppl-types-unemployment","strand":"People as Resource","kind":"mcq"},{"id":"unemployment-people-willing-and-able-to-work-but-unable-to-find-it-001","band":"K5","grade":9,"subject":"Mathematics","concept":"unemployment: people willing and able to work but unable to find it","difficulty":2,"stem":"In a village of 625 people, the labour force is 500. Of the labour force, 100 are willing and able to work but cannot find work. What is the unemployment rate?","options":["20%","16%","25%","80%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Used the total population (625) as the denominator instead of the labour force."},{"option_index":2,"misconception":"Used the employed people (400) as the denominator instead of the labour force."},{"option_index":3,"misconception":"Calculated the employed share of the labour force, not the unemployed share."}],"explanation":"Unemployment rate = 100/500 = 20%.","concept_id":"eco610-ppl-unemployment-def","strand":"People as Resource","kind":"mcq"},{"id":"unemployment-people-willing-and-able-to-work-but-unable-to-find-it-002","band":"K5","grade":9,"subject":"Mathematics","concept":"unemployment: people willing and able to work but unable to find it","difficulty":2,"stem":"In a district, the unemployment rate is 12%. The labour force is 1,500. How many people are unemployed?","options":["12","180","1320","125"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Treated the percentage rate as a count of people."},{"option_index":2,"misconception":"Found the number of employed people instead of unemployed people."},{"option_index":3,"misconception":"Divided the labour force by 12 instead of multiplying by 0.12."}],"explanation":"Unemployed = 12% of 1,500 = 180.","concept_id":"eco610-ppl-unemployment-def","strand":"People as Resource","kind":"mcq"},{"id":"unemployment-people-willing-and-able-to-work-but-unable-to-find-it-003","band":"K5","grade":9,"subject":"Mathematics","concept":"unemployment: people willing and able to work but unable to find it","difficulty":2,"stem":"120 people are unemployed, which is 8% of the labour force. What is the labour force?","options":["960","150","1500","15"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Multiplied 120 by 8 instead of dividing by 0.08."},{"option_index":1,"misconception":"Used 0.8 instead of 0.08 for 8%."},{"option_index":3,"misconception":"Divided 120 by 8 instead of by 0.08."}],"explanation":"Labour force = 120 ÷ 0.08 = 1,500.","concept_id":"eco610-ppl-unemployment-def","strand":"People as Resource","kind":"mcq"},{"id":"unemployment-people-willing-and-able-to-work-but-unable-to-find-it-004","band":"K5","grade":9,"subject":"Mathematics","concept":"unemployment: people willing and able to work but unable to find it","difficulty":2,"stem":"In a city, the labour force is 2,000 and the unemployment rate is 12%. How many people are employed?","options":["240","2000","2240","1760"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Found the number of unemployed people instead of employed people."},{"option_index":1,"misconception":"Gave the whole labour force instead of the employed part."},{"option_index":2,"misconception":"Added the unemployed to the labour force instead of subtracting them."}],"explanation":"Employed = 88% of 2,000 = 1,760.","concept_id":"eco610-ppl-unemployment-def","strand":"People as Resource","kind":"mcq"},{"id":"unemployment-people-willing-and-able-to-work-but-unable-to-find-it-005","band":"K5","grade":9,"subject":"Mathematics","concept":"unemployment: people willing and able to work but unable to find it","difficulty":2,"stem":"In a town of 4,000 people, the labour force is 2,500. Of the labour force, 250 are unemployed. How many people are not in the labour force?","options":["1500","1250","1750","3750"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Found the number employed in the labour force instead of people outside the labour force."},{"option_index":2,"misconception":"Included the unemployed people in the not-in-labour-force group."},{"option_index":3,"misconception":"Subtracted unemployed people from total population instead of subtracting the labour force."}],"explanation":"Not in labour force = 4,000 − 2,500 = 1,500.","concept_id":"eco610-ppl-unemployment-def","strand":"People as Resource","kind":"mcq"},{"id":"unemployment-people-willing-and-able-to-work-but-unable-to-find-it-006","band":"K5","grade":9,"subject":"Mathematics","concept":"unemployment: people willing and able to work but unable to find it","difficulty":2,"stem":"A district has 2,000 people. 500 are not in the labour force. 1,200 are employed. The rest of the labour force is unemployed. What is the unemployment rate?","options":["15%","20%","25%","80%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Used the total population as the denominator instead of the labour force."},{"option_index":2,"misconception":"Used the employed people as the denominator instead of the labour force."},{"option_index":3,"misconception":"Calculated the employed share of the labour force, not the unemployed share."}],"explanation":"Labour force = 2,000 − 500 = 1,500; unemployed = 1,500 − 1,200 = 300; rate = 300/1,500 = 20%.","concept_id":"eco610-ppl-unemployment-def","strand":"People as Resource","kind":"mcq"},{"id":"unemployment-people-willing-and-able-to-work-but-unable-to-find-it-007","band":"K5","grade":9,"subject":"Mathematics","concept":"unemployment: people willing and able to work but unable to find it","difficulty":2,"stem":"Group A: labour force 400, unemployed 40. Group B: labour force 500, unemployed 75. What is the difference between their unemployment rates, in percentage points?","options":["10","15","5","25"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reported only Group A's unemployment rate."},{"option_index":1,"misconception":"Reported only Group B's unemployment rate."},{"option_index":3,"misconception":"Added the two rates instead of subtracting them."}],"explanation":"Group A rate = 40/400 = 10%; Group B rate = 75/500 = 15%; difference = 5 percentage points.","concept_id":"eco610-ppl-unemployment-def","strand":"People as Resource","kind":"mcq"},{"id":"unemployment-people-willing-and-able-to-work-but-unable-to-find-it-008","band":"K5","grade":9,"subject":"Mathematics","concept":"unemployment: people willing and able to work but unable to find it","difficulty":2,"stem":"In a region with 4,000 people, 1,600 are employed and 400 are unemployed. What is the unemployment rate?","options":["10%","25%","80%","20%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Used the total population as the denominator instead of the labour force."},{"option_index":1,"misconception":"Used the employed people as the denominator instead of the labour force."},{"option_index":2,"misconception":"Calculated the employed share of the labour force, not the unemployed share."}],"explanation":"Labour force = 1,600 + 400 = 2,000; unemployment rate = 400/2,000 = 20%.","concept_id":"eco610-ppl-unemployment-def","strand":"People as Resource","kind":"mcq"},{"id":"unemployment-people-willing-and-able-to-work-but-unable-to-find-it-009","band":"K5","grade":9,"subject":"Mathematics","concept":"unemployment: people willing and able to work but unable to find it","difficulty":2,"stem":"In a town of 5,000 people, 1,500 are not in the labour force. 3,000 are employed. The rest of the labour force is unemployed. How many people are unemployed?","options":["500","1500","2000","3500"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Gave the number of people not in the labour force."},{"option_index":2,"misconception":"Subtracted employed people from total population without excluding people not in the labour force."},{"option_index":3,"misconception":"Gave the total labour force instead of the unemployed part."}],"explanation":"Labour force = 5,000 − 1,500 = 3,500; unemployed = 3,500 − 3,000 = 500.","concept_id":"eco610-ppl-unemployment-def","strand":"People as Resource","kind":"mcq"},{"id":"unemployment-people-willing-and-able-to-work-but-unable-to-find-it-010","band":"K5","grade":9,"subject":"Mathematics","concept":"unemployment: people willing and able to work but unable to find it","difficulty":2,"stem":"In a district, 2,400 people are employed and 600 are unemployed. What is the labour force?","options":["1800","3000","2400","600"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Subtracted unemployed people from employed people instead of adding."},{"option_index":2,"misconception":"Counted only employed people as the labour force."},{"option_index":3,"misconception":"Gave only the unemployed people."}],"explanation":"Labour force = employed + unemployed = 2,400 + 600 = 3,000.","concept_id":"eco610-ppl-unemployment-def","strand":"People as Resource","kind":"mcq"},{"id":"how-unemployment-wastes-human-resources-and-increases-dependence-on-others-001","band":"K5","grade":9,"subject":"Mathematics","concept":"how unemployment wastes human resources and increases dependence on others","difficulty":2,"stem":"A village has 800 people of working age. If 20% of them are unemployed, how many working-age people are unemployed?","options":["20","640","160","200"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Treats the percentage as the actual number of people."},{"option_index":1,"misconception":"Finds the number of employed people instead of the unemployed."},{"option_index":3,"misconception":"Uses 25% instead of 20%."}],"explanation":"20% of 800 = 0.20 × 800 = 160.","concept_id":"eco610-ppl-unemployment-impact","strand":"People as Resource","kind":"mcq"},{"id":"how-unemployment-wastes-human-resources-and-increases-dependence-on-others-002","band":"K5","grade":9,"subject":"Mathematics","concept":"how unemployment wastes human resources and increases dependence on others","difficulty":2,"stem":"In a town, 600 people are employed and each employed person supports 3 dependents. How many dependents in total are supported by these employed people?","options":["1800","200","603","180"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Divides 600 by 3, reversing the support relation."},{"option_index":2,"misconception":"Adds 600 and 3 instead of multiplying."},{"option_index":3,"misconception":"Misplaces the decimal when multiplying by 0.3 instead of 3."}],"explanation":"Total dependents = 600 × 3 = 1800.","concept_id":"eco610-ppl-unemployment-impact","strand":"People as Resource","kind":"mcq"},{"id":"how-unemployment-wastes-human-resources-and-increases-dependence-on-others-003","band":"K5","grade":9,"subject":"Mathematics","concept":"how unemployment wastes human resources and increases dependence on others","difficulty":3,"stem":"An unemployed person could produce goods worth ₹1,200 per month. If 15 people remain unemployed for 4 months, what is the total value of lost production?","options":["₹4,800","₹18,000","₹60,000","₹72,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Calculates the loss for one person over 4 months only."},{"option_index":1,"misconception":"Calculates the loss for 15 people for one month only."},{"option_index":2,"misconception":"Rounds ₹1,200 to ₹1,000 before multiplying."}],"explanation":"Lost value = 1200 × 15 × 4 = ₹72,000.","concept_id":"eco610-ppl-unemployment-impact","strand":"People as Resource","kind":"mcq"},{"id":"how-unemployment-wastes-human-resources-and-increases-dependence-on-others-004","band":"K5","grade":9,"subject":"Mathematics","concept":"how unemployment wastes human resources and increases dependence on others","difficulty":3,"stem":"A district has 2,000 workers. Originally 200 were unemployed. Then 100 more workers lose their jobs. By what percent did the number of unemployed workers increase?","options":["5%","33.3%","50%","66.7%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Compares the increase to the total number of workers instead of the original unemployed."},{"option_index":1,"misconception":"Compares the increase to the new number of unemployed (300)."},{"option_index":3,"misconception":"Divides the original unemployed by the new unemployed (200/300)."}],"explanation":"Increase = 100; percent increase = 100/200 × 100 = 50%.","concept_id":"eco610-ppl-unemployment-impact","strand":"People as Resource","kind":"mcq"},{"id":"how-unemployment-wastes-human-resources-and-increases-dependence-on-others-005","band":"K5","grade":9,"subject":"Mathematics","concept":"how unemployment wastes human resources and increases dependence on others","difficulty":2,"stem":"The dependency ratio is the number of dependents per 100 employed people. If 40 employed people support 120 dependents, what is the dependency ratio?","options":["3","33.3","160","300"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Gives dependents per employed person without multiplying by 100."},{"option_index":1,"misconception":"Reverses the ratio and divides 40 by 120."},{"option_index":2,"misconception":"Adds the number of employed and dependents."}],"explanation":"Dependency ratio = (120/40) × 100 = 300 dependents per 100 employed.","concept_id":"eco610-ppl-unemployment-impact","strand":"People as Resource","kind":"mcq"},{"id":"how-unemployment-wastes-human-resources-and-increases-dependence-on-others-006","band":"K5","grade":9,"subject":"Mathematics","concept":"how unemployment wastes human resources and increases dependence on others","difficulty":2,"stem":"In a family, 3 earning members support 9 non-earning members. If one earner becomes unemployed, how many dependents per earning member must the remaining earners support?","options":["3","4.5","6","11"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses the original ratio before the earner became unemployed."},{"option_index":2,"misconception":"Subtracts 3 earners from 9 dependents."},{"option_index":3,"misconception":"Adds the new number of earners to the dependents."}],"explanation":"Remaining earners = 2, so dependents per earner = 9/2 = 4.5.","concept_id":"eco610-ppl-unemployment-impact","strand":"People as Resource","kind":"mcq"},{"id":"how-unemployment-wastes-human-resources-and-increases-dependence-on-others-007","band":"K5","grade":9,"subject":"Mathematics","concept":"how unemployment wastes human resources and increases dependence on others","difficulty":2,"stem":"A factory has 500 workers. If 80 workers lose their jobs, what percent of the total workers lost jobs?","options":["8%","16%","20%","84%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Halves the correct percentage due to a decimal-place error."},{"option_index":2,"misconception":"Compares the 80 job losses to the 400 remaining workers."},{"option_index":3,"misconception":"Finds the percent of workers still employed instead of job losses."}],"explanation":"Percent = (80/500) × 100 = 16%.","concept_id":"eco610-ppl-unemployment-impact","strand":"People as Resource","kind":"mcq"},{"id":"how-unemployment-wastes-human-resources-and-increases-dependence-on-others-008","band":"K5","grade":9,"subject":"Mathematics","concept":"how unemployment wastes human resources and increases dependence on others","difficulty":2,"stem":"A village has 1,000 working-age people. If 350 are unemployed, how many employed people are there to support them and other dependents?","options":["65","350","650","1350"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Places the decimal incorrectly after subtracting, making 650 into 65."},{"option_index":1,"misconception":"Gives the number of unemployed people instead of employed people."},{"option_index":3,"misconception":"Adds the unemployed to the total instead of subtracting."}],"explanation":"Employed = 1000 − 350 = 650.","concept_id":"eco610-ppl-unemployment-impact","strand":"People as Resource","kind":"mcq"},{"id":"how-unemployment-wastes-human-resources-and-increases-dependence-on-others-009","band":"K5","grade":9,"subject":"Mathematics","concept":"how unemployment wastes human resources and increases dependence on others","difficulty":2,"stem":"An unemployed person needs ₹2,500 per month from family for basic needs. If 12 unemployed people depend on their families, what is the total monthly dependence amount?","options":["₹2,512","₹3,000","₹25,000","₹30,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Adds 2,500 and 12 instead of multiplying."},{"option_index":1,"misconception":"Uses ₹250 instead of ₹2,500."},{"option_index":2,"misconception":"Multiplies by 10 instead of 12."}],"explanation":"Total = 2500 × 12 = ₹30,000.","concept_id":"eco610-ppl-unemployment-impact","strand":"People as Resource","kind":"mcq"},{"id":"how-unemployment-wastes-human-resources-and-increases-dependence-on-others-010","band":"K5","grade":9,"subject":"Mathematics","concept":"how unemployment wastes human resources and increases dependence on others","difficulty":3,"stem":"In a town, 3,000 employed people support 6,000 dependents. If 600 employed people become unemployed, and the total number of dependents increases by 600, how many more dependents per employed person must the remaining employed people support?","options":["0.25","0.75","2","2.75"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Computes newly unemployed people per remaining employed person (600/2400)."},{"option_index":2,"misconception":"Gives the original dependents per employed person."},{"option_index":3,"misconception":"Gives the new dependents per employed person instead of the increase."}],"explanation":"Original per employed = 6000/3000=2. New dependents = 6600, remaining employed = 2400, new per employed = 2.75; increase = 0.75.","concept_id":"eco610-ppl-unemployment-impact","strand":"People as Resource","kind":"mcq"},{"id":"why-farmers-need-credit-for-seeds-fertiliser-and-equipment-before-the-harvest-001","band":"K5","grade":9,"subject":"Mathematics","concept":"why farmers need credit for seeds, fertiliser and equipment before the harvest","difficulty":2,"stem":"A farmer needs ₹8,000 for seeds and ₹12,000 for fertiliser before the harvest. What total credit is needed for these two inputs?","options":["₹4,000","₹96,000","₹2,00,000","₹20,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Subtracts the smaller amount from the larger instead of adding the two input costs."},{"option_index":1,"misconception":"Multiplies the two costs instead of adding them."},{"option_index":2,"misconception":"Makes a place-value error by writing 20,000 as 2,00,000."}],"explanation":"₹8,000 + ₹12,000 = ₹20,000.","concept_id":"eco610-rur-credit-need","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-farmers-need-credit-for-seeds-fertiliser-and-equipment-before-the-harvest-002","band":"K5","grade":9,"subject":"Mathematics","concept":"why farmers need credit for seeds, fertiliser and equipment before the harvest","difficulty":2,"stem":"A farmer borrows ₹15,000 at 12% simple interest per year for one year to buy seeds. How much interest must be paid?","options":["₹16,800","₹1,500","₹1,800","₹180"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Adds interest to principal and gives total repayment instead of interest."},{"option_index":1,"misconception":"Uses 10% instead of 12% by dropping the 2 in the rate."},{"option_index":3,"misconception":"Divides the correct interest by 10 through a decimal-place error."}],"explanation":"Interest = 15000 × 12/100 × 1 = ₹1,800.","concept_id":"eco610-rur-credit-need","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-farmers-need-credit-for-seeds-fertiliser-and-equipment-before-the-harvest-003","band":"K5","grade":9,"subject":"Mathematics","concept":"why farmers need credit for seeds, fertiliser and equipment before the harvest","difficulty":3,"stem":"A farmer repays a fertiliser loan after one year with 10% simple interest. The total repayment is ₹22,000. What was the principal borrowed?","options":["₹19,800","₹2,000","₹24,200","₹20,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Subtracts 10% of the total repayment instead of dividing by 1.10."},{"option_index":1,"misconception":"Reports only the interest amount, not the principal."},{"option_index":2,"misconception":"Adds another 10% to the total repayment instead of removing the interest."}],"explanation":"Principal = 22000 ÷ 1.10 = ₹20,000.","concept_id":"eco610-rur-credit-need","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-farmers-need-credit-for-seeds-fertiliser-and-equipment-before-the-harvest-004","band":"K5","grade":9,"subject":"Mathematics","concept":"why farmers need credit for seeds, fertiliser and equipment before the harvest","difficulty":2,"stem":"Seeds cost ₹4,500, fertiliser costs ₹7,500, and equipment hire costs ₹3,000. The farmer has ₹5,000 saved. How much credit is needed?","options":["₹10,000","₹15,000","₹20,000","₹5,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds the input costs but forgets to subtract the farmer's savings."},{"option_index":2,"misconception":"Adds the savings to the input costs instead of subtracting them."},{"option_index":3,"misconception":"Mistakes the amount saved for the amount of credit needed."}],"explanation":"Total cost = 4500 + 7500 + 3000 = ₹15,000; credit = 15000 − 5000 = ₹10,000.","concept_id":"eco610-rur-credit-need","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-farmers-need-credit-for-seeds-fertiliser-and-equipment-before-the-harvest-005","band":"K5","grade":9,"subject":"Mathematics","concept":"why farmers need credit for seeds, fertiliser and equipment before the harvest","difficulty":2,"stem":"A farmer needs ₹18,000 before harvest and will earn ₹25,000 after harvest. After repaying the ₹18,000, how much money is left?","options":["₹43,000","₹7,000","₹25,000","₹18,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Adds income and loan instead of subtracting the loan from income."},{"option_index":2,"misconception":"Gives the harvest income without subtracting the loan."},{"option_index":3,"misconception":"Gives the loan amount without considering the harvest income."}],"explanation":"₹25,000 − ₹18,000 = ₹7,000.","concept_id":"eco610-rur-credit-need","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-farmers-need-credit-for-seeds-fertiliser-and-equipment-before-the-harvest-006","band":"K5","grade":9,"subject":"Mathematics","concept":"why farmers need credit for seeds, fertiliser and equipment before the harvest","difficulty":3,"stem":"A farmer borrows ₹12,000 at 8% simple interest per year and repays after 6 months. How much interest is due?","options":["₹960","₹12,480","₹480","₹1,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Calculates interest for a full year instead of half a year."},{"option_index":1,"misconception":"Adds the interest to the principal and gives total repayment."},{"option_index":3,"misconception":"Rounds 8% to about 8.33% or otherwise overestimates the half-year interest."}],"explanation":"Interest = 12000 × 8/100 × 6/12 = ₹480.","concept_id":"eco610-rur-credit-need","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-farmers-need-credit-for-seeds-fertiliser-and-equipment-before-the-harvest-007","band":"K5","grade":9,"subject":"Mathematics","concept":"why farmers need credit for seeds, fertiliser and equipment before the harvest","difficulty":2,"stem":"A farmer spends ₹2,500 on seeds, ₹3,500 on fertiliser, and ₹1,000 on equipment. The produce sells for ₹9,000. What is the profit?","options":["₹2,000","₹11,000","₹5,500","₹7,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds total costs to selling price instead of subtracting costs from selling price."},{"option_index":2,"misconception":"Subtracts only seeds and equipment from selling price and omits fertiliser."},{"option_index":3,"misconception":"Gives total cost instead of profit."}],"explanation":"Total cost = 2500 + 3500 + 1000 = ₹7,000; profit = 9000 − 7000 = ₹2,000.","concept_id":"eco610-rur-credit-need","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-farmers-need-credit-for-seeds-fertiliser-and-equipment-before-the-harvest-008","band":"K5","grade":9,"subject":"Mathematics","concept":"why farmers need credit for seeds, fertiliser and equipment before the harvest","difficulty":3,"stem":"A lender charges simple interest at 2% per month. A farmer borrows ₹9,000 for 3 months. How much interest is charged?","options":["₹180","₹540","₹1,080","₹9,540"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses only 1 month instead of 3 months."},{"option_index":2,"misconception":"Uses 6 months instead of 3 months or doubles the correct interest."},{"option_index":3,"misconception":"Adds interest to principal and gives total repayment."}],"explanation":"Interest = 9000 × 2/100 × 3 = ₹540.","concept_id":"eco610-rur-credit-need","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-farmers-need-credit-for-seeds-fertiliser-and-equipment-before-the-harvest-009","band":"K5","grade":9,"subject":"Mathematics","concept":"why farmers need credit for seeds, fertiliser and equipment before the harvest","difficulty":3,"stem":"A farmer takes a ₹20,000 loan at 6% simple interest per year. How much must be repaid in total after one year?","options":["₹21,200","₹20,600","₹1,200","₹22,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses 3% instead of 6%, as if the time were half a year."},{"option_index":2,"misconception":"Gives only the interest, not the total repayment."},{"option_index":3,"misconception":"Uses 10% interest instead of 6%."}],"explanation":"Interest = 20000 × 6/100 = ₹1,200; total = 20000 + 1200 = ₹21,200.","concept_id":"eco610-rur-credit-need","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-farmers-need-credit-for-seeds-fertiliser-and-equipment-before-the-harvest-010","band":"K5","grade":9,"subject":"Mathematics","concept":"why farmers need credit for seeds, fertiliser and equipment before the harvest","difficulty":2,"stem":"A cooperative gives seeds worth ₹6,000 and fertiliser worth ₹4,000 on credit. The farmer repays the total in 4 equal monthly installments. How much is each installment?","options":["₹1,000","₹1,500","₹2,500","₹10,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Divides only the fertiliser cost by 4 and ignores seeds."},{"option_index":1,"misconception":"Divides only the seed cost by 4 and ignores fertiliser."},{"option_index":3,"misconception":"Gives the total credit without dividing into installments."}],"explanation":"Total credit = 6000 + 4000 = ₹10,000; each installment = 10000 ÷ 4 = ₹2,500.","concept_id":"eco610-rur-credit-need","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-rural-livelihoods-are-diversifying-beyond-farming-alone-001","band":"K5","grade":9,"subject":"Mathematics","concept":"why rural livelihoods are diversifying beyond farming alone","difficulty":2,"stem":"In a village, 240 households are surveyed. If 60 households earn from non-farm work, what is the ratio of non-farm households to total households in simplest form?","options":["4:1","1:3","1:4","3:1"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reverses the ratio, putting total households before non-farm households."},{"option_index":1,"misconception":"Compares non-farm households to farm households (60 to 180) instead of to total households."},{"option_index":3,"misconception":"Reverses the part-to-whole comparison, using farm households to non-farm households."}],"explanation":"60/240 = 1/4, so the ratio is 1:4.","concept_id":"eco610-rur-diversification","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-rural-livelihoods-are-diversifying-beyond-farming-alone-002","band":"K5","grade":9,"subject":"Mathematics","concept":"why rural livelihoods are diversifying beyond farming alone","difficulty":2,"stem":"In a rural block, 35% of the 400 households have dairy as an additional livelihood. How many households have dairy?","options":["35","260","175","140"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Confuses the percentage value with the actual count of households."},{"option_index":1,"misconception":"Calculates the complement (65% of 400) instead of 35% of 400."},{"option_index":2,"misconception":"Uses 35% of 500 instead of 35% of 400."}],"explanation":"35% of 400 = 0.35 × 400 = 140.","concept_id":"eco610-rur-diversification","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-rural-livelihoods-are-diversifying-beyond-farming-alone-003","band":"K5","grade":9,"subject":"Mathematics","concept":"why rural livelihoods are diversifying beyond farming alone","difficulty":2,"stem":"A farmer earns ₹18,000 from crops and ₹6,000 from poultry. What is the ratio of crop income to poultry income in simplest form?","options":["1:3","3:1","3:4","4:3"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Reverses the ratio, comparing poultry income to crop income."},{"option_index":2,"misconception":"Compares crop income to total income (18,000:24,000)."},{"option_index":3,"misconception":"Compares total income to crop income (24,000:18,000)."}],"explanation":"18,000:6,000 simplifies by 6,000 to 3:1.","concept_id":"eco610-rur-diversification","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-rural-livelihoods-are-diversifying-beyond-farming-alone-004","band":"K5","grade":9,"subject":"Mathematics","concept":"why rural livelihoods are diversifying beyond farming alone","difficulty":2,"stem":"A household's monthly income is ₹12,000. Farm income is ₹7,200, and the rest is non-farm income. What percent of the monthly income is non-farm?","options":["60%","48%","40%","52%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses the farm income share (7,200/12,000) as the non-farm share."},{"option_index":1,"misconception":"Makes a place-value error and reads ₹4,800 as 48%."},{"option_index":3,"misconception":"Subtracts the place-value error 48% from 100% instead of finding the correct non-farm share."}],"explanation":"Non-farm income = ₹12,000 − ₹7,200 = ₹4,800; 4,800/12,000 = 40%.","concept_id":"eco610-rur-diversification","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-rural-livelihoods-are-diversifying-beyond-farming-alone-005","band":"K5","grade":9,"subject":"Mathematics","concept":"why rural livelihoods are diversifying beyond farming alone","difficulty":2,"stem":"In a survey of 500 rural workers, 300 work only in farming, 120 combine farming with dairy, and 80 work only in non-farm jobs. What percentage of workers have a livelihood beyond farming alone (dairy or non-farm)?","options":["16%","24%","60%","40%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Counts only the 80 non-farm workers, ignoring those combining farming with dairy."},{"option_index":1,"misconception":"Counts only the 120 dairy workers, ignoring the non-farm workers."},{"option_index":2,"misconception":"Calculates the percentage working only in farming instead of beyond farming alone."}],"explanation":"(120 + 80)/500 = 200/500 = 40%.","concept_id":"eco610-rur-diversification","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-rural-livelihoods-are-diversifying-beyond-farming-alone-006","band":"K5","grade":9,"subject":"Mathematics","concept":"why rural livelihoods are diversifying beyond farming alone","difficulty":2,"stem":"A village's total income from all livelihoods is ₹25,00,000. Farm income is ₹15,00,000, dairy income is ₹5,00,000, and other non-farm income is ₹5,00,000. What fraction of total income comes from non-farm sources (dairy + other non-farm)?","options":["3/5","2/5","1/5","1/2"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses the farm income fraction (15,00,000/25,00,000) instead of non-farm sources."},{"option_index":2,"misconception":"Counts only one non-farm component (₹5,00,000) instead of both dairy and other non-farm."},{"option_index":3,"misconception":"Assumes non-farm and farm incomes are equal halves."}],"explanation":"(5,00,000 + 5,00,000)/25,00,000 = 10,00,000/25,00,000 = 2/5.","concept_id":"eco610-rur-diversification","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-rural-livelihoods-are-diversifying-beyond-farming-alone-007","band":"K5","grade":9,"subject":"Mathematics","concept":"why rural livelihoods are diversifying beyond farming alone","difficulty":2,"stem":"Due to crop failure, a farmer's farm income drops from ₹20,000 to ₹12,000. How much extra non-farm income is needed to keep total income at ₹20,000?","options":["₹12,000","₹20,000","₹8,000","₹32,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses the new farm income as the required non-farm income."},{"option_index":1,"misconception":"Uses the target total income as the required extra income."},{"option_index":3,"misconception":"Adds the old farm income and new farm income instead of finding the difference."}],"explanation":"Required extra = ₹20,000 − ₹12,000 = ₹8,000.","concept_id":"eco610-rur-diversification","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-rural-livelihoods-are-diversifying-beyond-farming-alone-008","band":"K5","grade":9,"subject":"Mathematics","concept":"why rural livelihoods are diversifying beyond farming alone","difficulty":2,"stem":"A rural household earns ₹24,000 per month. It spends 1/3 of its income on farming costs and 1/4 on household expenses, and saves the rest. How much does it save?","options":["₹14,000","₹10,000","₹8,000","₹6,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Adds the two spending fractions and gives total spending, not savings."},{"option_index":2,"misconception":"Gives the farming-cost amount instead of savings."},{"option_index":3,"misconception":"Gives the household-expense amount instead of savings."}],"explanation":"Farming costs = ₹8,000, household expenses = ₹6,000, so savings = ₹24,000 − ₹14,000 = ₹10,000.","concept_id":"eco610-rur-diversification","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-rural-livelihoods-are-diversifying-beyond-farming-alone-009","band":"K5","grade":9,"subject":"Mathematics","concept":"why rural livelihoods are diversifying beyond farming alone","difficulty":2,"stem":"In a village, the number of households doing non-farm work increased from 50 to 100. What is the percentage increase in non-farm households?","options":["50%","200%","150%","100%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Divides the increase (50) by the final value (100) instead of the initial value."},{"option_index":1,"misconception":"Divides the final value (100) by the initial value (50) without subtracting 1."},{"option_index":2,"misconception":"Adds the final value and the increase (100 + 50) and treats it as a percentage."}],"explanation":"Percentage increase = (100 − 50)/50 × 100 = 100%.","concept_id":"eco610-rur-diversification","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"why-rural-livelihoods-are-diversifying-beyond-farming-alone-010","band":"K5","grade":9,"subject":"Mathematics","concept":"why rural livelihoods are diversifying beyond farming alone","difficulty":2,"stem":"A cooperative has 320 members. 3/8 are in farming, 1/4 are in dairy, and the rest are in handicrafts. How many members are in handicrafts?","options":["120","200","80","160"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds the farming and dairy members (120 + 80) instead of finding the remaining members."},{"option_index":2,"misconception":"Gives the number in dairy only, not the remaining handicrafts members."},{"option_index":3,"misconception":"Assumes half the members are in handicrafts after taking the first two groups."}],"explanation":"Farming = 3/8 × 320 = 120; dairy = 1/4 × 320 = 80; handicrafts = 320 − 120 − 80 = 120.","concept_id":"eco610-rur-diversification","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"farming-as-the-main-livelihood-activity-in-rural-india-001","band":"K5","grade":9,"subject":"Mathematics","concept":"farming as the main livelihood activity in rural India","difficulty":2,"stem":"In a village, 65% of 800 households depend on farming. How many households depend on farming?","options":["480","52","520","280"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"uses 60% instead of 65% and computes 0.60 × 800"},{"option_index":1,"misconception":"misplaces the decimal and computes 65% of 80 instead of 800"},{"option_index":3,"misconception":"finds the non-farming households (35% of 800) instead of farming households"}],"explanation":"65% of 800 = 0.65 × 800 = 520.","concept_id":"eco610-rur-farming-as-livelihood","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"farming-as-the-main-livelihood-activity-in-rural-india-002","band":"K5","grade":9,"subject":"Mathematics","concept":"farming as the main livelihood activity in rural India","difficulty":2,"stem":"A farmer earns ₹18,000 per month from crops and ₹4,500 from dairy. What percent of the total monthly income comes from crops?","options":["80%","75%","20%","82%"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"compares ₹18,000 with ₹24,000 instead of the actual total ₹22,500"},{"option_index":2,"misconception":"gives the dairy share (20%) instead of the crop share"},{"option_index":3,"misconception":"misreads dairy income as ₹4,000 and computes 18,000/22,000 ≈ 82%"}],"explanation":"Total = 18,000 + 4,500 = ₹22,500; crop share = 18,000/22,500 × 100 = 80%.","concept_id":"eco610-rur-farming-as-livelihood","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"farming-as-the-main-livelihood-activity-in-rural-india-003","band":"K5","grade":9,"subject":"Mathematics","concept":"farming as the main livelihood activity in rural India","difficulty":2,"stem":"A village has 1,250 acres of land. If 68% is used for farming, how many acres are NOT used for farming?","options":["850","320","680","400"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"calculates 68% of 1,250, which is the farming land, not the non-farming land"},{"option_index":1,"misconception":"uses 32% of 1,000 instead of 32% of 1,250"},{"option_index":2,"misconception":"uses 68% of 1,000 instead of 32% of 1,250"}],"explanation":"Non-farming = 100% − 68% = 32%; 32% of 1,250 = 0.32 × 1,250 = 400.","concept_id":"eco610-rur-farming-as-livelihood","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"farming-as-the-main-livelihood-activity-in-rural-india-004","band":"K5","grade":9,"subject":"Mathematics","concept":"farming as the main livelihood activity in rural India","difficulty":2,"stem":"The average yield of 4 farms is 18 quintals. Three farms yield 15, 20, and 16 quintals. What is the yield of the fourth farm?","options":["18","21","17","51"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"assumes the missing yield equals the average"},{"option_index":2,"misconception":"averages the three given yields: 51/3 = 17"},{"option_index":3,"misconception":"gives the sum of the three given yields"}],"explanation":"Total = 4 × 18 = 72 quintals; sum of three = 51; fourth = 72 − 51 = 21 quintals.","concept_id":"eco610-rur-farming-as-livelihood","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"farming-as-the-main-livelihood-activity-in-rural-india-005","band":"K5","grade":9,"subject":"Mathematics","concept":"farming as the main livelihood activity in rural India","difficulty":2,"stem":"A farmer's wheat production increased from 1,200 kg to 1,500 kg. What is the percentage increase?","options":["20%","30%","125%","25%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"uses the new value 1,500 as the base: 300/1500 × 100"},{"option_index":1,"misconception":"uses 1,000 as the base instead of the original 1,200"},{"option_index":2,"misconception":"finds the ratio new/original (1500/1200) instead of the percentage increase"}],"explanation":"Increase = 1,500 − 1,200 = 300 kg; percentage increase = 300/1,200 × 100 = 25%.","concept_id":"eco610-rur-farming-as-livelihood","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"farming-as-the-main-livelihood-activity-in-rural-india-006","band":"K5","grade":9,"subject":"Mathematics","concept":"farming as the main livelihood activity in rural India","difficulty":2,"stem":"In a rural block, 3 out of every 5 workers are engaged in farming. If there are 2,400 workers, how many are NOT engaged in farming?","options":["960","1440","800","480"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"finds the farming workers (3/5 of 2,400) instead of non-farming workers"},{"option_index":2,"misconception":"uses 2,000 as the total and finds 2/5 of it"},{"option_index":3,"misconception":"finds only one-fifth of 2,400 instead of two-fifths"}],"explanation":"Non-farming workers = 2/5 × 2,400 = 960.","concept_id":"eco610-rur-farming-as-livelihood","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"farming-as-the-main-livelihood-activity-in-rural-india-007","band":"K5","grade":9,"subject":"Mathematics","concept":"farming as the main livelihood activity in rural India","difficulty":2,"stem":"A farmer borrows ₹25,000 at 8% simple interest per annum for 2 years to buy seeds. What is the total amount to repay?","options":["₹27,000","₹4,000","₹29,000","₹25,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"adds simple interest for only 1 year (₹2,000) to the principal"},{"option_index":1,"misconception":"gives only the interest, not the total repayment amount"},{"option_index":3,"misconception":"gives only the principal, ignoring the interest"}],"explanation":"Interest = 25000 × 8 × 2 / 100 = ₹4,000; total = 25,000 + 4,000 = ₹29,000.","concept_id":"eco610-rur-farming-as-livelihood","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"farming-as-the-main-livelihood-activity-in-rural-india-008","band":"K5","grade":9,"subject":"Mathematics","concept":"farming as the main livelihood activity in rural India","difficulty":2,"stem":"A rectangular farm is 120 m long and 80 m wide. If 25% of the area is used for a vegetable plot, what is the area of the vegetable plot?","options":["7200 m²","9600 m²","2000 m²","2400 m²"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"finds the remaining 75% of the area instead of the 25% vegetable plot"},{"option_index":1,"misconception":"gives the total area of the farm instead of 25% of it"},{"option_index":2,"misconception":"uses 100 m as the length and finds 25% of 8000 m²"}],"explanation":"Area = 120 × 80 = 9600 m²; vegetable plot = 25% of 9600 = 2400 m².","concept_id":"eco610-rur-farming-as-livelihood","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"farming-as-the-main-livelihood-activity-in-rural-india-009","band":"K5","grade":9,"subject":"Mathematics","concept":"farming as the main livelihood activity in rural India","difficulty":2,"stem":"A village has 480 farming families. This is 60% of all families. How many families are there in total?","options":["288","720","800","1200"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"finds 60% of 480 instead of finding the whole from the given part"},{"option_index":1,"misconception":"adds 50% of 480 to 480 instead of dividing by 60%"},{"option_index":3,"misconception":"divides 480 by 40% (the non-farming percent) instead of by 60%"}],"explanation":"Total families = 480 ÷ 0.60 = 800.","concept_id":"eco610-rur-farming-as-livelihood","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"farming-as-the-main-livelihood-activity-in-rural-india-010","band":"K5","grade":9,"subject":"Mathematics","concept":"farming as the main livelihood activity in rural India","difficulty":2,"stem":"A farmer sells milk at ₹40 per litre. If he sells 12.5 litres daily, how much does he earn in 7 days?","options":["₹3,000","₹3,500","₹3,750","₹4,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"multiplies by 6 days instead of 7 days"},{"option_index":2,"misconception":"multiplies by 7.5 days instead of 7 days"},{"option_index":3,"misconception":"multiplies by 8 days instead of 7 days"}],"explanation":"Daily earning = 40 × 12.5 = ₹500; in 7 days = 500 × 7 = ₹3,500.","concept_id":"eco610-rur-farming-as-livelihood","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"labour-and-capital-as-variable-inputs-combined-with-land-to-produce-output-001","band":"K5","grade":9,"subject":"Mathematics","concept":"labour and capital as variable inputs combined with land to produce output","difficulty":2,"stem":"A farm has fixed land. Its output is given by Q = 5L + 8K + 30, where L is units of labour and K is units of capital. What is Q when L = 4 and K = 3?","options":["44","77","74","104"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Forgets the fixed land contribution and adds only labour and capital."},{"option_index":1,"misconception":"Swaps the coefficients of labour and capital."},{"option_index":3,"misconception":"Adds the fixed land contribution twice."}],"explanation":"5×4 + 8×3 + 30 = 20 + 24 + 30 = 74.","concept_id":"eco610-rur-labour-capital-inputs","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"labour-and-capital-as-variable-inputs-combined-with-land-to-produce-output-002","band":"K5","grade":9,"subject":"Mathematics","concept":"labour and capital as variable inputs combined with land to produce output","difficulty":2,"stem":"Output is Q = 7L + 4K + 25, with land fixed. If labour rises from 3 to 5 units while capital stays at 5 units, by how much does output increase?","options":["8","14","22","35"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses the capital coefficient (4) for the change in labour."},{"option_index":2,"misconception":"Adds both input coefficients before multiplying by the change in labour."},{"option_index":3,"misconception":"Uses the new labour amount only, ignoring the change and the other inputs."}],"explanation":"Change in Q = 7(5−3) = 14; capital and land do not change.","concept_id":"eco610-rur-labour-capital-inputs","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"labour-and-capital-as-variable-inputs-combined-with-land-to-produce-output-003","band":"K5","grade":9,"subject":"Mathematics","concept":"labour and capital as variable inputs combined with land to produce output","difficulty":2,"stem":"Output is Q = 3L + 7K + 15, with land fixed. What is Q when L = 6 and K = 2?","options":["32","62","63","47"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Forgets the fixed land contribution."},{"option_index":1,"misconception":"Adds the fixed land contribution twice."},{"option_index":2,"misconception":"Swaps the labour and capital coefficients."}],"explanation":"3×6 + 7×2 + 15 = 18 + 14 + 15 = 47.","concept_id":"eco610-rur-labour-capital-inputs","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"labour-and-capital-as-variable-inputs-combined-with-land-to-produce-output-004","band":"K5","grade":9,"subject":"Mathematics","concept":"labour and capital as variable inputs combined with land to produce output","difficulty":2,"stem":"In the production function Q = 10L + 15K + 50, land is fixed. What number represents land's fixed contribution to output?","options":["10","15","50","25"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Mistakes the labour coefficient for the fixed land contribution."},{"option_index":1,"misconception":"Mistakes the capital coefficient for the fixed land contribution."},{"option_index":3,"misconception":"Adds the labour and capital coefficients."}],"explanation":"The constant term 50 is not multiplied by L or K, so it is the fixed land contribution.","concept_id":"eco610-rur-labour-capital-inputs","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"labour-and-capital-as-variable-inputs-combined-with-land-to-produce-output-005","band":"K5","grade":9,"subject":"Mathematics","concept":"labour and capital as variable inputs combined with land to produce output","difficulty":2,"stem":"Output is Q = 8L + 5K + 30, with land fixed. How many more units of output does one extra unit of labour add than one extra unit of capital?","options":["3","5","8","13"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Chooses the capital coefficient instead of the difference."},{"option_index":2,"misconception":"Chooses the labour coefficient instead of the difference."},{"option_index":3,"misconception":"Adds the two coefficients instead of subtracting."}],"explanation":"Labour adds 8 per unit and capital adds 5 per unit, so the difference is 8−5 = 3.","concept_id":"eco610-rur-labour-capital-inputs","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"labour-and-capital-as-variable-inputs-combined-with-land-to-produce-output-006","band":"K5","grade":9,"subject":"Mathematics","concept":"labour and capital as variable inputs combined with land to produce output","difficulty":2,"stem":"A farm has fixed land and initial output Q = 4L + 6K + 20. Initially L = 2 and K = 3. If both L and K are doubled, by how much does output increase?","options":["46","52","26","72"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Assumes the whole output, including land's contribution, doubles."},{"option_index":1,"misconception":"Reports the new variable-input part only, not the increase."},{"option_index":3,"misconception":"Reports the new total output instead of the increase."}],"explanation":"Initial Q = 8+18+20 = 46. New L=4, K=6 gives Q = 16+36+20 = 72. Increase = 72−46 = 26.","concept_id":"eco610-rur-labour-capital-inputs","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"labour-and-capital-as-variable-inputs-combined-with-land-to-produce-output-007","band":"K5","grade":9,"subject":"Mathematics","concept":"labour and capital as variable inputs combined with land to produce output","difficulty":2,"stem":"With land fixed, a farmer uses L = 3 units of labour and K = 2 units of capital. Labour costs ₹200 per unit and capital costs ₹500 per unit. What is the total variable cost?","options":["600","1000","1600","700"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Counts only labour cost and omits capital cost."},{"option_index":1,"misconception":"Counts only capital cost and omits labour cost."},{"option_index":3,"misconception":"Adds the two per-unit prices instead of multiplying by the quantities."}],"explanation":"3×200 + 2×500 = 600 + 1000 = 1600.","concept_id":"eco610-rur-labour-capital-inputs","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"labour-and-capital-as-variable-inputs-combined-with-land-to-produce-output-008","band":"K5","grade":9,"subject":"Mathematics","concept":"labour and capital as variable inputs combined with land to produce output","difficulty":2,"stem":"Output is Q = 2L + 3K + 10, with land fixed. What is Q when L = 7 and K = 4?","options":["26","36","39","46"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Forgets the fixed land contribution."},{"option_index":2,"misconception":"Swaps the labour and capital coefficients."},{"option_index":3,"misconception":"Adds the fixed land contribution twice."}],"explanation":"2×7 + 3×4 + 10 = 14 + 12 + 10 = 36.","concept_id":"eco610-rur-labour-capital-inputs","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"labour-and-capital-as-variable-inputs-combined-with-land-to-produce-output-009","band":"K5","grade":9,"subject":"Mathematics","concept":"labour and capital as variable inputs combined with land to produce output","difficulty":2,"stem":"Output is Q = 4L + 6K + 20, with land fixed. If K = 2 and Q = 52, what is L?","options":["4","8","10","5"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Swaps the coefficients of labour and capital while solving."},{"option_index":1,"misconception":"Ignores the capital contribution."},{"option_index":2,"misconception":"Ignores the fixed land contribution."}],"explanation":"4L + 6×2 + 20 = 52, so 4L + 32 = 52, L = 5.","concept_id":"eco610-rur-labour-capital-inputs","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"labour-and-capital-as-variable-inputs-combined-with-land-to-produce-output-010","band":"K5","grade":9,"subject":"Mathematics","concept":"labour and capital as variable inputs combined with land to produce output","difficulty":2,"stem":"Output is Q = 12L + 9K + 40, with land fixed. What is Q when no labour and no capital are used (L = 0, K = 0)?","options":["0","9","12","40"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Thinks output must be zero when variable inputs are zero, ignoring fixed land."},{"option_index":1,"misconception":"Mistakes the capital coefficient for land's fixed contribution."},{"option_index":2,"misconception":"Mistakes the labour coefficient for land's fixed contribution."}],"explanation":"Putting L = 0 and K = 0 leaves Q = 40, the fixed land contribution.","concept_id":"eco610-rur-labour-capital-inputs","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"land-as-a-fixed-natural-resource-input-to-farm-production-001","band":"K5","grade":9,"subject":"Mathematics","concept":"land as a fixed natural resource input to farm production","difficulty":2,"stem":"A farm has a fixed area of 6 hectares. The farmer uses 300 kg of seed in total, spread equally. How much seed is used per hectare?","options":["300 kg","50 kg","1800 kg","6 kg"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Reports the total seed used as the per-hectare seed amount."},{"option_index":2,"misconception":"Multiplies total seed by land area instead of dividing."},{"option_index":3,"misconception":"Uses the fixed land area in hectares as the per-hectare seed amount."}],"explanation":"300 kg ÷ 6 hectares = 50 kg per hectare.","concept_id":"eco610-rur-land-as-resource","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"land-as-a-fixed-natural-resource-input-to-farm-production-002","band":"K5","grade":9,"subject":"Mathematics","concept":"land as a fixed natural resource input to farm production","difficulty":2,"stem":"On a fixed 12-acre plot, 4 workers produce 600 bushels of wheat. What is the output per worker?","options":["600 bushels","50 bushels","150 bushels","2400 bushels"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reports total output instead of output per worker."},{"option_index":1,"misconception":"Divides output by acres, confusing land with labour."},{"option_index":3,"misconception":"Multiplies output by workers instead of dividing."}],"explanation":"600 bushels ÷ 4 workers = 150 bushels per worker.","concept_id":"eco610-rur-land-as-resource","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"land-as-a-fixed-natural-resource-input-to-farm-production-003","band":"K5","grade":9,"subject":"Mathematics","concept":"land as a fixed natural resource input to farm production","difficulty":2,"stem":"A field has a fixed area of 20 hectares. Each hectare yields 4 tonnes of rice. What is the total rice production?","options":["80 tonnes","5 tonnes","24 tonnes","16 tonnes"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Divides land area by yield instead of multiplying."},{"option_index":2,"misconception":"Adds land area and yield."},{"option_index":3,"misconception":"Subtracts yield from land area."}],"explanation":"20 hectares × 4 tonnes per hectare = 80 tonnes.","concept_id":"eco610-rur-land-as-resource","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"land-as-a-fixed-natural-resource-input-to-farm-production-004","band":"K5","grade":9,"subject":"Mathematics","concept":"land as a fixed natural resource input to farm production","difficulty":2,"stem":"A farmer owns a fixed 40 acres of land. He plants wheat on 10 acres. What percentage of his fixed land is used for wheat?","options":["10%","40%","75%","25%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Writes the used acres as a percent."},{"option_index":1,"misconception":"Writes the total acres as a percent."},{"option_index":2,"misconception":"Computes the unused land percentage (30/40 = 75%)."}],"explanation":"10 ÷ 40 × 100 = 25%.","concept_id":"eco610-rur-land-as-resource","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"land-as-a-fixed-natural-resource-input-to-farm-production-005","band":"K5","grade":9,"subject":"Mathematics","concept":"land as a fixed natural resource input to farm production","difficulty":2,"stem":"A fixed 5-hectare farm gives 100 tonnes of output with 1 worker. With 2 workers on the same land, output rises to 180 tonnes. What is the marginal output added by the second worker?","options":["100 tonnes","80 tonnes","180 tonnes","90 tonnes"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Gives the first worker's output, not the addition from the second worker."},{"option_index":2,"misconception":"Gives the total output with two workers, not the marginal output."},{"option_index":3,"misconception":"Gives the average output per worker (180 ÷ 2 = 90), confusing marginal with average."}],"explanation":"180 tonnes − 100 tonnes = 80 tonnes added by the second worker.","concept_id":"eco610-rur-land-as-resource","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"land-as-a-fixed-natural-resource-input-to-farm-production-006","band":"K5","grade":9,"subject":"Mathematics","concept":"land as a fixed natural resource input to farm production","difficulty":2,"stem":"Land in a village is fixed at 1,200 hectares. It is divided equally among 80 farmers. How much land does each farmer get?","options":["1,200 hectares","96,000 hectares","80 hectares","15 hectares"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Reports the total fixed land as each farmer's share."},{"option_index":1,"misconception":"Multiplies farmers by hectares instead of dividing."},{"option_index":2,"misconception":"Confuses the number of farmers with hectares per farmer."}],"explanation":"1,200 hectares ÷ 80 farmers = 15 hectares per farmer.","concept_id":"eco610-rur-land-as-resource","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"land-as-a-fixed-natural-resource-input-to-farm-production-007","band":"K5","grade":9,"subject":"Mathematics","concept":"land as a fixed natural resource input to farm production","difficulty":2,"stem":"A fixed 25-acre farm has 20% of its land unusable for crops. How many acres are usable?","options":["20 acres","5 acres","25 acres","30 acres"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Gives the unusable area (20% of 25 = 5) instead of the usable area."},{"option_index":2,"misconception":"Ignores the unusable part and reports total land."},{"option_index":3,"misconception":"Adds 20% of 25 to 25 instead of subtracting."}],"explanation":"25 − 20% of 25 = 25 − 5 = 20 acres usable.","concept_id":"eco610-rur-land-as-resource","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"land-as-a-fixed-natural-resource-input-to-farm-production-008","band":"K5","grade":9,"subject":"Mathematics","concept":"land as a fixed natural resource input to farm production","difficulty":2,"stem":"Two fixed 10-hectare plots are treated with fertilizer. Plot A uses 200 kg and Plot B uses 250 kg. How much more fertilizer per hectare does Plot B use than Plot A?","options":["5 kg per hectare","50 kg per hectare","20 kg per hectare","25 kg per hectare"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Subtracts totals (250 − 200 = 50) and calls it per hectare."},{"option_index":2,"misconception":"Gives Plot A's fertilizer per hectare (200 ÷ 10 = 20)."},{"option_index":3,"misconception":"Gives Plot B's fertilizer per hectare (250 ÷ 10 = 25)."}],"explanation":"(250 − 200) ÷ 10 = 5 kg per hectare more.","concept_id":"eco610-rur-land-as-resource","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"land-as-a-fixed-natural-resource-input-to-farm-production-009","band":"K5","grade":9,"subject":"Mathematics","concept":"land as a fixed natural resource input to farm production","difficulty":2,"stem":"A farm's land is fixed at 8 hectares. If the farmer uses 48 kg of pesticide per hectare, how much pesticide is needed in total?","options":["6 kg","56 kg","384 kg","40 kg"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Divides land area by per-hectare amount instead of multiplying."},{"option_index":1,"misconception":"Adds land area and per-hectare amount."},{"option_index":3,"misconception":"Subtracts land area from per-hectare amount."}],"explanation":"8 hectares × 48 kg per hectare = 384 kg.","concept_id":"eco610-rur-land-as-resource","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"land-as-a-fixed-natural-resource-input-to-farm-production-010","band":"K5","grade":9,"subject":"Mathematics","concept":"land as a fixed natural resource input to farm production","difficulty":2,"stem":"A fixed 20-hectare farm currently produces 500 tonnes of wheat. To produce 750 tonnes on the same fixed land, what must be the new yield per hectare?","options":["25 tonnes per hectare","12.5 tonnes per hectare","37.5 tonnes per hectare","750 tonnes per hectare"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Gives the current yield per hectare (500 ÷ 20 = 25), not the new yield."},{"option_index":1,"misconception":"Gives the extra yield per hectare needed (250 ÷ 20 = 12.5), not the total new yield."},{"option_index":3,"misconception":"Gives the target total output as a per-hectare yield."}],"explanation":"750 tonnes ÷ 20 hectares = 37.5 tonnes per hectare.","concept_id":"eco610-rur-land-as-resource","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"non-farm-activities-in-rural-areas-dairy-small-scale-manufacturing-and-services-001","band":"K5","grade":9,"subject":"Mathematics","concept":"non-farm activities in rural areas: dairy, small-scale manufacturing and services","difficulty":2,"stem":"A dairy cooperative collects milk from 24 farmers. If each farmer gives 12 1/2 litres of milk per day, how many litres of milk are collected in one day?","options":["288 litres","300 litres","312 litres","240 litres"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Ignores the 1/2 litre and uses 12 litres per farmer, giving 24×12=288."},{"option_index":2,"misconception":"Rounds each farmer's 12 1/2 litres up to 13 litres, giving 24×13=312."},{"option_index":3,"misconception":"Uses 10 litres per farmer instead of 12 1/2, giving 24×10=240."}],"explanation":"24×12 1/2 = 24×12 + 24×1/2 = 288 + 12 = 300 litres.","concept_id":"eco610-rur-non-farm-activities","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"non-farm-activities-in-rural-areas-dairy-small-scale-manufacturing-and-services-002","band":"K5","grade":9,"subject":"Mathematics","concept":"non-farm activities in rural areas: dairy, small-scale manufacturing and services","difficulty":2,"stem":"A small-scale pottery unit makes 85 clay lamps in a day. It packs them in boxes of 12. How many full boxes can be packed from one day's production?","options":["6 boxes","8 boxes","84 boxes","7 boxes"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Subtracts one full box because there is a leftover lamp, instead of using the 7 complete boxes."},{"option_index":1,"misconception":"Rounds 85÷12 up to 8, ignoring that the 8th box would not be full."},{"option_index":2,"misconception":"Confuses the 84 lamps packed in 7 full boxes with the number of boxes."}],"explanation":"85÷12 = 7 remainder 1, so 7 full boxes can be packed.","concept_id":"eco610-rur-non-farm-activities","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"non-farm-activities-in-rural-areas-dairy-small-scale-manufacturing-and-services-003","band":"K5","grade":9,"subject":"Mathematics","concept":"non-farm activities in rural areas: dairy, small-scale manufacturing and services","difficulty":2,"stem":"A rural repair service earns ₹1,250 per day. How much does it earn in 30 days?","options":["₹3,750","₹36,000","₹37,500","₹1,280"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Misplaces the decimal/zero and gives one-tenth of the correct amount."},{"option_index":1,"misconception":"Rounds ₹1,250 to ₹1,200 before multiplying by 30."},{"option_index":3,"misconception":"Adds 30 to ₹1,250 instead of multiplying."}],"explanation":"1,250×30 = 37,500 rupees.","concept_id":"eco610-rur-non-farm-activities","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"non-farm-activities-in-rural-areas-dairy-small-scale-manufacturing-and-services-004","band":"K5","grade":9,"subject":"Mathematics","concept":"non-farm activities in rural areas: dairy, small-scale manufacturing and services","difficulty":2,"stem":"A dairy farmer has 48 cows. Each cow gives 7 1/2 litres of milk per day. How many litres of milk does the farmer get in one day?","options":["360 litres","336 litres","348 litres","384 litres"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses 7 litres per cow and ignores the 1/2 litre, giving 48×7=336."},{"option_index":2,"misconception":"Treats 1/2 litre as 1/4 litre, giving 48×7 + 48/4 = 348."},{"option_index":3,"misconception":"Rounds each cow's yield up to 8 litres, giving 48×8=384."}],"explanation":"48×7 1/2 = 48×7 + 48×1/2 = 336 + 24 = 360 litres.","concept_id":"eco610-rur-non-farm-activities","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"non-farm-activities-in-rural-areas-dairy-small-scale-manufacturing-and-services-005","band":"K5","grade":9,"subject":"Mathematics","concept":"non-farm activities in rural areas: dairy, small-scale manufacturing and services","difficulty":2,"stem":"A small-scale unit packs 3/4 kg of handmade soap in each box. How many full boxes can be made from 15 kg of soap?","options":["11 boxes","12 boxes","15 boxes","20 boxes"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Multiplies 15 by 3/4 to get 11.25 and then floors it to 11."},{"option_index":1,"misconception":"Multiplies 15 by 3/4 to get 11.25 and rounds it up to 12."},{"option_index":2,"misconception":"Assumes each box uses 1 kg of soap instead of 3/4 kg."}],"explanation":"15 ÷ 3/4 = 15 × 4/3 = 20 full boxes.","concept_id":"eco610-rur-non-farm-activities","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"non-farm-activities-in-rural-areas-dairy-small-scale-manufacturing-and-services-006","band":"K5","grade":9,"subject":"Mathematics","concept":"non-farm activities in rural areas: dairy, small-scale manufacturing and services","difficulty":2,"stem":"A rural handicraft centre has 18 artisans. Each artisan makes 24 baskets in a week. How many baskets do all the artisans make in a week?","options":["432 baskets","42 baskets","216 baskets","400 baskets"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds 18 and 24 instead of multiplying."},{"option_index":2,"misconception":"Uses half the artisans (9 instead of 18), giving 9×24 = 216."},{"option_index":3,"misconception":"Rounds both numbers to 20 and multiplies, giving 20×20 = 400."}],"explanation":"18×24 = 432 baskets.","concept_id":"eco610-rur-non-farm-activities","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"non-farm-activities-in-rural-areas-dairy-small-scale-manufacturing-and-services-007","band":"K5","grade":9,"subject":"Mathematics","concept":"non-farm activities in rural areas: dairy, small-scale manufacturing and services","difficulty":2,"stem":"A dairy cooperative sells milk at ₹42 per litre. If it sells 125 litres in a day, how much money does it get that day?","options":["₹525","₹4,200","₹5,000","₹5,250"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Misplaces the decimal and gives one-tenth of the correct amount."},{"option_index":1,"misconception":"Uses 100 litres instead of 125 litres, giving 42×100 = 4,200."},{"option_index":2,"misconception":"Rounds ₹42 down to ₹40 and then multiplies by 125, giving 5,000."}],"explanation":"42×125 = 5,250 rupees.","concept_id":"eco610-rur-non-farm-activities","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"non-farm-activities-in-rural-areas-dairy-small-scale-manufacturing-and-services-008","band":"K5","grade":9,"subject":"Mathematics","concept":"non-farm activities in rural areas: dairy, small-scale manufacturing and services","difficulty":2,"stem":"A small-scale unit makes 1,250 candles. It packs 25 candles in each packet. How many packets are made?","options":["5 packets","50 packets","63 packets","31,250 packets"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Misplaces a zero and divides by 250 instead of 25."},{"option_index":2,"misconception":"Uses 20 candles per packet to get 62.5 and then rounds up to 63."},{"option_index":3,"misconception":"Multiplies 1,250 by 25 instead of dividing."}],"explanation":"1,250÷25 = 50 packets.","concept_id":"eco610-rur-non-farm-activities","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"non-farm-activities-in-rural-areas-dairy-small-scale-manufacturing-and-services-009","band":"K5","grade":9,"subject":"Mathematics","concept":"non-farm activities in rural areas: dairy, small-scale manufacturing and services","difficulty":2,"stem":"A rural service provider charges ₹350 for repairing a pump. In a month he repairs 28 pumps. His other expenses for the month are ₹1,200. What is his profit?","options":["₹7,400","₹9,800","₹8,600","₹11,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Subtracts ₹2,400 (double the expenses) instead of ₹1,200."},{"option_index":1,"misconception":"Forgets to subtract the expenses and gives only the total earning."},{"option_index":3,"misconception":"Adds the expenses instead of subtracting them."}],"explanation":"Total earning = 350×28 = 9,800; profit = 9,800 - 1,200 = 8,600 rupees.","concept_id":"eco610-rur-non-farm-activities","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"non-farm-activities-in-rural-areas-dairy-small-scale-manufacturing-and-services-010","band":"K5","grade":9,"subject":"Mathematics","concept":"non-farm activities in rural areas: dairy, small-scale manufacturing and services","difficulty":2,"stem":"A dairy farmer uses 2/5 of the milk to make curd and 1/4 of the milk to make butter. What fraction of the milk remains?","options":["3/20","13/20","17/20","7/20"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Subtracts 1/4 from 2/5 and treats the difference 3/20 as the remaining fraction."},{"option_index":1,"misconception":"Adds the used fractions and stops at 13/20 instead of subtracting from 1."},{"option_index":2,"misconception":"Subtracts only the difference 3/20 from 1, giving 17/20."}],"explanation":"Used fraction = 2/5 + 1/4 = 13/20, so remaining = 1 - 13/20 = 7/20.","concept_id":"eco610-rur-non-farm-activities","strand":"Rural Livelihoods and Agriculture","kind":"mcq"},{"id":"how-the-three-sectors-of-the-economy-differ-in-what-they-produce-001","band":"K5","grade":10,"subject":"Mathematics","concept":"how the three sectors of the economy differ in what they produce","difficulty":2,"stem":"A village has 60 workers. 24 work in farming, 16 work in a cloth factory, and 20 work in shops. How many workers are in the sector that produces manufactured goods?","options":["24","16","20","40"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Confuses primary sector (farming raw materials) with secondary sector (manufacturing)."},{"option_index":2,"misconception":"Confuses tertiary sector (shops/services) with secondary sector."},{"option_index":3,"misconception":"Adds primary and secondary workers, thinking secondary includes raw material production."}],"explanation":"Cloth factory work is secondary-sector manufacturing, so 16 workers are counted.","concept_id":"eco610-sec-comparing-three","strand":"Sectors of the Economy","kind":"mcq"},{"id":"how-the-three-sectors-of-the-economy-differ-in-what-they-produce-002","band":"K5","grade":10,"subject":"Mathematics","concept":"how the three sectors of the economy differ in what they produce","difficulty":2,"stem":"In a town, 45 people extract raw materials, 30 process them in factories, and 75 provide services. How many people work in the tertiary sector?","options":["30","45","75","150"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Confuses secondary-sector processing with tertiary-sector services."},{"option_index":1,"misconception":"Confuses primary-sector extraction with tertiary-sector services."},{"option_index":3,"misconception":"Adds all sectors, thinking the tertiary sector is the total workforce."}],"explanation":"Providing services is tertiary-sector work, so 75 people are in the tertiary sector.","concept_id":"eco610-sec-comparing-three","strand":"Sectors of the Economy","kind":"mcq"},{"id":"how-the-three-sectors-of-the-economy-differ-in-what-they-produce-003","band":"K5","grade":10,"subject":"Mathematics","concept":"how the three sectors of the economy differ in what they produce","difficulty":2,"stem":"A country's workforce of 200 is divided as: 50 in mining, 70 in manufacturing, 80 in banking. What fraction of the workforce is in the primary sector? Simplify.","options":["1/4","7/20","2/5","3/5"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses secondary-sector manufacturing (70/200) instead of primary-sector mining."},{"option_index":2,"misconception":"Uses tertiary-sector banking (80/200) instead of primary-sector mining."},{"option_index":3,"misconception":"Adds primary and secondary workers (120/200), thinking primary includes manufacturing."}],"explanation":"Primary-sector workers are 50 miners, so the fraction is 50/200 = 1/4.","concept_id":"eco610-sec-comparing-three","strand":"Sectors of the Economy","kind":"mcq"},{"id":"how-the-three-sectors-of-the-economy-differ-in-what-they-produce-004","band":"K5","grade":10,"subject":"Mathematics","concept":"how the three sectors of the economy differ in what they produce","difficulty":2,"stem":"A survey shows 25% of workers grow crops, 40% make goods in factories, and the rest provide services. What percent of workers are in the tertiary sector?","options":["25%","40%","65%","35%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Takes the primary-sector percentage as the tertiary-sector percentage."},{"option_index":1,"misconception":"Takes the secondary-sector percentage as the tertiary-sector percentage."},{"option_index":2,"misconception":"Adds primary and secondary percentages, thinking tertiary is the sum of the other two."}],"explanation":"Tertiary percent is 100% − 25% − 40% = 35%.","concept_id":"eco610-sec-comparing-three","strand":"Sectors of the Economy","kind":"mcq"},{"id":"how-the-three-sectors-of-the-economy-differ-in-what-they-produce-005","band":"K5","grade":10,"subject":"Mathematics","concept":"how the three sectors of the economy differ in what they produce","difficulty":2,"stem":"In a state, 120 workers are in the primary sector, 90 in the secondary sector, and 150 in the tertiary sector. How many more workers are in the tertiary sector than in the secondary sector?","options":["30","90","150","60"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Subtracts secondary from primary (120−90) instead of tertiary from secondary."},{"option_index":1,"misconception":"Gives the secondary-sector count instead of the difference asked."},{"option_index":2,"misconception":"Gives the tertiary-sector count instead of the difference asked."}],"explanation":"The difference is 150 − 90 = 60 workers.","concept_id":"eco610-sec-comparing-three","strand":"Sectors of the Economy","kind":"mcq"},{"id":"how-the-three-sectors-of-the-economy-differ-in-what-they-produce-006","band":"K5","grade":10,"subject":"Mathematics","concept":"how the three sectors of the economy differ in what they produce","difficulty":2,"stem":"A factory employs 80 workers. 20 extract raw materials, 35 manufacture goods, and 25 provide services. What fraction of workers are in the secondary sector? Simplify.","options":["1/4","5/16","11/16","7/16"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Uses primary-sector raw material extraction (20/80) instead of secondary-sector manufacturing."},{"option_index":1,"misconception":"Uses tertiary-sector services (25/80) instead of secondary-sector manufacturing."},{"option_index":2,"misconception":"Adds primary and secondary workers (55/80), thinking secondary includes raw material extraction."}],"explanation":"Secondary-sector workers are 35 manufacturers, so the fraction is 35/80 = 7/16.","concept_id":"eco610-sec-comparing-three","strand":"Sectors of the Economy","kind":"mcq"},{"id":"how-the-three-sectors-of-the-economy-differ-in-what-they-produce-007","band":"K5","grade":10,"subject":"Mathematics","concept":"how the three sectors of the economy differ in what they produce","difficulty":2,"stem":"In an economy, the primary sector produces 400 units, the secondary sector produces 300 units, and the tertiary sector produces 500 units. What is the ratio of secondary sector production to tertiary sector production, in simplest form?","options":["3:5","5:3","4:5","3:8"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Reverses the ratio, giving tertiary:secondary instead of secondary:tertiary."},{"option_index":2,"misconception":"Uses primary:tertiary (400:500) instead of secondary:tertiary."},{"option_index":3,"misconception":"Compares secondary to primary+tertiary (300:800), thinking tertiary includes primary."}],"explanation":"Secondary:tertiary = 300:500 = 3:5.","concept_id":"eco610-sec-comparing-three","strand":"Sectors of the Economy","kind":"mcq"},{"id":"how-the-three-sectors-of-the-economy-differ-in-what-they-produce-008","band":"K5","grade":10,"subject":"Mathematics","concept":"how the three sectors of the economy differ in what they produce","difficulty":2,"stem":"A village has 180 workers. 60 work in agriculture, 45 in small-scale manufacturing, and 75 in transport and trade. What fraction of workers are in the primary sector? Simplify.","options":["1/4","1/3","5/12","3/5"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Uses secondary-sector manufacturing (45/180) instead of primary-sector agriculture."},{"option_index":2,"misconception":"Uses tertiary-sector transport and trade (75/180) instead of primary-sector agriculture."},{"option_index":3,"misconception":"Confuses 60 primary workers with 60% and writes it as 3/5."}],"explanation":"Primary-sector workers are 60 farmers, so the fraction is 60/180 = 1/3.","concept_id":"eco610-sec-comparing-three","strand":"Sectors of the Economy","kind":"mcq"},{"id":"how-the-three-sectors-of-the-economy-differ-in-what-they-produce-009","band":"K5","grade":10,"subject":"Mathematics","concept":"how the three sectors of the economy differ in what they produce","difficulty":2,"stem":"A country's GDP is divided: primary 20%, secondary 30%, tertiary 50%. If the total GDP is ₹800 crore, what is the value produced by the secondary sector?","options":["₹160 crore","₹400 crore","₹560 crore","₹240 crore"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Uses the 20% primary share instead of the 30% secondary share."},{"option_index":1,"misconception":"Uses the 50% tertiary share instead of the 30% secondary share."},{"option_index":2,"misconception":"Computes 70% (primary+tertiary) or 800−240, thinking secondary is the remainder."}],"explanation":"Secondary value is 30% of ₹800 crore = ₹240 crore.","concept_id":"eco610-sec-comparing-three","strand":"Sectors of the Economy","kind":"mcq"},{"id":"how-the-three-sectors-of-the-economy-differ-in-what-they-produce-010","band":"K5","grade":10,"subject":"Mathematics","concept":"how the three sectors of the economy differ in what they produce","difficulty":2,"stem":"An economy has 500 workers. 150 are in the primary sector, 200 in the secondary sector, and 150 in the tertiary sector. How many workers are in the sectors that produce goods (primary and secondary together)?","options":["150","200","350","500"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Counts only the primary sector."},{"option_index":1,"misconception":"Counts only the secondary sector."},{"option_index":3,"misconception":"Counts all workers including tertiary, confusing goods-producing sectors with all sectors."}],"explanation":"Goods-producing sectors are primary and secondary: 150 + 200 = 350 workers.","concept_id":"eco610-sec-comparing-three","strand":"Sectors of the Economy","kind":"mcq"},{"id":"gross-domestic-product-as-the-value-of-all-final-goods-and-services-produced-in-a-year-001","band":"K5","grade":10,"subject":"Mathematics","concept":"Gross Domestic Product as the value of all final goods and services produced in a year","difficulty":2,"stem":"A factory sells final goods worth ₹500 crore in a year. It used intermediate goods worth ₹200 crore. What is the value of final goods to be included in GDP?","options":["₹300 crore","₹500 crore","₹700 crore","₹200 crore"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Subtracts intermediate goods from final output, confusing value added with final output."},{"option_index":2,"misconception":"Adds intermediate goods to final output, double counting them."},{"option_index":3,"misconception":"Counts only intermediate goods, ignoring final output."}],"explanation":"GDP includes final goods and services only, so ₹500 crore is counted.","concept_id":"eco610-sec-gdp","strand":"Sectors of the Economy","kind":"mcq"},{"id":"gross-domestic-product-as-the-value-of-all-final-goods-and-services-produced-in-a-year-002","band":"K5","grade":10,"subject":"Mathematics","concept":"Gross Domestic Product as the value of all final goods and services produced in a year","difficulty":2,"stem":"Final goods and services produced within a country's domestic territory in a year are worth ₹920 crore. Foreign companies produce ₹120 crore of this within the country, and domestic companies produce ₹150 crore abroad. What is the country's GDP?","options":["₹920 crore","₹950 crore","₹800 crore","₹1,070 crore"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds net factor income from abroad, giving GNP instead of GDP."},{"option_index":2,"misconception":"Excludes production by foreign companies inside the domestic territory."},{"option_index":3,"misconception":"Adds production abroad to domestic production, confusing GDP with GNP."}],"explanation":"GDP includes all production inside domestic territory, regardless of ownership, so ₹920 crore.","concept_id":"eco610-sec-gdp","strand":"Sectors of the Economy","kind":"mcq"},{"id":"gross-domestic-product-as-the-value-of-all-final-goods-and-services-produced-in-a-year-003","band":"K5","grade":10,"subject":"Mathematics","concept":"Gross Domestic Product as the value of all final goods and services produced in a year","difficulty":2,"stem":"For an economy: Consumption = ₹400 crore, Investment = ₹150 crore, Government spending = ₹100 crore, Exports = ₹80 crore, Imports = ₹120 crore. Using GDP = C + I + G + (X - M), find GDP.","options":["₹650 crore","₹850 crore","₹610 crore","₹690 crore"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Ignores net exports, using only C + I + G."},{"option_index":1,"misconception":"Adds both exports and imports instead of subtracting imports."},{"option_index":3,"misconception":"Subtracts exports and adds imports, reversing the trade balance."}],"explanation":"GDP = 400 + 150 + 100 + (80 - 120) = ₹610 crore.","concept_id":"eco610-sec-gdp","strand":"Sectors of the Economy","kind":"mcq"},{"id":"gross-domestic-product-as-the-value-of-all-final-goods-and-services-produced-in-a-year-004","band":"K5","grade":10,"subject":"Mathematics","concept":"Gross Domestic Product as the value of all final goods and services produced in a year","difficulty":2,"stem":"A farmer sells wheat to a mill for ₹200. The mill sells flour to a bakery for ₹350. The bakery sells bread to consumers for ₹500. What is the contribution to GDP as the value of final goods?","options":["₹1,050","₹350","₹150","₹500"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Sums all intermediate and final sales, double counting the wheat and flour."},{"option_index":1,"misconception":"Counts an intermediate good (flour) instead of the final good."},{"option_index":2,"misconception":"Counts only the bakery's value added, not the total value of final output."}],"explanation":"GDP counts the final good only, so bread's value ₹500 is included.","concept_id":"eco610-sec-gdp","strand":"Sectors of the Economy","kind":"mcq"},{"id":"gross-domestic-product-as-the-value-of-all-final-goods-and-services-produced-in-a-year-005","band":"K5","grade":10,"subject":"Mathematics","concept":"Gross Domestic Product as the value of all final goods and services produced in a year","difficulty":2,"stem":"In a year, a country produces final goods worth ₹600 crore and final services worth ₹400 crore. It also produces intermediate goods worth ₹250 crore. What is its GDP?","options":["₹1,250 crore","₹1,000 crore","₹750 crore","₹600 crore"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Adds intermediate goods to final goods and services, double counting."},{"option_index":2,"misconception":"Subtracts intermediate goods from final output."},{"option_index":3,"misconception":"Counts only final goods and ignores final services."}],"explanation":"GDP = final goods + final services = 600 + 400 = ₹1,000 crore.","concept_id":"eco610-sec-gdp","strand":"Sectors of the Economy","kind":"mcq"},{"id":"gross-domestic-product-as-the-value-of-all-final-goods-and-services-produced-in-a-year-006","band":"K5","grade":10,"subject":"Mathematics","concept":"Gross Domestic Product as the value of all final goods and services produced in a year","difficulty":2,"stem":"A new car is produced in 2023 for ₹8 lakh. In 2024, it is resold for ₹6 lakh. How much of the 2024 resale is counted in 2024 GDP?","options":["₹6 lakh","₹8 lakh","₹0","₹2 lakh"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Counts the second-hand sale as current production."},{"option_index":1,"misconception":"Counts the original production value again in the resale year."},{"option_index":3,"misconception":"Counts the price difference as if it were newly produced value."}],"explanation":"Second-hand sales are not current production, so ₹0 is counted in 2024 GDP.","concept_id":"eco610-sec-gdp","strand":"Sectors of the Economy","kind":"mcq"},{"id":"gross-domestic-product-as-the-value-of-all-final-goods-and-services-produced-in-a-year-007","band":"K5","grade":10,"subject":"Mathematics","concept":"Gross Domestic Product as the value of all final goods and services produced in a year","difficulty":2,"stem":"A country produces final goods and services worth ₹1,200 crore in a year. It also sells shares worth ₹300 crore and old furniture worth ₹80 crore. What is its GDP?","options":["₹1,200 crore","₹1,580 crore","₹1,500 crore","₹1,280 crore"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Adds all sales including financial assets and second-hand goods."},{"option_index":2,"misconception":"Adds the sale of financial assets to GDP."},{"option_index":3,"misconception":"Adds the sale of second-hand goods to GDP."}],"explanation":"GDP includes only current final production, so it remains ₹1,200 crore.","concept_id":"eco610-sec-gdp","strand":"Sectors of the Economy","kind":"mcq"},{"id":"gross-domestic-product-as-the-value-of-all-final-goods-and-services-produced-in-a-year-008","band":"K5","grade":10,"subject":"Mathematics","concept":"Gross Domestic Product as the value of all final goods and services produced in a year","difficulty":2,"stem":"A company produces 1,000 cars in 2024. It sells 800 cars at ₹5 lakh each; the remaining 200 cars are added to inventory. What value of car production is included in 2024 GDP?","options":["₹40 crore","₹10 crore","₹50 crore","₹90 crore"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Counts only the cars sold, ignoring inventory investment."},{"option_index":1,"misconception":"Counts only the unsold inventory, ignoring sales."},{"option_index":3,"misconception":"Adds the value of sold cars and produced cars, double counting."}],"explanation":"GDP includes all cars produced: 1,000 × ₹5 lakh = ₹50 crore.","concept_id":"eco610-sec-gdp","strand":"Sectors of the Economy","kind":"mcq"},{"id":"gross-domestic-product-as-the-value-of-all-final-goods-and-services-produced-in-a-year-009","band":"K5","grade":10,"subject":"Mathematics","concept":"Gross Domestic Product as the value of all final goods and services produced in a year","difficulty":2,"stem":"A government pays pensions of ₹50 crore and produces final services worth ₹200 crore in a year. What is the government's contribution to GDP?","options":["₹250 crore","₹150 crore","₹200 crore","₹50 crore"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Adds transfer payments like pensions to GDP."},{"option_index":1,"misconception":"Subtracts transfer payments from production."},{"option_index":3,"misconception":"Counts only the pension transfer as production."}],"explanation":"Pensions are transfer payments, not production, so only ₹200 crore is included.","concept_id":"eco610-sec-gdp","strand":"Sectors of the Economy","kind":"mcq"},{"id":"gross-domestic-product-as-the-value-of-all-final-goods-and-services-produced-in-a-year-010","band":"K5","grade":10,"subject":"Mathematics","concept":"Gross Domestic Product as the value of all final goods and services produced in a year","difficulty":2,"stem":"A country's GNP is ₹950 crore. Net factor income from abroad is ₹50 crore. What is its GDP?","options":["₹1,000 crore","₹850 crore","₹50 crore","₹900 crore"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Adds net factor income from abroad to GNP instead of subtracting."},{"option_index":1,"misconception":"Subtracts twice the net factor income from abroad."},{"option_index":2,"misconception":"Counts only the net factor income from abroad."}],"explanation":"GDP = GNP - net factor income from abroad = 950 - 50 = ₹900 crore.","concept_id":"eco610-sec-gdp","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-government-undertakes-public-sector-activities-for-collective-welfare-001","band":"K5","grade":10,"subject":"Mathematics","concept":"why government undertakes public sector activities for collective welfare","difficulty":2,"stem":"A district government builds a public park because private firms will not provide it for collective welfare. The total cost is ₹12,00,000, shared equally by 40,000 residents. What is the cost per resident?","options":["₹3","₹300","₹30","₹3,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Cancels zeros incorrectly, dividing by 4,00,000 instead of 40,000, making the quotient 10 times too small."},{"option_index":1,"misconception":"Divides by 4,000 instead of 40,000, making the quotient 10 times too large."},{"option_index":3,"misconception":"Divides by 400 instead of 40,000, making the quotient 100 times too large."}],"explanation":"12,00,000 ÷ 40,000 = 30, so the shared cost is ₹30 per resident.","concept_id":"eco610-sec-govt-role-public","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-government-undertakes-public-sector-activities-for-collective-welfare-002","band":"K5","grade":10,"subject":"Mathematics","concept":"why government undertakes public sector activities for collective welfare","difficulty":2,"stem":"A village of 1,200 people needs street lights, a public good that private sellers cannot easily charge for. The total cost is ₹2,40,000. If the government funds it equally, what is the cost per person?","options":["₹200","₹20","₹2,000","₹240"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Divides by 12,000 instead of 1,200, a zero error one place to the left."},{"option_index":2,"misconception":"Divides by 120 instead of 1,200, a zero error one place to the right."},{"option_index":3,"misconception":"Uses 1,000 as the divisor instead of 1,200."}],"explanation":"2,40,000 ÷ 1,200 = 200, so the average cost is ₹200 per person.","concept_id":"eco610-sec-govt-role-public","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-government-undertakes-public-sector-activities-for-collective-welfare-003","band":"K5","grade":10,"subject":"Mathematics","concept":"why government undertakes public sector activities for collective welfare","difficulty":2,"stem":"The government gives a subsidy of ₹45,00,000 to 90 small farmers for collective welfare. How much does each farmer receive?","options":["₹5,000","₹5,00,000","₹45,000","₹50,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Divides by 900 instead of 90, a zero error one place to the left."},{"option_index":1,"misconception":"Divides by 9 instead of 90, a zero error one place to the right."},{"option_index":2,"misconception":"Uses 100 as the divisor instead of 90."}],"explanation":"45,00,000 ÷ 90 = 50,000, so each farmer receives ₹50,000.","concept_id":"eco610-sec-govt-role-public","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-government-undertakes-public-sector-activities-for-collective-welfare-004","band":"K5","grade":10,"subject":"Mathematics","concept":"why government undertakes public sector activities for collective welfare","difficulty":2,"stem":"A municipality collects ₹8,40,000 as tax from 1,200 households to run a public health centre. What is the average tax per household?","options":["₹70","₹700","₹7,000","₹840"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Divides by 12,000 instead of 1,200, a zero error one place to the left."},{"option_index":2,"misconception":"Divides by 120 instead of 1,200, a zero error one place to the right."},{"option_index":3,"misconception":"Uses 1,000 as the divisor instead of 1,200."}],"explanation":"8,40,000 ÷ 1,200 = 700, so the average tax is ₹700 per household.","concept_id":"eco610-sec-govt-role-public","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-government-undertakes-public-sector-activities-for-collective-welfare-005","band":"K5","grade":10,"subject":"Mathematics","concept":"why government undertakes public sector activities for collective welfare","difficulty":2,"stem":"The government spends ₹6,00,000 on free textbooks for 8,000 students to promote equality. What is the spending per student?","options":["₹75","₹7.50","₹750","₹60"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Misplaces the decimal one place left, dividing by 80,000 instead of 8,000."},{"option_index":2,"misconception":"Misplaces the decimal one place right, dividing by 800 instead of 8,000."},{"option_index":3,"misconception":"Uses 10,000 as the divisor instead of 8,000."}],"explanation":"6,00,000 ÷ 8,000 = 75, so spending per student is ₹75.","concept_id":"eco610-sec-govt-role-public","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-government-undertakes-public-sector-activities-for-collective-welfare-006","band":"K5","grade":10,"subject":"Mathematics","concept":"why government undertakes public sector activities for collective welfare","difficulty":2,"stem":"Electricity distribution in a town has a fixed cost of ₹18,00,000. Since private firms may not serve all areas profitably, the government provides it. If 60,000 residents share the fixed cost equally, what is the cost per resident?","options":["₹3","₹300","₹30","₹60"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Divides by 6,00,000 instead of 60,000, a zero error one place to the left."},{"option_index":1,"misconception":"Divides by 6,000 instead of 60,000, a zero error one place to the right."},{"option_index":3,"misconception":"Uses 30,000 as the divisor instead of 60,000."}],"explanation":"18,00,000 ÷ 60,000 = 30, so the cost per resident is ₹30.","concept_id":"eco610-sec-govt-role-public","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-government-undertakes-public-sector-activities-for-collective-welfare-007","band":"K5","grade":10,"subject":"Mathematics","concept":"why government undertakes public sector activities for collective welfare","difficulty":2,"stem":"A government project for collective welfare gives benefits worth ₹25,00,000 and costs ₹16,00,000. What is the net benefit?","options":["₹41,00,000","₹25,00,000","₹16,00,000","₹9,00,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Adds cost and benefit instead of subtracting."},{"option_index":1,"misconception":"Reports gross benefit instead of net benefit."},{"option_index":2,"misconception":"Reports cost instead of net benefit."}],"explanation":"Net benefit = 25,00,000 − 16,00,000 = 9,00,000.","concept_id":"eco610-sec-govt-role-public","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-government-undertakes-public-sector-activities-for-collective-welfare-008","band":"K5","grade":10,"subject":"Mathematics","concept":"why government undertakes public sector activities for collective welfare","difficulty":2,"stem":"A public library costs ₹12,00,000 and is open to all 15,000 residents because it is non-rival. What is the average cost per resident?","options":["₹8","₹80","₹800","₹75"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Divides by 1,50,000 instead of 15,000, a zero error one place to the left."},{"option_index":2,"misconception":"Divides by 1,500 instead of 15,000, a zero error one place to the right."},{"option_index":3,"misconception":"Uses 16,000 as the divisor instead of 15,000."}],"explanation":"12,00,000 ÷ 15,000 = 80, so the average cost is ₹80 per resident.","concept_id":"eco610-sec-govt-role-public","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-government-undertakes-public-sector-activities-for-collective-welfare-009","band":"K5","grade":10,"subject":"Mathematics","concept":"why government undertakes public sector activities for collective welfare","difficulty":2,"stem":"A government vaccination drive costs ₹9,60,000 and benefits 4,800 people by preventing disease spread. What is the cost per beneficiary?","options":["₹20","₹2,000","₹200","₹240"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Divides by 48,000 instead of 4,800, a zero error one place to the left."},{"option_index":1,"misconception":"Divides by 480 instead of 4,800, a zero error one place to the right."},{"option_index":3,"misconception":"Uses 4,000 as the divisor instead of 4,800."}],"explanation":"9,60,000 ÷ 4,800 = 200, so the cost per beneficiary is ₹200.","concept_id":"eco610-sec-govt-role-public","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-government-undertakes-public-sector-activities-for-collective-welfare-010","band":"K5","grade":10,"subject":"Mathematics","concept":"why government undertakes public sector activities for collective welfare","difficulty":2,"stem":"The government provides free meals to 24,000 students at a total monthly cost of ₹1,08,00,000 for equity. What is the cost per student per month?","options":["₹450","₹45","₹4,500","₹400"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Divides by 2,40,000 instead of 24,000, a zero error one place to the left."},{"option_index":2,"misconception":"Divides by 2,400 instead of 24,000, a zero error one place to the right."},{"option_index":3,"misconception":"Uses 27,000 as the divisor instead of 24,000."}],"explanation":"1,08,00,000 ÷ 24,000 = 450, so the cost per student per month is ₹450.","concept_id":"eco610-sec-govt-role-public","strand":"Sectors of the Economy","kind":"mcq"},{"id":"organised-versus-unorganised-sector-by-job-security-and-regulation-001","band":"K5","grade":10,"subject":"Mathematics","concept":"organised versus unorganised sector by job security and regulation","difficulty":2,"stem":"A labour survey of 1,200 workers found that 45% are in the organised sector with job security. How many workers are in the organised sector?","options":["660","540","450","54"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Calculated the complement (55% of 1200) as if it asked for the unorganised sector."},{"option_index":2,"misconception":"Used 1000 as the total instead of 1200, giving 45% of 1000."},{"option_index":3,"misconception":"Misplaced the decimal and used 4.5% instead of 45%."}],"explanation":"45% of 1200 = 0.45 × 1200 = 540.","concept_id":"eco610-sec-organised-unorganised","strand":"Sectors of the Economy","kind":"mcq"},{"id":"organised-versus-unorganised-sector-by-job-security-and-regulation-002","band":"K5","grade":10,"subject":"Mathematics","concept":"organised versus unorganised sector by job security and regulation","difficulty":2,"stem":"In an unorganised workshop, 8 out of 40 workers have written contracts. What percentage of workers have no written contract?","options":["20%","8%","80%","32%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Found the percentage with contracts (8/40) instead of without contracts."},{"option_index":1,"misconception":"Treated the count 8 directly as a percentage."},{"option_index":3,"misconception":"Subtracted 8 from 40 to get 32 and then read 32 as a percentage."}],"explanation":"No contract = 40 − 8 = 32; 32/40 × 100 = 80%.","concept_id":"eco610-sec-organised-unorganised","strand":"Sectors of the Economy","kind":"mcq"},{"id":"organised-versus-unorganised-sector-by-job-security-and-regulation-003","band":"K5","grade":10,"subject":"Mathematics","concept":"organised versus unorganised sector by job security and regulation","difficulty":2,"stem":"In an organised sector firm, 3 out of 5 workers get paid leave. What is the ratio of workers who get paid leave to workers who do not get paid leave?","options":["3:5","2:3","5:3","3:2"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Compared leave-getting workers to total workers, not to workers without leave."},{"option_index":1,"misconception":"Reversed the correct part-to-part ratio."},{"option_index":2,"misconception":"Compared total workers to leave-getting workers instead of leave-getting to non-leave-getting."}],"explanation":"3 get leave, so 2 do not; ratio is 3:2.","concept_id":"eco610-sec-organised-unorganised","strand":"Sectors of the Economy","kind":"mcq"},{"id":"organised-versus-unorganised-sector-by-job-security-and-regulation-004","band":"K5","grade":10,"subject":"Mathematics","concept":"organised versus unorganised sector by job security and regulation","difficulty":2,"stem":"A city has 250 organised sector workers and 150 unorganised sector workers. What fraction of all workers are in the unorganised sector?","options":["3/8","5/8","3/5","5/3"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Found the organised sector fraction (250/400) instead of the unorganised fraction."},{"option_index":2,"misconception":"Divided unorganised workers by organised workers (150/250) instead of by total workers."},{"option_index":3,"misconception":"Inverted the organised-to-unorganised worker ratio (250/150)."}],"explanation":"Total = 400; unorganised fraction = 150/400 = 3/8.","concept_id":"eco610-sec-organised-unorganised","strand":"Sectors of the Economy","kind":"mcq"},{"id":"organised-versus-unorganised-sector-by-job-security-and-regulation-005","band":"K5","grade":10,"subject":"Mathematics","concept":"organised versus unorganised sector by job security and regulation","difficulty":2,"stem":"Unorganised sector workers earn ₹240 per day, while organised sector workers earn ₹360 per day. What is the ratio of organised sector wage to unorganised sector wage?","options":["2:3","3:1","3:2","2:1"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reversed the ratio, putting unorganised wage first."},{"option_index":1,"misconception":"Compared organised wage to the difference (360 − 240 = 120), giving 360:120."},{"option_index":3,"misconception":"Compared unorganised wage to the difference, giving 240:120."}],"explanation":"360:240 simplifies by 120 to 3:2.","concept_id":"eco610-sec-organised-unorganised","strand":"Sectors of the Economy","kind":"mcq"},{"id":"organised-versus-unorganised-sector-by-job-security-and-regulation-006","band":"K5","grade":10,"subject":"Mathematics","concept":"organised versus unorganised sector by job security and regulation","difficulty":2,"stem":"A state has 18 lakh organised sector workers and 42 lakh unorganised sector workers. What is the ratio of organised to unorganised sector workers?","options":["7:3","3:10","3:7","7:10"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reversed the organised-to-unorganised ratio."},{"option_index":1,"misconception":"Compared organised workers to total workers (18:60) instead of to unorganised workers."},{"option_index":3,"misconception":"Compared unorganised workers to total workers (42:60) instead of to organised workers."}],"explanation":"18:42 simplifies by 6 to 3:7.","concept_id":"eco610-sec-organised-unorganised","strand":"Sectors of the Economy","kind":"mcq"},{"id":"organised-versus-unorganised-sector-by-job-security-and-regulation-007","band":"K5","grade":10,"subject":"Mathematics","concept":"organised versus unorganised sector by job security and regulation","difficulty":2,"stem":"In a sample of 500 workers, 125 are in the organised sector with job security. The rest are in the unorganised sector. What percent of the sample are in the unorganised sector?","options":["25%","75%","125%","37.5%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Found the organised sector percent (125/500) instead of the unorganised percent."},{"option_index":2,"misconception":"Used the count 125 directly as a percentage."},{"option_index":3,"misconception":"Divided 375 by 1000 instead of by 500, giving 37.5%."}],"explanation":"Unorganised = 500 − 125 = 375; 375/500 × 100 = 75%.","concept_id":"eco610-sec-organised-unorganised","strand":"Sectors of the Economy","kind":"mcq"},{"id":"organised-versus-unorganised-sector-by-job-security-and-regulation-008","band":"K5","grade":10,"subject":"Mathematics","concept":"organised versus unorganised sector by job security and regulation","difficulty":2,"stem":"A labour law covers organised sector establishments with 10 or more workers. In a survey of 60 establishments, 24 are covered. What fraction of the surveyed establishments are NOT covered?","options":["2/5","3/2","5/3","3/5"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Found the covered fraction (24/60) instead of the not-covered fraction."},{"option_index":1,"misconception":"Compared not-covered establishments to covered establishments (36/24)."},{"option_index":2,"misconception":"Inverted the correct not-covered fraction (60/36)."}],"explanation":"Not covered = 60 − 24 = 36; 36/60 = 3/5.","concept_id":"eco610-sec-organised-unorganised","strand":"Sectors of the Economy","kind":"mcq"},{"id":"organised-versus-unorganised-sector-by-job-security-and-regulation-009","band":"K5","grade":10,"subject":"Mathematics","concept":"organised versus unorganised sector by job security and regulation","difficulty":2,"stem":"In an organised sector factory, 90% of 300 workers have regular contracts. How many workers do NOT have regular contracts?","options":["270","90","30","3"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Found the number of workers WITH regular contracts, not without."},{"option_index":1,"misconception":"Used 90% as a count of 90 workers directly."},{"option_index":3,"misconception":"Misplaced the decimal and computed 1% of 300 instead of 10%."}],"explanation":"Without contracts = 10% of 300 = 30.","concept_id":"eco610-sec-organised-unorganised","strand":"Sectors of the Economy","kind":"mcq"},{"id":"organised-versus-unorganised-sector-by-job-security-and-regulation-010","band":"K5","grade":10,"subject":"Mathematics","concept":"organised versus unorganised sector by job security and regulation","difficulty":2,"stem":"An unorganised sector worker earns ₹180 per day and works 26 days a month. An organised sector worker earns ₹250 per day and works 22 days a month. What is the difference in their monthly earnings?","options":["4680","5500","10180","820"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Reported only the unorganised worker's monthly earning (180 × 26)."},{"option_index":1,"misconception":"Reported only the organised worker's monthly earning (250 × 22)."},{"option_index":2,"misconception":"Added the two monthly earnings instead of finding the difference."}],"explanation":"Organised = ₹250 × 22 = ₹5500; unorganised = ₹180 × 26 = ₹4680; difference = ₹820.","concept_id":"eco610-sec-organised-unorganised","strand":"Sectors of the Economy","kind":"mcq"},{"id":"primary-sector-producing-by-directly-exploiting-natural-resources-001","band":"K5","grade":10,"subject":"Mathematics","concept":"primary sector: producing by directly exploiting natural resources","difficulty":2,"stem":"A farmer harvests wheat from 5 hectares. If the yield is 3.2 tonnes per hectare, how many tonnes of wheat does the farmer harvest in total?","options":["8.2 tonnes","1.6 tonnes","16 tonnes","15 tonnes"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Adds hectares and yield instead of multiplying."},{"option_index":1,"misconception":"Places decimal incorrectly after multiplying (treats 3.2 as 0.32)."},{"option_index":3,"misconception":"Rounds 3.2 down to 3 before multiplying."}],"explanation":"5 × 3.2 = 16 tonnes.","concept_id":"eco610-sec-primary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"primary-sector-producing-by-directly-exploiting-natural-resources-002","band":"K5","grade":10,"subject":"Mathematics","concept":"primary sector: producing by directly exploiting natural resources","difficulty":2,"stem":"A coal mine produces 480 tonnes of coal in 12 days at a constant rate. How many tonnes per day does it produce?","options":["40 tonnes/day","468 tonnes/day","5760 tonnes/day","4 tonnes/day"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Subtracts days from total instead of dividing."},{"option_index":2,"misconception":"Multiplies total by days instead of dividing."},{"option_index":3,"misconception":"Divides by 120 instead of 12, misplacing decimal."}],"explanation":"480 ÷ 12 = 40 tonnes/day.","concept_id":"eco610-sec-primary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"primary-sector-producing-by-directly-exploiting-natural-resources-003","band":"K5","grade":10,"subject":"Mathematics","concept":"primary sector: producing by directly exploiting natural resources","difficulty":3,"stem":"A fishing boat catches 0.6 tonne of fish per trip. How many tonnes does it catch in 8 trips?","options":["48 tonnes","4.2 tonnes","0.075 tonnes","4.8 tonnes"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Ignores the decimal in 0.6 and multiplies 6 by 8."},{"option_index":1,"misconception":"Multiplies by 7 trips instead of 8 (off-by-one)."},{"option_index":2,"misconception":"Divides 0.6 by 8 instead of multiplying."}],"explanation":"0.6 × 8 = 4.8 tonnes.","concept_id":"eco610-sec-primary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"primary-sector-producing-by-directly-exploiting-natural-resources-004","band":"K5","grade":10,"subject":"Mathematics","concept":"primary sector: producing by directly exploiting natural resources","difficulty":2,"stem":"A lumberjack cuts 15 trees per day. How many trees does he cut in 6 days?","options":["21 trees","90 trees","2.5 trees","75 trees"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Adds days to trees per day instead of multiplying."},{"option_index":2,"misconception":"Divides trees per day by days."},{"option_index":3,"misconception":"Multiplies by 5 days instead of 6 (off-by-one)."}],"explanation":"15 × 6 = 90 trees.","concept_id":"eco610-sec-primary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"primary-sector-producing-by-directly-exploiting-natural-resources-005","band":"K5","grade":10,"subject":"Mathematics","concept":"primary sector: producing by directly exploiting natural resources","difficulty":3,"stem":"In a village of 250 workers, 60% work in the primary sector. How many workers work in the primary sector?","options":["60 workers","190 workers","150 workers","15 workers"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Treats the percentage 60% as 60 workers."},{"option_index":1,"misconception":"Subtracts 60 from total instead of taking 60%."},{"option_index":3,"misconception":"Finds 6% instead of 60% (divides by 10)."}],"explanation":"60% of 250 = 0.60 × 250 = 150 workers.","concept_id":"eco610-sec-primary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"primary-sector-producing-by-directly-exploiting-natural-resources-006","band":"K5","grade":10,"subject":"Mathematics","concept":"primary sector: producing by directly exploiting natural resources","difficulty":3,"stem":"A farmer has a rectangular field 120 m long and 80 m wide. He plants crops on 3/4 of the field. What area is planted?","options":["7200 m²","2400 m²","9600 m²","4800 m²"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Computes 1/4 of the area instead of 3/4."},{"option_index":2,"misconception":"Uses the total field area without applying the fraction."},{"option_index":3,"misconception":"Mistakes 3/4 for 1/2 of the area."}],"explanation":"120 × 80 = 9600 m²; 3/4 × 9600 = 7200 m².","concept_id":"eco610-sec-primary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"primary-sector-producing-by-directly-exploiting-natural-resources-007","band":"K5","grade":10,"subject":"Mathematics","concept":"primary sector: producing by directly exploiting natural resources","difficulty":2,"stem":"A mine extracts 2.5 tonnes of ore per hour. How many tonnes does it extract in 8 hours?","options":["10.5 tonnes","0.3125 tonnes","2.0 tonnes","20 tonnes"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Adds hours to tonnes per hour instead of multiplying."},{"option_index":1,"misconception":"Divides tonnes per hour by hours."},{"option_index":2,"misconception":"Misplaces decimal and treats 2.5 as 0.25."}],"explanation":"2.5 × 8 = 20 tonnes.","concept_id":"eco610-sec-primary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"primary-sector-producing-by-directly-exploiting-natural-resources-008","band":"K5","grade":10,"subject":"Mathematics","concept":"primary sector: producing by directly exploiting natural resources","difficulty":3,"stem":"A fishing cooperative sells 4.5 tonnes of fish at ₹120 per kg. What is the total revenue?","options":["₹540","₹5,40,000","₹54,000","₹4,500"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Multiplies 4.5 tonnes by ₹120 without converting tonnes to kg."},{"option_index":2,"misconception":"Converts to kg but uses ₹12 per kg instead of ₹120."},{"option_index":3,"misconception":"Converts 4.5 tonnes to 4,500 kg but forgets to multiply by the price."}],"explanation":"4.5 tonnes = 4500 kg; 4500 × 120 = ₹5,40,000.","concept_id":"eco610-sec-primary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"primary-sector-producing-by-directly-exploiting-natural-resources-009","band":"K5","grade":10,"subject":"Mathematics","concept":"primary sector: producing by directly exploiting natural resources","difficulty":2,"stem":"A dairy farmer has 24 cows. Each cow gives 12 litres of milk daily. How many litres of milk does the farmer get daily?","options":["36 litres","2 litres","288 litres","240 litres"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Adds number of cows and litres per cow instead of multiplying."},{"option_index":1,"misconception":"Divides cows by litres per cow."},{"option_index":3,"misconception":"Misreads 24 as 20 and multiplies by 12."}],"explanation":"24 × 12 = 288 litres.","concept_id":"eco610-sec-primary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"primary-sector-producing-by-directly-exploiting-natural-resources-010","band":"K5","grade":10,"subject":"Mathematics","concept":"primary sector: producing by directly exploiting natural resources","difficulty":3,"stem":"A forestry worker plants 3 saplings per 5 m². How many saplings are needed for 200 m²?","options":["120 saplings","600 saplings","40 saplings","80 saplings"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Multiplies area by saplings per group without dividing by 5."},{"option_index":2,"misconception":"Finds the number of 5 m² groups but forgets to multiply by 3 saplings."},{"option_index":3,"misconception":"Uses 2 saplings per 5 m² instead of 3."}],"explanation":"200 ÷ 5 = 40 groups; 40 × 3 = 120 saplings.","concept_id":"eco610-sec-primary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"public-sector-versus-private-sector-by-ownership-and-objective-001","band":"K5","grade":10,"subject":"Mathematics","concept":"public sector versus private sector by ownership and objective","difficulty":2,"stem":"Which sector is owned and controlled by the government and aims at public welfare rather than profit?","options":["Public sector","Private sector","Joint sector","Cooperative sector"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Confuses private ownership with public welfare objective"},{"option_index":2,"misconception":"Thinks government plus private ownership is pure public sector"},{"option_index":3,"misconception":"Confuses member ownership with government ownership"}],"explanation":"Public sector is government-owned and has public welfare as its main objective.","concept_id":"eco610-sec-public-private","strand":"Sectors of the Economy","kind":"mcq"},{"id":"public-sector-versus-private-sector-by-ownership-and-objective-002","band":"K5","grade":10,"subject":"Mathematics","concept":"public sector versus private sector by ownership and objective","difficulty":2,"stem":"A firm is owned by private individuals and its main objective is to earn profit. Which sector does it belong to?","options":["Public sector","Private sector","Joint sector","Cooperative sector"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Equates private profit motive with government ownership"},{"option_index":2,"misconception":"Thinks any private involvement makes it joint sector"},{"option_index":3,"misconception":"Confuses individual private ownership with cooperative membership"}],"explanation":"Private sector is owned by private individuals and aims at profit.","concept_id":"eco610-sec-public-private","strand":"Sectors of the Economy","kind":"mcq"},{"id":"public-sector-versus-private-sector-by-ownership-and-objective-003","band":"K5","grade":10,"subject":"Mathematics","concept":"public sector versus private sector by ownership and objective","difficulty":2,"stem":"In a city, 8 hospitals are run by the government for free treatment, and 12 are run by private companies for profit. What is the ratio of public sector hospitals to private sector hospitals in simplest form?","options":["2:3","3:2","8:12","12:8"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Reverses the order of the ratio"},{"option_index":2,"misconception":"Gives the ratio without simplifying"},{"option_index":3,"misconception":"Uses private to public and does not simplify"}],"explanation":"Ratio public:private = 8:12 = 2:3.","concept_id":"eco610-sec-public-private","strand":"Sectors of the Economy","kind":"mcq"},{"id":"public-sector-versus-private-sector-by-ownership-and-objective-004","band":"K5","grade":10,"subject":"Mathematics","concept":"public sector versus private sector by ownership and objective","difficulty":2,"stem":"A company is owned jointly by the government and a private group, with profit shared. Which sector is it?","options":["Public sector","Private sector","Joint sector","Cooperative sector"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Ignores the private ownership share"},{"option_index":1,"misconception":"Ignores the government ownership share"},{"option_index":3,"misconception":"Confuses joint ownership with member-owned cooperative"}],"explanation":"Joint sector is owned jointly by government and private entities.","concept_id":"eco610-sec-public-private","strand":"Sectors of the Economy","kind":"mcq"},{"id":"public-sector-versus-private-sector-by-ownership-and-objective-005","band":"K5","grade":10,"subject":"Mathematics","concept":"public sector versus private sector by ownership and objective","difficulty":2,"stem":"Which objective is typical of the public sector?","options":["Profit maximization","Market monopoly","Shareholder profit","Public welfare"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Confuses private sector objective with public sector"},{"option_index":1,"misconception":"Thinks public sector aims to eliminate competition"},{"option_index":2,"misconception":"Thinks public sector is owned by shareholders"}],"explanation":"Public sector primarily aims at public welfare, not profit.","concept_id":"eco610-sec-public-private","strand":"Sectors of the Economy","kind":"mcq"},{"id":"public-sector-versus-private-sector-by-ownership-and-objective-006","band":"K5","grade":10,"subject":"Mathematics","concept":"public sector versus private sector by ownership and objective","difficulty":2,"stem":"A firm's main aim is profit maximization and it is owned by a single private entrepreneur. Which sector does it belong to?","options":["Public sector","Private sector","Joint sector","Cooperative sector"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Equates profit motive with government ownership"},{"option_index":2,"misconception":"Thinks private entrepreneur with government rules is joint"},{"option_index":3,"misconception":"Confuses single owner with cooperative"}],"explanation":"Private sector firms are privately owned and aim at profit.","concept_id":"eco610-sec-public-private","strand":"Sectors of the Economy","kind":"mcq"},{"id":"public-sector-versus-private-sector-by-ownership-and-objective-007","band":"K5","grade":10,"subject":"Mathematics","concept":"public sector versus private sector by ownership and objective","difficulty":2,"stem":"In a survey, 25% of firms are public sector and the rest are private. If there are 40 firms, how many are private sector?","options":["10","25","30","15"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Calculates 25% of 40 as private instead of public"},{"option_index":1,"misconception":"Uses the percentage value 25 as a number of firms"},{"option_index":3,"misconception":"Subtracts 25 from 40 instead of 25% of 40"}],"explanation":"Public = 25% of 40 = 10, so private = 40 - 10 = 30.","concept_id":"eco610-sec-public-private","strand":"Sectors of the Economy","kind":"mcq"},{"id":"public-sector-versus-private-sector-by-ownership-and-objective-008","band":"K5","grade":10,"subject":"Mathematics","concept":"public sector versus private sector by ownership and objective","difficulty":2,"stem":"Which ownership pattern matches the public sector?","options":["Government ownership","Private individual ownership","Joint ownership","Member ownership"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Confuses private with public"},{"option_index":2,"misconception":"Confuses joint sector with public sector"},{"option_index":3,"misconception":"Confuses cooperative with public sector"}],"explanation":"Public sector is owned by the government.","concept_id":"eco610-sec-public-private","strand":"Sectors of the Economy","kind":"mcq"},{"id":"public-sector-versus-private-sector-by-ownership-and-objective-009","band":"K5","grade":10,"subject":"Mathematics","concept":"public sector versus private sector by ownership and objective","difficulty":2,"stem":"A cooperative society is owned by its members and aims at mutual help. Which sector is it?","options":["Public sector","Private sector","Joint sector","Cooperative sector"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Thinks government owns cooperative"},{"option_index":1,"misconception":"Confuses member ownership with private ownership"},{"option_index":2,"misconception":"Thinks cooperative is government-private partnership"}],"explanation":"Cooperative sector is owned by members and aims at mutual help.","concept_id":"eco610-sec-public-private","strand":"Sectors of the Economy","kind":"mcq"},{"id":"public-sector-versus-private-sector-by-ownership-and-objective-010","band":"K5","grade":10,"subject":"Mathematics","concept":"public sector versus private sector by ownership and objective","difficulty":2,"stem":"If 3 out of 10 firms are public sector, what percentage are private sector?","options":["30%","70%","10%","3%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Gives public sector percentage instead of private"},{"option_index":2,"misconception":"Confuses total firms with percentage"},{"option_index":3,"misconception":"Uses number of public firms as percentage"}],"explanation":"Public = 3/10 = 30%, so private = 70%.","concept_id":"eco610-sec-public-private","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-the-tertiary-sector-s-share-of-gdp-has-risen-fastest-in-india-001","band":"K5","grade":10,"subject":"Mathematics","concept":"why the tertiary sector's share of GDP has risen fastest in India","difficulty":2,"stem":"In 1990, the tertiary sector contributed 40% of India's GDP. In 2020, it contributed 54%. By how many percentage points did the tertiary sector's share increase?","options":["14","35","54","40"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"mistaking the relative increase (14/40 = 35%) for a percentage-point increase"},{"option_index":2,"misconception":"reporting the final share instead of the increase"},{"option_index":3,"misconception":"reporting the initial share instead of the increase"}],"explanation":"Percentage-point increase = 54 - 40 = 14.","concept_id":"eco610-sec-rising-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-the-tertiary-sector-s-share-of-gdp-has-risen-fastest-in-india-002","band":"K5","grade":10,"subject":"Mathematics","concept":"why the tertiary sector's share of GDP has risen fastest in India","difficulty":2,"stem":"India's GDP is ₹200 lakh crore. If the tertiary sector's share is 55%, what is the GDP contributed by the tertiary sector?","options":["90","110","55","145"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"calculating the remaining 45% of GDP instead of the tertiary 55%"},{"option_index":2,"misconception":"treating the percentage as the amount in lakh crore"},{"option_index":3,"misconception":"subtracting 55 from 200, misusing percent as a whole number"}],"explanation":"Tertiary GDP = 55% of ₹200 lakh crore = 0.55 × 200 = ₹110 lakh crore.","concept_id":"eco610-sec-rising-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-the-tertiary-sector-s-share-of-gdp-has-risen-fastest-in-india-003","band":"K5","grade":10,"subject":"Mathematics","concept":"why the tertiary sector's share of GDP has risen fastest in India","difficulty":2,"stem":"If the tertiary sector's share of GDP rises from 50% to 60%, by what fraction of the original share has it increased?","options":["1/6","1/10","1/5","5/6"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"dividing the increase by the new share (10/60) instead of the original share"},{"option_index":1,"misconception":"dividing the percentage-point increase by 100 instead of by the original share"},{"option_index":3,"misconception":"dividing the original share by the new share (50/60) instead of finding the increase"}],"explanation":"Increase = 10 percentage points, so fraction of original = 10/50 = 1/5.","concept_id":"eco610-sec-rising-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-the-tertiary-sector-s-share-of-gdp-has-risen-fastest-in-india-004","band":"K5","grade":10,"subject":"Mathematics","concept":"why the tertiary sector's share of GDP has risen fastest in India","difficulty":2,"stem":"In a year, the shares of primary, secondary, and tertiary sectors in GDP are 15%, 25%, and 60%. What is the ratio of the tertiary sector's share to the secondary sector's share in simplest form?","options":["5:12","3:1","12:25","12:5"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"writing the ratio in reverse order (secondary to tertiary)"},{"option_index":1,"misconception":"rounding 60:25 to 60:20"},{"option_index":2,"misconception":"simplifying only the first term by 5 and leaving 25 unchanged"}],"explanation":"60:25 = 12:5 after dividing both terms by 5.","concept_id":"eco610-sec-rising-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-the-tertiary-sector-s-share-of-gdp-has-risen-fastest-in-india-005","band":"K5","grade":10,"subject":"Mathematics","concept":"why the tertiary sector's share of GDP has risen fastest in India","difficulty":2,"stem":"Suppose the tertiary sector grows by 8% in a year and the secondary sector grows by 4%. If both sectors were worth ₹100 crore at the start, how much more is the tertiary sector worth than the secondary sector at the end of the year?","options":["₹8 crore","₹12 crore","₹4 crore","₹104 crore"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"taking the tertiary sector's growth amount as the difference"},{"option_index":1,"misconception":"adding both growth amounts instead of comparing final values"},{"option_index":3,"misconception":"reporting the secondary sector's final value rather than the difference"}],"explanation":"Tertiary end value = ₹108 crore, secondary end value = ₹104 crore, difference = ₹4 crore.","concept_id":"eco610-sec-rising-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-the-tertiary-sector-s-share-of-gdp-has-risen-fastest-in-india-006","band":"K5","grade":10,"subject":"Mathematics","concept":"why the tertiary sector's share of GDP has risen fastest in India","difficulty":2,"stem":"The tertiary sector's share of GDP increased by 2 percentage points every year for 5 years. If its share was 48% at the end, what was its share at the start?","options":["43%","38%","53%","48%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"subtracting 5 years instead of 5 × 2 percentage points"},{"option_index":2,"misconception":"adding 5 percentage points instead of subtracting"},{"option_index":3,"misconception":"ignoring the change and reporting the final share"}],"explanation":"Total increase = 2 × 5 = 10 percentage points, so start = 48 - 10 = 38%.","concept_id":"eco610-sec-rising-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-the-tertiary-sector-s-share-of-gdp-has-risen-fastest-in-india-007","band":"K5","grade":10,"subject":"Mathematics","concept":"why the tertiary sector's share of GDP has risen fastest in India","difficulty":2,"stem":"In 2020, India's GDP was ₹150 lakh crore. The tertiary sector's share was 54%. What was the GDP contributed by the tertiary sector?","options":["₹81 lakh crore","₹54 lakh crore","₹96 lakh crore","₹150 lakh crore"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"treating the percentage as the amount in lakh crore"},{"option_index":2,"misconception":"subtracting 54 from 150, misusing percent as a whole number"},{"option_index":3,"misconception":"reporting total GDP instead of the tertiary sector's GDP"}],"explanation":"Tertiary GDP = 54% of ₹150 lakh crore = 0.54 × 150 = ₹81 lakh crore.","concept_id":"eco610-sec-rising-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-the-tertiary-sector-s-share-of-gdp-has-risen-fastest-in-india-008","band":"K5","grade":10,"subject":"Mathematics","concept":"why the tertiary sector's share of GDP has risen fastest in India","difficulty":2,"stem":"The tertiary sector's share of GDP rose from 45% to 54%. What is the percentage increase in the tertiary sector's share relative to its original share?","options":["9%","16 2/3%","18%","20%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"reporting the percentage-point increase as a percentage increase"},{"option_index":1,"misconception":"dividing the increase by the new share (9/54) instead of the original share"},{"option_index":2,"misconception":"dividing the increase by the average of the two shares (9/50)"}],"explanation":"Increase = 9 percentage points; relative increase = 9/45 = 0.20 = 20%.","concept_id":"eco610-sec-rising-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-the-tertiary-sector-s-share-of-gdp-has-risen-fastest-in-india-009","band":"K5","grade":10,"subject":"Mathematics","concept":"why the tertiary sector's share of GDP has risen fastest in India","difficulty":2,"stem":"If the tertiary sector's share is 60% and India's GDP is ₹250 lakh crore, what is the combined GDP of the primary and secondary sectors?","options":["₹150 lakh crore","₹60 lakh crore","₹100 lakh crore","₹250 lakh crore"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"calculating the tertiary sector's GDP (60% of 250) instead of the combined other sectors"},{"option_index":1,"misconception":"treating 60% as ₹60 lakh crore"},{"option_index":3,"misconception":"giving total GDP instead of the combined primary and secondary GDP"}],"explanation":"Primary + secondary share = 100% - 60% = 40%, so combined GDP = 0.40 × ₹250 lakh crore = ₹100 lakh crore.","concept_id":"eco610-sec-rising-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"why-the-tertiary-sector-s-share-of-gdp-has-risen-fastest-in-india-010","band":"K5","grade":10,"subject":"Mathematics","concept":"why the tertiary sector's share of GDP has risen fastest in India","difficulty":2,"stem":"In a year, the tertiary sector's share is 60% and the primary sector's share is 15%. By how many percentage points does the tertiary sector's share exceed the primary sector's share?","options":["60","45","15","75"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"reporting the tertiary share itself"},{"option_index":2,"misconception":"reporting the primary share itself"},{"option_index":3,"misconception":"adding the two shares instead of subtracting"}],"explanation":"Difference = 60% - 15% = 45 percentage points.","concept_id":"eco610-sec-rising-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"secondary-sector-transforming-raw-materials-into-manufactured-goods-001","band":"K5","grade":10,"subject":"Mathematics","concept":"secondary sector: transforming raw materials into manufactured goods","difficulty":2,"stem":"A workshop takes in 4 kg of raw material and produces 3 kg of finished goods. What percentage of the raw material is lost as waste?","options":["20%","33⅓%","25%","75%"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses 1 kg out of 5 kg total instead of 1 kg out of 4 kg raw material."},{"option_index":1,"misconception":"Compares waste with finished goods (1/3) instead of with raw material (1/4)."},{"option_index":3,"misconception":"Compares finished goods with raw material (3/4) and calls that waste."}],"explanation":"Waste = 4 − 3 = 1 kg; 1/4 × 100 = 25%.","concept_id":"eco610-sec-secondary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"secondary-sector-transforming-raw-materials-into-manufactured-goods-002","band":"K5","grade":10,"subject":"Mathematics","concept":"secondary sector: transforming raw materials into manufactured goods","difficulty":2,"stem":"A factory's raw material costs ₹200 per unit. Processing adds 30% of the raw-material cost. The manufacturer sells at a profit of 10% on the total cost. What is the selling price per unit?","options":["₹260","₹266","₹280","₹286"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Forgets to add the 10% profit."},{"option_index":1,"misconception":"Takes 10% profit only on the processing cost (₹60) instead of on total cost."},{"option_index":2,"misconception":"Adds 30% and 10% both to the raw-material cost instead of taking 10% of total cost."}],"explanation":"Total cost = 200 + 60 = ₹260; 10% of 260 = ₹26; SP = ₹286.","concept_id":"eco610-sec-secondary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"secondary-sector-transforming-raw-materials-into-manufactured-goods-003","band":"K5","grade":10,"subject":"Mathematics","concept":"secondary sector: transforming raw materials into manufactured goods","difficulty":2,"stem":"A smelter needs 5 kg of ore to produce 3 kg of metal. How much metal can be produced from 40 kg of ore?","options":["24 kg","15 kg","40 kg","66⅔ kg"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Uses 3/(5+3) of the ore mass instead of the ratio 3/5."},{"option_index":2,"misconception":"Assumes the mass of metal equals the mass of ore with no loss."},{"option_index":3,"misconception":"Inverts the ratio and multiplies by 5/3 instead of 3/5."}],"explanation":"40 × (3/5) = 24 kg.","concept_id":"eco610-sec-secondary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"secondary-sector-transforming-raw-materials-into-manufactured-goods-004","band":"K5","grade":10,"subject":"Mathematics","concept":"secondary sector: transforming raw materials into manufactured goods","difficulty":2,"stem":"A factory manufactured 2,500 units in January and 3,000 units in February. What was the percentage increase in production?","options":["16⅔%","20%","120%","500%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Divides the increase by the February value instead of the January value."},{"option_index":2,"misconception":"Reports the new production as a percentage of the old instead of the increase."},{"option_index":3,"misconception":"Reports the absolute increase of 500 as a percentage without dividing by the original value."}],"explanation":"Increase = 500; 500/2500 × 100 = 20%.","concept_id":"eco610-sec-secondary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"secondary-sector-transforming-raw-materials-into-manufactured-goods-005","band":"K5","grade":10,"subject":"Mathematics","concept":"secondary sector: transforming raw materials into manufactured goods","difficulty":2,"stem":"A machine processes raw material into goods at 120 kg/hour. A second machine processes at 80 kg/hour. Working together, how many hours will they take to process 1,000 kg?","options":["8⅓ h","10 h","5 h","12.5 h"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Uses only the faster machine's rate."},{"option_index":1,"misconception":"Averages the two rates instead of adding them."},{"option_index":3,"misconception":"Uses only the slower machine's rate."}],"explanation":"Combined rate = 120 + 80 = 200 kg/h; 1000/200 = 5 h.","concept_id":"eco610-sec-secondary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"secondary-sector-transforming-raw-materials-into-manufactured-goods-006","band":"K5","grade":10,"subject":"Mathematics","concept":"secondary sector: transforming raw materials into manufactured goods","difficulty":2,"stem":"A factory has fixed costs of ₹2,400 and makes each item for a variable cost of ₹18. It sells each item for ₹30. How many items must it sell to break even?","options":["50","80","133⅓","200"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Divides fixed cost by the sum of selling price and variable cost (30+18)."},{"option_index":1,"misconception":"Divides fixed cost by the selling price only."},{"option_index":2,"misconception":"Divides fixed cost by the variable cost only."}],"explanation":"Contribution per item = 30 − 18 = ₹12; 2400/12 = 200.","concept_id":"eco610-sec-secondary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"secondary-sector-transforming-raw-materials-into-manufactured-goods-007","band":"K5","grade":10,"subject":"Mathematics","concept":"secondary sector: transforming raw materials into manufactured goods","difficulty":2,"stem":"A factory processes 1,500 tonnes of raw material and loses 12% as waste. How much finished product is obtained?","options":["1320 tonnes","180 tonnes","1200 tonnes","1680 tonnes"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Reports the waste amount instead of the finished product."},{"option_index":2,"misconception":"Subtracts 20% instead of 12%."},{"option_index":3,"misconception":"Adds 12% instead of subtracting it."}],"explanation":"Finished = 1500 × (1 − 0.12) = 1320 tonnes.","concept_id":"eco610-sec-secondary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"secondary-sector-transforming-raw-materials-into-manufactured-goods-008","band":"K5","grade":10,"subject":"Mathematics","concept":"secondary sector: transforming raw materials into manufactured goods","difficulty":2,"stem":"A factory uses 2.5 kg of raw material to produce 1 kg of finished product. How much finished product can be made from 20 kg of raw material?","options":["5 kg","10 kg","50 kg","8 kg"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Divides by 4 instead of 2.5."},{"option_index":1,"misconception":"Divides by 2 instead of 2.5."},{"option_index":2,"misconception":"Multiplies by 2.5 instead of dividing."}],"explanation":"20 ÷ 2.5 = 8 kg.","concept_id":"eco610-sec-secondary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"secondary-sector-transforming-raw-materials-into-manufactured-goods-009","band":"K5","grade":10,"subject":"Mathematics","concept":"secondary sector: transforming raw materials into manufactured goods","difficulty":2,"stem":"A manufacturer turns raw material costing ₹450 into a product sold for ₹540. What is the profit percentage on the cost price?","options":["16⅔%","20%","25%","120%"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Divides profit by selling price instead of cost price."},{"option_index":2,"misconception":"Uses ₹90 as a fraction of ₹360 instead of ₹450."},{"option_index":3,"misconception":"Reports the selling price as a percentage of cost instead of the profit."}],"explanation":"Profit = 540 − 450 = ₹90; 90/450 × 100 = 20%.","concept_id":"eco610-sec-secondary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"secondary-sector-transforming-raw-materials-into-manufactured-goods-010","band":"K5","grade":10,"subject":"Mathematics","concept":"secondary sector: transforming raw materials into manufactured goods","difficulty":2,"stem":"A manufacturing unit packs 1.2 kg of product per box. How many full boxes can be filled from 50 kg of product?","options":["41","42","41⅔","60"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Rounds up even though there is not enough product for a full 42nd box."},{"option_index":2,"misconception":"Gives the exact quotient instead of the number of full boxes."},{"option_index":3,"misconception":"Multiplies 50 by 1.2 instead of dividing."}],"explanation":"50 ÷ 1.2 = 41⅔, so only 41 full boxes can be filled.","concept_id":"eco610-sec-secondary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"comparing-sectors-by-their-share-of-gdp-versus-their-share-of-employment-001","band":"K5","grade":10,"subject":"Mathematics","concept":"comparing sectors by their share of GDP versus their share of employment","difficulty":2,"stem":"In a country, the primary sector has 18% of GDP and 45% of employment. By how many percentage points does its employment share exceed its GDP share?","options":["27 percentage points","63 percentage points","18 percentage points","45 percentage points"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Added the two shares (18 + 45) instead of subtracting."},{"option_index":2,"misconception":"Reported the GDP share itself instead of the difference."},{"option_index":3,"misconception":"Reported the employment share itself instead of the difference."}],"explanation":"45% − 18% = 27 percentage points.","concept_id":"eco610-sec-sector-contribution","strand":"Sectors of the Economy","kind":"mcq"},{"id":"comparing-sectors-by-their-share-of-gdp-versus-their-share-of-employment-002","band":"K5","grade":10,"subject":"Mathematics","concept":"comparing sectors by their share of GDP versus their share of employment","difficulty":2,"stem":"A sector has 60% of GDP and 20% of employment. What is the ratio of its GDP share to its employment share in simplest form?","options":["1:3","3:1","40:1","2:1"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Reversed the ratio and compared employment share to GDP share."},{"option_index":2,"misconception":"Subtracted the shares (60 − 20 = 40) and wrote that as a ratio to 1."},{"option_index":3,"misconception":"Subtracted the shares (40) and simplified 40:20 to 2:1 instead of dividing the original shares."}],"explanation":"60:20 simplifies to 3:1.","concept_id":"eco610-sec-sector-contribution","strand":"Sectors of the Economy","kind":"mcq"},{"id":"comparing-sectors-by-their-share-of-gdp-versus-their-share-of-employment-003","band":"K5","grade":10,"subject":"Mathematics","concept":"comparing sectors by their share of GDP versus their share of employment","difficulty":2,"stem":"In a country, the secondary sector has 28% of GDP and 25% of employment. What is the ratio of GDP share to employment share in simplest form?","options":["25:28","3:25","28:25","28:3"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reversed the ratio."},{"option_index":1,"misconception":"Subtracted 28 − 25 = 3 and put the difference over employment share."},{"option_index":3,"misconception":"Subtracted 28 − 25 = 3 and put GDP share over the difference."}],"explanation":"28 and 25 have no common factor, so the ratio is 28:25.","concept_id":"eco610-sec-sector-contribution","strand":"Sectors of the Economy","kind":"mcq"},{"id":"comparing-sectors-by-their-share-of-gdp-versus-their-share-of-employment-004","band":"K5","grade":10,"subject":"Mathematics","concept":"comparing sectors by their share of GDP versus their share of employment","difficulty":2,"stem":"A sector has 50% of employment and 20% of GDP. What is the ratio of its employment share to its GDP share in simplest form?","options":["2:5","3:2","7:2","5:2"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Reversed the ratio and compared GDP share to employment share."},{"option_index":1,"misconception":"Subtracted the shares (50 − 20 = 30) and simplified 30:20 to 3:2."},{"option_index":2,"misconception":"Added the shares (50 + 20 = 70) and simplified 70:20 to 7:2."}],"explanation":"50:20 simplifies to 5:2.","concept_id":"eco610-sec-sector-contribution","strand":"Sectors of the Economy","kind":"mcq"},{"id":"comparing-sectors-by-their-share-of-gdp-versus-their-share-of-employment-005","band":"K5","grade":10,"subject":"Mathematics","concept":"comparing sectors by their share of GDP versus their share of employment","difficulty":2,"stem":"In a country, the tertiary sector has 54% of GDP and 30% of employment. What is the value of (GDP share) ÷ (employment share), correct to one decimal place?","options":["0.6","24.0","84.0","1.8"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Reversed the division (30 ÷ 54 ≈ 0.6) instead of 54 ÷ 30."},{"option_index":1,"misconception":"Subtracted the shares (54 − 30 = 24) instead of dividing."},{"option_index":2,"misconception":"Added the shares (54 + 30 = 84) instead of dividing."}],"explanation":"54 ÷ 30 = 1.8.","concept_id":"eco610-sec-sector-contribution","strand":"Sectors of the Economy","kind":"mcq"},{"id":"comparing-sectors-by-their-share-of-gdp-versus-their-share-of-employment-006","band":"K5","grade":10,"subject":"Mathematics","concept":"comparing sectors by their share of GDP versus their share of employment","difficulty":2,"stem":"The table shows shares for three sectors. Agriculture: GDP 20%, employment 50%. Industry: GDP 30%, employment 25%. Services: GDP 50%, employment 25%. What is the largest gap, in percentage points, between a sector's employment share and its GDP share?","options":["30","25","5","10"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Chose the services gap (50 − 25 = 25) instead of the largest gap."},{"option_index":2,"misconception":"Chose the industry gap (30 − 25 = 5) instead of the largest gap."},{"option_index":3,"misconception":"Compared GDP shares (30 − 20 = 10) instead of comparing employment and GDP shares within a sector."}],"explanation":"Largest gap is agriculture: 50 − 20 = 30 percentage points.","concept_id":"eco610-sec-sector-contribution","strand":"Sectors of the Economy","kind":"mcq"},{"id":"comparing-sectors-by-their-share-of-gdp-versus-their-share-of-employment-007","band":"K5","grade":10,"subject":"Mathematics","concept":"comparing sectors by their share of GDP versus their share of employment","difficulty":2,"stem":"In a country, the primary sector has 12% of GDP and 36% of employment. What fraction of the employment share is the GDP share?","options":["3","1/3","1/4","24"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Reversed the fraction: 36/12 = 3."},{"option_index":2,"misconception":"Simplified 12/36 incorrectly by using 12/48 or misreading the employment share."},{"option_index":3,"misconception":"Subtracted the shares (36 − 12 = 24) instead of forming a fraction."}],"explanation":"12/36 simplifies to 1/3.","concept_id":"eco610-sec-sector-contribution","strand":"Sectors of the Economy","kind":"mcq"},{"id":"comparing-sectors-by-their-share-of-gdp-versus-their-share-of-employment-008","band":"K5","grade":10,"subject":"Mathematics","concept":"comparing sectors by their share of GDP versus their share of employment","difficulty":2,"stem":"A sector has 70% of GDP and 20% of employment. What is the value of (GDP share) ÷ (employment share)?","options":["2/7","50","3.5","3"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reversed the division (20/70) instead of 70/20."},{"option_index":1,"misconception":"Subtracted the shares (70 − 20 = 50) instead of dividing."},{"option_index":3,"misconception":"Rounded 3.5 down to the nearest whole number instead of keeping the exact value."}],"explanation":"70 ÷ 20 = 3.5.","concept_id":"eco610-sec-sector-contribution","strand":"Sectors of the Economy","kind":"mcq"},{"id":"comparing-sectors-by-their-share-of-gdp-versus-their-share-of-employment-009","band":"K5","grade":10,"subject":"Mathematics","concept":"comparing sectors by their share of GDP versus their share of employment","difficulty":2,"stem":"In a country, the secondary sector has 24% of GDP and 30% of employment. By how many percentage points does its employment share exceed its GDP share?","options":["6","54","24","30"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Added the two shares (24 + 30) instead of subtracting."},{"option_index":2,"misconception":"Reported the GDP share itself instead of the difference."},{"option_index":3,"misconception":"Reported the employment share itself instead of the difference."}],"explanation":"30% − 24% = 6 percentage points.","concept_id":"eco610-sec-sector-contribution","strand":"Sectors of the Economy","kind":"mcq"},{"id":"comparing-sectors-by-their-share-of-gdp-versus-their-share-of-employment-010","band":"K5","grade":10,"subject":"Mathematics","concept":"comparing sectors by their share of GDP versus their share of employment","difficulty":2,"stem":"A sector has 45% of GDP and 60% of employment. What is the ratio of its GDP share to its employment share in simplest form?","options":["4:3","1:4","3:4","1:3"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Reversed the ratio and compared employment share to GDP share."},{"option_index":1,"misconception":"Subtracted 60 − 45 = 15 and simplified 15:60 to 1:4."},{"option_index":3,"misconception":"Subtracted 60 − 45 = 15 and simplified 15:45 to 1:3."}],"explanation":"45:60 simplifies to 3:4.","concept_id":"eco610-sec-sector-contribution","strand":"Sectors of the Economy","kind":"mcq"},{"id":"tertiary-sector-services-that-support-production-in-the-other-sectors-001","band":"K5","grade":10,"subject":"Mathematics","concept":"tertiary sector: services that support production in the other sectors","difficulty":2,"stem":"A farmer sells wheat worth ₹12,000 to a wholesaler. The wholesaler charges 6% commission for storage and transport. How much commission is charged?","options":["₹72","₹720","₹1,200","₹7,200"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Treated 6% as 0.6% instead of 6%."},{"option_index":2,"misconception":"Treated 6% as 10%."},{"option_index":3,"misconception":"Treated 6% as 60%."}],"explanation":"6% of ₹12,000 = 0.06 × 12,000 = ₹720.","concept_id":"eco610-sec-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"tertiary-sector-services-that-support-production-in-the-other-sectors-002","band":"K5","grade":10,"subject":"Mathematics","concept":"tertiary sector: services that support production in the other sectors","difficulty":2,"stem":"A dairy cooperative uses cold storage for 2,400 litres of milk. The service charges ₹3.50 per litre per month. What is the monthly charge?","options":["₹840","₹84,000","₹8,400","₹7,200"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Misplaced decimal and used ₹0.35 per litre."},{"option_index":1,"misconception":"Multiplied by 35 instead of 3.5."},{"option_index":3,"misconception":"Used ₹3 per litre instead of ₹3.50."}],"explanation":"2,400 × 3.50 = ₹8,400.","concept_id":"eco610-sec-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"tertiary-sector-services-that-support-production-in-the-other-sectors-003","band":"K5","grade":10,"subject":"Mathematics","concept":"tertiary sector: services that support production in the other sectors","difficulty":2,"stem":"A transport company carries 18 tonnes of goods over 25 km. The freight charge is ₹4 per tonne-km. What is the total freight charge?","options":["₹72","₹100","₹450","₹1,800"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Multiplied tonnes by rate only and ignored distance."},{"option_index":1,"misconception":"Multiplied distance by rate only and ignored tonnes."},{"option_index":2,"misconception":"Computed tonne-km but forgot to multiply by the rate."}],"explanation":"18 × 25 × 4 = ₹1,800.","concept_id":"eco610-sec-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"tertiary-sector-services-that-support-production-in-the-other-sectors-004","band":"K5","grade":10,"subject":"Mathematics","concept":"tertiary sector: services that support production in the other sectors","difficulty":2,"stem":"A bank gives a loan of ₹50,000 to a small manufacturer at 12% simple interest per year for 2 years. How much interest does the manufacturer pay?","options":["₹6,000","₹10,000","₹12,000","₹1,200"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Forgot to multiply by time and calculated only one year's interest."},{"option_index":1,"misconception":"Used 10% rate instead of 12%."},{"option_index":3,"misconception":"Misplaced decimal and used 1.2% rate."}],"explanation":"Simple interest = 50,000 × 12 × 2 / 100 = ₹12,000.","concept_id":"eco610-sec-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"tertiary-sector-services-that-support-production-in-the-other-sectors-005","band":"K5","grade":10,"subject":"Mathematics","concept":"tertiary sector: services that support production in the other sectors","difficulty":2,"stem":"A shopkeeper sends 45 packets by courier. Each packet weighs 200 g. The courier charges ₹25 per kg. How much is the courier charge?","options":["₹225","₹22.50","₹1,125","₹2,250"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Converted 200 g as 0.02 kg instead of 0.2 kg."},{"option_index":2,"misconception":"Charged ₹25 per packet instead of per kg."},{"option_index":3,"misconception":"Converted 200 g as 2 kg instead of 0.2 kg."}],"explanation":"Total weight = 45 × 200 g = 9 kg; charge = 9 × 25 = ₹225.","concept_id":"eco610-sec-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"tertiary-sector-services-that-support-production-in-the-other-sectors-006","band":"K5","grade":10,"subject":"Mathematics","concept":"tertiary sector: services that support production in the other sectors","difficulty":2,"stem":"An insurance company insures a factory for ₹8,00,000. The annual premium is 0.5% of the insured value. What is the annual premium?","options":["₹400","₹4,000","₹8,000","₹40,000"],"answer_index":1,"distractors":[{"option_index":0,"misconception":"Treated 0.5% as 0.05%."},{"option_index":2,"misconception":"Treated 0.5% as 1%."},{"option_index":3,"misconception":"Treated 0.5% as 5%."}],"explanation":"0.5% of ₹8,00,000 = 0.005 × 8,00,000 = ₹4,000.","concept_id":"eco610-sec-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"tertiary-sector-services-that-support-production-in-the-other-sectors-007","band":"K5","grade":10,"subject":"Mathematics","concept":"tertiary sector: services that support production in the other sectors","difficulty":2,"stem":"A wholesale trader buys goods for ₹10,000 and sells them to retailers for ₹12,500. What is the wholesale margin as a percentage of cost?","options":["20%","125%","2.5%","25%"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Calculated margin on selling price instead of cost."},{"option_index":1,"misconception":"Expressed selling price as a percentage of cost instead of margin as a percentage of cost."},{"option_index":2,"misconception":"Misplaced decimal when converting 0.25 to a percentage."}],"explanation":"Margin = 12,500 − 10,000 = ₹2,500; (2,500 / 10,000) × 100 = 25%.","concept_id":"eco610-sec-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"tertiary-sector-services-that-support-production-in-the-other-sectors-008","band":"K5","grade":10,"subject":"Mathematics","concept":"tertiary sector: services that support production in the other sectors","difficulty":2,"stem":"A company sends 2,500 SMS for order updates. The communication service charges ₹0.80 per SMS. What is the monthly bill?","options":["₹200","₹20,000","₹2,500","₹2,000"],"answer_index":3,"distractors":[{"option_index":0,"misconception":"Treated ₹0.80 as ₹0.08 per SMS."},{"option_index":1,"misconception":"Treated ₹0.80 as ₹8 per SMS."},{"option_index":2,"misconception":"Rounded ₹0.80 up to ₹1 per SMS."}],"explanation":"2,500 × 0.80 = ₹2,000.","concept_id":"eco610-sec-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"tertiary-sector-services-that-support-production-in-the-other-sectors-009","band":"K5","grade":10,"subject":"Mathematics","concept":"tertiary sector: services that support production in the other sectors","difficulty":2,"stem":"A producer rents warehouse space of 150 square metres at ₹120 per square metre per month. What is the monthly rent?","options":["₹18,000","₹1,800","₹180,000","₹15,000"],"answer_index":0,"distractors":[{"option_index":1,"misconception":"Misplaced decimal and divided by 10."},{"option_index":2,"misconception":"Used ₹1,200 per square metre instead of ₹120."},{"option_index":3,"misconception":"Used ₹100 per square metre instead of ₹120."}],"explanation":"150 × 120 = ₹18,000.","concept_id":"eco610-sec-tertiary","strand":"Sectors of the Economy","kind":"mcq"},{"id":"tertiary-sector-services-that-support-production-in-the-other-sectors-010","band":"K5","grade":10,"subject":"Mathematics","concept":"tertiary sector: services that support production in the other sectors","difficulty":2,"stem":"An advertising service charges 15% commission on sales. If it generates sales worth ₹5,00,000, how much commission is charged?","options":["₹7,500","₹50,000","₹75,000","₹1,25,000"],"answer_index":2,"distractors":[{"option_index":0,"misconception":"Misplaced decimal and used 1.5% instead of 15%."},{"option_index":1,"misconception":"Used 10% instead of 15%."},{"option_index":3,"misconception":"Used 25% instead of 15%."}],"explanation":"15% of ₹5,00,000 = 0.15 × 5,00,000 = ₹75,000.","concept_id":"eco610-sec-tertiary","strand":"Sectors of the Economy","kind":"mcq"}],"drillCounts":{}};
